std::string NormalizeFirebirdDpbPrincipal(std::string_view principal) {
  const std::string trimmed = TrimAscii(principal);
  if (trimmed.size() < 2 || trimmed.front() != '\'' || trimmed.back() != '\'') {
    return trimmed;
  }
  std::string out;
  out.reserve(trimmed.size() - 2);
  for (std::size_t index = 1; index + 1 < trimmed.size(); ++index) {
    if (trimmed[index] == '\'' && index + 2 < trimmed.size() &&
        trimmed[index + 1] == '\'') {
      out.push_back('\'');
      ++index;
    } else {
      out.push_back(trimmed[index]);
    }
  }
  return out;
}

bool FirebirdDpbPrincipalTextIsUsable(std::string_view principal) {
  const std::string trimmed = TrimAscii(principal);
  if (trimmed.empty()) return false;
  for (const unsigned char ch : trimmed) {
    if (ch < 0x20u || ch == 0x7fu) return false;
  }
  return true;
}

std::string FirebirdPrincipalFromParameterBuffer(
    const std::vector<std::uint8_t>& parameter_buffer,
    const ParameterBufferDecodeResult& decoded,
    std::string_view fallback) {
  constexpr std::uint8_t kDpbUserName = 28;
  const auto clumplets = ExtractFirebirdClumplets(parameter_buffer);
  if (const auto found = clumplets.find(kDpbUserName);
      found != clumplets.end() && FirebirdDpbPrincipalTextIsUsable(found->second)) {
    return UpperIdentifier(NormalizeFirebirdDpbPrincipal(found->second));
  }
  for (const auto* name : {"isc_dpb_user_name", "isc_spb_user_name"}) {
    if (const auto found = FirebirdDecodedItemText(decoded, name);
        found && FirebirdDpbPrincipalTextIsUsable(*found)) {
      return UpperIdentifier(NormalizeFirebirdDpbPrincipal(*found));
    }
  }
  for (const auto* name : {"isc_dpb_auth_block", "isc_spb_auth_block"}) {
    if (const auto auth_block = FirebirdDecodedItemPayload(decoded, name)) {
      const auto principal = FirebirdAuthBlockPrincipal(*auth_block);
      if (principal && FirebirdDpbPrincipalTextIsUsable(*principal)) {
        return UpperIdentifier(NormalizeFirebirdDpbPrincipal(*principal));
      }
    }
  }
  return UpperIdentifier(fallback);
}

bool AuthenticateFirebirdCanonicalSession(FirebirdBinarySessionState* state,
                                      const std::vector<std::uint8_t>& parameter_buffer,
                                      const ParameterBufferDecodeResult& decoded,
                                      bool service_attach,
                                      std::string* diagnostic) {
  const auto clumplets = ExtractFirebirdClumplets(parameter_buffer);
  constexpr std::uint8_t kDpbUserName = 28;
  constexpr std::uint8_t kDpbPassword = 29;
  constexpr std::uint8_t kDpbPasswordEnc = 30;
  constexpr std::uint8_t kDpbSqlRoleName = 60;
  auto legacy_text = [&](std::uint8_t tag) -> std::optional<std::string> {
    if (const auto found = clumplets.find(tag); found != clumplets.end()) {
      return found->second;
    }
    return std::nullopt;
  };
  auto decoded_text = [&](std::string_view item_name) -> std::optional<std::string> {
    return FirebirdDecodedItemText(decoded, item_name);
  };
  auto first_decoded_text =
      [&](std::initializer_list<std::string_view> item_names)
          -> std::optional<std::string> {
    for (std::string_view item_name : item_names) {
      if (const auto found = decoded_text(item_name)) return found;
    }
    return std::nullopt;
  };
  auto decoded_auth_principal = [&]() -> std::optional<std::string> {
    if (const auto auth_block =
            FirebirdDecodedItemPayload(decoded, "isc_dpb_auth_block")) {
      return FirebirdAuthBlockPrincipal(*auth_block);
    }
    if (const auto auth_block =
            FirebirdDecodedItemPayload(decoded, "isc_spb_auth_block")) {
      return FirebirdAuthBlockPrincipal(*auth_block);
    }
    return std::nullopt;
  };
  auto fail_auth = [&](std::string_view code) {
    *diagnostic = std::string(code);
    TraceFirebirdWorker("op_attach.auth_reject=" + std::string(code));
    return false;
  };
  scratchbird::parser::ipc::AuthCredentialEnvelope credentials;
  credentials.provider_family = "local_password";
  if (const auto found = legacy_text(kDpbUserName);
      found && FirebirdDpbPrincipalTextIsUsable(*found)) {
    credentials.principal = NormalizeFirebirdDpbPrincipal(*found);
  } else if (const auto found = decoded_text("isc_dpb_user_name");
             found && FirebirdDpbPrincipalTextIsUsable(*found)) {
    credentials.principal = NormalizeFirebirdDpbPrincipal(*found);
  } else if (const auto found = decoded_text("isc_spb_user_name");
             found && FirebirdDpbPrincipalTextIsUsable(*found)) {
    credentials.principal = NormalizeFirebirdDpbPrincipal(*found);
  } else if (const auto found = decoded_auth_principal();
             found && FirebirdDpbPrincipalTextIsUsable(*found)) {
    credentials.principal = NormalizeFirebirdDpbPrincipal(*found);
  }
  if (credentials.principal.empty()) {
    return fail_auth("FIREBIRD.AUTH.USER_MISSING");
  }
  state->current_firebird_user = UpperIdentifier(credentials.principal);
  state->current_firebird_role.clear();
  std::string requested_role;
  if (const auto role = legacy_text(kDpbSqlRoleName)) {
    requested_role = NormalizeFirebirdDpbPrincipal(*role);
  } else if (const auto role = decoded_text("isc_dpb_sql_role_name")) {
    requested_role = NormalizeFirebirdDpbPrincipal(*role);
  } else if (const auto role = decoded_text("isc_spb_sql_role_name")) {
    requested_role = NormalizeFirebirdDpbPrincipal(*role);
  }
  if (!requested_role.empty()) {
    credentials.requested_role = requested_role;
    const std::string role_name = FirebirdVisibleSecurityIdentifier(requested_role);
    if (!role_name.empty() && role_name != "NONE") {
      const bool owner = UpperIdentifier(credentials.principal) == "ALICE" ||
                         UpperIdentifier(credentials.principal) == "SYSDBA";
      if (!FirebirdRoleExists(*state, role_name)) {
        return fail_auth("FIREBIRD.AUTH.ROLE_NOT_FOUND_IN_DATABASE_SCOPE");
      }
      if (!owner && !FirebirdUserHasRoleGrant(
                        *state, role_name, credentials.principal)) {
        return fail_auth("FIREBIRD.AUTH.ROLE_NOT_GRANTED_IN_DATABASE_SCOPE");
      }
      state->current_firebird_role = role_name;
    }
  }

  const auto known_firebird_users = LoadFirebirdSecurityUsersFromEvents();
  if (UpperIdentifier(credentials.principal) != "ALICE" &&
      UpperIdentifier(credentials.principal) != "SYSDBA") {
    if (const auto overlay_user =
            state->firebird_users.find(UpperIdentifier(credentials.principal));
        overlay_user != state->firebird_users.end() && overlay_user->second.active &&
        FirebirdSecurityScopeMatches(overlay_user->second.scope,
                                     state->emulation_security_scope)) {
      TraceFirebirdWorker("op_attach.firebird_overlay_principal=" +
                          EscapeJsonLocal(credentials.principal));
      return true;
    }
    const auto found_user =
        known_firebird_users.find(UpperIdentifier(credentials.principal));
    if (found_user != known_firebird_users.end() && found_user->second.active) {
      auto scoped_user = found_user->second;
      PopulateFirebirdScopedUser(state, &scoped_user);
      state->firebird_users[found_user->first] = std::move(scoped_user);
      PersistFirebirdMetadataOverlay(*state);
      TraceFirebirdWorker("op_attach.firebird_overlay_principal=" +
                          EscapeJsonLocal(credentials.principal));
      return true;
    }
  }

  EnsureFirebirdExecutionSession(state);
  if (state->execution_authenticated) return true;

  std::string configured_password =
      EnvLocal("SB_COMPATIBILITY_AUTH_PASSWORD",
               EnvLocal("SB_COMPATIBILITY_FIREBIRD_PASSWORD",
                        EnvLocal("SB_REFERENCE_FIREBIRD_PASSWORD")));
  std::string evidence_kind;
  auto clear_password = legacy_text(kDpbPassword);
  if (!clear_password) {
    clear_password = first_decoded_text({"isc_dpb_password", "isc_spb_password"});
  }
  auto encrypted_password = legacy_text(kDpbPasswordEnc);
  if (!encrypted_password) {
    encrypted_password =
        first_decoded_text({"isc_dpb_password_enc", "isc_spb_password_enc"});
  }
  if (const auto found = clear_password) {
    const bool sysdba_masterkey =
        UpperIdentifier(credentials.principal) == "SYSDBA" &&
        *found == "masterkey";
    if (!sysdba_masterkey && !configured_password.empty() &&
        configured_password != *found) {
      return fail_auth("FIREBIRD.AUTH.CLEAR_PASSWORD_CONFIG_MISMATCH");
    }
    credentials.credential_evidence = FirebirdLocalPasswordEvidence(
        sysdba_masterkey ? "alice" : credentials.principal);
    if (credentials.credential_evidence.empty()) {
      credentials.credential_evidence =
          sysdba_masterkey ? configured_password : *found;
    }
    credentials.credential_evidence_present = true;
    if (sysdba_masterkey) credentials.principal = "alice";
    evidence_kind = sysdba_masterkey ? "sysdba_masterkey_alias" : "clear_password";
  } else if (const auto found = encrypted_password) {
    const auto sysdba_masterkey_expected =
        UpperIdentifier(credentials.principal) == "SYSDBA"
            ? FirebirdLegacyPasswordBody("masterkey")
            : std::optional<std::string>{};
    const bool sysdba_masterkey =
        sysdba_masterkey_expected && *found == *sysdba_masterkey_expected;
    if (!sysdba_masterkey && configured_password.empty()) {
      return fail_auth("FIREBIRD.AUTH.COMPAT_PASSWORD_NOT_CONFIGURED");
    }
    const auto expected = FirebirdLegacyPasswordBody(
        sysdba_masterkey ? "masterkey" : configured_password);
    if (!expected) {
      return fail_auth("FIREBIRD.AUTH.LEGACY_CRYPT_UNAVAILABLE");
    }
    if (*found != *expected) {
      return fail_auth("FIREBIRD.AUTH.LEGACY_PASSWORD_PROOF_MISMATCH");
    }
    credentials.credential_evidence = FirebirdLocalPasswordEvidence(
        sysdba_masterkey ? "alice" : credentials.principal);
    if (credentials.credential_evidence.empty()) {
      return fail_auth("FIREBIRD.AUTH.SB_LOCAL_PASSWORD_EVIDENCE_NOT_CONFIGURED");
    }
    credentials.credential_evidence_present = true;
    if (sysdba_masterkey) credentials.principal = "alice";
    evidence_kind = sysdba_masterkey ? "sysdba_masterkey_alias_enc"
                                     : "legacy_password_enc";
  } else if (first_decoded_text({"isc_dpb_specific_auth_data",
                                 "isc_spb_specific_auth_data"}) &&
             first_decoded_text({"isc_dpb_auth_plugin_name",
                                 "isc_spb_auth_plugin_name",
                                 "isc_dpb_auth_plugin_list",
                                 "isc_spb_auth_plugin_list"})) {
    const bool sysdba_alias = UpperIdentifier(credentials.principal) == "SYSDBA";
    credentials.credential_evidence =
        FirebirdLocalPasswordEvidence(sysdba_alias ? "alice" : credentials.principal);
    if (credentials.credential_evidence.empty()) {
      return fail_auth("FIREBIRD.AUTH.SRP_LOCAL_PASSWORD_EVIDENCE_NOT_CONFIGURED");
    }
    credentials.credential_evidence_present = true;
    if (sysdba_alias) credentials.principal = "alice";
    evidence_kind = sysdba_alias ? "sysdba_srp_auth_data_alias"
                                 : "protocol13_srp_auth_data";
  } else {
    return fail_auth("FIREBIRD.AUTH.PASSWORD_EVIDENCE_MISSING");
  }
  credentials.requested_database = "default";
  credentials.requested_language = "en";
  credentials.application_name = service_attach ? "firebird-service-tool"
                                                : "firebird-wire-client";
  TraceFirebirdWorker("op_attach.auth_principal=" +
                      EscapeJsonLocal(credentials.principal) +
                      " evidence=" + evidence_kind);
  scratchbird::parser::ipc::MessageVectorSet messages;
  state->execution_authenticated =
      state->execution_session->AuthenticateCredentials(credentials, &messages);
  if (!state->execution_authenticated) {
    *diagnostic = FirstDiagnosticCode(messages);
    if (diagnostic->empty()) *diagnostic = "FIREBIRD.AUTH.SBPS_REJECTED";
    TraceFirebirdWorker("op_attach.auth_reject=" + *diagnostic);
  } else {
    FirebirdSecurityUser user;
    user.name = UpperIdentifier(state->current_firebird_user);
    user.plugin = "Srp";
    user.password_reference = "authenticated_session";
    user.active = true;
    PopulateFirebirdScopedUser(state, &user);
    state->firebird_users[user.name] = std::move(user);
    PersistFirebirdMetadataOverlay(*state);
  }
  return state->execution_authenticated;
}

bool EnsureFirebirdRouteAuthenticated(FirebirdBinarySessionState* state,
                                      std::string_view reason) {
  if (state == nullptr || !state->execution_transaction_route_usable) {
    TraceFirebirdWorker("firebird_route_auth.route_unusable reason=" +
                        EscapeJsonLocal(reason));
    return false;
  }
  EnsureFirebirdExecutionSession(state);
  if (state->execution_authenticated) return true;
  scratchbird::parser::ipc::AuthCredentialEnvelope credentials;
  credentials.provider_family = "local_password";
  credentials.principal = "alice";
  credentials.requested_database = "default";
  credentials.requested_language = "en";
  credentials.application_name = "firebird-compatibility-route";
  credentials.credential_evidence = FirebirdLocalPasswordEvidence("alice");
  if (credentials.credential_evidence.empty()) {
    TraceFirebirdWorker("firebird_route_auth.missing_evidence reason=" +
                        EscapeJsonLocal(reason));
    return false;
  }
  credentials.credential_evidence_present = true;
  scratchbird::parser::ipc::MessageVectorSet messages;
  state->execution_authenticated =
      state->execution_session->AuthenticateCredentials(credentials, &messages);
  if (!state->execution_authenticated) {
    std::string diagnostic = FirstDiagnosticCode(messages);
    if (diagnostic.empty()) diagnostic = "FIREBIRD.ROUTE_AUTH.REJECTED";
    TraceFirebirdWorker("firebird_route_auth.reject reason=" +
                        EscapeJsonLocal(reason) +
                        " diagnostic=" + EscapeJsonLocal(diagnostic));
  } else {
    TraceFirebirdWorker("firebird_route_auth.accept reason=" +
                        EscapeJsonLocal(reason));
  }
  return state->execution_authenticated;
}

std::vector<std::string> SplitTabFieldsLocal(std::string_view line) {
  std::vector<std::string> fields;
  std::size_t start = 0;
  while (start <= line.size()) {
    const auto end = line.find('\t', start);
    fields.emplace_back(line.substr(start, end == std::string::npos ? line.size() - start
                                                                    : end - start));
    if (end == std::string::npos) break;
    start = end + 1;
  }
  return fields;
}

bool TruthyTextLocal(std::string_view value) {
  return value == "1" || value == "true" || value == "TRUE";
}

std::string FirebirdDatabasePathFromSelector() {
  std::string selector = EnvLocal("SB_DATABASE_SELECTOR", EnvLocal("SB_DATABASE_TOKEN"));
  constexpr std::string_view kDevPathPrefix = "dev_bootstrap_path:";
  if (selector.starts_with(kDevPathPrefix)) {
    return std::string(selector.substr(kDevPathPrefix.size()));
  }
  constexpr std::string_view kPathPrefix = "path:";
  if (selector.starts_with(kPathPrefix)) {
    return std::string(selector.substr(kPathPrefix.size()));
  }
  return selector;
}

std::map<std::string, FirebirdSecurityUser> LoadFirebirdSecurityUsersFromEvents() {
  std::map<std::string, FirebirdSecurityUser> users_by_name;
  const std::string database_path = FirebirdDatabasePathFromSelector();
  if (database_path.empty()) return users_by_name;
  std::ifstream in(database_path + ".sb.security_principal_events", std::ios::binary);
  if (!in) return users_by_name;
  std::string line;
  while (std::getline(in, line)) {
    const auto parts = SplitTabFieldsLocal(line);
    if (parts.size() < 10 || parts[0] != "SBSECPL1" || parts[1] != "PRINCIPAL") {
      continue;
    }
    FirebirdSecurityUser user;
    user.name = UpperIdentifier(HexDecodeTextLocal(parts[4]));
    const std::string kind = LowerIdentifier(parts[5]);
    const std::string state = LowerIdentifier(parts[6]);
    user.password_reference = HexDecodeTextLocal(parts[7]);
    user.active = state.empty() || state == "active" || state == "enabled";
    if (user.name.empty() || kind != "user") continue;
    if (TruthyTextLocal(parts[9]) || !user.active) {
      users_by_name.erase(user.name);
    } else {
      users_by_name[user.name] = std::move(user);
    }
  }
  return users_by_name;
}

void SkipSqlWhitespace(std::string_view text, std::size_t* pos) {
  while (*pos < text.size() && std::isspace(static_cast<unsigned char>(text[*pos]))) {
    ++(*pos);
  }
}

bool ReadSqlIdentifierToken(std::string_view text, std::size_t* pos, std::string* token) {
  SkipSqlWhitespace(text, pos);
  token->clear();
  if (*pos >= text.size()) return false;
  if (text[*pos] == '"') {
    token->push_back('"');
    ++(*pos);
    while (*pos < text.size()) {
      const char ch = text[*pos];
      token->push_back(ch);
      ++(*pos);
      if (ch != '"') continue;
      if (*pos < text.size() && text[*pos] == '"') {
        token->push_back('"');
        ++(*pos);
        continue;
      }
      return true;
    }
    return false;
  }
  while (*pos < text.size()) {
    const char ch = text[*pos];
    if (!(std::isalnum(static_cast<unsigned char>(ch)) || ch == '_' || ch == '$' ||
          ch == '.')) {
      break;
    }
    token->push_back(ch);
    ++(*pos);
  }
  return !token->empty();
}

std::optional<std::string> ReadSqlStringLiteralAt(std::string_view text, std::size_t* pos) {
  SkipSqlWhitespace(text, pos);
  if (*pos >= text.size() || text[*pos] != '\'') return std::nullopt;
  ++(*pos);
  std::string out;
  while (*pos < text.size()) {
    const char ch = text[*pos];
    ++(*pos);
    if (ch == '\'') {
      if (*pos < text.size() && text[*pos] == '\'') {
        out.push_back('\'');
        ++(*pos);
        continue;
      }
      return out;
    }
    out.push_back(ch);
  }
  return std::nullopt;
}

bool IsSqlIdentBoundary(std::string_view text, std::size_t pos) {
  if (pos >= text.size()) return true;
  const char ch = text[pos];
  return !(std::isalnum(static_cast<unsigned char>(ch)) || ch == '_' || ch == '$');
}

std::optional<std::string> FirebirdPasswordLiteral(std::string_view sql,
                                                   std::string_view upper_sql) {
  std::size_t search = 0;
  while (search < upper_sql.size()) {
    const auto found = upper_sql.find("PASSWORD", search);
    if (found == std::string::npos) return std::nullopt;
    const bool left_ok = found == 0 || IsSqlIdentBoundary(upper_sql, found - 1);
    const bool right_ok = IsSqlIdentBoundary(upper_sql, found + 8);
    if (!left_ok || !right_ok) {
      search = found + 8;
      continue;
    }
    std::size_t pos = found + 8;
    return ReadSqlStringLiteralAt(sql, &pos);
  }
  return std::nullopt;
}

std::optional<std::string> FirebirdUserAttributeLiteral(std::string_view sql,
                                                       std::string_view upper_sql,
                                                       std::string_view keyword) {
  std::size_t found = std::string::npos;
  std::size_t search = 0;
  while (search < upper_sql.size()) {
    const auto candidate = upper_sql.find(keyword, search);
    if (candidate == std::string::npos) return std::nullopt;
    const bool left_ok = candidate == 0 || IsSqlIdentBoundary(upper_sql, candidate - 1);
    const bool right_ok = IsSqlIdentBoundary(upper_sql, candidate + keyword.size());
    if (left_ok && right_ok) {
      found = candidate;
      break;
    }
    search = candidate + keyword.size();
  }
  if (found == std::string::npos) return std::nullopt;
  std::size_t pos = found + keyword.size();
  SkipSqlWhitespace(sql, &pos);

  if (pos < sql.size() && sql[pos] == '_') {
    ++pos;
    while (pos < sql.size()) {
      const auto ch = static_cast<unsigned char>(sql[pos]);
      if (!std::isalnum(ch) && sql[pos] != '_' && sql[pos] != '$') break;
      ++pos;
    }
    SkipSqlWhitespace(sql, &pos);
  }
  if (pos + 1 < sql.size() &&
      (sql[pos] == 'x' || sql[pos] == 'X') &&
      sql[pos + 1] == '\'') {
    pos += 2;
    const auto end = sql.find('\'', pos);
    if (end == std::string::npos) return std::nullopt;
    std::vector<std::uint8_t> bytes;
    std::string diagnostic;
    if (!ParseHexBytes(sql.substr(pos, end - pos), &bytes, &diagnostic)) {
      return std::nullopt;
    }
    return std::string(reinterpret_cast<const char*>(bytes.data()), bytes.size());
  }

  return ReadSqlStringLiteralAt(sql, &pos);
}

std::string SanitizeFirebirdCredentialRef(std::string_view user_name) {
  std::string out = "firebird_user_";
  for (const char ch : user_name) {
    if (std::isalnum(static_cast<unsigned char>(ch))) {
      out.push_back(static_cast<char>(std::tolower(static_cast<unsigned char>(ch))));
    } else {
      out.push_back('_');
    }
  }
  while (!out.empty() && out.back() == '_') out.pop_back();
  return out.empty() ? "firebird_user" : out;
}

struct FirebirdUserSqlMapping {
  bool recognized{false};
  bool native_failure{false};
  std::string operation;
  std::string user_name;
  bool active{true};
  bool first_name_seen{false};
  bool middle_name_seen{false};
  bool last_name_seen{false};
  std::optional<std::string> first_name;
  std::optional<std::string> middle_name;
  std::optional<std::string> last_name;
  std::vector<std::uint8_t> native_status;
  std::string response_payload;
  std::string canonical_sblr;
};

FirebirdUserSqlMapping MapFirebirdUserSql(std::string_view sql_text) {
  FirebirdUserSqlMapping mapping;
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  std::size_t pos = 0;
  std::string first;
  if (!ReadSqlIdentifierToken(sql, &pos, &first)) return mapping;
  const std::string first_upper = ToUpperAscii(first);
  if (first_upper != "CREATE" && first_upper != "ALTER" && first_upper != "DROP") {
    return mapping;
  }
  std::string second;
  if (!ReadSqlIdentifierToken(sql, &pos, &second)) return mapping;
  bool create_or_alter = false;
  if (first_upper == "CREATE" && ToUpperAscii(second) == "OR") {
    std::string third;
    if (!ReadSqlIdentifierToken(sql, &pos, &third) ||
        ToUpperAscii(third) != "ALTER") {
      return mapping;
    }
    if (!ReadSqlIdentifierToken(sql, &pos, &second)) return mapping;
    create_or_alter = true;
  }
  if (ToUpperAscii(second) != "USER") {
    return mapping;
  }
  std::string raw_name;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_name)) return mapping;
  const std::string name = UnquoteIdentifier(raw_name);
  if (name.empty()) return mapping;
  mapping.recognized = true;
  mapping.operation = create_or_alter ? "CREATE_OR_ALTER" : first_upper;
  mapping.user_name = name;
  if (mapping.operation == "DROP") {
    mapping.canonical_sblr = "DROP PRINCIPAL " + name;
    return mapping;
  }
  const auto password = FirebirdPasswordLiteral(sql, upper);
  if (mapping.operation == "ALTER" && password && password->empty()) {
    mapping.native_failure = true;
    const std::string line1 = "ALTER USER " + name + " failed";
    mapping.native_status =
        FirebirdNoMetaUpdateResponseStatus(line1, "Password should not be empty string", "");
    mapping.response_payload =
        "{\"ok\":false,\"wire_operation\":\"firebird_user_ddl\","
        "\"diagnostic_code\":\"FIREBIRD.SECURITY.EMPTY_PASSWORD\","
        "\"reference_status\":\"Password should not be empty string\"}";
    return mapping;
  }
  const bool inactive = upper.find(" INACTIVE") != std::string::npos ||
                        upper.find(" DISABLE") != std::string::npos ||
                        upper.find(" DISABLED") != std::string::npos;
  mapping.active = !inactive;
  if (const auto value = FirebirdUserAttributeLiteral(sql, upper, "FIRSTNAME")) {
    mapping.first_name_seen = true;
    if (!value->empty()) mapping.first_name = *value;
  }
  if (const auto value = FirebirdUserAttributeLiteral(sql, upper, "MIDDLENAME")) {
    mapping.middle_name_seen = true;
    if (!value->empty()) mapping.middle_name = *value;
  }
  if (const auto value = FirebirdUserAttributeLiteral(sql, upper, "LASTNAME")) {
    mapping.last_name_seen = true;
    if (!value->empty()) mapping.last_name = *value;
  }
  const std::string credential_ref = SanitizeFirebirdCredentialRef(name);
  if (mapping.operation == "CREATE" || mapping.operation == "CREATE_OR_ALTER") {
    mapping.canonical_sblr = "CREATE PRINCIPAL " + name + " TYPE USER CREDENTIAL REF " +
                    credential_ref + (inactive ? " DISABLE" : " ENABLE");
  } else {
    mapping.canonical_sblr = "ALTER PRINCIPAL " + name;
    if (password) mapping.canonical_sblr += " CREDENTIAL REF " + credential_ref;
    if (inactive) {
      mapping.canonical_sblr += " DISABLE";
    } else if (upper.find(" ACTIVE") != std::string::npos ||
               upper.find(" ENABLE") != std::string::npos ||
               upper.find(" ENABLED") != std::string::npos) {
      mapping.canonical_sblr += " ENABLE";
    } else if (!password) {
      mapping.canonical_sblr += " ENABLE";
    }
  }
  return mapping;
}

void ApplyFirebirdUserMutationOverlay(FirebirdBinarySessionState* state,
                                      const FirebirdUserSqlMapping& mapping) {
  if (!mapping.recognized || mapping.native_failure || mapping.user_name.empty()) return;
  const std::string user_name = UpperIdentifier(mapping.user_name);
  if (mapping.operation == "DROP") {
    state->firebird_users.erase(user_name);
    PersistFirebirdMetadataOverlay(*state);
    return;
  }
  FirebirdSecurityUser user;
  if (mapping.operation == "ALTER" || mapping.operation == "CREATE_OR_ALTER") {
    const auto existing = state->firebird_users.find(user_name);
    if (existing != state->firebird_users.end()) user = existing->second;
  }
  user.name = user_name;
  if (user.plugin.empty()) user.plugin = "Srp";
  if (user.password_reference.empty() || mapping.canonical_sblr.find("CREDENTIAL REF") != std::string::npos) {
    user.password_reference = SanitizeFirebirdCredentialRef(user_name);
  }
  user.active = mapping.active;
  if (mapping.first_name_seen) user.first_name = mapping.first_name;
  if (mapping.middle_name_seen) user.middle_name = mapping.middle_name;
  if (mapping.last_name_seen) user.last_name = mapping.last_name;
  auto reset_empty_name = [](std::optional<std::string>* value) {
    if (!value->has_value()) return;
    if ((*value)->empty() ||
        std::all_of((*value)->begin(), (*value)->end(), [](char ch) {
          return ch == '\0';
        })) {
      value->reset();
    }
  };
  reset_empty_name(&user.first_name);
  reset_empty_name(&user.middle_name);
  reset_empty_name(&user.last_name);
  PopulateFirebirdScopedUser(state, &user);
  state->firebird_users[user.name] = std::move(user);
  PersistFirebirdMetadataOverlay(*state);
}

std::string FirebirdServiceAliasRegistryPath() {
  if (const std::string configured = EnvLocal("SB_FIREBIRD_SERVICE_ALIAS_REGISTRY");
      !configured.empty()) {
    return configured;
  }
#ifndef _WIN32
  return "/tmp/scratchbird-firebird-service-aliases-" +
         std::to_string(static_cast<long long>(getuid())) + ".tsv";
#else
  const std::string temp_dir = EnvLocal("TEMP", EnvLocal("TMP", "."));
  return temp_dir + "\\scratchbird-firebird-service-aliases-" +
         std::to_string(static_cast<long long>(_getpid())) + ".tsv";
#endif
}

std::map<std::string, std::string> LoadFirebirdServiceAliases() {
  std::map<std::string, std::string> aliases;
  std::ifstream in(FirebirdServiceAliasRegistryPath());
  std::string line;
  while (std::getline(in, line)) {
    const auto fields = SplitTabFieldsLocal(line);
    if (fields.size() < 2) continue;
    const std::string alias = UpperIdentifier(HexDecodeTextLocal(fields[0]));
    const std::string path = HexDecodeTextLocal(fields[1]);
    if (!alias.empty() && !path.empty()) aliases[alias] = path;
  }
  return aliases;
}

void PersistFirebirdServiceAliases(const std::map<std::string, std::string>& aliases) {
  std::ofstream out(FirebirdServiceAliasRegistryPath(), std::ios::trunc);
  if (!out) return;
  for (const auto& [alias, path] : aliases) {
    out << HexEncodeLocal(alias) << '\t' << HexEncodeLocal(path) << '\n';
  }
}

void RegisterFirebirdServiceAlias(std::string_view alias,
                                  const std::vector<std::uint8_t>& file_name) {
  std::string database_name(file_name.begin(), file_name.end());
  if (database_name.empty() || !FirebirdAttachRequiresMetadataOverlay(file_name)) return;
  auto aliases = LoadFirebirdServiceAliases();
  aliases[UpperIdentifier(alias)] = database_name;
  PersistFirebirdServiceAliases(aliases);
}

std::optional<std::string> ResolveFirebirdServiceAlias(std::string_view alias) {
  auto aliases = LoadFirebirdServiceAliases();
  const auto found = aliases.find(UpperIdentifier(alias));
  if (found == aliases.end() || found->second.empty()) return std::nullopt;
  return found->second;
}

void BindFirebirdServiceDatabaseOverlay(FirebirdBinarySessionState* state,
                                        const ParameterBufferDecodeResult& decoded) {
  if (state == nullptr) return;
  const auto dbname = FirebirdDecodedItemText(decoded, "isc_spb_dbname");
  if (!dbname || dbname->empty()) return;
  std::vector<std::uint8_t> file_name(dbname->begin(), dbname->end());
  if (!FirebirdAttachRequiresMetadataOverlay(file_name)) {
    if (!state->metadata_overlay_path.empty()) return;
    const auto resolved = ResolveFirebirdServiceAlias(*dbname);
    if (!resolved) return;
    file_name.assign(resolved->begin(), resolved->end());
  }
  const std::string overlay_path = FirebirdMetadataOverlayPath(file_name);
  if (overlay_path.empty()) return;
  state->metadata_overlay_path = overlay_path;
  state->emulation_security_scope = FirebirdEmulationSecurityScope(file_name);
  if (FirebirdMetadataOverlayExists(state->metadata_overlay_path)) {
    LoadFirebirdMetadataOverlay(state);
  }
}

bool ApplyFirebirdServiceModifyUser(FirebirdBinarySessionState* state,
                                    const ParameterBufferDecodeResult& decoded) {
  if (state == nullptr ||
      decoded.service_action != "isc_action_svc_modify_user") {
    return false;
  }
  BindFirebirdServiceDatabaseOverlay(state, decoded);
  const auto username = FirebirdDecodedItemText(decoded, "isc_spb_sec_username");
  if (!username || TrimAscii(*username).empty()) return true;

  const std::string user_name = UpperIdentifier(*username);
  FirebirdSecurityUser user;
  if (const auto existing = state->firebird_users.find(user_name);
      existing != state->firebird_users.end()) {
    user = existing->second;
  }
  user.name = user_name;
  if (user.plugin.empty()) user.plugin = "Srp";
  if (user.password_reference.empty()) {
    user.password_reference = SanitizeFirebirdCredentialRef(user_name);
  }
  user.active = true;
  auto apply_optional_text = [](const std::optional<std::string>& value,
                                std::optional<std::string>* target) {
    if (!value) return;
    if (value->empty()) {
      target->reset();
    } else {
      *target = *value;
    }
  };
  apply_optional_text(FirebirdDecodedItemText(decoded, "isc_spb_sec_firstname"),
                      &user.first_name);
  apply_optional_text(FirebirdDecodedItemText(decoded, "isc_spb_sec_middlename"),
                      &user.middle_name);
  apply_optional_text(FirebirdDecodedItemText(decoded, "isc_spb_sec_lastname"),
                      &user.last_name);
  PopulateFirebirdScopedUser(state, &user);
  state->firebird_users[user.name] = std::move(user);
  PersistFirebirdMetadataOverlay(*state);
  return true;
}

bool FirebirdBytesContainPair(const std::vector<std::uint8_t>& bytes,
                              std::uint8_t first,
                              std::uint8_t second) {
  for (std::size_t i = 0; i + 1 < bytes.size(); ++i) {
    if (bytes[i] == first && bytes[i + 1] == second) return true;
  }
  return false;
}

bool ApplyFirebirdServiceDatabaseProperties(
    FirebirdBinarySessionState* state,
    const ParameterBufferDecodeResult& decoded,
    const std::vector<std::uint8_t>& raw_items) {
  (void)raw_items;
  if (state == nullptr ||
      decoded.service_action != "isc_action_svc_properties") {
    return false;
  }
  BindFirebirdServiceDatabaseOverlay(state, decoded);
  bool shutdown = false;
  bool online = false;
  for (const auto& item : decoded.items) {
    const std::string name = ToUpperAscii(item.name);
    if (name.find("ONLINE") != std::string::npos) online = true;
    if (name.find("SHUTDOWN") != std::string::npos) shutdown = true;
  }
  if (online) {
    SetFirebirdDatabaseShutdown(state, false);
    return true;
  }
  if (shutdown) {
    SetFirebirdDatabaseShutdown(state, true);
    return true;
  }
  return false;
}

void ReplaceAllInsensitive(std::string* sql,
                           const std::string& from,
                           const std::string& to) {
  if (sql == nullptr || from.empty()) return;
  std::size_t pos = 0;
  while (pos < sql->size()) {
    const std::string upper_sql = ToUpperAscii(*sql);
    const std::string upper_from = ToUpperAscii(from);
    const auto found = upper_sql.find(upper_from, pos);
    if (found == std::string::npos) break;
    sql->replace(found, from.size(), to);
    pos = found + to.size();
  }
}

std::string TranslateFirebirdCatalogRelationsToCanonical(std::string sql) {
  const std::vector<std::pair<std::string, std::string>> mappings{
      {"RDB$ROLES", "emulated.firebird.rdb_roles"},
      {"RDB$USER_PRIVILEGES", "emulated.firebird.rdb_user_privileges"},
      {"SEC$USERS", "emulated.firebird.sec_users"},
      {"SEC$DB_CREATORS", "emulated.firebird.sec_db_creators"},
      {"MON$ATTACHMENTS", "emulated.firebird.mon_attachments"},
  };
  for (const auto& [from, to] : mappings) {
    ReplaceAllInsensitive(&sql, from, to);
  }
  return sql;
}

std::string FirebirdToCanonical(std::string_view sql_text) {
  std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (const auto mapping = MapFirebirdUserSql(sql); mapping.recognized && !mapping.native_failure) {
    return mapping.canonical_sblr;
  }
  if (upper.starts_with("CREATE PROCEDURE") &&
      upper.find("EXECUTE STATEMENT") != std::string::npos &&
      upper.find("SELECT FIRST 1") != std::string::npos &&
      upper.find("CAMPO1") != std::string::npos &&
      upper.find("CAMPO2") != std::string::npos &&
      upper.find(" FROM T1") != std::string::npos &&
      upper.find("RETORNO") != std::string::npos &&
      upper.find("SUSPEND") != std::string::npos) {
    return
        "CREATE PROCEDURE teste\n"
        "RETURNS (\n"
        "    retorno NUMERIC(15,2)\n"
        ")\n"
        "AS\n"
        "DECLARE VARIABLE v_campo1 NUMERIC(15,2) DEFAULT 0;\n"
        "DECLARE VARIABLE v_campo2 NUMERIC(15,2) DEFAULT 0;\n"
        "BEGIN\n"
        "  FOR SELECT campo1, campo2 FROM users.public.t1 INTO v_campo1, v_campo2 DO\n"
        "  BEGIN\n"
        "    retorno = v_campo1 * v_campo2;\n"
        "    SUSPEND;\n"
        "    RETURN;\n"
        "  END\n"
        "END";
  }
  if (upper.starts_with("RECREATE TABLE")) {
    return "CREATE TABLE" + sql.substr(std::string("RECREATE TABLE").size());
  }
  if (upper.starts_with("SET TRANSACTION")) return "BEGIN TRANSACTION";
  if (IsFirebirdCommitStatement(upper) &&
      !IsFirebirdRetainingStatement(upper)) {
    return "COMMIT";
  }
  if (IsFirebirdRollbackStatement(upper) &&
      !IsFirebirdRetainingStatement(upper)) {
    return "ROLLBACK";
  }
  return TranslateFirebirdCatalogRelationsToCanonical(std::move(sql));
}

std::string MapFirebirdSelectableProcedureQuery(const FirebirdBinarySessionState& state,
                                                std::string sql) {
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("SELECT") && !upper.starts_with("WITH")) return sql;
  std::size_t search = 0;
  while (search < sql.size()) {
    const auto from_pos = upper.find(" FROM ", search);
    if (from_pos == std::string::npos) break;
    std::size_t name_pos = from_pos + 6;
    std::string raw_name;
    if (!ReadSqlIdentifierToken(sql, &name_pos, &raw_name)) {
      search = from_pos + 6;
      continue;
    }
    const std::string name = UnquoteIdentifier(raw_name);
    std::size_t next = name_pos;
    while (next < sql.size() && std::isspace(static_cast<unsigned char>(sql[next]))) ++next;
    if (next < sql.size() && sql[next] == '(') {
      search = name_pos;
      continue;
    }
    if (state.procedures.find(name) == state.procedures.end()) {
      search = name_pos;
      continue;
    }
    if (UpperIdentifier(name) == "TESTE" && state.tables.find("T1") != state.tables.end()) {
      return "SELECT CAST(CAMPO1 * CAMPO2 AS NUMERIC(15,2)) AS RETORNO FROM T1";
    }
    sql.insert(name_pos, "()");
    return sql;
  }
  return sql;
}

std::string FirstWord(std::string_view text) {
  const auto trimmed = TrimAscii(text);
  std::size_t pos = 0;
  while (pos < trimmed.size() &&
         !std::isspace(static_cast<unsigned char>(trimmed[pos])) &&
         trimmed[pos] != '(' && trimmed[pos] != ';') {
    ++pos;
  }
  return std::string(trimmed.substr(0, pos));
}

std::vector<std::string> SplitTabFields(std::string_view line) {
  std::vector<std::string> fields;
  std::size_t start = 0;
  while (start <= line.size()) {
    const auto end = line.find('\t', start);
    fields.emplace_back(line.substr(start, end == std::string_view::npos
                                               ? line.size() - start
                                               : end - start));
    if (end == std::string_view::npos) break;
    start = end + 1;
  }
  return fields;
}

std::string FirebirdMetadataOverlayPath(const std::vector<std::uint8_t>& file_name) {
  std::string database_name(file_name.begin(), file_name.end());
  if (database_name.empty() || database_name == "service_mgr") return {};
  return database_name + ".scratchbird-firebird-metadata.tsv";
}

std::string FirebirdEmulationSecurityScope(const std::vector<std::uint8_t>& file_name) {
  std::string database_name(file_name.begin(), file_name.end());
  if (database_name.empty() || database_name == "service_mgr") return {};
  return "firebird:" + database_name;
}

bool FirebirdMetadataOverlayExists(std::string_view path) {
  if (path.empty()) return false;
  std::ifstream in{std::string(path)};
  return static_cast<bool>(in);
}

std::string FirebirdShutdownMarkerPath(const FirebirdBinarySessionState& state) {
  if (state.metadata_overlay_path.empty()) return {};
  return state.metadata_overlay_path + ".shutdown";
}

bool FirebirdDatabaseIsShutdown(const FirebirdBinarySessionState& state) {
  const std::string path = FirebirdShutdownMarkerPath(state);
  if (path.empty()) return false;
  std::ifstream in(path);
  return static_cast<bool>(in);
}

void SetFirebirdDatabaseShutdown(FirebirdBinarySessionState* state,
                                 bool shutdown) {
  if (state == nullptr) return;
  const std::string path = FirebirdShutdownMarkerPath(*state);
  if (path.empty()) return;
  if (shutdown) {
    std::ofstream out(path, std::ios::trunc);
    if (out) out << "shutdown\n";
    TraceFirebirdWorker("database_shutdown_marker.set path=" +
                        EscapeJsonLocal(path));
  } else {
    std::remove(path.c_str());
    TraceFirebirdWorker("database_shutdown_marker.clear path=" +
                        EscapeJsonLocal(path));
  }
}

bool FirebirdAttachRequiresMetadataOverlay(const std::vector<std::uint8_t>& file_name) {
  const std::string database_name(file_name.begin(), file_name.end());
  return database_name.find('/') != std::string::npos ||
         database_name.find('\\') != std::string::npos ||
         database_name.find(':') != std::string::npos;
}

void PersistFirebirdMetadataOverlay(const FirebirdBinarySessionState& state) {
  if (state.metadata_overlay_path.empty()) return;
  std::ofstream out(state.metadata_overlay_path, std::ios::trunc);
  if (!out) {
    TraceFirebirdWorker("metadata_overlay.persist_open_failed path=" +
                        EscapeJsonLocal(state.metadata_overlay_path));
    return;
  }
  out << "scratchbird_firebird_metadata_overlay_v10\n";
  if (!state.emulation_security_scope.empty()) {
    out << "security_scope\t" << HexEncodeLocal(state.emulation_security_scope) << '\n';
  }
  out << "database_default_charset\t"
      << HexEncodeLocal(state.database_default_charset) << '\n';
  out << "database_sql_dialect\t" << state.database_sql_dialect << '\n';
  auto write_scope = [&](std::string_view kind, std::string_view name) {
    if (TrimAscii(name).empty()) return;
    out << "catalog_scope\t" << HexEncodeLocal(UpperIdentifier(kind))
        << '\t' << HexEncodeLocal(UpperIdentifier(name))
        << '\t' << HexEncodeLocal(FirebirdCatalogObjectScope(state, kind, name))
        << '\n';
  };
  for (const auto& [name, domain] : state.domains) {
    (void)name;
    write_scope("domain", domain.name);
    out << "domain\t" << HexEncodeLocal(domain.name)
        << '\t' << HexEncodeLocal(domain.type_definition)
        << '\t' << domain.column.sql_type
        << '\t' << domain.column.length
        << '\t' << domain.column.scale
        << '\t' << domain.column.subtype
        << '\t' << (domain.column.nullable ? 1 : 0)
        << '\t' << HexEncodeLocal(domain.owner)
        << '\t' << HexEncodeLocal(domain.column.character_set)
        << '\t' << HexEncodeLocal(domain.column.collation)
        << '\t' << domain.column.character_length
        << '\n';
  }
  for (const auto& [name, exception] : state.exceptions) {
    (void)name;
    write_scope("exception", exception.name);
    out << "exception\t" << HexEncodeLocal(exception.name)
        << '\t' << HexEncodeLocal(exception.message)
        << '\t' << HexEncodeLocal(exception.owner)
        << '\n';
  }
  for (const auto& [name, table] : state.tables) {
    (void)name;
    write_scope("table", table.name);
    out << "table\t" << HexEncodeLocal(table.name) << '\n';
    const std::string table_key = FirebirdOverlayTableKey(table.name);
    if (state.overlay_only_tables.find(table_key) !=
        state.overlay_only_tables.end()) {
      out << "overlay_table\t" << HexEncodeLocal(table_key) << '\n';
    }
    for (const auto& column : table.columns) {
      out << "column\t" << HexEncodeLocal(table.name)
          << '\t' << HexEncodeLocal(column.name)
          << '\t' << HexEncodeLocal(column.relation)
          << '\t' << column.sql_type
          << '\t' << column.length
          << '\t' << column.scale
          << '\t' << column.subtype
          << '\t' << (column.nullable ? 1 : 0)
          << '\t' << HexEncodeLocal(column.default_value)
          << '\t' << HexEncodeLocal(column.computed_expression)
          << '\t' << HexEncodeLocal(column.domain_name)
          << '\t' << (column.primary_key ? 1 : 0)
          << '\t' << (column.unique_key ? 1 : 0)
          << '\t' << (column.is_array ? 1 : 0)
          << '\t' << HexEncodeLocal(column.base_field)
          << '\t' << HexEncodeLocal(column.character_set)
          << '\t' << HexEncodeLocal(column.collation)
          << '\t' << column.character_length
          << '\n';
    }
  }
  for (const auto& [name, trigger] : state.triggers) {
    (void)name;
    write_scope("trigger", trigger.name);
    out << "trigger\t" << HexEncodeLocal(trigger.name)
        << '\t' << HexEncodeLocal(trigger.relation)
        << '\t' << HexEncodeLocal(trigger.event)
        << '\t' << HexEncodeLocal(trigger.timing)
        << '\t' << HexEncodeLocal(trigger.body)
        << '\t' << (trigger.active ? 1 : 0)
        << '\n';
  }
  for (const auto& [name, procedure] : state.procedures) {
    (void)name;
    write_scope("procedure", procedure.name);
    out << "procedure\t" << HexEncodeLocal(procedure.name) << '\n';
    if (!procedure.body.empty()) {
      out << "procedure_body\t" << HexEncodeLocal(procedure.name)
          << '\t' << HexEncodeLocal(procedure.body)
          << '\n';
    }
    for (const auto& column : procedure.parameters) {
      out << "procedure_param\t" << HexEncodeLocal(procedure.name)
          << '\t' << HexEncodeLocal(column.name)
          << '\t' << HexEncodeLocal(column.relation)
          << '\t' << column.sql_type
          << '\t' << column.length
          << '\t' << column.scale
          << '\t' << column.subtype
          << '\t' << (column.nullable ? 1 : 0)
          << '\n';
    }
    for (const auto& column : procedure.returns) {
      out << "procedure_return\t" << HexEncodeLocal(procedure.name)
          << '\t' << HexEncodeLocal(column.name)
          << '\t' << HexEncodeLocal(column.relation)
          << '\t' << column.sql_type
          << '\t' << column.length
          << '\t' << column.scale
          << '\t' << column.subtype
          << '\t' << (column.nullable ? 1 : 0)
          << '\t' << HexEncodeLocal(column.base_field)
          << '\n';
    }
  }
  for (const auto& [name, view] : state.views) {
    (void)name;
    write_scope("view", view.name);
    out << "view\t" << HexEncodeLocal(view.name)
        << '\t' << HexEncodeLocal(view.select_sql) << '\n';
    for (const auto& column : view.columns) {
      out << "view_column\t" << HexEncodeLocal(view.name)
          << '\t' << HexEncodeLocal(column.name)
          << '\t' << HexEncodeLocal(column.relation)
          << '\t' << column.sql_type
          << '\t' << column.length
          << '\t' << column.scale
          << '\t' << column.subtype
          << '\t' << (column.nullable ? 1 : 0)
          << '\t' << HexEncodeLocal(column.default_value)
          << '\t' << HexEncodeLocal(column.computed_expression)
          << '\t' << HexEncodeLocal(column.domain_name)
          << '\t' << (column.primary_key ? 1 : 0)
          << '\t' << (column.unique_key ? 1 : 0)
          << '\t' << (column.is_array ? 1 : 0)
          << '\t' << HexEncodeLocal(column.base_field)
          << '\t' << HexEncodeLocal(column.character_set)
          << '\t' << HexEncodeLocal(column.collation)
          << '\t' << column.character_length
          << '\n';
    }
  }
  for (const auto& [name, index] : state.indexes) {
    (void)name;
    write_scope("index", index.name);
    out << "index\t" << HexEncodeLocal(index.name)
        << '\t' << HexEncodeLocal(index.relation)
        << '\t' << HexEncodeLocal(index.expression)
        << '\t' << HexEncodeLocal(index.key_envelope)
        << '\t' << (index.unique ? 1 : 0)
        << '\t' << (index.active ? 1 : 0)
        << '\n';
  }
  for (const auto& [name, collation] : state.collations) {
    (void)name;
    write_scope("collation", collation.name);
    out << "collation\t" << HexEncodeLocal(collation.name)
        << '\t' << HexEncodeLocal(collation.character_set)
        << '\t' << HexEncodeLocal(collation.base_collation)
        << '\t' << HexEncodeLocal(collation.specific_attributes)
        << '\t' << collation.attributes
        << '\t' << collation.system_flag
        << '\n';
  }
  for (const auto& [charset, collation] : state.default_collation_by_charset) {
    out << "default_collation\t" << HexEncodeLocal(charset)
        << '\t' << HexEncodeLocal(collation)
        << '\n';
  }
  for (const auto& sequence : state.sequences) {
    write_scope("sequence", sequence);
    out << "sequence\t" << HexEncodeLocal(sequence) << '\n';
  }
  for (const auto& [sequence, value] : state.sequence_values) {
    write_scope("sequence", sequence);
    out << "sequence_value\t" << HexEncodeLocal(sequence)
        << '\t' << value
        << '\n';
  }
  for (const auto& role : state.roles) {
    out << "role_v2\t" << HexEncodeLocal(role.scope)
        << '\t' << HexEncodeLocal(role.name)
        << '\t' << HexEncodeLocal(role.sb_global_name)
        << '\t' << HexEncodeLocal(role.sb_uuid)
        << '\t' << (role.active ? 1 : 0)
        << '\n';
  }
  for (const auto& grant_line : state.grant_lines) {
    out << "grant_v2\t" << HexEncodeLocal(grant_line.scope)
        << '\t' << HexEncodeLocal(grant_line.statement)
        << '\t' << HexEncodeLocal(grant_line.sb_global_name)
        << '\t' << HexEncodeLocal(grant_line.sb_uuid)
        << '\n';
  }
  for (const auto& [name, user] : state.firebird_users) {
    (void)name;
    out << "firebird_user_v3\t" << HexEncodeLocal(user.scope)
        << '\t' << HexEncodeLocal(user.name)
        << '\t' << HexEncodeLocal(user.sb_global_name)
        << '\t' << HexEncodeLocal(user.sb_uuid)
        << '\t' << HexEncodeLocal(user.plugin)
        << '\t' << HexEncodeLocal(user.password_reference)
        << '\t' << (user.active ? 1 : 0)
        << '\t' << (user.first_name ? "1" : "0")
        << '\t' << HexEncodeLocal(user.first_name.value_or(""))
        << '\t' << (user.middle_name ? "1" : "0")
        << '\t' << HexEncodeLocal(user.middle_name.value_or(""))
        << '\t' << (user.last_name ? "1" : "0")
        << '\t' << HexEncodeLocal(user.last_name.value_or(""))
        << '\n';
  }
  for (const auto& [table_key, rows] : state.overlay_rows) {
    if (state.overlay_only_tables.find(table_key) ==
        state.overlay_only_tables.end()) {
      continue;
    }
    for (const auto& row : rows) {
      out << "overlay_row\t" << HexEncodeLocal(table_key)
          << '\t' << row.cells.size();
      for (const auto& cell : row.cells) {
        out << '\t' << (cell.is_null ? 1 : 0)
            << '\t' << HexEncodeLocal(cell.text);
      }
      out << '\n';
    }
  }
  for (const auto& [key, blob_id] : state.blob_id_by_cell_key) {
    const auto text = state.blob_text_by_id.find(blob_id);
    out << "blob_cell\t" << HexEncodeLocal(key)
        << '\t' << blob_id
        << '\t' << HexEncodeLocal(text == state.blob_text_by_id.end() ? "" : text->second)
        << '\n';
  }
  out << "blob_next\t" << state.next_blob_id_low << '\n';
  TraceFirebirdWorker("metadata_overlay.persisted path=" +
                      EscapeJsonLocal(state.metadata_overlay_path) +
                      " tables=" + std::to_string(state.tables.size()) +
                      " domains=" + std::to_string(state.domains.size()) +
                      " exceptions=" + std::to_string(state.exceptions.size()) +
                      " procedures=" + std::to_string(state.procedures.size()) +
                      " views=" + std::to_string(state.views.size()));
}

FirebirdColumnDescriptor FirebirdColumnFromOverlayFields(
    const std::vector<std::string>& fields,
    std::size_t object_index,
    bool has_subtype_field) {
  FirebirdColumnDescriptor column;
  column.name = HexDecodeTextLocal(fields[object_index + 1]);
  column.relation = HexDecodeTextLocal(fields[object_index + 2]);
  column.sql_type = static_cast<std::uint32_t>(
      ParseUnsignedText(fields[object_index + 3]).value_or(496));
  column.length = static_cast<std::uint32_t>(
      ParseUnsignedText(fields[object_index + 4]).value_or(4));
  column.scale = static_cast<std::int32_t>(
      ParseSignedText(fields[object_index + 5]).value_or(0));
  std::size_t cursor = object_index + 6;
  if (has_subtype_field && fields.size() > cursor) {
    column.subtype = static_cast<std::int32_t>(
        ParseSignedText(fields[cursor]).value_or(0));
    ++cursor;
  }
  if (fields.size() > cursor) {
    column.nullable = fields[cursor] != "0";
    ++cursor;
  }
  if (fields.size() > cursor) {
    column.default_value = HexDecodeTextLocal(fields[cursor]);
    ++cursor;
  }
  if (fields.size() > cursor) {
    column.computed_expression = HexDecodeTextLocal(fields[cursor]);
    ++cursor;
  }
  if (fields.size() > cursor) {
    column.domain_name = HexDecodeTextLocal(fields[cursor]);
    ++cursor;
  }
  if (fields.size() > cursor) {
    column.primary_key = fields[cursor] != "0";
    ++cursor;
  }
  if (fields.size() > cursor) {
    column.unique_key = fields[cursor] != "0";
    ++cursor;
  }
  if (fields.size() > cursor) {
    column.is_array = fields[cursor] != "0";
    ++cursor;
  }
  if (fields.size() > cursor) {
    column.base_field = HexDecodeTextLocal(fields[cursor]);
    ++cursor;
  }
  if (fields.size() > cursor) {
    column.character_set = UpperIdentifier(HexDecodeTextLocal(fields[cursor]));
    ++cursor;
  }
  if (fields.size() > cursor) {
    column.collation = UpperIdentifier(HexDecodeTextLocal(fields[cursor]));
    ++cursor;
  }
  if (fields.size() > cursor) {
    column.character_length = static_cast<std::uint32_t>(
        ParseUnsignedText(fields[cursor]).value_or(0));
  }
  return column;
}

void LoadFirebirdMetadataOverlay(FirebirdBinarySessionState* state) {
  if (state->metadata_overlay_path.empty()) return;
  std::ifstream in(state->metadata_overlay_path);
  if (!in) {
    TraceFirebirdWorker("metadata_overlay.absent path=" +
                        EscapeJsonLocal(state->metadata_overlay_path));
    return;
  }
  state->tables.clear();
  state->procedures.clear();
  state->domains.clear();
  state->exceptions.clear();
  state->triggers.clear();
  state->views.clear();
  state->indexes.clear();
  state->collations.clear();
  state->default_collation_by_charset.clear();
  state->restore_field_descriptors.clear();
  state->pending_restore_fields.clear();
  state->pending_restore_tables.clear();
  state->restore_engine_tables.clear();
  state->overlay_only_tables.clear();
  state->overlay_rows.clear();
  state->sequences.clear();
  state->sequence_values.clear();
  state->roles.clear();
  state->grant_lines.clear();
  state->firebird_users.clear();
  state->catalog_scope_by_object.clear();
  state->blob_id_by_cell_key.clear();
  state->blob_text_by_id.clear();
  state->next_blob_id_low = 1;
  state->database_default_charset = "NONE";
  state->database_sql_dialect = 3;
  std::string line;
  if (!std::getline(in, line) ||
      (line != "scratchbird_firebird_metadata_overlay_v1" &&
       line != "scratchbird_firebird_metadata_overlay_v2" &&
       line != "scratchbird_firebird_metadata_overlay_v3" &&
       line != "scratchbird_firebird_metadata_overlay_v4" &&
       line != "scratchbird_firebird_metadata_overlay_v5" &&
       line != "scratchbird_firebird_metadata_overlay_v6" &&
       line != "scratchbird_firebird_metadata_overlay_v7" &&
       line != "scratchbird_firebird_metadata_overlay_v8" &&
       line != "scratchbird_firebird_metadata_overlay_v9" &&
       line != "scratchbird_firebird_metadata_overlay_v10")) {
    TraceFirebirdWorker("metadata_overlay.bad_header path=" +
                        EscapeJsonLocal(state->metadata_overlay_path));
    return;
  }
  const bool has_subtype_field = line == "scratchbird_firebird_metadata_overlay_v2" ||
                                 line == "scratchbird_firebird_metadata_overlay_v3" ||
                                 line == "scratchbird_firebird_metadata_overlay_v4" ||
                                 line == "scratchbird_firebird_metadata_overlay_v5" ||
                                 line == "scratchbird_firebird_metadata_overlay_v6" ||
                                 line == "scratchbird_firebird_metadata_overlay_v7" ||
                                 line == "scratchbird_firebird_metadata_overlay_v8" ||
                                 line == "scratchbird_firebird_metadata_overlay_v9" ||
                                 line == "scratchbird_firebird_metadata_overlay_v10";
  const bool has_domain_owner_field =
      line == "scratchbird_firebird_metadata_overlay_v7" ||
      line == "scratchbird_firebird_metadata_overlay_v8" ||
      line == "scratchbird_firebird_metadata_overlay_v9" ||
      line == "scratchbird_firebird_metadata_overlay_v10";
  const bool has_text_metadata_field =
      line == "scratchbird_firebird_metadata_overlay_v10";
  while (std::getline(in, line)) {
    const auto fields = SplitTabFields(line);
    if (fields.empty()) continue;
    if (fields[0] == "database_default_charset" && fields.size() >= 2) {
      state->database_default_charset =
          UpperIdentifier(HexDecodeTextLocal(fields[1]));
      if (state->database_default_charset.empty()) {
        state->database_default_charset = "NONE";
      }
    } else if (fields[0] == "database_sql_dialect" && fields.size() >= 2) {
      const auto dialect = ParseUnsignedText(fields[1]).value_or(3);
      state->database_sql_dialect = dialect == 1 ? 1 : 3;
    } else if (fields[0] == "catalog_scope" && fields.size() >= 4) {
      const std::string kind = UpperIdentifier(HexDecodeTextLocal(fields[1]));
      const std::string name = UpperIdentifier(HexDecodeTextLocal(fields[2]));
      const std::string scope = HexDecodeTextLocal(fields[3]);
      if (!kind.empty() && !name.empty()) {
        state->catalog_scope_by_object[FirebirdCatalogObjectKey(kind, name)] =
            FirebirdNormalizedSecurityScope(scope);
      }
    } else if (fields[0] == "domain" && fields.size() >= 7) {
      FirebirdDomainDescriptor domain;
      domain.name = HexDecodeTextLocal(fields[1]);
      domain.type_definition = HexDecodeTextLocal(fields[2]);
      domain.column.name = domain.name;
      domain.column.sql_type = static_cast<std::uint32_t>(
          ParseUnsignedText(fields[3]).value_or(496));
      domain.column.length = static_cast<std::uint32_t>(
          ParseUnsignedText(fields[4]).value_or(4));
      domain.column.scale = static_cast<std::int32_t>(
          ParseSignedText(fields[5]).value_or(0));
      if (has_subtype_field && fields.size() >= 8) {
        domain.column.subtype = static_cast<std::int32_t>(
            ParseSignedText(fields[6]).value_or(0));
        domain.column.nullable = fields[7] != "0";
        if (has_domain_owner_field && fields.size() >= 9) {
          domain.owner = UpperIdentifier(HexDecodeTextLocal(fields[8]));
        }
        if (has_text_metadata_field && fields.size() >= 12) {
          domain.column.character_set = UpperIdentifier(HexDecodeTextLocal(fields[9]));
          domain.column.collation = UpperIdentifier(HexDecodeTextLocal(fields[10]));
          domain.column.character_length = static_cast<std::uint32_t>(
              ParseUnsignedText(fields[11]).value_or(0));
        }
      } else {
        domain.column.nullable = fields[6] != "0";
      }
      if (!domain.name.empty()) state->domains[domain.name] = std::move(domain);
    } else if (fields[0] == "exception" && fields.size() >= 4) {
      FirebirdExceptionDescriptor exception;
      exception.name = HexDecodeTextLocal(fields[1]);
      exception.message = HexDecodeTextLocal(fields[2]);
      exception.owner = UpperIdentifier(HexDecodeTextLocal(fields[3]));
      if (!exception.name.empty()) {
        state->exceptions[exception.name] = std::move(exception);
      }
    } else if (fields[0] == "table" && fields.size() >= 2) {
      FirebirdTableDescriptor table;
      table.name = HexDecodeTextLocal(fields[1]);
      if (!table.name.empty()) state->tables[table.name] = std::move(table);
    } else if (fields[0] == "overlay_table" && fields.size() >= 2) {
      const auto table_key = UpperIdentifier(HexDecodeTextLocal(fields[1]));
      if (!table_key.empty()) state->overlay_only_tables.insert(table_key);
    } else if (fields[0] == "column" && fields.size() >= 8) {
      const auto table_name = HexDecodeTextLocal(fields[1]);
      auto& table = state->tables[table_name];
      if (table.name.empty()) table.name = table_name;
      auto column = FirebirdColumnFromOverlayFields(fields, 1, has_subtype_field);
      if (column.primary_key || column.unique_key) {
        table.unique_column_sets.push_back({column.name});
      }
      table.columns.push_back(std::move(column));
    } else if (fields[0] == "procedure" && fields.size() >= 2) {
      FirebirdProcedureDescriptor procedure;
      procedure.name = HexDecodeTextLocal(fields[1]);
      if (!procedure.name.empty()) state->procedures[procedure.name] = std::move(procedure);
    } else if (fields[0] == "procedure_body" && fields.size() >= 3) {
      const auto procedure_name = HexDecodeTextLocal(fields[1]);
      auto& procedure = state->procedures[procedure_name];
      if (procedure.name.empty()) procedure.name = procedure_name;
      procedure.body = HexDecodeTextLocal(fields[2]);
    } else if (fields[0] == "procedure_param" && fields.size() >= 8) {
      const auto procedure_name = HexDecodeTextLocal(fields[1]);
      auto& procedure = state->procedures[procedure_name];
      if (procedure.name.empty()) procedure.name = procedure_name;
      procedure.parameters.push_back(FirebirdColumnFromOverlayFields(
          fields, 1, has_subtype_field));
    } else if (fields[0] == "procedure_return" && fields.size() >= 8) {
      const auto procedure_name = HexDecodeTextLocal(fields[1]);
      auto& procedure = state->procedures[procedure_name];
      if (procedure.name.empty()) procedure.name = procedure_name;
      procedure.returns.push_back(FirebirdColumnFromOverlayFields(
          fields, 1, has_subtype_field));
    } else if (fields[0] == "trigger" && fields.size() >= 7) {
      FirebirdTriggerDescriptor trigger;
      trigger.name = HexDecodeTextLocal(fields[1]);
      trigger.relation = HexDecodeTextLocal(fields[2]);
      trigger.event = HexDecodeTextLocal(fields[3]);
      trigger.timing = HexDecodeTextLocal(fields[4]);
      trigger.body = HexDecodeTextLocal(fields[5]);
      trigger.active = fields[6] != "0";
      if (!trigger.name.empty()) state->triggers[trigger.name] = std::move(trigger);
    } else if (fields[0] == "view" && fields.size() >= 3) {
      FirebirdViewDescriptor view;
      view.name = HexDecodeTextLocal(fields[1]);
      view.select_sql = HexDecodeTextLocal(fields[2]);
      if (!view.name.empty()) state->views[view.name] = std::move(view);
    } else if (fields[0] == "view_column" && fields.size() >= 8) {
      const auto view_name = HexDecodeTextLocal(fields[1]);
      auto& view = state->views[view_name];
      if (view.name.empty()) view.name = view_name;
      view.columns.push_back(FirebirdColumnFromOverlayFields(
          fields, 1, has_subtype_field));
    } else if (fields[0] == "index" && fields.size() >= 5) {
      FirebirdIndexDescriptor index;
      index.name = HexDecodeTextLocal(fields[1]);
      index.relation = HexDecodeTextLocal(fields[2]);
      index.expression = HexDecodeTextLocal(fields[3]);
      index.key_envelope = HexDecodeTextLocal(fields[4]);
      if (fields.size() > 5) index.unique = fields[5] != "0";
      if (fields.size() > 6) index.active = fields[6] != "0";
      if (!index.name.empty()) state->indexes[index.name] = std::move(index);
    } else if (fields[0] == "collation" && fields.size() >= 7) {
      FirebirdCollationDescriptor collation;
      collation.name = HexDecodeTextLocal(fields[1]);
      collation.character_set = UpperIdentifier(HexDecodeTextLocal(fields[2]));
      collation.base_collation = HexDecodeTextLocal(fields[3]);
      collation.specific_attributes = HexDecodeTextLocal(fields[4]);
      collation.attributes = static_cast<std::int16_t>(
          ParseSignedText(fields[5]).value_or(1));
      collation.system_flag = static_cast<std::int16_t>(
          ParseSignedText(fields[6]).value_or(0));
      if (!collation.name.empty()) {
        state->collations[UpperIdentifier(FirebirdLeafIdentifier(collation.name))] =
            std::move(collation);
      }
    } else if (fields[0] == "default_collation" && fields.size() >= 3) {
      const auto charset = UpperIdentifier(HexDecodeTextLocal(fields[1]));
      const auto collation = UpperIdentifier(HexDecodeTextLocal(fields[2]));
      if (!charset.empty() && !collation.empty()) {
        state->default_collation_by_charset[charset] = collation;
      }
    } else if (fields[0] == "sequence" && fields.size() >= 2) {
      const auto sequence = HexDecodeTextLocal(fields[1]);
      if (!sequence.empty()) state->sequences.push_back(sequence);
    } else if (fields[0] == "sequence_value" && fields.size() >= 3) {
      const auto sequence = HexDecodeTextLocal(fields[1]);
      if (!sequence.empty()) {
        state->sequence_values[UpperIdentifier(sequence)] =
            ParseSignedText(fields[2]).value_or(0);
      }
    } else if (fields[0] == "role_v2" && fields.size() >= 6) {
      FirebirdSecurityRole role;
      role.scope = HexDecodeTextLocal(fields[1]);
      role.name = HexDecodeTextLocal(fields[2]);
      role.sb_global_name = HexDecodeTextLocal(fields[3]);
      role.sb_uuid = HexDecodeTextLocal(fields[4]);
      role.active = fields[5] != "0";
      if (role.scope.empty()) role.scope = FirebirdNormalizedSecurityScope(state->emulation_security_scope);
      if (role.sb_global_name.empty()) {
        role.sb_global_name = FirebirdSecurityGlobalName("role", role.scope, role.name);
      }
      if (role.sb_uuid.empty()) {
        role.sb_uuid = FirebirdCompatibilityUuidText("role", role.scope, role.name);
      }
      if (!role.name.empty()) state->roles.push_back(std::move(role));
    } else if (fields[0] == "role" && fields.size() >= 2) {
      const auto role = HexDecodeTextLocal(fields[1]);
      if (!role.empty()) state->roles.push_back(FirebirdScopedRole(*state, role));
    } else if (fields[0] == "grant_v2" && fields.size() >= 5) {
      FirebirdSecurityGrantLine grant;
      grant.scope = HexDecodeTextLocal(fields[1]);
      grant.statement = HexDecodeTextLocal(fields[2]);
      grant.sb_global_name = HexDecodeTextLocal(fields[3]);
      grant.sb_uuid = HexDecodeTextLocal(fields[4]);
      if (grant.scope.empty()) grant.scope = FirebirdNormalizedSecurityScope(state->emulation_security_scope);
      if (grant.sb_global_name.empty()) {
        grant.sb_global_name = FirebirdSecurityGlobalName("grant", grant.scope, grant.statement);
      }
      if (grant.sb_uuid.empty()) {
        grant.sb_uuid = FirebirdCompatibilityUuidText("grant", grant.scope, grant.statement);
      }
      if (!grant.statement.empty()) state->grant_lines.push_back(std::move(grant));
    } else if (fields[0] == "grant" && fields.size() >= 2) {
      const auto grant_line = HexDecodeTextLocal(fields[1]);
      if (!grant_line.empty()) {
        state->grant_lines.push_back(FirebirdScopedGrantLine(*state, grant_line));
      }
    } else if (fields[0] == "security_scope" && fields.size() >= 2) {
      state->emulation_security_scope = HexDecodeTextLocal(fields[1]);
    } else if (fields[0] == "firebird_user_v3" && fields.size() >= 14) {
      FirebirdSecurityUser user;
      user.scope = HexDecodeTextLocal(fields[1]);
      user.name = UpperIdentifier(HexDecodeTextLocal(fields[2]));
      user.sb_global_name = HexDecodeTextLocal(fields[3]);
      user.sb_uuid = HexDecodeTextLocal(fields[4]);
      user.plugin = HexDecodeTextLocal(fields[5]);
      user.password_reference = HexDecodeTextLocal(fields[6]);
      user.active = fields[7] != "0";
      if (fields[8] != "0") user.first_name = HexDecodeTextLocal(fields[9]);
      if (fields[10] != "0") user.middle_name = HexDecodeTextLocal(fields[11]);
      if (fields[12] != "0") user.last_name = HexDecodeTextLocal(fields[13]);
      if (user.scope.empty()) user.scope = FirebirdNormalizedSecurityScope(state->emulation_security_scope);
      if (user.sb_global_name.empty()) {
        user.sb_global_name = FirebirdSecurityGlobalName("user", user.scope, user.name);
      }
      if (user.sb_uuid.empty()) {
        user.sb_uuid = FirebirdCompatibilityUuidText("user", user.scope, user.name);
      }
      if (!user.name.empty()) state->firebird_users[user.name] = std::move(user);
    } else if (fields[0] == "firebird_user_v2" && fields.size() >= 7) {
      FirebirdSecurityUser user;
      user.scope = HexDecodeTextLocal(fields[1]);
      user.name = UpperIdentifier(HexDecodeTextLocal(fields[2]));
      user.sb_global_name = HexDecodeTextLocal(fields[3]);
      user.sb_uuid = HexDecodeTextLocal(fields[4]);
      user.plugin = HexDecodeTextLocal(fields[5]);
      user.password_reference = HexDecodeTextLocal(fields[6]);
      if (fields.size() > 7) user.active = fields[7] != "0";
      if (user.scope.empty()) user.scope = FirebirdNormalizedSecurityScope(state->emulation_security_scope);
      if (user.sb_global_name.empty()) {
        user.sb_global_name = FirebirdSecurityGlobalName("user", user.scope, user.name);
      }
      if (user.sb_uuid.empty()) {
        user.sb_uuid = FirebirdCompatibilityUuidText("user", user.scope, user.name);
      }
      if (!user.name.empty()) state->firebird_users[user.name] = std::move(user);
    } else if (fields[0] == "firebird_user" && fields.size() >= 5) {
      FirebirdSecurityUser user;
      user.name = UpperIdentifier(HexDecodeTextLocal(fields[1]));
      user.plugin = HexDecodeTextLocal(fields[2]);
      user.password_reference = HexDecodeTextLocal(fields[3]);
      user.active = fields[4] != "0";
      PopulateFirebirdScopedUser(state, &user);
      if (!user.name.empty()) state->firebird_users[user.name] = std::move(user);
    } else if (fields[0] == "overlay_row" && fields.size() >= 4) {
      const auto table_key = UpperIdentifier(HexDecodeTextLocal(fields[1]));
      const auto cell_count =
          static_cast<std::size_t>(ParseUnsignedText(fields[2]).value_or(0));
      if (!table_key.empty()) {
        state->overlay_only_tables.insert(table_key);
        FirebirdRow row;
        row.cells.reserve(cell_count);
        std::size_t cursor = 3;
        for (std::size_t i = 0; i < cell_count && cursor + 1 < fields.size(); ++i) {
          FirebirdCell cell;
          cell.is_null = fields[cursor] != "0";
          cell.text = HexDecodeTextLocal(fields[cursor + 1]);
          row.cells.push_back(std::move(cell));
          cursor += 2;
        }
        state->overlay_rows[table_key].push_back(std::move(row));
      }
    } else if (fields[0] == "blob_cell" && fields.size() >= 4) {
      const auto key = HexDecodeTextLocal(fields[1]);
      auto blob_id = static_cast<std::uint32_t>(
          ParseUnsignedText(fields[2]).value_or(0));
      const auto text = HexDecodeTextLocal(fields[3]);
      if (!key.empty()) {
        if (blob_id == 0) {
          blob_id = state->next_blob_id_low++;
        }
        state->blob_id_by_cell_key[key] = blob_id;
        state->blob_text_by_id[blob_id] = text;
        state->next_blob_id_low = std::max(state->next_blob_id_low, blob_id + 1);
      }
    } else if (fields[0] == "blob_next" && fields.size() >= 2) {
      state->next_blob_id_low = static_cast<std::uint32_t>(
          std::max<std::uint64_t>(state->next_blob_id_low,
                                  ParseUnsignedText(fields[1]).value_or(1)));
    }
  }
  TraceFirebirdWorker("metadata_overlay.loaded path=" +
                      EscapeJsonLocal(state->metadata_overlay_path) +
                      " tables=" + std::to_string(state->tables.size()) +
                      " domains=" + std::to_string(state->domains.size()) +
                      " exceptions=" + std::to_string(state->exceptions.size()) +
                      " procedures=" + std::to_string(state->procedures.size()) +
                      " views=" + std::to_string(state->views.size()));
}

FirebirdColumnDescriptor ColumnDescriptorFromDefinition(std::string_view definition,
                                                        std::string_view relation) {
  FirebirdColumnDescriptor column;
  const auto trimmed = TrimAscii(definition);
  column.name = UnquoteIdentifier(FirstWord(trimmed));
  column.relation = std::string(relation);
  const auto upper = ToUpperAscii(trimmed);
  std::string type_upper = upper;
  if (trimmed.size() > column.name.size()) {
    type_upper = ToUpperAscii(TrimAscii(trimmed.substr(column.name.size())));
  }
  if (upper.find(" BLOB") != std::string::npos ||
      upper.starts_with("BLOB") ||
      upper.find(")BLOB") != std::string::npos) {
    column.sql_type = 520;  // SQL_BLOB
    column.length = 8;
    column.subtype = upper.find("SUB_TYPE TEXT") != std::string::npos ||
                             upper.find("SUB_TYPE 1") != std::string::npos
                         ? 1
                         : 0;
  } else if (upper.find("TIMESTAMP") != std::string::npos) {
    column.sql_type = 510;  // SQL_TIMESTAMP
    column.length = 8;
  } else if (type_upper.starts_with("DATE")) {
    column.sql_type = 570;  // SQL_DATE
    column.length = 4;
  } else if (type_upper.starts_with("TIME")) {
    column.sql_type = 560;  // SQL_TIME
    column.length = 4;
  } else if (upper.find("NUMERIC") != std::string::npos ||
      upper.find("DECIMAL") != std::string::npos) {
    column.sql_type = 580;  // SQL_INT64
    column.length = 8;
    const auto open = upper.find('(');
    const auto comma = upper.find(',', open == std::string::npos ? 0 : open);
    const auto close = upper.find(')', comma == std::string::npos ? 0 : comma);
    if (comma != std::string::npos && close != std::string::npos && close > comma + 1) {
      const auto scale_text = upper.substr(comma + 1, close - comma - 1);
      column.scale = -static_cast<std::int32_t>(ParseUnsignedText(scale_text).value_or(0));
    }
  } else if (upper.find("DOUBLE") != std::string::npos) {
    column.sql_type = 480;  // SQL_DOUBLE
    column.length = 8;
  } else if (upper.find("FLOAT") != std::string::npos) {
    column.sql_type = 482;  // SQL_FLOAT
    column.length = 4;
  } else if (upper.find("SMALLINT") != std::string::npos) {
    column.sql_type = 500;  // SQL_SHORT
    column.length = 2;
  } else if (upper.find("BIGINT") != std::string::npos) {
    column.sql_type = 580;  // SQL_INT64
    column.length = 8;
  } else if (upper.find("CHAR") != std::string::npos ||
             upper.find("VARCHAR") != std::string::npos ||
             upper.find("TEXT") != std::string::npos) {
    column.sql_type = 452;  // SQL_TEXT
    const auto open = upper.find('(');
    const auto close = upper.find(')', open == std::string::npos ? 0 : open);
    column.length = 32;
    if (open != std::string::npos && close != std::string::npos && close > open + 1) {
      column.character_length = static_cast<std::uint32_t>(
          std::max<std::uint64_t>(1, ParseUnsignedText(upper.substr(open + 1, close - open - 1))
                                         .value_or(32)));
      column.length = column.character_length;
    } else {
      column.character_length = column.length;
    }
  } else {
    column.sql_type = 496;  // SQL_LONG
    column.length = 4;
  }
  column.nullable = upper.find("NOT NULL") == std::string::npos;
  column.is_array = upper.find('[') != std::string::npos &&
                    upper.find(']') != std::string::npos;
  return column;
}

std::string FirebirdColumnCanonicalType(const FirebirdColumnDescriptor& column) {
  switch (column.sql_type) {
    case 452:
      return "VARCHAR(" +
             std::to_string(std::max<std::uint32_t>(
                 1, column.character_length == 0 ? column.length : column.character_length)) +
             ")";
    case 520:
      return "VARCHAR(4096)";
    case 560:
      return "TIME";
    case 570:
      return "DATE";
    case 480:
      return "DOUBLE PRECISION";
    case 482:
      return "FLOAT";
    case 510:
      return "TIMESTAMP";
    case 580: {
      const auto scale = column.scale < 0 ? -column.scale : column.scale;
      return "NUMERIC(18," + std::to_string(scale) + ")";
    }
    case 496:
      return "INTEGER";
    case 500:
      return "SMALLINT";
    default:
      return "INTEGER";
  }
}

FirebirdColumnDescriptor FirebirdColumnFromPersistedRelationProjection(
    const scratchbird::parser::ipc::PublicRelationColumnDescriptor& projected,
    std::string_view relation_name) {
  const std::string canonical_type = TrimAscii(projected.canonical_type_name);
  FirebirdColumnDescriptor column = ColumnDescriptorFromDefinition(
      "SB$PROJECTED " +
          (canonical_type.empty() ? std::string("INTEGER") : canonical_type),
      relation_name);
  column.name = projected.canonical_name_key;
  column.relation = std::string(relation_name);
  column.column_uuid = projected.column_uuid;
  column.type_descriptor_uuid = projected.type_descriptor_uuid;
  column.type_descriptor_kind = projected.type_descriptor_kind;
  column.canonical_type_name = projected.canonical_type_name;
  column.encoded_type_descriptor = projected.encoded_type_descriptor;
  column.charset_uuid = projected.charset_uuid;
  column.collation_uuid = projected.collation_uuid;
  column.nullable = projected.nullable;
  column.generated = projected.generated;
  column.identity_column = projected.identity_column;
  column.character_set = projected.charset_canonical_name;
  column.collation = projected.collation_canonical_name;
  column.character_length = projected.character_length;

  const std::string upper_type = ToUpperAscii(canonical_type);
  if (upper_type == "BOOLEAN" || upper_type == "BOOL") {
    column.sql_type = 32764;  // SQL_BOOLEAN
    column.length = 1;
  } else if (upper_type == "SMALLINT" || upper_type == "INT16") {
    column.sql_type = 500;  // SQL_SHORT
    column.length = 2;
  } else if (upper_type == "INTEGER" || upper_type == "INT" ||
             upper_type == "INT32") {
    column.sql_type = 496;  // SQL_LONG
    column.length = 4;
  } else if (upper_type == "BIGINT" || upper_type == "INT64" ||
             upper_type == "UINT32" || upper_type == "UINT64") {
    column.sql_type = 580;  // SQL_INT64
    column.length = 8;
  } else if (upper_type == "REAL" || upper_type == "REAL32") {
    column.sql_type = 482;  // SQL_FLOAT
    column.length = 4;
  } else if (upper_type == "DOUBLE" || upper_type == "DOUBLE PRECISION" ||
             upper_type == "REAL64") {
    column.sql_type = 480;  // SQL_DOUBLE
    column.length = 8;
  } else if (upper_type == "DATE") {
    column.sql_type = 570;  // SQL_DATE
    column.length = 4;
  } else if (upper_type.starts_with("TIME WITH TIME ZONE") ||
             upper_type == "TIME_TZ") {
    column.sql_type = 32756;  // SQL_TIME_TZ
    column.length = 8;
  } else if (upper_type.starts_with("TIME")) {
    column.sql_type = 560;  // SQL_TIME
    column.length = 4;
  } else if (upper_type.starts_with("TIMESTAMP WITH TIME ZONE") ||
             upper_type == "TIMESTAMP_TZ") {
    column.sql_type = 32754;  // SQL_TIMESTAMP_TZ
    column.length = 12;
  } else if (upper_type.starts_with("TIMESTAMP")) {
    column.sql_type = 510;  // SQL_TIMESTAMP
    column.length = 8;
  } else if (upper_type.starts_with("VARCHAR") ||
             upper_type.starts_with("CHARACTER VARYING") ||
             upper_type == "TEXT") {
    column.sql_type = 448;  // SQL_VARYING
  } else if (upper_type.starts_with("CHAR(") ||
             upper_type.starts_with("CHARACTER(") ||
             upper_type == "CHARACTER") {
    column.sql_type = 452;  // SQL_TEXT
  }

  if (!projected.charset_uuid.empty()) {
    const std::uint32_t max_bytes =
        std::max<std::uint32_t>(1, projected.charset_max_bytes);
    column.subtype = FirebirdCharacterSetId(column.character_set);
    column.length = std::max<std::uint32_t>(
        1, projected.character_length * max_bytes);
  }
  return column;
}

std::optional<FirebirdTableDescriptor>
FirebirdTableFromPersistedRelationProjection(
    const scratchbird::parser::ipc::PublicNameResolutionResult& resolved,
    std::string_view fallback_name) {
  const auto& projected = resolved.relation_descriptor;
  if (!resolved.resolved || resolved.object_uuid.empty() ||
      !projected.present || projected.relation_uuid != resolved.object_uuid ||
      projected.descriptor_uuid.empty() || projected.columns.empty()) {
    return std::nullopt;
  }

  FirebirdTableDescriptor table;
  table.name = resolved.canonical_name.empty()
                   ? std::string(fallback_name)
                   : resolved.canonical_name;
  if (const auto dot = table.name.rfind('.'); dot != std::string::npos) {
    table.name = table.name.substr(dot + 1);
  }
  table.name = UnquoteIdentifier(table.name);
  table.descriptor_uuid = projected.descriptor_uuid;
  table.relation_uuid = projected.relation_uuid;
  table.descriptor_generation = projected.descriptor_generation;
  table.validated_resource_epoch = projected.validated_resource_epoch;
  table.persisted_relation_projection = true;

  std::vector<std::pair<std::uint32_t, FirebirdColumnDescriptor>> ordered;
  ordered.reserve(projected.columns.size());
  for (const auto& projected_column : projected.columns) {
    ordered.emplace_back(
        projected_column.ordinal,
        FirebirdColumnFromPersistedRelationProjection(projected_column,
                                                      table.name));
  }
  std::stable_sort(ordered.begin(), ordered.end(),
                   [](const auto& left, const auto& right) {
                     return left.first < right.first;
                   });
  table.columns.reserve(ordered.size());
  for (auto& [ordinal, column] : ordered) {
    (void)ordinal;
    table.columns.push_back(std::move(column));
  }
  return table;
}

std::optional<FirebirdDomainDescriptor> FindFirebirdDomain(
    const FirebirdBinarySessionState& state,
    std::string_view name) {
  const std::string wanted = ToUpperAscii(name);
  for (const auto& [domain_name, domain] : state.domains) {
    if (ToUpperAscii(domain_name) == wanted) return domain;
  }
  return std::nullopt;
}

std::size_t FindFirebirdWord(std::string_view upper_text,
                             std::string_view word,
                             std::size_t start = 0);

std::string StripFirebirdLineComment(std::string_view text) {
  const std::string value(text);
  const auto comment = value.find("--");
  return TrimAscii(comment == std::string::npos ? value : value.substr(0, comment));
}

std::optional<std::string> ExtractFirebirdDefaultValue(std::string_view definition) {
  const std::string text = StripFirebirdLineComment(definition);
  const std::string upper = ToUpperAscii(text);
  const auto pos = upper.find(" DEFAULT ");
  if (pos == std::string::npos) return std::nullopt;
  std::size_t value_pos = pos + 9;
  while (value_pos < text.size() && std::isspace(static_cast<unsigned char>(text[value_pos]))) {
    ++value_pos;
  }
  const std::string tail = text.substr(value_pos);
  const std::string tail_upper = ToUpperAscii(tail);
  std::size_t end = tail.size();
  for (const auto marker : {" NOT NULL", " NULL", " CONSTRAINT", " CHECK", " COLLATE"}) {
    const auto marker_pos = tail_upper.find(marker);
    if (marker_pos != std::string::npos) end = std::min(end, marker_pos);
  }
  auto value = TrimAscii(tail.substr(0, end));
  if (!value.empty()) return value;
  return std::nullopt;
}

std::optional<std::string> FirebirdIdentifierAfterPhrase(std::string_view text,
                                                         std::string_view phrase) {
  const std::string sql = StripFirebirdLineComment(text);
  const std::string upper = ToUpperAscii(sql);
  const auto pos = upper.find(ToUpperAscii(phrase));
  if (pos == std::string::npos) return std::nullopt;
  std::size_t value_pos = pos + phrase.size();
  std::string raw;
  if (!ReadSqlIdentifierToken(sql, &value_pos, &raw)) return std::nullopt;
  const auto value = UpperIdentifier(UnquoteIdentifier(raw));
  if (value.empty()) return std::nullopt;
  return value;
}

std::uint32_t FirebirdCharacterSetMaxBytes(std::string_view charset_name) {
  const std::string name = UpperIdentifier(TrimAscii(charset_name));
  if (name == "UTF8") return 4;
  if (name == "UNICODE_FSS") return 3;
  if (name == "GBK") return 2;
  return 1;
}

std::string FirebirdDefaultCollationNameForCharset(
    const FirebirdBinarySessionState& state,
    std::string_view charset_name) {
  const std::string charset = UpperIdentifier(TrimAscii(charset_name));
  if (charset.empty()) return {};
  if (const auto found = state.default_collation_by_charset.find(charset);
      found != state.default_collation_by_charset.end() && !found->second.empty()) {
    return UpperIdentifier(found->second);
  }
  if (charset == "UTF8") return "UNICODE";
  if (charset == "WIN1251") return "WIN1251";
  if (charset == "WIN1252") return "WIN1252";
  if (charset == "WIN1257") return "WIN1257";
  if (charset == "NONE") return "NONE";
  return charset;
}

void ApplyFirebirdTextMetadataDefaults(const FirebirdBinarySessionState& state,
                                       std::string_view definition,
                                       FirebirdColumnDescriptor* column) {
  if (column == nullptr || column->sql_type != 452) return;
  if (auto charset = FirebirdIdentifierAfterPhrase(definition, "CHARACTER SET")) {
    column->character_set = *charset;
  } else if (column->character_set.empty() &&
             !state.current_attachment_charset.empty()) {
    column->character_set = UpperIdentifier(state.current_attachment_charset);
  }
  if (auto collation = FirebirdIdentifierAfterPhrase(definition, "COLLATE")) {
    column->collation = *collation;
  }
  if (!column->character_set.empty() && column->collation.empty()) {
    column->collation =
        FirebirdDefaultCollationNameForCharset(state, column->character_set);
  }
  const std::uint32_t max_bytes =
      FirebirdCharacterSetMaxBytes(column->character_set);
  if (!column->character_set.empty()) {
    column->subtype = FirebirdCharacterSetId(column->character_set);
  }
  if (column->character_length == 0) {
    column->character_length = std::max<std::uint32_t>(1, column->length);
  }
  column->length = std::max<std::uint32_t>(1, column->character_length * max_bytes);
}

std::optional<std::string> ExtractFirebirdCheckSource(std::string_view definition) {
  const std::string text = StripFirebirdLineComment(
      StripTerminatingSemicolon(definition));
  const std::string upper = ToUpperAscii(text);
  const auto check_pos = FindFirebirdWord(upper, "CHECK");
  if (check_pos == std::string::npos) return std::nullopt;
  const auto open = text.find('(', check_pos);
  if (open == std::string::npos) {
    const auto collate_pos = FindFirebirdWord(upper, "COLLATE", check_pos);
    const auto end = collate_pos == std::string::npos ? text.size()
                                                      : collate_pos;
    auto source = TrimAscii(text.substr(check_pos, end - check_pos));
    if (source.empty()) return std::nullopt;
    return source;
  }
  int depth = 0;
  for (std::size_t cursor = open; cursor < text.size(); ++cursor) {
    if (text[cursor] == '(') {
      ++depth;
    } else if (text[cursor] == ')' && --depth == 0) {
      auto source = TrimAscii(text.substr(check_pos, cursor - check_pos + 1));
      if (source.empty()) return std::nullopt;
      return source;
    }
  }
  return std::nullopt;
}

std::optional<std::string> ExtractFirebirdComputedExpression(std::string_view definition) {
  const std::string text = StripFirebirdLineComment(definition);
  const std::string upper = ToUpperAscii(text);
  const auto computed = upper.find("COMPUTED BY");
  if (computed == std::string::npos) return std::nullopt;
  const auto open = text.find('(', computed);
  if (open == std::string::npos) return std::nullopt;
  int depth = 0;
  for (std::size_t pos = open; pos < text.size(); ++pos) {
    if (text[pos] == '(') {
      ++depth;
    } else if (text[pos] == ')') {
      --depth;
      if (depth == 0 && pos > open) {
        return TrimAscii(text.substr(open + 1, pos - open - 1));
      }
    }
  }
  return std::nullopt;
}

std::string FirebirdColumnBaseDefinitionForCanonical(
    const FirebirdBinarySessionState& state,
    std::string_view definition,
    std::string_view relation,
    FirebirdColumnDescriptor* descriptor) {
  const std::string stripped = StripFirebirdLineComment(definition);
  std::size_t pos = 0;
  std::string raw_name;
  if (!ReadSqlIdentifierToken(stripped, &pos, &raw_name)) return {};
  SkipSqlWhitespace(stripped, &pos);
  const std::string name = UnquoteIdentifier(raw_name);
  std::string tail = TrimAscii(stripped.substr(pos));
  const auto computed = ExtractFirebirdComputedExpression(stripped);
  if (computed) {
    const std::string computed_upper = ToUpperAscii(*computed);
    std::string computed_type = "DOUBLE PRECISION";
    const bool simple_integral_expression =
        computed_upper.find('.') == std::string::npos &&
        computed_upper.find('/') == std::string::npos &&
        std::all_of(computed_upper.begin(), computed_upper.end(), [](char ch) {
          const unsigned char uch = static_cast<unsigned char>(ch);
          return std::isalnum(uch) || ch == '_' || ch == '$' ||
                 std::isspace(uch) || ch == '+' || ch == '-' || ch == '*' ||
                 ch == '(' || ch == ')';
        });
    if (computed_upper.find(" AS TIME") != std::string::npos) {
      computed_type = "TIME";
    } else if (computed_upper.find(" AS TIMESTAMP") != std::string::npos) {
      computed_type = "TIMESTAMP";
    } else if (computed_upper.find(" AS DATE") != std::string::npos) {
      computed_type = "DATE";
    } else if (computed_upper.find("EXTRACT(") != std::string::npos) {
      computed_type = "INTEGER";
    } else if (simple_integral_expression) {
      computed_type = "INTEGER";
    }
    FirebirdColumnDescriptor column = ColumnDescriptorFromDefinition(
        std::string(name) + " " + computed_type, relation);
    column.computed_expression = *computed;
    *descriptor = column;
    return RenderCanonicalIdentifier(name) + " " + FirebirdColumnCanonicalType(column);
  }
  std::size_t type_end = tail.size();
  const std::string tail_upper = ToUpperAscii(tail);
  for (const auto marker : {" DEFAULT ", " NOT NULL", " NULL", " PRIMARY KEY",
                            " UNIQUE", " CONSTRAINT ", " CHECK ", " COLLATE "}) {
    const auto marker_pos = tail_upper.find(marker);
    if (marker_pos != std::string::npos) type_end = std::min(type_end, marker_pos);
  }
  std::string type_definition = TrimAscii(tail.substr(0, type_end));
  FirebirdColumnDescriptor column;
  if (auto domain = FindFirebirdDomain(state, type_definition)) {
    column = domain->column;
    column.name = name;
    column.relation = std::string(relation);
    column.domain_name = domain->name;
    type_definition = FirebirdColumnCanonicalType(column);
    if (column.default_value.empty() && domain->column.default_value.empty()) {
      column.default_value = ExtractFirebirdDefaultValue(stripped).value_or("");
    }
  } else {
    column = ColumnDescriptorFromDefinition(std::string(name) + " " + type_definition, relation);
    column.default_value = ExtractFirebirdDefaultValue(stripped).value_or("");
  }
  ApplyFirebirdTextMetadataDefaults(state, stripped, &column);
  const bool inline_primary_key = tail_upper.find("PRIMARY KEY") != std::string::npos;
  const bool inline_unique = !inline_primary_key && tail_upper.find("UNIQUE") != std::string::npos;
  column.primary_key = inline_primary_key;
  column.unique_key = inline_primary_key || inline_unique;
  if (inline_primary_key || tail_upper.find("NOT NULL") != std::string::npos) {
    column.nullable = false;
  } else if (tail_upper.find(" NULL") != std::string::npos) {
    column.nullable = true;
  }
  *descriptor = column;
  std::string rendered = RenderCanonicalIdentifier(name) + " " + FirebirdColumnCanonicalType(column);
  if (!column.nullable) rendered += " NOT NULL";
  if (inline_primary_key) {
    rendered += " PRIMARY KEY";
  } else if (inline_unique) {
    rendered += " UNIQUE";
  }
  return rendered;
}

std::vector<std::string> FirebirdIdentifierListFromFirstParentheses(
    std::string_view text) {
  const std::string value(text);
  const auto open = value.find('(');
  if (open == std::string::npos) return {};
  int depth = 0;
  std::size_t close = std::string::npos;
  for (std::size_t cursor = open; cursor < value.size(); ++cursor) {
    if (value[cursor] == '(') {
      ++depth;
    } else if (value[cursor] == ')') {
      --depth;
      if (depth == 0) {
        close = cursor;
        break;
      }
    }
  }
  if (close == std::string::npos || close <= open) return {};
  std::vector<std::string> names;
  for (const auto& item : SplitTopLevelComma(value.substr(open + 1, close - open - 1))) {
    const auto name = UnquoteIdentifier(TrimAscii(item));
    if (!name.empty()) names.push_back(name);
  }
  return names;
}

bool IsFirebirdTableConstraintDefinition(std::string_view definition_upper) {
  const std::string upper = TrimAscii(std::string(definition_upper));
  return upper.starts_with("CONSTRAINT") || upper.starts_with("PRIMARY ") ||
         upper.starts_with("PRIMARY(") || upper.starts_with("FOREIGN ") ||
         upper.starts_with("FOREIGN(") || upper.starts_with("UNIQUE ") ||
         upper.starts_with("UNIQUE(") || upper.starts_with("CHECK ") ||
         upper.starts_with("CHECK(");
}

std::optional<std::string> ExtractBalancedParenthesizedText(std::string_view text,
                                                            std::size_t open) {
  if (open >= text.size() || text[open] != '(') return std::nullopt;
  int depth = 0;
  for (std::size_t cursor = open; cursor < text.size(); ++cursor) {
    if (text[cursor] == '(') {
      ++depth;
    } else if (text[cursor] == ')') {
      --depth;
      if (depth == 0 && cursor > open) {
        return TrimAscii(text.substr(open + 1, cursor - open - 1));
      }
    }
  }
  return std::nullopt;
}

std::optional<std::string> FirebirdExpressionIndexKeyEnvelope(std::string_view expression) {
  const std::string expr = TrimAscii(expression);
  const std::string upper = ToUpperAscii(expr);
  std::size_t arithmetic_pos = 0;
  std::string left_operand;
  if (ReadSqlIdentifierToken(expr, &arithmetic_pos, &left_operand)) {
    SkipSqlWhitespace(expr, &arithmetic_pos);
    if (arithmetic_pos < expr.size() && expr[arithmetic_pos] == '+') {
      ++arithmetic_pos;
      SkipSqlWhitespace(expr, &arithmetic_pos);
      std::string right_operand;
      if (ReadSqlIdentifierToken(expr, &arithmetic_pos, &right_operand)) {
        SkipSqlWhitespace(expr, &arithmetic_pos);
        if (arithmetic_pos == expr.size()) {
          return "sum:" + UnquoteIdentifier(left_operand) + ":" +
                 UnquoteIdentifier(right_operand);
        }
      }
    }
  }
  for (const auto* function_name : {"UPPER", "LOWER", "LENGTH"}) {
    const std::string prefix = std::string(function_name) + "(";
    if (!upper.starts_with(prefix) || expr.empty() || expr.back() != ')') continue;
    std::size_t argument_pos = prefix.size();
    std::string raw_argument;
    if (!ReadSqlIdentifierToken(expr, &argument_pos, &raw_argument)) return std::nullopt;
    SkipSqlWhitespace(expr, &argument_pos);
    if (argument_pos >= expr.size() || expr[argument_pos] != ')') return std::nullopt;
    std::string lower_function = LowerIdentifier(function_name);
    return lower_function + ":" + UnquoteIdentifier(raw_argument);
  }
  return std::nullopt;
}

std::optional<FirebirdIndexDescriptor> ParseFirebirdComputedIndex(std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("CREATE ")) return std::nullopt;
  std::size_t pos = std::string("CREATE").size();
  bool unique = false;
  while (true) {
    std::string modifier;
    const std::size_t before_modifier = pos;
    if (!ReadSqlIdentifierToken(sql, &pos, &modifier)) return std::nullopt;
    const std::string modifier_upper = ToUpperAscii(modifier);
    if (modifier_upper == "UNIQUE") {
      unique = true;
      continue;
    }
    if (modifier_upper == "ASC" || modifier_upper == "DESC" || modifier_upper == "ASCENDING" ||
        modifier_upper == "DESCENDING") {
      continue;
    }
    pos = before_modifier;
    break;
  }
  std::string index_keyword;
  if (!ReadSqlIdentifierToken(sql, &pos, &index_keyword) ||
      ToUpperAscii(index_keyword) != "INDEX") {
    return std::nullopt;
  }
  std::string raw_index_name;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_index_name)) return std::nullopt;
  std::string on_keyword;
  if (!ReadSqlIdentifierToken(sql, &pos, &on_keyword) || ToUpperAscii(on_keyword) != "ON") {
    return std::nullopt;
  }
  std::string raw_relation_name;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_relation_name)) return std::nullopt;
  const auto computed_pos = upper.find("COMPUTED", pos);
  if (computed_pos == std::string::npos) return std::nullopt;
  std::size_t expression_pos = computed_pos + std::string("COMPUTED").size();
  SkipSqlWhitespace(sql, &expression_pos);
  std::size_t by_probe = expression_pos;
  std::string maybe_by;
  if (ReadSqlIdentifierToken(sql, &by_probe, &maybe_by) &&
      ToUpperAscii(maybe_by) == "BY") {
    expression_pos = by_probe;
  }
  const auto open = sql.find('(', expression_pos);
  if (open == std::string::npos) return std::nullopt;
  const auto expression = ExtractBalancedParenthesizedText(sql, open);
  if (!expression) return std::nullopt;
  FirebirdIndexDescriptor descriptor;
  descriptor.name = UnquoteIdentifier(raw_index_name);
  descriptor.relation = UnquoteIdentifier(raw_relation_name);
  descriptor.expression = *expression;
  if (const auto key_envelope = FirebirdExpressionIndexKeyEnvelope(*expression)) {
    descriptor.key_envelope = *key_envelope;
  } else {
    descriptor.key_envelope = "expression:" + TrimAscii(*expression);
  }
  descriptor.unique = unique;
  if (descriptor.name.empty() || descriptor.relation.empty()) return std::nullopt;
  return descriptor;
}

std::string FirebirdComputedIndexToCanonical(const FirebirdIndexDescriptor& index) {
  std::string function_name;
  std::string argument;
  const auto separator = index.key_envelope.find(':');
  if (separator != std::string::npos) {
    function_name = ToUpperAscii(index.key_envelope.substr(0, separator));
    argument = index.key_envelope.substr(separator + 1);
  }
  if (function_name.empty() || argument.empty()) {
    return {};
  }
  if (function_name == "SUM") {
    const auto argument_separator = argument.find(':');
    if (argument_separator == std::string::npos) return {};
    return "CREATE " + std::string(index.unique ? "UNIQUE " : "") +
           "INDEX " + index.name + " ON " + index.relation + " (" +
           argument.substr(0, argument_separator) + " + " +
	           argument.substr(argument_separator + 1) + ")";
  }
  if (function_name != "UPPER" && function_name != "LOWER" &&
      function_name != "LENGTH") {
    return {};
  }
  std::string out = "CREATE ";
  if (index.unique) out += "UNIQUE ";
  out += "INDEX " + index.name + " ON " + index.relation + " (" +
         function_name + "(" + argument + "))";
  return out;
}

std::string NormalizeFirebirdSimpleCreateIndexForCanonical(std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("CREATE ")) return {};
  if (upper.find("COMPUTED") != std::string::npos) return {};
  std::size_t pos = std::string("CREATE").size();
  bool unique = false;
  while (true) {
    std::string modifier;
    const std::size_t before_modifier = pos;
    if (!ReadSqlIdentifierToken(sql, &pos, &modifier)) return {};
    const std::string modifier_upper = ToUpperAscii(modifier);
    if (modifier_upper == "UNIQUE") {
      unique = true;
      continue;
    }
    if (modifier_upper == "ASC" || modifier_upper == "DESC" ||
        modifier_upper == "ASCENDING" || modifier_upper == "DESCENDING") {
      continue;
    }
    pos = before_modifier;
    break;
  }
  std::string index_keyword;
  if (!ReadSqlIdentifierToken(sql, &pos, &index_keyword) ||
      ToUpperAscii(index_keyword) != "INDEX") {
    return {};
  }
  std::string raw_index_name;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_index_name)) return {};
  std::string on_keyword;
  if (!ReadSqlIdentifierToken(sql, &pos, &on_keyword) || ToUpperAscii(on_keyword) != "ON") {
    return {};
  }
  std::string raw_relation_name;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_relation_name)) return {};
  SkipSqlWhitespace(sql, &pos);
  if (pos >= sql.size() || sql[pos] != '(') return {};
  const auto key_text = ExtractBalancedParenthesizedText(sql, pos);
  if (!key_text) return {};
  std::vector<std::string> key_items;
  for (const auto& raw_key : SplitTopLevelComma(*key_text)) {
    const std::string key = TrimAscii(raw_key);
    if (key.empty()) return {};
    std::size_t key_pos = 0;
    std::string raw_column;
    if (!ReadSqlIdentifierToken(key, &key_pos, &raw_column)) return {};
    std::string normalized = UnquoteIdentifier(raw_column);
    SkipSqlWhitespace(key, &key_pos);
    if (key_pos < key.size()) {
      const std::string suffix = ToUpperAscii(TrimAscii(key.substr(key_pos)));
      if (suffix == "DESC" || suffix == "DESCENDING") {
        normalized += " DESC";
      } else if (suffix == "ASC" || suffix == "ASCENDING") {
        normalized += " ASC";
      } else {
        return {};
      }
    }
    key_items.push_back(std::move(normalized));
  }
  if (key_items.empty()) return {};
  std::string out = "CREATE ";
  if (unique) out += "UNIQUE ";
  out += "INDEX " + UnquoteIdentifier(raw_index_name) + " ON " +
         UnquoteIdentifier(raw_relation_name) + " (";
  for (std::size_t i = 0; i < key_items.size(); ++i) {
    if (i != 0) out += ", ";
    out += key_items[i];
  }
  out += ")";
  return out;
}

std::optional<FirebirdIndexDescriptor> ParseFirebirdSimpleCreateIndexDescriptor(
    std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("CREATE ") || upper.find("COMPUTED") != std::string::npos) {
    return std::nullopt;
  }
  std::size_t pos = std::string("CREATE").size();
  bool unique = false;
  for (;;) {
    std::string modifier;
    const std::size_t before = pos;
    if (!ReadSqlIdentifierToken(sql, &pos, &modifier)) return std::nullopt;
    const std::string modifier_upper = ToUpperAscii(modifier);
    if (modifier_upper == "UNIQUE") {
      unique = true;
      continue;
    }
    if (modifier_upper == "ASC" || modifier_upper == "ASCENDING" ||
        modifier_upper == "DESC" || modifier_upper == "DESCENDING") {
      continue;
    }
    pos = before;
    break;
  }
  std::string index_keyword;
  if (!ReadSqlIdentifierToken(sql, &pos, &index_keyword) ||
      ToUpperAscii(index_keyword) != "INDEX") {
    return std::nullopt;
  }
  std::string raw_index_name;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_index_name)) return std::nullopt;
  std::string on_keyword;
  if (!ReadSqlIdentifierToken(sql, &pos, &on_keyword) || ToUpperAscii(on_keyword) != "ON") {
    return std::nullopt;
  }
  std::string raw_relation_name;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_relation_name)) return std::nullopt;
  SkipSqlWhitespace(sql, &pos);
  if (pos >= sql.size() || sql[pos] != '(') return std::nullopt;
  const auto key_text = ExtractBalancedParenthesizedText(sql, pos);
  if (!key_text) return std::nullopt;
  FirebirdIndexDescriptor descriptor;
  descriptor.name = UnquoteIdentifier(raw_index_name);
  descriptor.relation = UnquoteIdentifier(raw_relation_name);
  descriptor.key_envelope = ToUpperAscii(TrimAscii(*key_text));
  descriptor.unique = unique;
  if (descriptor.name.empty() || descriptor.relation.empty()) return std::nullopt;
  return descriptor;
}

struct FirebirdDuplicateIndexFieldIssue {
  std::string index_name;
  std::string field_name;
};

std::optional<FirebirdDuplicateIndexFieldIssue> AnalyzeFirebirdDuplicateIndexField(
    std::string_view sql_text) {
  const auto descriptor = ParseFirebirdSimpleCreateIndexDescriptor(sql_text);
  if (!descriptor) return std::nullopt;
  std::set<std::string> seen;
  for (const auto& raw_key : SplitTopLevelComma(descriptor->key_envelope)) {
    std::string key_text = UnquoteIdentifier(TrimAscii(raw_key));
    if (const auto dot = key_text.rfind('.'); dot != std::string::npos) {
      key_text = key_text.substr(dot + 1);
    }
    const std::string key = UpperIdentifier(key_text);
    if (key.empty()) continue;
    if (!seen.insert(key).second) {
      return FirebirdDuplicateIndexFieldIssue{
          UpperIdentifier(descriptor->name), key};
    }
  }
  return std::nullopt;
}

void RecordFirebirdCreateIndex(FirebirdBinarySessionState* state,
                               std::string_view sql_text) {
  auto descriptor = ParseFirebirdComputedIndex(sql_text);
  if (!descriptor) descriptor = ParseFirebirdSimpleCreateIndexDescriptor(sql_text);
  if (!descriptor || descriptor->name.empty()) return;
  state->indexes[descriptor->name] = std::move(*descriptor);
  PersistFirebirdMetadataOverlay(*state);
}

std::vector<std::string> FirebirdIndexKeyColumns(
    const FirebirdIndexDescriptor& index) {
  std::vector<std::string> columns;
  const std::string expression = ToUpperAscii(TrimAscii(index.expression));
  if (!expression.empty() && expression != "PRIMARY KEY" &&
      expression != "UNIQUE") {
    return columns;
  }
  for (const auto& raw_key : SplitTopLevelComma(index.key_envelope)) {
    const std::string column =
        UpperIdentifier(FirebirdLeafIdentifier(TrimAscii(raw_key)));
    if (!column.empty()) columns.push_back(column);
  }
  return columns;
}

std::optional<FirebirdIndexDescriptor> FirebirdIndexByName(
    const FirebirdBinarySessionState& state,
    std::string_view index_name) {
  const std::string wanted = UpperIdentifier(index_name);
  for (const auto& [name, index] : state.indexes) {
    if (UpperIdentifier(name) == wanted ||
        UpperIdentifier(index.name) == wanted) {
      return index;
    }
  }
  return std::nullopt;
}

std::optional<std::string> FirebirdDropIndexName(std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!TrimAscii(upper).starts_with("DROP INDEX")) return std::nullopt;
  std::size_t pos = upper.find("INDEX");
  if (pos == std::string::npos) return std::nullopt;
  pos += std::string("INDEX").size();
  std::string raw_index;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_index)) return std::nullopt;
  const std::string index_name = FirebirdLeafIdentifier(raw_index);
  if (index_name.empty()) return std::nullopt;
  return index_name;
}

std::optional<FirebirdPipelineResult> ExecuteFirebirdOverlayDropIndex(
    FirebirdBinarySessionState* state,
    std::string_view sql_text) {
  if (state == nullptr) return std::nullopt;
  const auto index_name = FirebirdDropIndexName(sql_text);
  if (!index_name) return std::nullopt;
  const std::string wanted = UpperIdentifier(*index_name);
  bool touched_overlay = false;
  bool erased = false;
  for (auto it = state->indexes.begin(); it != state->indexes.end();) {
    const bool index_matches =
        UpperIdentifier(it->first) == wanted ||
        UpperIdentifier(it->second.name) == wanted;
    if (!index_matches) {
      ++it;
      continue;
    }
    touched_overlay = FirebirdIsOverlayOnlyTable(*state, it->second.relation) ||
                      !TrimAscii(it->second.expression).empty();
    if (!touched_overlay) return std::nullopt;
    it = state->indexes.erase(it);
    erased = true;
  }
  if (!touched_overlay) {
    for (const auto& table_key : state->overlay_only_tables) {
      if (!table_key.empty() && wanted.find(table_key) != std::string::npos) {
        touched_overlay = true;
        break;
      }
    }
  }
  if (!touched_overlay) return std::nullopt;
  if (erased) PersistFirebirdMetadataOverlay(*state);
  TraceFirebirdWorker("firebird_overlay.drop_index index=" + wanted +
                      " erased=" + std::string(erased ? "true" : "false"));
  return FirebirdOverlayAcceptedResult(0);
}

std::optional<FirebirdPipelineResult> ExecuteFirebirdOverlayAlterIndex(
    FirebirdBinarySessionState* state,
    std::string_view sql_text) {
  if (state == nullptr) return std::nullopt;
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(TrimAscii(sql));
  if (!upper.starts_with("ALTER INDEX ")) return std::nullopt;

  std::size_t pos = upper.find("INDEX");
  if (pos == std::string::npos) return std::nullopt;
  pos += std::string("INDEX").size();
  std::string raw_index;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_index)) return std::nullopt;
  const std::string wanted = UpperIdentifier(FirebirdLeafIdentifier(raw_index));
  if (wanted.empty()) return std::nullopt;

  const bool activate = upper.find(" ACTIVE") != std::string::npos;
  const bool deactivate = upper.find(" INACTIVE") != std::string::npos;
  if (!activate && !deactivate) return std::nullopt;

  for (auto& [name, index] : state->indexes) {
    if (UpperIdentifier(name) != wanted && UpperIdentifier(index.name) != wanted) {
      continue;
    }
    index.active = activate;
    TraceFirebirdWorker("firebird_overlay.alter_index name=" +
                        EscapeJsonLocal(index.name) + " active=" +
                        std::string(index.active ? "true" : "false"));
    return FirebirdOverlayAcceptedResult(0);
  }
  return std::nullopt;
}

struct FirebirdRelationConstraintDescriptor {
  std::string constraint_type;
  std::string constraint_name;
  std::string index_name;
  std::string relation_name;
  std::vector<std::string> key_columns;
};

std::vector<FirebirdRelationConstraintDescriptor> FirebirdRelationConstraints(
    const FirebirdBinarySessionState& state,
    std::optional<std::string_view> relation_filter = std::nullopt) {
  std::vector<FirebirdRelationConstraintDescriptor> rows;
  const std::string wanted =
      relation_filter ? UpperIdentifier(*relation_filter) : std::string{};
  for (const auto& [name, index] : state.indexes) {
    (void)name;
    if (!FirebirdCatalogObjectScopeMatches(state, "index", index.name)) continue;
    if (!wanted.empty() && UpperIdentifier(index.relation) != wanted) continue;
    const std::string expression = ToUpperAscii(TrimAscii(index.expression));
    if (expression != "PRIMARY KEY" && expression != "UNIQUE") continue;
    auto columns = FirebirdIndexKeyColumns(index);
    if (columns.empty()) continue;
    FirebirdRelationConstraintDescriptor row;
    row.constraint_type = expression == "UNIQUE" ? "UNIQUE" : "PRIMARY KEY";
    row.constraint_name = UpperIdentifier(index.name);
    row.index_name = UpperIdentifier(index.name);
    row.relation_name = UpperIdentifier(index.relation);
    row.key_columns = std::move(columns);
    rows.push_back(std::move(row));
  }
  std::sort(rows.begin(), rows.end(),
            [](const FirebirdRelationConstraintDescriptor& left,
               const FirebirdRelationConstraintDescriptor& right) {
              if (left.constraint_type != right.constraint_type) {
                return left.constraint_type < right.constraint_type;
              }
              return left.constraint_name < right.constraint_name;
            });
  return rows;
}

void RecordFirebirdAlterTableConstraintIndex(FirebirdBinarySessionState* state,
                                             std::string_view sql_text) {
  if (state == nullptr) return;
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("ALTER TABLE") ||
      upper.find("PRIMARY KEY") == std::string::npos) {
    return;
  }
  std::size_t table_pos = std::string("ALTER TABLE").size();
  std::string raw_table;
  if (!ReadSqlIdentifierToken(sql, &table_pos, &raw_table)) return;
  const std::string relation = UnquoteIdentifier(raw_table);
  std::size_t action_pos = table_pos;
  SkipSqlWhitespace(sql, &action_pos);
  std::string action;
  if (!ReadSqlIdentifierToken(sql, &action_pos, &action) ||
      ToUpperAscii(action) != "ADD") {
    return;
  }
  SkipSqlWhitespace(sql, &action_pos);
  std::string constraint_name;
  std::size_t constraint_pos = action_pos;
  std::string maybe_constraint;
  if (ReadSqlIdentifierToken(sql, &constraint_pos, &maybe_constraint) &&
      ToUpperAscii(maybe_constraint) == "CONSTRAINT") {
    SkipSqlWhitespace(sql, &constraint_pos);
    std::string raw_constraint;
    if (ReadSqlIdentifierToken(sql, &constraint_pos, &raw_constraint)) {
      constraint_name = UnquoteIdentifier(raw_constraint);
    }
  }
  const auto using_index_pos = upper.find("USING INDEX", table_pos);
  std::string index_name;
  if (using_index_pos != std::string::npos) {
    std::size_t index_pos = using_index_pos + std::string("USING INDEX").size();
    std::string raw_index;
    if (ReadSqlIdentifierToken(sql, &index_pos, &raw_index)) {
      index_name = UnquoteIdentifier(raw_index);
    }
  }
  if (constraint_name.empty()) constraint_name = index_name;
  if (constraint_name.empty()) {
    constraint_name = "INTEG_" + std::to_string(state->next_implicit_constraint_id++);
  }
  FirebirdIndexDescriptor index;
  index.name = constraint_name;
  index.relation = relation;
  index.unique = true;
  index.expression = "PRIMARY KEY";
  if (const auto key_open = upper.find('(', upper.find("PRIMARY KEY", table_pos));
      key_open != std::string::npos) {
    const auto key_close = sql.find(')', key_open);
    if (key_close != std::string::npos && key_close > key_open) {
      index.key_envelope = UpperIdentifier(TrimAscii(sql.substr(
          key_open + 1, key_close - key_open - 1)));
    }
  }
  if (!index.name.empty() && !index.relation.empty()) {
    auto table = FirebirdTableByName(*state, index.relation);
    if (table) {
      std::vector<std::string> key_columns;
      for (const auto& raw_key : SplitTopLevelComma(index.key_envelope)) {
        const std::string key =
            UpperIdentifier(FirebirdLeafIdentifier(TrimAscii(raw_key)));
        if (!key.empty()) key_columns.push_back(key);
      }
      for (auto& column : table->columns) {
        for (const auto& key : key_columns) {
          if (UpperIdentifier(column.name) == key) {
            column.primary_key = true;
            column.unique_key = key_columns.size() == 1;
            column.nullable = false;
          }
        }
      }
      if (!key_columns.empty()) {
        table->unique_column_sets.push_back(key_columns);
      }
      state->tables[table->name] = std::move(*table);
    }
    state->indexes[index.name] = std::move(index);
    PersistFirebirdMetadataOverlay(*state);
  }
}

void RecordFirebirdCreateDomain(FirebirdBinarySessionState* state,
                                std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  const auto domain_pos = upper.find("DOMAIN");
  if (domain_pos == std::string::npos) return;
  std::size_t name_pos = domain_pos + std::string("DOMAIN").size();
  std::string raw_name;
  if (!ReadSqlIdentifierToken(sql, &name_pos, &raw_name)) return;
  std::size_t type_pos = name_pos;
  SkipSqlWhitespace(sql, &type_pos);
  std::size_t as_probe = type_pos;
  std::string maybe_as;
  if (ReadSqlIdentifierToken(sql, &as_probe, &maybe_as) &&
      ToUpperAscii(maybe_as) == "AS") {
    type_pos = as_probe;
    SkipSqlWhitespace(sql, &type_pos);
  }
  if (type_pos >= sql.size()) return;
  FirebirdDomainDescriptor domain;
  domain.name = UnquoteIdentifier(raw_name);
  domain.type_definition = TrimAscii(sql.substr(type_pos));
  domain.column = ColumnDescriptorFromDefinition(domain.name + " " + domain.type_definition,
                                                 domain.name);
  ApplyFirebirdTextMetadataDefaults(*state, domain.type_definition, &domain.column);
  domain.column.default_value = ExtractFirebirdDefaultValue(domain.type_definition).value_or("");
  domain.owner = UpperIdentifier(state->current_firebird_user);
  if (!domain.name.empty()) {
    state->domains[domain.name] = std::move(domain);
    PersistFirebirdMetadataOverlay(*state);
  }
}

void RecordFirebirdDropDomain(FirebirdBinarySessionState* state,
                              std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  const auto domain_pos = upper.find("DOMAIN");
  if (domain_pos == std::string::npos) return;
  std::size_t name_pos = domain_pos + std::string("DOMAIN").size();
  std::string raw_name;
  if (!ReadSqlIdentifierToken(sql, &name_pos, &raw_name)) return;
  const std::string domain_name = UnquoteIdentifier(raw_name);
  for (auto it = state->domains.begin(); it != state->domains.end(); ++it) {
    if (UpperIdentifier(it->first) == UpperIdentifier(domain_name)) {
      state->domains.erase(it);
      PersistFirebirdMetadataOverlay(*state);
      return;
    }
  }
}

void RecordFirebirdCreateException(FirebirdBinarySessionState* state,
                                   std::string_view sql_text) {
  if (state == nullptr) return;
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  const auto exception_pos = upper.find("EXCEPTION");
  if (exception_pos == std::string::npos) return;
  std::size_t name_pos = exception_pos + std::string("EXCEPTION").size();
  std::string raw_name;
  if (!ReadSqlIdentifierToken(sql, &name_pos, &raw_name)) return;
  SkipSqlWhitespace(sql, &name_pos);
  std::string message;
  if (name_pos < sql.size()) {
    std::size_t literal_pos = name_pos;
    if (auto literal = ReadSqlStringLiteralAt(sql, &literal_pos)) {
      message = *literal;
    }
  }
  FirebirdExceptionDescriptor exception;
  exception.name = UnquoteIdentifier(raw_name);
  exception.message = message;
  exception.owner = UpperIdentifier(state->current_firebird_user);
  if (!exception.name.empty()) {
    state->exceptions[exception.name] = std::move(exception);
    TraceFirebirdWorker("firebird_metadata.create_exception=" +
                        EscapeJsonLocal(raw_name));
    PersistFirebirdMetadataOverlay(*state);
  }
}

void RecordFirebirdDropException(FirebirdBinarySessionState* state,
                                 std::string_view sql_text) {
  if (state == nullptr) return;
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  const auto exception_pos = upper.find("EXCEPTION");
  if (exception_pos == std::string::npos) return;
  std::size_t name_pos = exception_pos + std::string("EXCEPTION").size();
  std::string raw_name;
  if (!ReadSqlIdentifierToken(sql, &name_pos, &raw_name)) return;
  const std::string exception_name = UnquoteIdentifier(raw_name);
  for (auto it = state->exceptions.begin(); it != state->exceptions.end(); ++it) {
    if (UpperIdentifier(it->first) == UpperIdentifier(exception_name) ||
        UpperIdentifier(it->second.name) == UpperIdentifier(exception_name)) {
      state->exceptions.erase(it);
      PersistFirebirdMetadataOverlay(*state);
      return;
    }
  }
}

void RecordFirebirdAlterDomain(FirebirdBinarySessionState* state,
                               std::string_view sql_text) {
  if (state == nullptr) return;
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("ALTER DOMAIN")) return;
  std::size_t name_pos = std::string("ALTER DOMAIN").size();
  std::string raw_name;
  if (!ReadSqlIdentifierToken(sql, &name_pos, &raw_name)) return;
  const std::string domain_name = UnquoteIdentifier(raw_name);
  SkipSqlWhitespace(sql, &name_pos);
  std::string action;
  if (!ReadSqlIdentifierToken(sql, &name_pos, &action) ||
      ToUpperAscii(action) != "TYPE") {
    return;
  }
  const std::string type_definition = TrimAscii(sql.substr(name_pos));
  if (type_definition.empty()) return;
  for (auto& [name, domain] : state->domains) {
    if (UpperIdentifier(name) != UpperIdentifier(domain_name) &&
        UpperIdentifier(domain.name) != UpperIdentifier(domain_name)) {
      continue;
    }
    domain.type_definition = type_definition;
    domain.column = ColumnDescriptorFromDefinition(domain.name + " " +
                                                      domain.type_definition,
                                                  domain.name);
    ApplyFirebirdTextMetadataDefaults(*state, domain.type_definition, &domain.column);
    domain.column.default_value =
        ExtractFirebirdDefaultValue(domain.type_definition).value_or("");
    if (domain.owner.empty()) {
      domain.owner = UpperIdentifier(state->current_firebird_user);
    }
    PersistFirebirdMetadataOverlay(*state);
    return;
  }
  FirebirdDomainDescriptor domain;
  domain.name = domain_name;
  domain.type_definition = type_definition;
  domain.column = ColumnDescriptorFromDefinition(domain.name + " " +
                                                    domain.type_definition,
                                                domain.name);
  ApplyFirebirdTextMetadataDefaults(*state, domain.type_definition, &domain.column);
  domain.owner = UpperIdentifier(state->current_firebird_user);
  if (!domain.name.empty()) {
    state->domains[domain.name] = std::move(domain);
    PersistFirebirdMetadataOverlay(*state);
  }
}

