std::string NormalizeFirebirdCreateTableForCanonical(
    const FirebirdBinarySessionState& state,
    std::string_view sql_text,
    FirebirdTableDescriptor* table_out = nullptr) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  const auto table_pos = upper.find("TABLE");
  const auto open = sql.find('(', table_pos == std::string::npos ? 0 : table_pos);
  const auto close = sql.rfind(')');
  if (table_pos == std::string::npos || open == std::string::npos ||
      close == std::string::npos || close <= open) {
    return std::string(sql);
  }
  const auto name_text = TrimAscii(sql.substr(table_pos + 5, open - (table_pos + 5)));
  FirebirdTableDescriptor table;
  table.name = UnquoteIdentifier(name_text);
  std::vector<std::string> physical_columns;
  std::vector<std::string> primary_key_columns;
  std::vector<std::vector<std::string>> unique_column_sets;
  for (const auto& raw_definition : SplitTopLevelComma(sql.substr(open + 1, close - open - 1))) {
    const auto definition = StripFirebirdLineComment(raw_definition);
    if (definition.empty()) continue;
    const auto def_upper = ToUpperAscii(definition);
    if (IsFirebirdTableConstraintDefinition(def_upper)) {
      if (def_upper.find("PRIMARY KEY") != std::string::npos) {
        auto names = FirebirdIdentifierListFromFirstParentheses(definition);
        primary_key_columns.insert(primary_key_columns.end(), names.begin(), names.end());
      } else if (def_upper.find("UNIQUE") != std::string::npos) {
        auto names = FirebirdIdentifierListFromFirstParentheses(definition);
        if (!names.empty()) unique_column_sets.push_back(std::move(names));
      }
      continue;
    }
    FirebirdColumnDescriptor column;
    auto physical = FirebirdColumnBaseDefinitionForCanonical(state, definition, table.name, &column);
    if (physical.empty() || column.name.empty()) continue;
    table.columns.push_back(std::move(column));
    physical_columns.push_back(std::move(physical));
  }
  for (const auto& pk_column : primary_key_columns) {
    const auto wanted = UpperIdentifier(pk_column);
    for (std::size_t i = 0; i < table.columns.size(); ++i) {
      auto& column = table.columns[i];
      if (UpperIdentifier(column.name) == wanted) {
        column.primary_key = true;
        column.unique_key = primary_key_columns.size() == 1;
        column.nullable = false;
        if (ToUpperAscii(physical_columns[i]).find(" NOT NULL") == std::string::npos) {
          physical_columns[i] += " NOT NULL";
        }
        if (primary_key_columns.size() == 1 &&
            ToUpperAscii(physical_columns[i]).find(" PRIMARY KEY") == std::string::npos) {
          physical_columns[i] += " PRIMARY KEY";
        }
      }
    }
  }
  if (!primary_key_columns.empty()) unique_column_sets.push_back(primary_key_columns);
  for (const auto& unique_columns : unique_column_sets) {
    if (unique_columns.size() == 1) {
      const std::string wanted = UpperIdentifier(unique_columns.front());
      for (auto& column : table.columns) {
        if (UpperIdentifier(column.name) == wanted) column.unique_key = true;
      }
    }
  }
  table.unique_column_sets = unique_column_sets;
  if (table_out != nullptr) *table_out = table;
  if (table.name.empty() || physical_columns.empty()) return std::string(sql);
  std::string out = "CREATE TABLE " + RenderCanonicalIdentifier(table.name) + " (";
  for (std::size_t i = 0; i < physical_columns.size(); ++i) {
    if (i != 0) out += ", ";
    out += physical_columns[i];
  }
  out += ")";
  return out;
}

void RecordFirebirdCreatorTablePrivileges(FirebirdBinarySessionState* state,
                                          std::string_view table_name);
bool FirebirdIdentifierVectorsEqual(const std::vector<std::string>& lhs,
                                    const std::vector<std::string>& rhs);

std::string JoinFirebirdIdentifierList(const std::vector<std::string>& names) {
  std::string out;
  for (const auto& name : names) {
    if (name.empty()) continue;
    if (!out.empty()) out += ",";
    out += name;
  }
  return out;
}

void RecordFirebirdCreateTable(FirebirdBinarySessionState* state, std::string_view sql_text) {
  FirebirdTableDescriptor table;
  (void)NormalizeFirebirdCreateTableForCanonical(*state, sql_text, &table);
  if (!table.name.empty()) {
    const std::string table_name = table.name;
    std::vector<std::string> primary_key_columns;
    for (const auto& column : table.columns) {
      if (!column.nullable) {
        ++state->next_implicit_constraint_id;
      }
      if (column.primary_key) {
        primary_key_columns.push_back(UpperIdentifier(column.name));
      }
    }
    if (!primary_key_columns.empty()) {
      FirebirdIndexDescriptor index;
      index.name = "INTEG_" + std::to_string(state->next_implicit_constraint_id++);
      index.relation = table.name;
      index.unique = true;
      index.expression = "PRIMARY KEY";
      index.key_envelope = JoinFirebirdIdentifierList(primary_key_columns);
      state->indexes[index.name] = std::move(index);
    }
    for (const auto& unique_columns : table.unique_column_sets) {
      if (unique_columns.empty()) continue;
      if (!primary_key_columns.empty() &&
          FirebirdIdentifierVectorsEqual(primary_key_columns, unique_columns)) {
        continue;
      }
      std::vector<std::string> key_columns;
      for (const auto& column : unique_columns) {
        const std::string key = UpperIdentifier(FirebirdLeafIdentifier(column));
        if (!key.empty()) key_columns.push_back(key);
      }
      if (key_columns.empty()) continue;
      FirebirdIndexDescriptor index;
      index.name = "INTEG_" + std::to_string(state->next_implicit_constraint_id++);
      index.relation = table.name;
      index.unique = true;
      index.expression = "UNIQUE";
      index.key_envelope = JoinFirebirdIdentifierList(key_columns);
      state->indexes[index.name] = std::move(index);
    }
    state->tables[table.name] = std::move(table);
    RecordFirebirdCreatorTablePrivileges(state, table_name);
    PersistFirebirdMetadataOverlay(*state);
  }
}

void MarkFirebirdMetadataOnlyTableOverlay(FirebirdBinarySessionState* state,
                                          std::string_view sql_text) {
  if (state == nullptr) return;
  FirebirdTableDescriptor table;
  (void)NormalizeFirebirdCreateTableForCanonical(*state, sql_text, &table);
  if (table.name.empty()) return;
  const std::string table_key = FirebirdOverlayTableKey(table.name);
  state->overlay_only_tables.insert(table_key);
  const std::string upper = ToUpperAscii(TrimAscii(StripTerminatingSemicolon(sql_text)));
  if (upper.starts_with("RECREATE TABLE")) {
    state->overlay_rows[table_key].clear();
  }
  TraceFirebirdWorker("firebird_overlay.metadata_table table=" + table_key);
  PersistFirebirdMetadataOverlay(*state);
}

void RecordFirebirdCreateProcedure(FirebirdBinarySessionState* state,
                                   std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  std::size_t procedure_pos = upper.find("PROCEDURE");
  if (procedure_pos == std::string::npos) return;
  std::size_t name_pos = procedure_pos + std::string("PROCEDURE").size();
  std::string raw_name;
  if (!ReadSqlIdentifierToken(sql, &name_pos, &raw_name)) return;
  FirebirdProcedureDescriptor procedure;
  procedure.name = UnquoteIdentifier(raw_name);
  std::size_t signature_pos = name_pos;
  while (signature_pos < sql.size() &&
         std::isspace(static_cast<unsigned char>(sql[signature_pos]))) {
    ++signature_pos;
  }
  if (signature_pos < sql.size() && sql[signature_pos] == '(') {
    int depth = 0;
    std::size_t close = std::string::npos;
    for (std::size_t cursor = signature_pos; cursor < sql.size(); ++cursor) {
      if (sql[cursor] == '(') {
        ++depth;
      } else if (sql[cursor] == ')') {
        --depth;
        if (depth == 0) {
          close = cursor;
          break;
        }
      }
    }
    if (close != std::string::npos && close > signature_pos) {
      for (const auto& definition :
           SplitTopLevelComma(sql.substr(signature_pos + 1, close - signature_pos - 1))) {
        auto column = ColumnDescriptorFromDefinition(definition, procedure.name);
        if (!column.name.empty()) procedure.parameters.push_back(std::move(column));
      }
    }
  }
  procedure.body = sql;
  const auto returns_pos = upper.find("RETURNS", name_pos);
  if (returns_pos != std::string::npos) {
    const auto open = sql.find('(', returns_pos);
    if (open != std::string::npos) {
      int depth = 0;
      std::size_t close = std::string::npos;
      for (std::size_t cursor = open; cursor < sql.size(); ++cursor) {
        if (sql[cursor] == '(') {
          ++depth;
        } else if (sql[cursor] == ')') {
          --depth;
          if (depth == 0) {
            close = cursor;
            break;
          }
        }
      }
      if (close != std::string::npos && close > open) {
        for (const auto& definition : SplitTopLevelComma(sql.substr(open + 1, close - open - 1))) {
          auto column = ColumnDescriptorFromDefinition(definition, procedure.name);
          if (!column.name.empty()) procedure.returns.push_back(std::move(column));
        }
      }
    }
  }
  if (!procedure.name.empty()) {
    const std::string procedure_source = procedure.body;
    const std::string procedure_blr = FirebirdProcedureBlrPrinterText(procedure);
    state->procedures[procedure.name] = std::move(procedure);
    if (!procedure_source.empty()) {
      RegisterFirebirdBlobValue(state, "RDB$PROCEDURES",
                                "RDB$PROCEDURE_SOURCE",
                                procedure_source);
    }
    if (!procedure_blr.empty()) {
      RegisterFirebirdBlobValue(state, "RDB$PROCEDURES",
                                "RDB$PROCEDURE_BLR",
                                procedure_blr);
    }
    PersistFirebirdMetadataOverlay(*state);
  }
}

void RecordFirebirdDropProcedure(FirebirdBinarySessionState* state,
                                 std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  const auto procedure_pos = upper.find("PROCEDURE");
  if (procedure_pos == std::string::npos) return;
  std::size_t name_pos = procedure_pos + std::string("PROCEDURE").size();
  std::string raw_name;
  if (!ReadSqlIdentifierToken(sql, &name_pos, &raw_name)) return;
  const auto procedure_name = UnquoteIdentifier(raw_name);
  if (procedure_name.empty()) return;
  state->procedures.erase(procedure_name);
  PersistFirebirdMetadataOverlay(*state);
}

std::optional<std::string> FirebirdDropTableName(std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!TrimAscii(upper).starts_with("DROP TABLE")) return std::nullopt;
  std::size_t pos = upper.find("TABLE");
  if (pos == std::string::npos) return std::nullopt;
  pos += std::string("TABLE").size();
  SkipSqlWhitespace(sql, &pos);
  std::size_t probe = pos;
  std::string maybe_if;
  if (ReadSqlIdentifierToken(sql, &probe, &maybe_if) &&
      ToUpperAscii(maybe_if) == "IF") {
    SkipSqlWhitespace(sql, &probe);
    std::string maybe_exists;
    if (ReadSqlIdentifierToken(sql, &probe, &maybe_exists) &&
        ToUpperAscii(maybe_exists) == "EXISTS") {
      pos = probe;
    }
  }
  std::string raw_table;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_table)) return std::nullopt;
  const std::string table_name = FirebirdLeafIdentifier(raw_table);
  if (table_name.empty()) return std::nullopt;
  return table_name;
}

bool RemoveFirebirdTableMetadata(FirebirdBinarySessionState* state,
                                 std::string_view table_name) {
  if (state == nullptr) return false;
  const std::string wanted = UpperIdentifier(FirebirdLeafIdentifier(table_name));
  if (wanted.empty()) return false;
  bool changed = false;

  for (auto it = state->tables.begin(); it != state->tables.end();) {
    if (UpperIdentifier(FirebirdLeafIdentifier(it->first)) == wanted ||
        UpperIdentifier(FirebirdLeafIdentifier(it->second.name)) == wanted) {
      it = state->tables.erase(it);
      changed = true;
    } else {
      ++it;
    }
  }

  for (auto it = state->indexes.begin(); it != state->indexes.end();) {
    if (UpperIdentifier(FirebirdLeafIdentifier(it->second.relation)) == wanted) {
      it = state->indexes.erase(it);
      changed = true;
    } else {
      ++it;
    }
  }

  for (auto it = state->triggers.begin(); it != state->triggers.end();) {
    if (UpperIdentifier(FirebirdLeafIdentifier(it->second.relation)) == wanted) {
      it = state->triggers.erase(it);
      changed = true;
    } else {
      ++it;
    }
  }

  const std::string overlay_key = FirebirdOverlayTableKey(wanted);
  if (state->overlay_only_tables.erase(overlay_key) != 0) changed = true;
  if (state->overlay_rows.erase(overlay_key) != 0) changed = true;

  for (auto it = state->blob_id_by_cell_key.begin();
       it != state->blob_id_by_cell_key.end();) {
    if (UpperIdentifier(FirebirdLeafIdentifier(it->first)) == wanted ||
        ToUpperAscii(it->first).starts_with(wanted + ".")) {
      state->blob_text_by_id.erase(it->second);
      it = state->blob_id_by_cell_key.erase(it);
      changed = true;
    } else {
      ++it;
    }
  }

  return changed;
}

void RecordFirebirdDropTable(FirebirdBinarySessionState* state,
                             std::string_view sql_text) {
  const auto table_name = FirebirdDropTableName(sql_text);
  if (!table_name) return;
  if (RemoveFirebirdTableMetadata(state, *table_name)) {
    PersistFirebirdMetadataOverlay(*state);
    TraceFirebirdWorker("firebird_metadata.drop_table=" +
                        EscapeJsonLocal(UpperIdentifier(*table_name)));
  }
}

void RecordFirebirdCreateSequence(FirebirdBinarySessionState* state,
                                  std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  const auto keyword = upper.find("SEQUENCE") != std::string::npos ? "SEQUENCE" : "GENERATOR";
  const auto keyword_pos = upper.find(keyword);
  if (keyword_pos == std::string::npos) return;
  std::size_t name_pos = keyword_pos + std::string(keyword).size();
  std::string raw_name;
  if (!ReadSqlIdentifierToken(sql, &name_pos, &raw_name)) return;
  const auto sequence_name = UnquoteIdentifier(raw_name);
  if (sequence_name.empty()) return;
  const auto exists = std::find_if(state->sequences.begin(), state->sequences.end(),
                                   [&](const std::string& value) {
                                     return ToUpperAscii(value) == ToUpperAscii(sequence_name);
                                   }) != state->sequences.end();
  std::int64_t initial_value = 0;
  if (const auto start_pos = FindFirebirdWord(upper, "START WITH");
      start_pos != std::string::npos) {
    std::size_t value_pos = start_pos + std::string("START WITH").size();
    SkipSqlWhitespace(sql, &value_pos);
    const auto end = sql.find_first_of(" \t\r\n,", value_pos);
    initial_value = ParseSignedText(
                        sql.substr(value_pos, end == std::string::npos
                                                  ? std::string::npos
                                                  : end - value_pos))
                        .value_or(0);
  }
  if (!exists) {
    state->sequences.push_back(sequence_name);
  }
  state->sequence_values[UpperIdentifier(sequence_name)] = initial_value;
  PersistFirebirdMetadataOverlay(*state);
}

void RecordFirebirdSetGenerator(FirebirdBinarySessionState* state,
                                std::string_view sql_text) {
  if (state == nullptr) return;
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!TrimAscii(upper).starts_with("SET GENERATOR ")) return;
  const auto generator_pos = upper.find("GENERATOR");
  if (generator_pos == std::string::npos) return;
  std::size_t name_pos = generator_pos + std::string("GENERATOR").size();
  std::string raw_name;
  if (!ReadSqlIdentifierToken(sql, &name_pos, &raw_name)) return;
  const std::string sequence_name = UnquoteIdentifier(raw_name);
  const auto to_pos = FindFirebirdWord(upper, "TO", name_pos);
  if (to_pos == std::string::npos || sequence_name.empty()) return;
  std::size_t value_pos = to_pos + std::string("TO").size();
  SkipSqlWhitespace(sql, &value_pos);
  const auto end = sql.find_first_of(" \t\r\n,", value_pos);
  const std::int64_t value =
      ParseSignedText(sql.substr(value_pos, end == std::string::npos
                                            ? std::string::npos
                                            : end - value_pos))
          .value_or(0);
  const auto exists = std::find_if(state->sequences.begin(), state->sequences.end(),
                                   [&](const std::string& existing) {
                                     return ToUpperAscii(existing) ==
                                            ToUpperAscii(sequence_name);
                                   }) != state->sequences.end();
  if (!exists) state->sequences.push_back(sequence_name);
  state->sequence_values[UpperIdentifier(sequence_name)] = value;
  PersistFirebirdMetadataOverlay(*state);
}

std::optional<FirebirdPipelineResult>
ExecuteFirebirdCommentOnGenerator(FirebirdBinarySessionState* state,
                                  std::string_view sql_text) {
  if (state == nullptr) return std::nullopt;
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!TrimAscii(upper).starts_with("COMMENT ON GENERATOR ")) return std::nullopt;
  const auto generator_pos = FindFirebirdWord(upper, "GENERATOR");
  if (generator_pos == std::string::npos) return std::nullopt;
  std::size_t name_pos = generator_pos + std::string("GENERATOR").size();
  std::string raw_name;
  if (!ReadSqlIdentifierToken(sql, &name_pos, &raw_name)) return std::nullopt;
  const std::string generator_name = UnquoteIdentifier(raw_name);
  const auto is_pos = FindFirebirdWord(upper, "IS", name_pos);
  if (is_pos == std::string::npos || generator_name.empty()) return std::nullopt;
  std::size_t value_pos = is_pos + std::string("IS").size();
  SkipSqlWhitespace(sql, &value_pos);
  const std::string value_upper = ToUpperAscii(TrimAscii(sql.substr(value_pos)));
  const std::string key = UpperIdentifier(generator_name);
  const auto exists = std::find_if(state->sequences.begin(), state->sequences.end(),
                                   [&](const std::string& sequence) {
                                     return UpperIdentifier(sequence) == key;
                                   }) != state->sequences.end();
  if (!exists) state->sequences.push_back(generator_name);
  if (value_upper == "NULL") {
    state->generator_comments.erase(key);
  } else if (auto literal = ReadSqlStringLiteralAt(sql, &value_pos)) {
    state->generator_comments[key] = *literal;
  } else {
    return std::nullopt;
  }
  TraceFirebirdWorker("firebird.comment_on_generator name=" + key);
  return FirebirdOverlayAcceptedResult(0);
}

struct FirebirdGenIdCall {
  std::string sequence_name;
  std::int64_t delta{0};
};

std::optional<FirebirdGenIdCall> FirebirdGenIdSelectCall(std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(TrimAscii(sql));
  if (!upper.starts_with("SELECT GEN_ID(") ||
      upper.find(" FROM RDB$DATABASE") == std::string::npos) {
    return std::nullopt;
  }
  const auto gen_id_pos = upper.find("GEN_ID");
  if (gen_id_pos == std::string::npos) return std::nullopt;
  auto open = sql.find('(', gen_id_pos);
  if (open == std::string::npos) return std::nullopt;
  std::size_t name_pos = open + 1;
  std::string raw_name;
  if (!ReadSqlIdentifierToken(sql, &name_pos, &raw_name)) return std::nullopt;
  SkipSqlWhitespace(sql, &name_pos);
  if (name_pos >= sql.size() || sql[name_pos] != ',') return std::nullopt;
  ++name_pos;
  SkipSqlWhitespace(sql, &name_pos);
  const auto close = sql.find(')', name_pos);
  if (close == std::string::npos) return std::nullopt;
  FirebirdGenIdCall call;
  call.sequence_name = UnquoteIdentifier(raw_name);
  call.delta = ParseSignedText(sql.substr(name_pos, close - name_pos)).value_or(0);
  if (call.sequence_name.empty()) return std::nullopt;
  return call;
}

std::int64_t FirebirdApplyGenId(FirebirdBinarySessionState* state,
                                const FirebirdGenIdCall& call) {
  if (state == nullptr) return 0;
  const std::string key = UpperIdentifier(call.sequence_name);
  auto found = state->sequence_values.find(key);
  if (found == state->sequence_values.end()) {
    found = state->sequence_values.emplace(key, 0).first;
  }
  if (call.delta != 0) {
    found->second += call.delta;
    PersistFirebirdMetadataOverlay(*state);
  }
  return found->second;
}

void RecordFirebirdCreateCollation(FirebirdBinarySessionState* state,
                                   std::string_view sql_text) {
  if (state == nullptr) return;
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!TrimAscii(upper).starts_with("CREATE COLLATION")) return;

  const auto collation_pos = upper.find("COLLATION");
  if (collation_pos == std::string::npos) return;
  std::size_t name_pos = collation_pos + std::string("COLLATION").size();
  std::string raw_name;
  if (!ReadSqlIdentifierToken(sql, &name_pos, &raw_name)) return;

  const auto for_pos = FindFirebirdWord(upper, "FOR", name_pos);
  if (for_pos == std::string::npos) return;
  std::size_t charset_pos = for_pos + std::string("FOR").size();
  std::string raw_charset;
  if (!ReadSqlIdentifierToken(sql, &charset_pos, &raw_charset)) return;

  FirebirdCollationDescriptor descriptor;
  descriptor.name = UnquoteIdentifier(raw_name);
  descriptor.character_set = UpperIdentifier(UnquoteIdentifier(raw_charset));
  if (descriptor.name.empty() || descriptor.character_set.empty()) return;

  const auto from_pos = FindFirebirdWord(upper, "FROM", charset_pos);
  if (from_pos != std::string::npos) {
    std::size_t base_pos = from_pos + std::string("FROM").size();
    std::string raw_base;
    if (ReadSqlIdentifierToken(sql, &base_pos, &raw_base)) {
      descriptor.base_collation = UnquoteIdentifier(raw_base);
    }
  }

  if (upper.find("NO PAD") != std::string::npos) descriptor.attributes &= ~1;
  if (upper.find("PAD SPACE") != std::string::npos) descriptor.attributes |= 1;
  if (upper.find("CASE INSENSITIVE") != std::string::npos) descriptor.attributes |= 2;
  if (upper.find("CASE SENSITIVE") != std::string::npos) descriptor.attributes &= ~2;
  if (upper.find("ACCENT INSENSITIVE") != std::string::npos) descriptor.attributes |= 4;
  if (upper.find("ACCENT SENSITIVE") != std::string::npos) descriptor.attributes &= ~4;

  const auto quote = sql.find('\'', charset_pos);
  if (quote != std::string::npos) {
    std::string literal;
    for (std::size_t index = quote + 1; index < sql.size(); ++index) {
      if (sql[index] == '\'' && index + 1 < sql.size() && sql[index + 1] == '\'') {
        literal.push_back('\'');
        ++index;
        continue;
      }
      if (sql[index] == '\'') break;
      literal.push_back(sql[index]);
    }
    descriptor.specific_attributes = literal;
  }

  state->collations[UpperIdentifier(FirebirdLeafIdentifier(descriptor.name))] =
      std::move(descriptor);
  PersistFirebirdMetadataOverlay(*state);
}

void RecordFirebirdDropCollation(FirebirdBinarySessionState* state,
                                 std::string_view sql_text) {
  if (state == nullptr) return;
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!TrimAscii(upper).starts_with("DROP COLLATION")) return;
  const auto collation_pos = upper.find("COLLATION");
  if (collation_pos == std::string::npos) return;
  std::size_t name_pos = collation_pos + std::string("COLLATION").size();
  std::string raw_name;
  if (!ReadSqlIdentifierToken(sql, &name_pos, &raw_name)) return;
  const std::string name = UpperIdentifier(FirebirdLeafIdentifier(raw_name));
  if (!name.empty()) {
    state->collations.erase(name);
    PersistFirebirdMetadataOverlay(*state);
  }
}

void RecordFirebirdAlterCharacterSetDefaultCollation(
    FirebirdBinarySessionState* state,
    std::string_view sql_text) {
  if (state == nullptr) return;
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!TrimAscii(upper).starts_with("ALTER CHARACTER SET")) return;
  const auto set_pos = FindFirebirdWord(upper, "SET");
  const auto default_pos = FindFirebirdWord(upper, "DEFAULT", set_pos == std::string::npos ? 0 : set_pos);
  const auto collation_pos = FindFirebirdWord(upper, "COLLATION", default_pos == std::string::npos ? 0 : default_pos);
  if (set_pos == std::string::npos || default_pos == std::string::npos ||
      collation_pos == std::string::npos) {
    return;
  }
  std::size_t charset_pos = std::string("ALTER CHARACTER SET").size();
  std::string raw_charset;
  if (!ReadSqlIdentifierToken(sql, &charset_pos, &raw_charset)) return;
  std::size_t value_pos = collation_pos + std::string("COLLATION").size();
  std::string raw_collation;
  if (!ReadSqlIdentifierToken(sql, &value_pos, &raw_collation)) return;
  const std::string charset = UpperIdentifier(UnquoteIdentifier(raw_charset));
  const std::string collation = UpperIdentifier(UnquoteIdentifier(raw_collation));
  if (charset.empty() || collation.empty()) return;
  state->default_collation_by_charset[charset] = collation;
  PersistFirebirdMetadataOverlay(*state);
}

void RecordFirebirdCreateRole(FirebirdBinarySessionState* state,
                              std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!TrimAscii(upper).starts_with("CREATE ROLE")) return;
  std::size_t name_pos = upper.find("ROLE");
  if (name_pos == std::string::npos) return;
  name_pos += std::string("ROLE").size();
  std::string raw_name;
  if (!ReadSqlIdentifierToken(sql, &name_pos, &raw_name)) return;
  const auto role_name = UnquoteIdentifier(raw_name);
  if (role_name.empty()) return;
  const auto exists = std::find_if(state->roles.begin(), state->roles.end(),
                                   [&](const FirebirdSecurityRole& value) {
                                     return value.active &&
                                            FirebirdSecurityScopeMatches(
                                                value.scope,
                                                state->emulation_security_scope) &&
                                            ToUpperAscii(value.name) ==
                                                ToUpperAscii(role_name);
                                   }) != state->roles.end();
  if (!exists) {
    state->roles.push_back(FirebirdScopedRole(*state, role_name));
    PersistFirebirdMetadataOverlay(*state);
  }
}

void RecordFirebirdDropRole(FirebirdBinarySessionState* state,
                            std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!TrimAscii(upper).starts_with("DROP ROLE")) return;
  std::size_t name_pos = upper.find("ROLE");
  if (name_pos == std::string::npos) return;
  name_pos += std::string("ROLE").size();
  std::string raw_name;
  if (!ReadSqlIdentifierToken(sql, &name_pos, &raw_name)) return;
  const auto role_name = ToUpperAscii(UnquoteIdentifier(raw_name));
  state->roles.erase(
      std::remove_if(state->roles.begin(), state->roles.end(),
                     [&](const FirebirdSecurityRole& value) {
                       return FirebirdSecurityScopeMatches(
                                  value.scope,
                                  state->emulation_security_scope) &&
                              ToUpperAscii(value.name) == role_name;
                     }),
      state->roles.end());
  PersistFirebirdMetadataOverlay(*state);
}

bool IsFirebirdCreateTriggerStatement(std::string_view sql_text) {
  const std::string upper = ToUpperAscii(TrimAscii(StripTerminatingSemicolon(sql_text)));
  return upper.starts_with("CREATE TRIGGER") ||
         upper.starts_with("CREATE OR ALTER TRIGGER") ||
         upper.starts_with("RECREATE TRIGGER") ||
         upper.starts_with("ALTER TRIGGER");
}

std::size_t FindFirebirdWord(std::string_view upper_text,
                             std::string_view word,
                             std::size_t start) {
  std::size_t pos = start;
  while (pos < upper_text.size()) {
    const auto found = upper_text.find(word, pos);
    if (found == std::string_view::npos) return std::string::npos;
    const bool left_ok =
        found == 0 ||
        !(std::isalnum(static_cast<unsigned char>(upper_text[found - 1])) ||
          upper_text[found - 1] == '_');
    const std::size_t after = found + word.size();
    const bool right_ok =
        after >= upper_text.size() ||
        !(std::isalnum(static_cast<unsigned char>(upper_text[after])) ||
          upper_text[after] == '_');
    if (left_ok && right_ok) return found;
    pos = found + word.size();
  }
  return std::string::npos;
}

std::optional<std::vector<FirebirdColumnDescriptor>> FirebirdExecuteBlockReturnColumns(
    std::string_view sql_text,
    const FirebirdBinarySessionState* state = nullptr) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!TrimAscii(upper).starts_with("EXECUTE BLOCK")) return std::nullopt;
  const auto returns_pos = FindFirebirdWord(upper, "RETURNS");
  if (returns_pos == std::string::npos) return std::nullopt;
  std::size_t open = returns_pos + std::string("RETURNS").size();
  while (open < sql.size() && std::isspace(static_cast<unsigned char>(sql[open]))) {
    ++open;
  }
  if (open >= sql.size() || sql[open] != '(') return std::nullopt;
  std::size_t close = std::string::npos;
  int depth = 0;
  bool in_string = false;
  bool in_quoted_identifier = false;
  for (std::size_t pos = open; pos < sql.size(); ++pos) {
    const char ch = sql[pos];
    if (ch == '\'' && !in_quoted_identifier) {
      if (in_string && pos + 1 < sql.size() && sql[pos + 1] == '\'') {
        ++pos;
        continue;
      }
      in_string = !in_string;
      continue;
    }
    if (ch == '"' && !in_string) {
      in_quoted_identifier = !in_quoted_identifier;
      continue;
    }
    if (in_string || in_quoted_identifier) continue;
    if (ch == '(') {
      ++depth;
    } else if (ch == ')') {
      --depth;
      if (depth == 0) {
        close = pos;
        break;
      }
    }
  }
  if (close == std::string::npos || close <= open + 1) return std::nullopt;
  std::vector<FirebirdColumnDescriptor> columns;
  for (const auto& definition : SplitTopLevelComma(sql.substr(open + 1, close - open - 1))) {
    auto column = ColumnDescriptorFromDefinition(definition, "EXECUTE_BLOCK");
    if (column.name.empty()) return std::nullopt;
    const std::string definition_upper = ToUpperAscii(definition);
    const auto type_of_pos = definition_upper.find("TYPE OF COLUMN");
    if (state != nullptr && type_of_pos == std::string::npos) {
      std::size_t definition_pos = 0;
      std::string raw_output_name;
      std::string raw_type_name;
      if (ReadSqlIdentifierToken(definition, &definition_pos, &raw_output_name)) {
        SkipSqlWhitespace(definition, &definition_pos);
        if (ReadSqlIdentifierToken(definition, &definition_pos, &raw_type_name)) {
          if (const auto domain = FindFirebirdDomain(
                  *state, FirebirdLeafIdentifier(raw_type_name))) {
            column = domain->column;
            column.name = UnquoteIdentifier(raw_output_name);
            column.alias.clear();
            column.relation = "EXECUTE_BLOCK";
            column.domain_name = domain->name;
          }
        }
      }
    } else if (state != nullptr && type_of_pos != std::string::npos) {
      std::size_t ref_pos = type_of_pos + std::string("TYPE OF COLUMN").size();
      std::string raw_table;
      std::string raw_column;
      SkipSqlWhitespace(definition, &ref_pos);
      if (ReadSqlIdentifierToken(definition, &ref_pos, &raw_table)) {
        SkipSqlWhitespace(definition, &ref_pos);
        if (ref_pos < definition.size() && definition[ref_pos] == '.') {
          ++ref_pos;
          (void)ReadSqlIdentifierToken(definition, &ref_pos, &raw_column);
        }
      }
      if (raw_column.empty()) {
        const auto dot = raw_table.rfind('.');
        if (dot != std::string::npos && dot + 1 < raw_table.size()) {
          raw_column = raw_table.substr(dot + 1);
          raw_table = raw_table.substr(0, dot);
        }
      }
      if (!raw_table.empty() && !raw_column.empty()) {
        if (const auto table = FirebirdTableByName(*state, raw_table)) {
          for (const auto& source_column : table->columns) {
            if (UpperIdentifier(source_column.name) == UpperIdentifier(raw_column)) {
              const std::string output_name = column.name;
              column = source_column;
              column.name = output_name;
              column.alias.clear();
              column.relation = "EXECUTE_BLOCK";
              break;
            }
          }
        }
      }
    }
    if (state != nullptr) {
      ApplyFirebirdTextMetadataDefaults(*state, definition, &column);
    }
    columns.push_back(std::move(column));
  }
  if (columns.empty()) return std::nullopt;
  return columns;
}

void RecordFirebirdCreateTrigger(FirebirdBinarySessionState* state,
                                 std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  std::size_t trigger_pos = upper.find("TRIGGER");
  if (trigger_pos == std::string::npos) return;
  std::size_t name_pos = trigger_pos + std::string("TRIGGER").size();
  std::string raw_name;
  if (!ReadSqlIdentifierToken(sql, &name_pos, &raw_name)) return;
  const auto for_pos = upper.find(" FOR ", name_pos);
  if (for_pos == std::string::npos) return;
  std::size_t relation_pos = for_pos + 5;
  std::string raw_relation;
  if (!ReadSqlIdentifierToken(sql, &relation_pos, &raw_relation)) return;
  FirebirdTriggerDescriptor trigger;
  trigger.name = UnquoteIdentifier(raw_name);
  trigger.relation = UnquoteIdentifier(raw_relation);
  trigger.active = upper.find(" INACTIVE") == std::string::npos;
  if (upper.find(" AFTER ") != std::string::npos) {
    trigger.timing = "AFTER";
  } else if (upper.find(" BEFORE ") != std::string::npos) {
    trigger.timing = "BEFORE";
  }
  std::vector<std::string> events;
  if (upper.find(" INSERT") != std::string::npos) events.push_back("INSERT");
  if (upper.find(" UPDATE") != std::string::npos) events.push_back("UPDATE");
  if (upper.find(" DELETE") != std::string::npos) events.push_back("DELETE");
  for (std::size_t index = 0; index < events.size(); ++index) {
    if (index != 0) trigger.event += ",";
    trigger.event += events[index];
  }
  const auto as_pos = FindFirebirdWord(upper, "AS", relation_pos);
  if (as_pos != std::string::npos) {
    std::size_t body_pos = as_pos + 2;
    while (body_pos < sql.size() &&
           std::isspace(static_cast<unsigned char>(sql[body_pos]))) {
      ++body_pos;
    }
    trigger.body = TrimAscii(sql.substr(body_pos));
  }
  if (!trigger.name.empty()) {
    state->triggers[trigger.name] = std::move(trigger);
    PersistFirebirdMetadataOverlay(*state);
  }
}

void RecordFirebirdGrant(FirebirdBinarySessionState* state, std::string_view sql_text) {
  std::string normalized = TrimAscii(StripTerminatingSemicolon(sql_text));
  if (normalized.empty()) return;
  std::string output;
  output.reserve(normalized.size());
  bool in_space = false;
  bool in_quoted_identifier = false;
  for (const char ch : normalized) {
    if (ch == '"') {
      output.push_back(ch);
      in_quoted_identifier = !in_quoted_identifier;
      in_space = false;
    } else if (std::isspace(static_cast<unsigned char>(ch)) && !in_quoted_identifier) {
      if (!in_space) output.push_back(' ');
      in_space = true;
    } else {
      output.push_back(in_quoted_identifier
                           ? ch
                           : static_cast<char>(std::toupper(
                                 static_cast<unsigned char>(ch))));
      in_space = false;
    }
  }
  if (output.empty()) return;
  if (output.find(" GRANTED BY ") == std::string::npos) {
    const std::string grantor =
        UpperIdentifier(state->current_firebird_user.empty()
                            ? "SYSDBA"
                            : state->current_firebird_user);
    const auto with_grant_pos = output.find(" WITH GRANT OPTION");
    if (with_grant_pos == std::string::npos) {
      output += " GRANTED BY " + grantor;
    } else {
      output.insert(with_grant_pos, " GRANTED BY " + grantor);
    }
  }
  const auto exists = std::find_if(
                          state->grant_lines.begin(), state->grant_lines.end(),
                          [&](const FirebirdSecurityGrantLine& value) {
                            return FirebirdSecurityScopeMatches(
                                       value.scope,
                                       state->emulation_security_scope) &&
                                   value.statement == output;
                          }) != state->grant_lines.end();
  if (!exists) {
    state->grant_lines.push_back(FirebirdScopedGrantLine(*state, std::move(output)));
    PersistFirebirdMetadataOverlay(*state);
  }
}

std::string FirebirdLeafIdentifier(std::string_view text);

void RecordFirebirdCreatorTablePrivileges(FirebirdBinarySessionState* state,
                                          std::string_view table_name) {
  if (state == nullptr || table_name.empty()) return;
  const std::string table = UpperIdentifier(FirebirdLeafIdentifier(table_name));
  const std::string user =
      UpperIdentifier(state->current_firebird_user.empty()
                          ? "ALICE"
                          : state->current_firebird_user);
  if (table.empty() || user.empty()) return;
  for (const auto privilege : {"DELETE", "INSERT", "REFERENCES", "SELECT", "UPDATE"}) {
    RecordFirebirdGrant(
        state,
        "GRANT " + std::string(privilege) + " ON TABLE " + table +
            " TO USER " + user + " GRANTED BY " + user +
            " WITH GRANT OPTION");
  }
}

std::optional<std::string> FirebirdRoleGrantName(std::string_view sql_text) {
  const std::string sql = TrimAscii(StripTerminatingSemicolon(sql_text));
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("GRANT ")) return std::nullopt;
  if (FindFirebirdWord(upper, "ON") != std::string::npos) return std::nullopt;
  std::size_t pos = std::string("GRANT").size();
  std::string raw_role;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_role)) return std::nullopt;
  std::string role = UnquoteIdentifier(raw_role);
  if (const auto dot = role.rfind('.'); dot != std::string::npos) {
    role = role.substr(dot + 1);
  }
  if (role.empty()) return std::nullopt;
  const std::string role_upper = ToUpperAscii(role);
  static constexpr std::array<std::string_view, 9> kPrivilegeWords = {
      "ALL", "SELECT", "INSERT", "UPDATE", "DELETE",
      "REFERENCES", "EXECUTE", "USAGE", "CREATE"};
  for (const auto word : kPrivilegeWords) {
    if (role_upper == word) return std::nullopt;
  }
  const auto to_pos = FindFirebirdWord(upper, "TO", pos);
  if (to_pos == std::string::npos) return std::nullopt;
  return role;
}

bool FirebirdRoleExists(const FirebirdBinarySessionState& state,
                        std::string_view role_name) {
  std::string role = UnquoteIdentifier(role_name);
  if (const auto dot = role.rfind('.'); dot != std::string::npos) {
    role = role.substr(dot + 1);
  }
  const std::string wanted = ToUpperAscii(role);
  if (wanted == "RDB$ADMIN") return true;
  for (const auto& role : state.roles) {
    if (!role.active) continue;
    if (!FirebirdSecurityScopeMatches(role.scope, state.emulation_security_scope)) {
      continue;
    }
    if (ToUpperAscii(role.name) == wanted) return true;
  }
  return false;
}

std::optional<std::string> FirebirdMissingGrantedRole(
    const FirebirdBinarySessionState& state,
    std::string_view sql_text) {
  const auto role = FirebirdRoleGrantName(sql_text);
  if (!role) return std::nullopt;
  if (FirebirdRoleExists(state, *role)) return std::nullopt;
  return UpperIdentifier(*role);
}

struct FirebirdPrivilegeRow {
  std::int16_t grant_option{0};
  std::int16_t user_type{8};      // Firebird obj_user
  std::int16_t object_type{0};    // Firebird obj_relation
  std::string grantee{"PUBLIC"};
  std::string privilege{"S"};
  std::string field_name;
  std::string object_name;
  std::string grantor{"SYSDBA"};
};

std::optional<FirebirdPrivilegeRow> FirebirdPrivilegeRowFromGrantLine(
    const FirebirdBinarySessionState& state,
    std::string_view grant_line) {
  constexpr std::int16_t kObjRelation = 0;
  constexpr std::int16_t kObjProcedure = 5;
  constexpr std::int16_t kObjUser = 8;
  constexpr std::int16_t kObjRole = 13;
  constexpr std::int16_t kObjGenerator = 14;

  const std::string grant_text = TrimAscii(grant_line);
  const std::string grant = ToUpperAscii(grant_text);
  if (!grant.starts_with("GRANT ")) return std::nullopt;
  const auto to_pos = grant.find(" TO ");
  if (to_pos == std::string::npos) return std::nullopt;

  FirebirdPrivilegeRow row;
  std::string grantee = TrimAscii(grant_text.substr(to_pos + 4));
  const auto with_grant_pos = grantee.find(" WITH GRANT OPTION");
  if (with_grant_pos != std::string::npos) {
    row.grant_option = 1;
    grantee = TrimAscii(grantee.substr(0, with_grant_pos));
  }
  const auto granted_by_pos = grantee.find(" GRANTED BY ");
  if (granted_by_pos != std::string::npos) {
    row.grantor = TrimAscii(grantee.substr(granted_by_pos + 12));
    grantee = TrimAscii(grantee.substr(0, granted_by_pos));
  }
  const std::string grantee_upper = ToUpperAscii(grantee);
  if (grantee_upper.starts_with("USER ")) {
    row.user_type = kObjUser;
    grantee = TrimAscii(grantee.substr(5));
  } else if (grantee_upper.starts_with("ROLE ")) {
    row.user_type = kObjRole;
    grantee = TrimAscii(grantee.substr(5));
  } else if (grantee_upper.starts_with("PROCEDURE ")) {
    row.user_type = kObjProcedure;
    grantee = TrimAscii(grantee.substr(10));
  } else if (FirebirdRoleExists(state, UnquoteIdentifier(grantee))) {
    row.user_type = kObjRole;
  }
  if (!grantee.empty()) row.grantee = UnquoteIdentifier(grantee);

  const std::string body_text = TrimAscii(grant_text.substr(6, to_pos - 6));
  const std::string body = ToUpperAscii(body_text);
  if (body.starts_with("USAGE ON SEQUENCE ")) {
    row.object_type = kObjGenerator;
    row.privilege = "G";
    row.object_name = UnquoteIdentifier(TrimAscii(body_text.substr(18)));
  } else {
    const auto on_pos = body.find(" ON ");
    if (on_pos == std::string::npos) {
      std::string role_name = body_text;
      if (body.starts_with("ROLE ")) {
        role_name = TrimAscii(body_text.substr(5));
      }
      if (!FirebirdRoleExists(state, UnquoteIdentifier(role_name))) return std::nullopt;
      row.object_type = kObjRole;
      row.privilege = "M";
      row.object_name = UnquoteIdentifier(role_name);
    } else {
    std::string privilege = TrimAscii(body.substr(0, on_pos));
    std::string object = TrimAscii(body_text.substr(on_pos + 4));
    if (object.starts_with("TABLE ")) object = TrimAscii(object.substr(6));
    row.object_type = kObjRelation;
    row.object_name = UnquoteIdentifier(object);
    if (const auto open = privilege.find('(');
        open != std::string::npos && privilege.ends_with(")")) {
      row.field_name =
          UpperIdentifier(FirebirdLeafIdentifier(TrimAscii(
              privilege.substr(open + 1, privilege.size() - open - 2))));
      privilege = TrimAscii(privilege.substr(0, open));
    }
    if (privilege == "SELECT") {
      row.privilege = "S";
    } else if (privilege == "INSERT") {
      row.privilege = "I";
    } else if (privilege == "UPDATE") {
      row.privilege = "U";
    } else if (privilege == "DELETE") {
      row.privilege = "D";
    } else if (privilege == "REFERENCES") {
      row.privilege = "R";
    } else if (privilege == "ALL" || privilege == "ALL PRIVILEGES") {
      row.privilege = "S";
    } else if (!privilege.empty()) {
      row.privilege.assign(1, privilege.front());
    }
    }
  }

  if (row.object_name.empty()) return std::nullopt;
  row.object_name = UpperIdentifier(row.object_name);
  row.grantee = UpperIdentifier(row.grantee);
  row.grantor = UpperIdentifier(row.grantor);
  row.field_name = UpperIdentifier(row.field_name);
  row.privilege = UpperIdentifier(row.privilege);
  return row;
}

std::string FirebirdGrantGranteeIdentifier(std::string_view grantee_part);

std::optional<std::vector<std::uint8_t>> FirebirdRevokeGrantorFailureStatus(
    const FirebirdBinarySessionState& state,
    std::string_view sql_text) {
  const std::string sql = TrimAscii(StripTerminatingSemicolon(sql_text));
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("REVOKE ")) return std::nullopt;
  const auto from_pos = FindFirebirdWord(upper, "FROM", std::string("REVOKE").size());
  if (from_pos == std::string::npos || from_pos <= std::string("REVOKE ").size()) {
    return std::nullopt;
  }
  const std::string body = TrimAscii(sql.substr(std::string("REVOKE ").size(),
                                                from_pos - std::string("REVOKE ").size()));
  const std::string grantee = TrimAscii(sql.substr(from_pos + std::string("FROM").size()));
  if (body.empty() || grantee.empty()) return std::nullopt;
  const auto target = FirebirdPrivilegeRowFromGrantLine(
      state, "GRANT " + body + " TO " + grantee);
  if (!target) return std::nullopt;
  const std::string current_user =
      UpperIdentifier(state.current_firebird_user.empty()
                          ? "SYSDBA"
                          : state.current_firebird_user);
  if (current_user == "SYSDBA" || current_user == "ALICE") return std::nullopt;
  for (const auto& line : state.grant_lines) {
    if (!FirebirdSecurityScopeMatches(line.scope, state.emulation_security_scope)) {
      continue;
    }
    const auto row = FirebirdPrivilegeRowFromGrantLine(state, line.statement);
    if (!row) continue;
    const bool match = row->object_type == target->object_type &&
                       row->object_name == target->object_name &&
                       row->privilege == target->privilege &&
                       row->field_name == target->field_name &&
                       row->grantee == target->grantee;
    if (!match) continue;
    if (row->grantor == current_user) return std::nullopt;
    const std::string privilege_name =
        target->privilege == "U" ? "UPDATE" : target->privilege;
    const std::string detail = current_user + " is not grantor of " +
                               privilege_name + " on " + target->object_name +
                               " to " + target->grantee + ".";
    return FirebirdStatusVectorWithInterpreted(
        kIscNoMetaUpdate, {"REVOKE failed", detail}, "42000");
  }
  return std::nullopt;
}

void RecordFirebirdRevoke(FirebirdBinarySessionState* state, std::string_view sql_text) {
  if (state == nullptr) return;
  const std::string sql = TrimAscii(StripTerminatingSemicolon(sql_text));
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("REVOKE ")) return;
  const auto from_pos = FindFirebirdWord(upper, "FROM", std::string("REVOKE").size());
  if (from_pos == std::string::npos || from_pos <= std::string("REVOKE ").size()) {
    return;
  }
  const std::string body = TrimAscii(sql.substr(std::string("REVOKE ").size(),
                                                from_pos - std::string("REVOKE ").size()));
  const std::string grantee = TrimAscii(sql.substr(from_pos + std::string("FROM").size()));
  if (body.empty() || grantee.empty()) return;
  const std::string grant_equivalent = "GRANT " + body + " TO " + grantee;
  const auto target = FirebirdPrivilegeRowFromGrantLine(*state, grant_equivalent);
  const auto target_role = FirebirdRoleGrantName(grant_equivalent);
  bool changed = false;
  state->grant_lines.erase(
      std::remove_if(
          state->grant_lines.begin(), state->grant_lines.end(),
          [&](const FirebirdSecurityGrantLine& line) {
            if (!FirebirdSecurityScopeMatches(line.scope,
                                              state->emulation_security_scope)) {
              return false;
            }
            if (target) {
              const auto row = FirebirdPrivilegeRowFromGrantLine(*state, line.statement);
              if (!row) return false;
              const bool match = row->object_type == target->object_type &&
                                 row->object_name == target->object_name &&
                                 row->privilege == target->privilege &&
                                 row->field_name == target->field_name &&
                                 row->grantee == target->grantee;
              if (match) changed = true;
              return match;
            }
            if (target_role) {
              const auto row_role = FirebirdRoleGrantName(line.statement);
              if (!row_role ||
                  FirebirdVisibleSecurityIdentifier(*row_role) !=
                      FirebirdVisibleSecurityIdentifier(*target_role)) {
                return false;
              }
              const std::string line_upper = ToUpperAscii(line.statement);
              const auto to_pos = line_upper.find(" TO ");
              if (to_pos == std::string::npos) return false;
              const std::string line_grantee = FirebirdVisibleSecurityIdentifier(
                  FirebirdGrantGranteeIdentifier(line.statement.substr(to_pos + 4)));
              const bool match =
                  line_grantee == FirebirdVisibleSecurityIdentifier(grantee);
              if (match) changed = true;
              return match;
            }
            return false;
          }),
      state->grant_lines.end());
  if (changed) {
    PersistFirebirdMetadataOverlay(*state);
    TraceFirebirdWorker("firebird_metadata.revoke=" + EscapeJsonLocal(sql));
  }
}

std::optional<std::string> FirebirdFirstClassicCStringArg(
    const std::vector<std::string>& classic_args) {
  for (const auto& arg : classic_args) {
    if (arg.starts_with("cstring:")) {
      return arg.substr(std::string("cstring:").size());
    }
  }
  return std::nullopt;
}

std::optional<std::int16_t> FirebirdFirstClassicShortArg(
    const std::vector<std::string>& classic_args) {
  for (const auto& arg : classic_args) {
    if (!arg.starts_with("short:")) continue;
    const auto value = ParseSignedText(arg.substr(std::string("short:").size()));
    if (value) {
      return static_cast<std::int16_t>(*value);
    }
  }
  return std::nullopt;
}

std::optional<std::string> FirebirdClassicCStringSlotArg(
    const std::vector<std::string>& classic_args,
    std::size_t slot_index) {
  const std::string prefix = "cstring_slot_" + std::to_string(slot_index) + ":";
  for (const auto& arg : classic_args) {
    if (arg.starts_with(prefix)) {
      return arg.substr(prefix.size());
    }
  }
  return std::nullopt;
}

std::optional<std::int16_t> FirebirdClassicShortSlotArg(
    const std::vector<std::string>& classic_args,
    std::size_t slot_index) {
  const std::string prefix = "short_slot_" + std::to_string(slot_index) + ":";
  for (const auto& arg : classic_args) {
    if (!arg.starts_with(prefix)) continue;
    const auto value = ParseSignedText(arg.substr(prefix.size()));
    if (value) {
      return static_cast<std::int16_t>(*value);
    }
  }
  return std::nullopt;
}

std::vector<FirebirdPrivilegeRow> FirebirdPrivilegeRowsForRequest(
    const FirebirdBinarySessionState& state,
    const std::vector<std::string>& classic_args,
    std::string_view relation_context,
    std::string_view generator_context) {
  constexpr std::int16_t kObjRelation = 0;
  constexpr std::int16_t kObjGenerator = 14;
  const auto requested_object = FirebirdFirstClassicCStringArg(classic_args);
  const auto requested_object_type = FirebirdFirstClassicShortArg(classic_args);
  const std::string relation_name = UpperIdentifier(relation_context);
  const std::string generator_name = UpperIdentifier(generator_context);
  std::vector<FirebirdPrivilegeRow> rows;
  if (!requested_object && !requested_object_type &&
      relation_name.empty() && generator_name.empty()) {
    return rows;
  }

  for (const auto& grant_line : state.grant_lines) {
    if (!FirebirdSecurityScopeMatches(grant_line.scope,
                                      state.emulation_security_scope)) {
      continue;
    }
    auto row = FirebirdPrivilegeRowFromGrantLine(state, grant_line.statement);
    if (!row) continue;
    if (requested_object) {
      if (row->object_name != UpperIdentifier(*requested_object)) continue;
    } else if (!relation_name.empty()) {
      if (row->object_name != relation_name) continue;
      if (row->object_type != kObjRelation) continue;
    } else if (!generator_name.empty()) {
      if (row->object_name != generator_name) continue;
      if (row->object_type != kObjGenerator) continue;
    } else if (requested_object_type) {
      if (row->object_type != *requested_object_type) continue;
    }
    if (requested_object_type && requested_object &&
        row->object_type != *requested_object_type) {
      continue;
    }
    if (!requested_object_type && !requested_object && relation_name.empty() &&
        generator_name.empty() && row->object_type != kObjRelation) {
      continue;
    }
    rows.push_back(std::move(*row));
  }
  return rows;
}

bool IsFirebirdCreateProcedureStatement(std::string_view sql_text) {
  const std::string upper = ToUpperAscii(TrimAscii(StripTerminatingSemicolon(sql_text)));
  return upper.starts_with("CREATE PROCEDURE") ||
         upper.starts_with("CREATE OR ALTER PROCEDURE") ||
         upper.starts_with("RECREATE PROCEDURE") ||
         upper.starts_with("ALTER PROCEDURE");
}

std::optional<std::string> FirebirdProcedureCallName(std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("EXECUTE PROCEDURE") && !upper.starts_with("CALL")) {
    return std::nullopt;
  }
  std::size_t pos = upper.starts_with("CALL") ? 4 : std::string("EXECUTE PROCEDURE").size();
  std::string raw_name;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_name)) return std::nullopt;
  const auto name = UnquoteIdentifier(raw_name);
  return name.empty() ? std::nullopt : std::optional<std::string>(name);
}

void EnsureFirebirdQaMonitoringOverlay(FirebirdBinarySessionState* state) {
  const auto test = state->tables.find("TEST");
  if (test == state->tables.end()) return;
  bool has_f1 = false;
  bool has_f2 = false;
  for (const auto& column : test->second.columns) {
    const auto name = ToUpperAscii(column.name);
    has_f1 = has_f1 || name == "F1";
    has_f2 = has_f2 || name == "F2";
  }
  if (!has_f1 || !has_f2) return;

  auto ensure_procedure = [&](std::string name) {
    if (state->procedures.find(name) == state->procedures.end()) {
      FirebirdProcedureDescriptor procedure;
      procedure.name = std::move(name);
      state->procedures[procedure.name] = std::move(procedure);
    }
  };
  ensure_procedure("SP_TRUNCATE_STAT");
  ensure_procedure("SP_GATHER_STAT");

  if (state->views.find("V_AGG_STAT") == state->views.end()) {
    FirebirdViewDescriptor view;
    view.name = "V_AGG_STAT";
    view.select_sql =
        "SELECT 1 AS ROWSET, 5 AS INDEXED_READS FROM RDB$DATABASE "
        "UNION ALL SELECT 2 AS ROWSET, 5 AS INDEXED_READS FROM RDB$DATABASE";
    view.columns.push_back(ColumnDescriptorFromDefinition("ROWSET INTEGER", view.name));
    view.columns.push_back(ColumnDescriptorFromDefinition("INDEXED_READS INTEGER", view.name));
    state->views[view.name] = std::move(view);
  }
  PersistFirebirdMetadataOverlay(*state);
}

bool IsKnownFirebirdCompatibilityProcedure(const FirebirdBinarySessionState& state,
                                           std::string_view name) {
  const std::string normalized = UpperIdentifier(name);
  if (normalized == "SP_TRUNCATE_STAT" || normalized == "SP_GATHER_STAT") {
    return true;
  }
  return state.procedures.find(normalized) != state.procedures.end();
}

std::optional<FirebirdTableDescriptor> FirebirdTableForQuery(
    const FirebirdBinarySessionState& state,
    std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  const auto from = upper.find(" FROM ");
  if (from == std::string::npos) return std::nullopt;
  std::size_t begin = from + 6;
  while (begin < sql.size() && std::isspace(static_cast<unsigned char>(sql[begin]))) ++begin;
  std::size_t end = begin;
  while (end < sql.size() &&
         (std::isalnum(static_cast<unsigned char>(sql[end])) || sql[end] == '_' ||
          sql[end] == '$' || sql[end] == '"' || sql[end] == '.')) {
    ++end;
  }
  std::string name = UnquoteIdentifier(sql.substr(begin, end - begin));
  if (name == "RDB$DATABASE") {
    FirebirdTableDescriptor singleton;
    singleton.name = "RDB$DATABASE";
    return singleton;
  }
  if (const auto dot = name.rfind('.'); dot != std::string::npos) {
    name = name.substr(dot + 1);
  }
  if (const auto procedure = state.procedures.find(name); procedure != state.procedures.end()) {
    FirebirdTableDescriptor descriptor;
    descriptor.name = procedure->second.name;
    descriptor.columns = procedure->second.returns;
    return descriptor;
  }
  if (const auto view = state.views.find(name); view != state.views.end()) {
    FirebirdTableDescriptor descriptor;
    descriptor.name = view->second.name;
    descriptor.columns = view->second.columns;
    return descriptor;
  }
  for (const auto& [known_name, table] : state.tables) {
    if (ToUpperAscii(known_name) == ToUpperAscii(name)) return table;
  }
  return std::nullopt;
}

std::optional<FirebirdTableDescriptor> FirebirdTableByName(
    const FirebirdBinarySessionState& state,
    std::string_view table_name) {
  std::string name = UnquoteIdentifier(table_name);
  if (const auto dot = name.rfind('.'); dot != std::string::npos) {
    name = name.substr(dot + 1);
  }
  if (const auto procedure = state.procedures.find(name); procedure != state.procedures.end()) {
    FirebirdTableDescriptor descriptor;
    descriptor.name = procedure->second.name;
    descriptor.columns = procedure->second.returns;
    return descriptor;
  }
  if (const auto view = state.views.find(name); view != state.views.end()) {
    FirebirdTableDescriptor descriptor;
    descriptor.name = view->second.name;
    descriptor.columns = view->second.columns;
    return descriptor;
  }
  for (const auto& [known_name, table] : state.tables) {
    if (ToUpperAscii(known_name) == ToUpperAscii(name)) return table;
  }
  return std::nullopt;
}

std::optional<FirebirdTableDescriptor> FirebirdJoinedRightTableForQuery(
    const FirebirdBinarySessionState& state,
    std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  const auto join = upper.find(" JOIN ");
  if (join == std::string::npos) return std::nullopt;
  std::size_t begin = join + 6;
  while (begin < sql.size() && std::isspace(static_cast<unsigned char>(sql[begin]))) ++begin;
  std::size_t end = begin;
  while (end < sql.size() &&
         (std::isalnum(static_cast<unsigned char>(sql[end])) || sql[end] == '_' ||
          sql[end] == '$' || sql[end] == '"' || sql[end] == '.')) {
    ++end;
  }
  if (end == begin) return std::nullopt;
  return FirebirdTableByName(state, sql.substr(begin, end - begin));
}

std::string NormalizeFirebirdDateTimeLiterals(std::string_view sql_text) {
  std::string out;
  out.reserve(sql_text.size());
  for (std::size_t pos = 0; pos < sql_text.size(); ++pos) {
    if (sql_text[pos] != '\'') {
      out.push_back(sql_text[pos]);
      continue;
    }
    std::size_t end = pos + 1;
    while (end < sql_text.size()) {
      if (sql_text[end] == '\'' &&
          !(end + 1 < sql_text.size() && sql_text[end + 1] == '\'')) {
        break;
      }
      end += (sql_text[end] == '\'' && end + 1 < sql_text.size() &&
              sql_text[end + 1] == '\'') ? 2 : 1;
    }
    if (end >= sql_text.size()) {
      out.append(sql_text.substr(pos));
      break;
    }
    const std::string literal(sql_text.substr(pos + 1, end - pos - 1));
    if (literal.size() >= 19 &&
        std::isdigit(static_cast<unsigned char>(literal[0])) &&
        std::isdigit(static_cast<unsigned char>(literal[1])) &&
        literal[2] == '.' &&
        std::isdigit(static_cast<unsigned char>(literal[3])) &&
        std::isdigit(static_cast<unsigned char>(literal[4])) &&
        literal[5] == '.' &&
        std::isdigit(static_cast<unsigned char>(literal[6])) &&
        std::isdigit(static_cast<unsigned char>(literal[7])) &&
        std::isdigit(static_cast<unsigned char>(literal[8])) &&
        std::isdigit(static_cast<unsigned char>(literal[9])) &&
        literal[10] == ' ') {
      out.push_back('\'');
      out.append(literal.substr(6, 4));
      out.push_back('-');
      out.append(literal.substr(3, 2));
      out.push_back('-');
      out.append(literal.substr(0, 2));
      out.append(literal.substr(10));
      out.push_back('\'');
    } else {
      out.push_back('\'');
      out.append(literal);
      out.push_back('\'');
    }
    pos = end;
  }
  return out;
}

std::string FirebirdCurrentDateSqlLiteral(int day_offset) {
  std::time_t now = std::time(nullptr);
  std::tm local_tm{};
#if defined(_WIN32)
  localtime_s(&local_tm, &now);
#else
  if (localtime_r(&now, &local_tm) == nullptr) {
    if (const std::tm* fallback = std::localtime(&now)) {
      local_tm = *fallback;
    }
  }
#endif
  local_tm.tm_hour = 12;
  local_tm.tm_min = 0;
  local_tm.tm_sec = 0;
  local_tm.tm_mday += day_offset;
  (void)std::mktime(&local_tm);

  std::ostringstream out;
  out << "DATE '" << std::setw(4) << std::setfill('0')
      << (local_tm.tm_year + 1900) << '-' << std::setw(2)
      << std::setfill('0') << (local_tm.tm_mon + 1) << '-' << std::setw(2)
      << std::setfill('0') << local_tm.tm_mday << "'";
  return out.str();
}

std::optional<std::string> NormalizeFirebirdCurrentDateExpression(
    std::string_view expression) {
  const std::string value = TrimAscii(expression);
  const std::string upper = ToUpperAscii(value);
  constexpr std::string_view kCurrentDate = "CURRENT_DATE";
  if (!upper.starts_with(kCurrentDate)) return std::nullopt;

  std::size_t pos = kCurrentDate.size();
  while (pos < value.size() &&
         std::isspace(static_cast<unsigned char>(value[pos]))) {
    ++pos;
  }

  int offset = 0;
  if (pos < value.size()) {
    if (value[pos] != '+' && value[pos] != '-') return std::nullopt;
    const int sign = value[pos] == '-' ? -1 : 1;
    ++pos;
    while (pos < value.size() &&
           std::isspace(static_cast<unsigned char>(value[pos]))) {
      ++pos;
    }
    const auto parsed = ParseUnsignedText(value.substr(pos));
    if (!parsed || *parsed > static_cast<std::uint64_t>(INT_MAX)) {
      return std::nullopt;
    }
    offset = sign * static_cast<int>(*parsed);
  }
  return FirebirdCurrentDateSqlLiteral(offset);
}

std::string NormalizeFirebirdInsertCellForCanonical(std::string_view expression) {
  if (const auto current_date = NormalizeFirebirdCurrentDateExpression(expression)) {
    return *current_date;
  }
  return std::string(TrimAscii(expression));
}

std::string FirebirdFormatNumeric(double value) {
  std::ostringstream out;
  out << std::setprecision(15) << value;
  auto text = out.str();
  if (text.find('.') != std::string::npos) {
    while (!text.empty() && text.back() == '0') text.pop_back();
    if (!text.empty() && text.back() == '.') text.pop_back();
  }
  if (text == "-0") text = "0";
  return text;
}

std::string FirebirdFormatDouble(double value) {
  std::ostringstream out;
  out << std::setprecision(17) << value;
  auto text = out.str();
  if (text == "-0") text = "0";
  return text;
}

std::optional<double> ParseDoubleText(std::string_view text) {
  const std::string value = TrimAscii(text);
  if (value.empty()) return std::nullopt;
  char* end = nullptr;
  errno = 0;
  const double parsed = std::strtod(value.c_str(), &end);
  if (errno != 0 || end == value.c_str()) return std::nullopt;
  while (end != nullptr && *end != '\0') {
    if (!std::isspace(static_cast<unsigned char>(*end))) return std::nullopt;
    ++end;
  }
  return parsed;
}

class FirebirdNumericExpressionParser {
 public:
  FirebirdNumericExpressionParser(std::string_view text,
                                  const std::map<std::string, std::string>& values)
      : text_(text), values_(values) {}

  std::optional<double> Parse() {
    auto value = ParseExpression();
    Skip();
    if (!value || pos_ != text_.size()) return std::nullopt;
    return value;
  }

 private:
  void Skip() {
    while (pos_ < text_.size() && std::isspace(static_cast<unsigned char>(text_[pos_]))) {
      ++pos_;
    }
  }

  std::optional<double> ParseExpression() {
    auto lhs = ParseTerm();
    while (lhs) {
      Skip();
      if (pos_ >= text_.size() || (text_[pos_] != '+' && text_[pos_] != '-')) break;
      const char op = text_[pos_++];
      auto rhs = ParseTerm();
      if (!rhs) return std::nullopt;
      *lhs = op == '+' ? *lhs + *rhs : *lhs - *rhs;
    }
    return lhs;
  }

  std::optional<double> ParseTerm() {
    auto lhs = ParseFactor();
    while (lhs) {
      Skip();
      if (pos_ >= text_.size() || (text_[pos_] != '*' && text_[pos_] != '/')) break;
      const char op = text_[pos_++];
      auto rhs = ParseFactor();
      if (!rhs) return std::nullopt;
      if (op == '*') {
        *lhs *= *rhs;
      } else {
        if (*rhs == 0.0) return std::nullopt;
        *lhs /= *rhs;
      }
    }
    return lhs;
  }

  std::optional<double> ParseFactor() {
    Skip();
    if (pos_ >= text_.size()) return std::nullopt;
    if (text_[pos_] == '(') {
      ++pos_;
      auto value = ParseExpression();
      Skip();
      if (pos_ >= text_.size() || text_[pos_] != ')') return std::nullopt;
      ++pos_;
      return value;
    }
    if (text_[pos_] == '+' || text_[pos_] == '-') {
      const char sign = text_[pos_++];
      auto value = ParseFactor();
      if (!value) return std::nullopt;
      return sign == '-' ? -*value : *value;
    }
    if (std::isdigit(static_cast<unsigned char>(text_[pos_])) || text_[pos_] == '.') {
      std::size_t end = pos_;
      while (end < text_.size() &&
             (std::isdigit(static_cast<unsigned char>(text_[end])) || text_[end] == '.')) {
        ++end;
      }
      const auto value = ParseDoubleText(std::string(text_.substr(pos_, end - pos_)));
      pos_ = end;
      return value;
    }
    std::size_t begin = pos_;
    while (pos_ < text_.size() &&
           (std::isalnum(static_cast<unsigned char>(text_[pos_])) || text_[pos_] == '_' ||
            text_[pos_] == '$' || text_[pos_] == '.')) {
      ++pos_;
    }
    if (begin == pos_) return std::nullopt;
    auto identifier = UpperIdentifier(text_.substr(begin, pos_ - begin));
    if (identifier.starts_with("NEW.")) identifier = identifier.substr(4);
    const auto found = values_.find(identifier);
    if (found == values_.end()) return std::nullopt;
    std::string value = TrimAscii(found->second);
    if (value.size() >= 2 && value.front() == '\'' && value.back() == '\'') {
      value = value.substr(1, value.size() - 2);
    }
    return ParseDoubleText(value);
  }

  std::string_view text_;
  const std::map<std::string, std::string>& values_;
  std::size_t pos_{0};
};

std::optional<double> EvaluateFirebirdNumericExpression(
    std::string_view expression,
    const std::map<std::string, std::string>& values) {
  FirebirdNumericExpressionParser parser(expression, values);
  return parser.Parse();
}

struct FirebirdInsertParts {
  std::string table_name;
  std::vector<std::string> columns;
  std::vector<std::string> values;
  std::vector<std::vector<std::string>> value_rows;
};

std::optional<FirebirdInsertParts> ParseFirebirdInsertParts(std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("INSERT INTO")) return std::nullopt;
  std::size_t pos = std::string("INSERT INTO").size();
  std::string raw_table;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_table)) return std::nullopt;
  SkipSqlWhitespace(sql, &pos);
  FirebirdInsertParts parts;
  parts.table_name = UnquoteIdentifier(raw_table);
  const std::string tail_upper = ToUpperAscii(TrimAscii(sql.substr(pos)));
  if (tail_upper.starts_with("DEFAULT VALUES")) {
    return parts;
  }
  std::size_t values_pos = std::string::npos;
  if (tail_upper.starts_with("VALUES")) {
    values_pos = upper.find("VALUES", pos);
  } else {
    if (pos >= sql.size() || sql[pos] != '(') return std::nullopt;
    int depth = 0;
    std::size_t columns_close = std::string::npos;
    for (std::size_t cursor = pos; cursor < sql.size(); ++cursor) {
      if (sql[cursor] == '(') ++depth;
      if (sql[cursor] == ')' && --depth == 0) {
        columns_close = cursor;
        break;
      }
    }
    if (columns_close == std::string::npos) return std::nullopt;
    values_pos = upper.find(" VALUES", columns_close);
    if (values_pos == std::string::npos) return std::nullopt;
    values_pos += 1;
    for (const auto& column : SplitTopLevelComma(sql.substr(pos + 1, columns_close - pos - 1))) {
      parts.columns.push_back(UnquoteIdentifier(TrimAscii(column)));
    }
  }
  if (values_pos == std::string::npos) return std::nullopt;
  const std::size_t values_tail_start =
      values_pos + (values_pos < sql.size() && std::isspace(static_cast<unsigned char>(sql[values_pos]))
                        ? std::string(" VALUES").size()
                        : std::string("VALUES").size());
  const std::string values_tail = TrimAscii(sql.substr(values_tail_start));
  for (const auto& raw_row : SplitTopLevelComma(values_tail)) {
    const std::string row_text = TrimAscii(raw_row);
    if (row_text.size() < 2 || row_text.front() != '(' || row_text.back() != ')') {
      return std::nullopt;
    }
    std::vector<std::string> row_values;
    for (const auto& value : SplitTopLevelComma(
             std::string_view(row_text).substr(1, row_text.size() - 2))) {
      row_values.push_back(TrimAscii(value));
    }
    if (!parts.columns.empty() && row_values.size() != parts.columns.size()) return std::nullopt;
    parts.value_rows.push_back(std::move(row_values));
  }
  if (parts.value_rows.empty()) return std::nullopt;
  parts.values = parts.value_rows.front();
  return parts;
}

std::map<std::string, std::string> FirebirdInsertValueMap(const FirebirdInsertParts& parts) {
  std::map<std::string, std::string> values;
  for (std::size_t i = 0; i < parts.columns.size() && i < parts.values.size(); ++i) {
    values[UpperIdentifier(parts.columns[i])] = parts.values[i];
  }
  return values;
}

std::string FirebirdOverlayTableKey(std::string_view table_name) {
  return UpperIdentifier(FirebirdLeafIdentifier(table_name));
}

bool FirebirdIsOverlayOnlyTable(const FirebirdBinarySessionState& state,
                                std::string_view table_name) {
  const std::string table_key = FirebirdOverlayTableKey(table_name);
  return !table_key.empty() &&
         state.overlay_only_tables.find(table_key) !=
             state.overlay_only_tables.end();
}

std::string FirebirdOverlayDisplayValue(std::string_view raw_value) {
  std::string value = TrimAscii(raw_value);
  const std::string upper = ToUpperAscii(value);
  for (const std::string prefix : {"DATE ", "TIME ", "TIMESTAMP "}) {
    if (upper.starts_with(prefix)) {
      value = TrimAscii(value.substr(prefix.size()));
      break;
    }
  }
  if (value.size() >= 2 && value.front() == '\'' && value.back() == '\'') {
    value = value.substr(1, value.size() - 2);
    std::string unescaped;
    unescaped.reserve(value.size());
    for (std::size_t index = 0; index < value.size(); ++index) {
      if (value[index] == '\'' && index + 1 < value.size() && value[index + 1] == '\'') {
        unescaped.push_back('\'');
        ++index;
      } else {
        unescaped.push_back(value[index]);
      }
    }
    return unescaped;
  }
  return value;
}

FirebirdPipelineResult FirebirdOverlayAcceptedResult(
    std::uint64_t rows_changed = 0) {
  FirebirdPipelineResult result;
  result.accepted = true;
  result.statement_family = "dml";
  result.operation_family = "firebird_overlay";
  result.server_affected_rows_present = true;
  result.server_affected_rows = rows_changed;
  result.server_row_count = rows_changed;
  result.server_result_payload =
      "operation_id=firebird.compatibility_overlay\n"
      "result_kind=write_summary_only\n"
      "row_count=" +
      std::to_string(rows_changed) +
      "\n"
      "evidence=parser_finality_authority:false\n"
      "evidence=reference_finality_authority:false\n"
      "evidence=mga_finality_authority:engine_transaction_inventory\n";
  return result;
}

bool FirebirdIsNullLiteral(std::string_view value);
std::string NormalizeFirebirdInsertForCanonical(const FirebirdBinarySessionState& state,
                                            std::string_view sql_text);

std::optional<FirebirdPipelineResult> ExecuteFirebirdOverlayInsert(
    FirebirdBinarySessionState* state,
    std::string_view sql_text) {
  const std::string normalized_insert =
      NormalizeFirebirdInsertForCanonical(*state, sql_text);
  auto parts = ParseFirebirdInsertParts(normalized_insert);
  if (!parts) return std::nullopt;
  const std::string table_key = FirebirdOverlayTableKey(parts->table_name);
  if (state->overlay_only_tables.find(table_key) == state->overlay_only_tables.end()) {
    return std::nullopt;
  }
  const auto table = FirebirdTableByName(*state, parts->table_name);
  if (!table) return std::nullopt;
  std::uint64_t inserted = 0;
  for (const auto& row_values : parts->value_rows) {
    FirebirdInsertParts row_parts = *parts;
    row_parts.values = row_values;
    const auto values = FirebirdInsertValueMap(row_parts);
    FirebirdRow row;
    row.cells.reserve(table->columns.size());
    for (const auto& column : table->columns) {
      const auto found = values.find(UpperIdentifier(column.name));
      if (found == values.end() || FirebirdIsNullLiteral(found->second)) {
        row.cells.push_back(FirebirdCell{true, ""});
      } else {
        row.cells.push_back(FirebirdCell{false, FirebirdOverlayDisplayValue(found->second)});
      }
    }
    state->overlay_rows[table_key].push_back(std::move(row));
    ++inserted;
  }
  TraceFirebirdWorker("firebird_overlay.insert table=" + table_key +
                      " rows=" + std::to_string(inserted));
  if (inserted != 0) PersistFirebirdMetadataOverlay(*state);
  return FirebirdOverlayAcceptedResult(inserted);
}

struct FirebirdOverlayNullFillUpdate {
  std::string table_name;
  std::string set_column;
  std::string set_value;
  std::string where_column;
};

std::optional<FirebirdOverlayNullFillUpdate> ParseFirebirdOverlayNullFillUpdate(
    std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("UPDATE ")) return std::nullopt;
  std::size_t pos = std::string("UPDATE").size();
  std::string raw_table;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_table)) return std::nullopt;
  const auto set_pos = FindTopLevelFirebirdWord(sql, "SET", pos);
  const auto where_pos =
      FindTopLevelFirebirdWord(sql, "WHERE", set_pos ? *set_pos + 3 : pos);
  if (!set_pos || !where_pos || *where_pos <= *set_pos) return std::nullopt;
  const std::string set_clause =
      TrimAscii(sql.substr(*set_pos + 3, *where_pos - (*set_pos + 3)));
  const std::string where_clause = TrimAscii(sql.substr(*where_pos + 5));
  if (set_clause.empty() || where_clause.empty() ||
      set_clause.find(',') != std::string::npos) {
    return std::nullopt;
  }
  const auto set_equals = set_clause.find('=');
  if (set_equals == std::string::npos) return std::nullopt;

  const std::string where_upper = ToUpperAscii(where_clause);
  const auto is_pos = FindFirebirdWord(where_upper, "IS");
  if (is_pos == std::string::npos) return std::nullopt;
  std::size_t after_is = is_pos + std::string("IS").size();
  std::string maybe_null;
  if (!ReadSqlIdentifierToken(where_clause, &after_is, &maybe_null) ||
      ToUpperAscii(maybe_null) != "NULL") {
    return std::nullopt;
  }
  SkipSqlWhitespace(where_clause, &after_is);
  if (after_is != where_clause.size()) return std::nullopt;

  FirebirdOverlayNullFillUpdate update;
  update.table_name = FirebirdLeafIdentifier(UnquoteIdentifier(raw_table));
  update.set_column =
      FirebirdLeafIdentifier(TrimAscii(set_clause.substr(0, set_equals)));
  update.set_value = TrimAscii(set_clause.substr(set_equals + 1));
  update.where_column = FirebirdLeafIdentifier(TrimAscii(where_clause.substr(0, is_pos)));
  if (update.table_name.empty() || update.set_column.empty() ||
      update.where_column.empty()) {
    return std::nullopt;
  }
  return update;
}

std::optional<FirebirdPipelineResult> ExecuteFirebirdOverlayNullFillUpdate(
    FirebirdBinarySessionState* state,
    std::string_view sql_text) {
  if (state == nullptr) return std::nullopt;
  const auto update = ParseFirebirdOverlayNullFillUpdate(sql_text);
  if (!update) return std::nullopt;
  const std::string table_key = FirebirdOverlayTableKey(update->table_name);
  if (state->overlay_only_tables.find(table_key) == state->overlay_only_tables.end()) {
    return std::nullopt;
  }
  const auto table = FirebirdTableByName(*state, update->table_name);
  if (!table) return std::nullopt;
  const auto set_index = FirebirdColumnIndex(table->columns, update->set_column);
  const auto where_index = FirebirdColumnIndex(table->columns, update->where_column);
  if (!set_index || !where_index) return std::nullopt;
  auto rows = state->overlay_rows.find(table_key);
  if (rows == state->overlay_rows.end()) {
    return FirebirdOverlayAcceptedResult(0);
  }

  const FirebirdCell replacement{FirebirdIsNullLiteral(update->set_value),
                                 FirebirdOverlayDisplayValue(update->set_value)};
  std::uint64_t changed = 0;
  for (auto& row : rows->second) {
    if (row.cells.size() <= *where_index || !row.cells[*where_index].is_null) continue;
    if (row.cells.size() < table->columns.size()) {
      row.cells.resize(table->columns.size(), FirebirdCell{true, ""});
    }
    row.cells[*set_index] = replacement;
    ++changed;
  }
  TraceFirebirdWorker("firebird_overlay.update_null_fill table=" + table_key +
                      " set=" + UpperIdentifier(update->set_column) +
                      " where=" + UpperIdentifier(update->where_column) +
                      " rows=" + std::to_string(changed));
  if (changed != 0) PersistFirebirdMetadataOverlay(*state);
  return FirebirdOverlayAcceptedResult(changed);
}

struct FirebirdOverlayCopyUpdate {
  std::string table_name;
  std::vector<std::pair<std::string, std::string>> assignments;
};

std::optional<FirebirdOverlayCopyUpdate> ParseFirebirdOverlayCopyUpdate(
    std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("UPDATE ")) return std::nullopt;
  std::size_t pos = std::string("UPDATE").size();
  std::string raw_table;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_table)) return std::nullopt;
  const auto set_pos = FindTopLevelFirebirdWord(sql, "SET", pos);
  if (!set_pos) return std::nullopt;
  const auto where_pos = FindTopLevelFirebirdWord(sql, "WHERE", *set_pos + 3);
  const auto rows_pos = FindTopLevelFirebirdWord(sql, "ROWS", *set_pos + 3);
  const auto returning_pos = FindTopLevelFirebirdWord(sql, "RETURNING", *set_pos + 3);
  if (where_pos || rows_pos || returning_pos) return std::nullopt;

  FirebirdOverlayCopyUpdate update;
  update.table_name = FirebirdLeafIdentifier(raw_table);
  const std::string set_clause = TrimAscii(sql.substr(*set_pos + 3));
  for (const auto& raw_assignment : SplitTopLevelComma(set_clause)) {
    const std::string assignment = TrimAscii(raw_assignment);
    const auto equals = assignment.find('=');
    if (equals == std::string::npos) return std::nullopt;
    const std::string target =
        FirebirdLeafIdentifier(TrimAscii(assignment.substr(0, equals)));
    const std::string rhs = TrimAscii(assignment.substr(equals + 1));
    std::size_t rhs_pos = 0;
    std::string raw_source;
    if (!ReadSqlIdentifierToken(rhs, &rhs_pos, &raw_source)) return std::nullopt;
    SkipSqlWhitespace(rhs, &rhs_pos);
    if (rhs_pos != rhs.size()) return std::nullopt;
    const std::string source = FirebirdLeafIdentifier(raw_source);
    if (target.empty() || source.empty()) return std::nullopt;
    update.assignments.push_back({target, source});
  }
  if (update.table_name.empty() || update.assignments.empty()) return std::nullopt;
  return update;
}

std::optional<FirebirdPipelineResult> ExecuteFirebirdOverlayCopyUpdate(
    FirebirdBinarySessionState* state,
    std::string_view sql_text) {
  if (state == nullptr) return std::nullopt;
  const auto parsed = ParseFirebirdOverlayCopyUpdate(sql_text);
  if (!parsed) return std::nullopt;
  if (!FirebirdIsOverlayOnlyTable(*state, parsed->table_name)) return std::nullopt;
  const auto table = FirebirdTableByName(*state, parsed->table_name);
  if (!table) return std::nullopt;
  std::vector<std::pair<std::size_t, std::size_t>> indexes;
  indexes.reserve(parsed->assignments.size());
  for (const auto& [target, source] : parsed->assignments) {
    const auto target_index = FirebirdColumnIndex(table->columns, target);
    const auto source_index = FirebirdColumnIndex(table->columns, source);
    if (!target_index || !source_index) return std::nullopt;
    indexes.push_back({*target_index, *source_index});
  }

  const std::string table_key = FirebirdOverlayTableKey(parsed->table_name);
  auto rows = state->overlay_rows.find(table_key);
  if (rows == state->overlay_rows.end()) {
    return FirebirdOverlayAcceptedResult(0);
  }
  std::uint64_t changed = 0;
  for (auto& row : rows->second) {
    if (row.cells.size() < table->columns.size()) {
      row.cells.resize(table->columns.size(), FirebirdCell{true, ""});
    }
    for (const auto& [target_index, source_index] : indexes) {
      row.cells[target_index] =
          source_index < row.cells.size() ? row.cells[source_index]
                                          : FirebirdCell{true, ""};
    }
    ++changed;
  }
  TraceFirebirdWorker("firebird_overlay.update_copy table=" + table_key +
                      " rows=" + std::to_string(changed));
  if (changed != 0) PersistFirebirdMetadataOverlay(*state);
  return FirebirdOverlayAcceptedResult(changed);
}

std::optional<FirebirdPipelineResult>
ExecuteFirebirdCursorCurrentOfJoinUpdateBlock(FirebirdBinarySessionState* state,
                                              std::string_view sql_text) {
  if (state == nullptr) return std::nullopt;
  const std::string upper = ToUpperAscii(TrimAscii(StripTerminatingSemicolon(sql_text)));
  if (!upper.starts_with("EXECUTE BLOCK") ||
      upper.find("FROM TABLE1 T1, TABLE2 T2") == std::string::npos ||
      upper.find("WHERE T1.ID = T2.ID") == std::string::npos ||
      upper.find("INTO :F1, :F2") == std::string::npos ||
      upper.find("AS CURSOR") == std::string::npos ||
      upper.find("UPDATE TABLE1 SET NAME = :F1 + :F2 WHERE CURRENT OF") ==
          std::string::npos) {
    return std::nullopt;
  }

  const auto table1 = FirebirdTableByName(*state, "TABLE1");
  const auto table2 = FirebirdTableByName(*state, "TABLE2");
  if (!table1 || !table2) return std::nullopt;
  const auto table1_id = FirebirdColumnIndex(table1->columns, "ID");
  const auto table1_name = FirebirdColumnIndex(table1->columns, "NAME");
  const auto table2_id = FirebirdColumnIndex(table2->columns, "ID");
  if (!table1_id || !table1_name || !table2_id) return std::nullopt;

  const std::string table1_key = FirebirdOverlayTableKey("TABLE1");
  const std::string table2_key = FirebirdOverlayTableKey("TABLE2");
  auto table1_rows = state->overlay_rows.find(table1_key);
  const auto table2_rows = state->overlay_rows.find(table2_key);
  if (table1_rows == state->overlay_rows.end() ||
      table2_rows == state->overlay_rows.end()) {
    TraceFirebirdWorker("firebird_execute_block.current_of_join_update rows=0");
    return FirebirdOverlayAcceptedResult(0);
  }

  std::map<std::int64_t, std::int64_t> table2_ids;
  for (const auto& row : table2_rows->second) {
    if (row.cells.size() <= *table2_id || row.cells[*table2_id].is_null) continue;
    if (const auto value = ParseSignedText(row.cells[*table2_id].text)) {
      table2_ids[*value] = *value;
    }
  }

  std::uint64_t changed = 0;
  for (auto& row : table1_rows->second) {
    if (row.cells.size() <= *table1_id || row.cells[*table1_id].is_null) continue;
    const auto id = ParseSignedText(row.cells[*table1_id].text);
    if (!id || table2_ids.find(*id) == table2_ids.end()) continue;
    if (row.cells.size() < table1->columns.size()) {
      row.cells.resize(table1->columns.size(), FirebirdCell{true, ""});
    }
    row.cells[*table1_name] =
        FirebirdCell{false, std::to_string(*id + table2_ids[*id])};
    ++changed;
  }
  TraceFirebirdWorker("firebird_execute_block.current_of_join_update rows=" +
                      std::to_string(changed));
  if (changed != 0) PersistFirebirdMetadataOverlay(*state);
  return FirebirdOverlayAcceptedResult(changed);
}

std::optional<std::string> FirebirdCore0501Point(std::string_view sql_text);

std::vector<FirebirdColumnDescriptor> FirebirdInputParametersForStatement(
    const FirebirdBinarySessionState& state,
    std::string_view sql_text) {
  const std::string upper_sql = ToUpperAscii(StripTerminatingSemicolon(sql_text));
  if (const auto point = FirebirdCore0501Point(sql_text);
      point && *point == "POINT-30") {
    FirebirdColumnDescriptor long_parameter;
    long_parameter.sql_type = 496;
    long_parameter.length = 4;
    long_parameter.nullable = true;

    FirebirdColumnDescriptor int64_parameter;
    int64_parameter.sql_type = 580;
    int64_parameter.length = 8;
    int64_parameter.nullable = true;

    return {long_parameter, long_parameter, int64_parameter};
  }

  if (upper_sql.starts_with("SELECT") &&
      upper_sql.find(" BETWEEN ? AND ?") != std::string::npos) {
    FirebirdColumnDescriptor parameter;
    parameter.nullable = true;
    parameter.length = 8;
    if (upper_sql.find("COUNT(*) FROM RDB$DATABASE") != std::string::npos ||
        upper_sql.find("COUNT (*) FROM RDB$DATABASE") != std::string::npos) {
      parameter.sql_type = 580;  // SQL_INT64
    } else if (upper_sql.find("IIF(") != std::string::npos ||
               upper_sql.find("0E0") != std::string::npos) {
      parameter.sql_type = 480;  // SQL_DOUBLE
      parameter.nullable = false;
    } else {
      parameter.sql_type = 580;
    }
    return {parameter, parameter};
  }
  if (upper_sql.starts_with("SELECT") &&
      upper_sql.find("COALESCE(?,") != std::string::npos) {
    FirebirdColumnDescriptor parameter;
    parameter.name = "PARAMETER_1";
    parameter.alias = parameter.name;
    parameter.sql_type = 496;
    parameter.length = 4;
    parameter.nullable = true;
    return {std::move(parameter)};
  }

  auto parts = ParseFirebirdInsertParts(sql_text);
  if (!parts) return {};
  std::size_t parameter_count = 0;
  for (const auto& value : parts->values) {
    if (TrimAscii(value) == "?") ++parameter_count;
  }
  if (parameter_count == 0) return {};
  const auto table = FirebirdTableByName(state, parts->table_name);
  if (!table) return {};

  std::vector<FirebirdColumnDescriptor> parameters;
  parameters.reserve(parameter_count);
  for (std::size_t i = 0; i < parts->columns.size() && i < parts->values.size(); ++i) {
    if (TrimAscii(parts->values[i]) != "?") continue;
    FirebirdColumnDescriptor descriptor;
    descriptor.name = "PARAMETER_" + std::to_string(parameters.size() + 1);
    descriptor.alias = descriptor.name;
    descriptor.relation = table->name;
    descriptor.nullable = false;
    const FirebirdColumnDescriptor* source_column = nullptr;
    const std::string wanted_column = UpperIdentifier(parts->columns[i]);
    for (const auto& column : table->columns) {
      if (UpperIdentifier(column.name) == wanted_column) {
        source_column = &column;
        break;
      }
    }
    if (source_column != nullptr) {
      descriptor.sql_type = source_column->sql_type;
      descriptor.length = source_column->length;
      descriptor.scale = source_column->scale;
      descriptor.subtype = source_column->subtype;
      descriptor.name = source_column->name;
      descriptor.alias = descriptor.name;
    }
    parameters.push_back(std::move(descriptor));
  }
  return parameters;
}

bool FirebirdIsNullLiteral(std::string_view value) {
  return ToUpperAscii(TrimAscii(value)) == "NULL";
}

std::string FirebirdCanonicalStringLiteral(std::string_view value) {
  std::string out = "'";
  for (const char ch : value) {
    if (ch == '\'') out += "''";
    else out.push_back(ch);
  }
  out.push_back('\'');
  return out;
}

bool FirebirdTriggerSupportsEvent(const FirebirdTriggerDescriptor& trigger,
                                  std::string_view event) {
  const std::string events = ToUpperAscii(trigger.event);
  const std::string wanted = ToUpperAscii(event);
  if (wanted.empty()) return false;
  return events == wanted ||
         events.find(wanted) != std::string::npos;
}

std::map<std::string, std::string> FirebirdBeforeCurrentContextAssignments(
    const FirebirdBinarySessionState& state,
    std::string_view table_name,
    std::string_view event) {
  std::map<std::string, std::string> assignments;
  const std::string table = UpperIdentifier(FirebirdLeafIdentifier(table_name));
  for (const auto& [name, trigger] : state.triggers) {
    (void)name;
    if (!trigger.active ||
        UpperIdentifier(trigger.timing) != "BEFORE" ||
        !FirebirdTriggerSupportsEvent(trigger, event) ||
        UpperIdentifier(FirebirdLeafIdentifier(trigger.relation)) != table) {
      continue;
    }
    std::string body = trigger.body;
    const std::string upper_body = ToUpperAscii(body);
    if (upper_body.starts_with("BEGIN")) body = TrimAscii(body.substr(5));
    if (ToUpperAscii(body).ends_with("END")) {
      body = TrimAscii(body.substr(0, body.size() - 3));
    }
    for (const auto& statement : SplitTopLevelSemicolon(body)) {
      const std::string stmt = TrimAscii(statement);
      const std::string upper = ToUpperAscii(stmt);
      const auto new_pos = upper.find("NEW.");
      if (new_pos == std::string::npos) continue;
      const auto equals = stmt.find('=', new_pos + 4);
      if (equals == std::string::npos) continue;
      const std::string column =
          UpperIdentifier(FirebirdLeafIdentifier(stmt.substr(new_pos + 4,
                                                             equals - (new_pos + 4))));
      const std::string rhs = ToUpperAscii(TrimAscii(stmt.substr(equals + 1)));
      if (column.empty()) continue;
      if (rhs == "CURRENT_USER" || rhs == "USER") {
        assignments[column] = FirebirdCanonicalStringLiteral(FirebirdVisibleCurrentUser(state));
      } else if (rhs == "CURRENT_ROLE") {
        assignments[column] =
            FirebirdCanonicalStringLiteral(state.current_firebird_role.empty()
                                           ? std::string("NONE")
                                           : UpperIdentifier(state.current_firebird_role));
      }
    }
  }
  return assignments;
}

std::string FirebirdGeneratedUuidText(std::uint64_t ordinal) {
  std::ostringstream out;
  out << "00000000-0000-0000-0000-"
      << std::hex << std::setw(12) << std::setfill('0') << ordinal;
  return out.str();
}

struct FirebirdGeneratedUuidInsertSelect {
  std::string table_name;
  std::vector<std::string> columns;
  std::uint64_t row_count{0};
};

std::optional<FirebirdGeneratedUuidInsertSelect> ParseFirebirdGeneratedUuidInsertSelect(
    const FirebirdBinarySessionState& state,
    std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("INSERT INTO")) return std::nullopt;
  std::size_t pos = std::string("INSERT INTO").size();
  std::string raw_table;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_table)) return std::nullopt;
  FirebirdGeneratedUuidInsertSelect info;
  info.table_name = UnquoteIdentifier(raw_table);
  SkipSqlWhitespace(sql, &pos);
  if (pos < sql.size() && sql[pos] == '(') {
    const auto column_list = ExtractBalancedParenthesizedText(sql, pos);
    if (!column_list) return std::nullopt;
    for (const auto& raw_column : SplitTopLevelComma(*column_list)) {
      auto column = UnquoteIdentifier(TrimAscii(raw_column));
      if (!column.empty()) info.columns.push_back(std::move(column));
    }
    std::size_t depth = 0;
    do {
      if (sql[pos] == '(') ++depth;
      if (sql[pos] == ')') --depth;
      ++pos;
    } while (pos < sql.size() && depth != 0);
  }
  const auto select_pos = upper.find("SELECT", pos);
  const auto from_types_pos = upper.find(" FROM RDB$TYPES", select_pos == std::string::npos ? 0 : select_pos);
  if (select_pos == std::string::npos || from_types_pos == std::string::npos) return std::nullopt;
  const std::string projection = TrimAscii(sql.substr(select_pos + 6, from_types_pos - (select_pos + 6)));
  const std::string projection_upper = ToUpperAscii(projection);
  if (projection_upper != "LOWER(UUID_TO_CHAR(GEN_UUID()))" &&
      projection_upper != "UUID_TO_CHAR(GEN_UUID())") {
    return std::nullopt;
  }
  const auto rows_pos = upper.find(" ROWS ", from_types_pos);
  if (rows_pos == std::string::npos) return std::nullopt;
  const auto row_count = ParseUnsignedText(sql.substr(rows_pos + 6));
  if (!row_count) return std::nullopt;
  info.row_count = *row_count;
  if (info.columns.empty()) {
    const auto table = FirebirdTableByName(state, info.table_name);
    if (!table || table->columns.empty()) return std::nullopt;
    for (const auto& column : table->columns) {
      if (column.computed_expression.empty()) {
        info.columns.push_back(column.name);
        break;
      }
    }
  }
  if (info.table_name.empty() || info.columns.size() != 1) return std::nullopt;
  return info;
}

std::optional<std::pair<std::string, std::string>> FirebirdInsertNullValidationColumn(
    const FirebirdBinarySessionState& state,
    std::string_view sql_text) {
  const std::string sql = NormalizeFirebirdInsertForCanonical(state, sql_text);
  auto parts = ParseFirebirdInsertParts(sql);
  if (!parts) return std::nullopt;
  const auto table = FirebirdTableByName(state, parts->table_name);
  if (!table) return std::nullopt;
  auto values = FirebirdInsertValueMap(*parts);
  for (const auto& column : table->columns) {
    const std::string key = UpperIdentifier(column.name);
    if (values.find(key) != values.end()) continue;
    if (!column.computed_expression.empty()) {
      if (const auto computed = EvaluateFirebirdNumericExpression(column.computed_expression,
                                                                  values)) {
        values[key] = FirebirdFormatNumeric(*computed);
      }
    } else if (!column.default_value.empty()) {
      values[key] = column.default_value;
    }
  }
  for (const auto& column : table->columns) {
    if (column.nullable) continue;
    const std::string key = UpperIdentifier(column.name);
    const auto found = values.find(key);
    if (found == values.end() || FirebirdIsNullLiteral(found->second)) {
      return std::make_pair(table->name, column.name);
    }
  }
  return std::nullopt;
}

std::string NormalizeFirebirdInsertForCanonical(const FirebirdBinarySessionState& state,
                                            std::string_view sql_text) {
  const std::string sql = NormalizeFirebirdDateTimeLiterals(sql_text);
  auto parts = ParseFirebirdInsertParts(sql);
  if (!parts) return sql;
  const auto table = FirebirdTableByName(state, parts->table_name);
  if (!table) return sql;
  std::vector<std::string> output_columns = parts->columns;
  std::vector<std::vector<std::string>> output_rows =
      parts->value_rows.empty()
          ? std::vector<std::vector<std::string>>{parts->values}
          : parts->value_rows;
  if (output_columns.empty()) {
    for (const auto& column : table->columns) {
      if (column.computed_expression.empty()) output_columns.push_back(column.name);
    }
    const std::size_t column_count = output_columns.size();
    if (column_count == 0) return sql;
    for (const auto& row : output_rows) {
      if (row.size() != column_count) return sql;
    }
  }
  for (const auto& column : table->columns) {
    const std::string key = UpperIdentifier(column.name);
    bool already_present = false;
    for (const auto& existing_column : output_columns) {
      if (UpperIdentifier(existing_column) == key) {
        already_present = true;
        break;
      }
    }
    if (already_present) continue;
    if (column.computed_expression.empty() && column.default_value.empty()) continue;

    std::vector<std::string> generated_values;
    generated_values.reserve(output_rows.size());
    bool generated_all_rows = true;
    for (const auto& row : output_rows) {
      std::map<std::string, std::string> row_values;
      for (std::size_t i = 0; i < parts->columns.size() && i < row.size(); ++i) {
        row_values[UpperIdentifier(parts->columns[i])] = row[i];
      }
      if (!column.computed_expression.empty()) {
        if (const auto computed = EvaluateFirebirdNumericExpression(column.computed_expression,
                                                                    row_values)) {
          generated_values.push_back(FirebirdFormatNumeric(*computed));
        } else {
          generated_all_rows = false;
          break;
        }
      } else {
        generated_values.push_back(column.default_value);
      }
    }
    if (!generated_all_rows || generated_values.size() != output_rows.size()) continue;
    output_columns.push_back(column.name);
    for (std::size_t row_index = 0; row_index < output_rows.size(); ++row_index) {
      output_rows[row_index].push_back(generated_values[row_index]);
    }
  }
  const auto before_assignments =
      FirebirdBeforeCurrentContextAssignments(state, parts->table_name, "INSERT");
  for (const auto& [column_name, literal_value] : before_assignments) {
    std::optional<std::size_t> existing_index;
    for (std::size_t index = 0; index < output_columns.size(); ++index) {
      if (UpperIdentifier(output_columns[index]) == column_name) {
        existing_index = index;
        break;
      }
    }
    if (!existing_index) {
      output_columns.push_back(column_name);
      existing_index = output_columns.size() - 1;
      for (auto& row : output_rows) row.push_back("NULL");
    }
    for (auto& row : output_rows) {
      if (row.size() <= *existing_index) {
        row.resize(*existing_index + 1, "NULL");
      }
      row[*existing_index] = literal_value;
    }
  }
  std::string out = "INSERT INTO " + parts->table_name + " (";
  for (std::size_t i = 0; i < output_columns.size(); ++i) {
    if (i != 0) out += ", ";
    out += output_columns[i];
  }
  out += ") VALUES ";
  for (std::size_t row_index = 0; row_index < output_rows.size(); ++row_index) {
    if (row_index != 0) out += ", ";
    out += "(";
    for (std::size_t i = 0; i < output_rows[row_index].size(); ++i) {
      if (i != 0) out += ", ";
      out += NormalizeFirebirdInsertCellForCanonical(output_rows[row_index][i]);
    }
    out += ")";
  }
  return out;
}

std::string NormalizeFirebirdUpdateForCanonical(const FirebirdBinarySessionState& state,
                                            std::string_view sql_text) {
  const std::string sql = NormalizeFirebirdDateTimeLiterals(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("UPDATE ")) return sql;
  std::size_t pos = std::string("UPDATE").size();
  std::string raw_table;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_table)) return sql;
  const auto set_pos = FindTopLevelFirebirdWord(sql, "SET", pos);
  if (!set_pos) return sql;
  const auto where_pos = FindTopLevelFirebirdWord(sql, "WHERE", *set_pos + 3);
  const auto rows_pos = FindTopLevelFirebirdWord(sql, "ROWS", *set_pos + 3);
  const auto returning_pos = FindTopLevelFirebirdWord(sql, "RETURNING", *set_pos + 3);
  std::size_t set_end = sql.size();
  if (where_pos) set_end = std::min(set_end, *where_pos);
  if (rows_pos) set_end = std::min(set_end, *rows_pos);
  if (returning_pos) set_end = std::min(set_end, *returning_pos);
  if (set_end <= *set_pos + 3) return sql;

  std::vector<std::pair<std::string, std::string>> assignments;
  const std::string set_clause = TrimAscii(sql.substr(*set_pos + 3,
                                                       set_end - (*set_pos + 3)));
  for (const auto& raw_assignment : SplitTopLevelComma(set_clause)) {
    const auto equals = raw_assignment.find('=');
    if (equals == std::string::npos) {
      return sql;
    }
    assignments.push_back({
        TrimAscii(raw_assignment.substr(0, equals)),
        TrimAscii(raw_assignment.substr(equals + 1))});
  }
  if (assignments.empty()) return sql;
  const auto before_assignments =
      FirebirdBeforeCurrentContextAssignments(state, raw_table, "UPDATE");
  if (before_assignments.empty()) return sql;
  for (const auto& [column_name, literal_value] : before_assignments) {
    bool replaced = false;
    for (auto& assignment : assignments) {
      if (UpperIdentifier(FirebirdLeafIdentifier(assignment.first)) == column_name) {
        assignment.second = literal_value;
        replaced = true;
        break;
      }
    }
    if (!replaced) assignments.push_back({column_name, literal_value});
  }

  std::string out = sql.substr(0, *set_pos + 3) + " ";
  for (std::size_t index = 0; index < assignments.size(); ++index) {
    if (index != 0) out += ", ";
    out += assignments[index].first + " = " + assignments[index].second;
  }
  const std::string tail = sql.substr(set_end);
  if (!tail.empty() && !std::isspace(static_cast<unsigned char>(tail.front()))) {
    out += " ";
  }
  out += tail;
  return out;
}

struct FirebirdBeforeUpdateContext {
  std::string table_name;
  std::string tail_clause;
  std::map<std::string, std::string> assignments;
};

std::optional<FirebirdBeforeUpdateContext> FirebirdBeforeUpdateCurrentContext(
    const FirebirdBinarySessionState& state,
    std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("UPDATE ")) return std::nullopt;
  std::size_t pos = std::string("UPDATE").size();
  std::string raw_table;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_table)) return std::nullopt;
  const auto set_pos = FindTopLevelFirebirdWord(sql, "SET", pos);
  if (!set_pos) return std::nullopt;
  const auto where_pos = FindTopLevelFirebirdWord(sql, "WHERE", *set_pos + 3);
  const auto rows_pos = FindTopLevelFirebirdWord(sql, "ROWS", *set_pos + 3);
  const auto returning_pos = FindTopLevelFirebirdWord(sql, "RETURNING", *set_pos + 3);
  std::size_t tail_pos = sql.size();
  if (where_pos) tail_pos = std::min(tail_pos, *where_pos);
  if (rows_pos) tail_pos = std::min(tail_pos, *rows_pos);
  if (returning_pos) tail_pos = std::min(tail_pos, *returning_pos);
  const auto assignments =
      FirebirdBeforeCurrentContextAssignments(state, raw_table, "UPDATE");
  if (assignments.empty()) return std::nullopt;
  FirebirdBeforeUpdateContext context;
  context.table_name = FirebirdLeafIdentifier(raw_table);
  context.tail_clause = tail_pos < sql.size() ? TrimAscii(sql.substr(tail_pos)) : "";
  context.assignments = assignments;
  if (context.table_name.empty()) return std::nullopt;
  return context;
}

std::string NormalizeFirebirdRedundantNumericBoundsForCanonical(
    std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!TrimAscii(upper).starts_with("SELECT")) return sql;
  const auto from_pos = FindTopLevelFirebirdWord(sql, "FROM", 6);
  if (!from_pos) return sql;
  std::string compact_projection;
  for (const char ch : sql.substr(std::string("SELECT").size(),
                                  *from_pos - std::string("SELECT").size())) {
    if (!std::isspace(static_cast<unsigned char>(ch))) {
      compact_projection.push_back(
          static_cast<char>(std::toupper(static_cast<unsigned char>(ch))));
    }
  }
  if (compact_projection != "COUNT(*)") return sql;

  const auto where_pos = FindTopLevelFirebirdWord(sql, "WHERE", *from_pos + 4);
  if (!where_pos) return sql;
  std::size_t predicate_end = sql.size();
  for (const auto clause : {"GROUP", "HAVING", "ORDER", "PLAN", "ROWS", "FOR",
                            "UNION"}) {
    if (const auto clause_pos =
            FindTopLevelFirebirdWord(sql, clause, *where_pos + 5)) {
      predicate_end = std::min(predicate_end, *clause_pos);
    }
  }
  const std::string where_clause =
      TrimAscii(sql.substr(*where_pos + 5, predicate_end - (*where_pos + 5)));
  const auto predicates = SplitTopLevelAnd(where_clause);
  if (predicates.size() < 2) return sql;

  static const std::regex numeric_comparison(
      R"(^\s*((?:"[^"]+"|[A-Za-z_$][A-Za-z0-9_$]*)(?:\s*\.\s*(?:"[^"]+"|[A-Za-z_$][A-Za-z0-9_$]*))?)\s*(<=|>=|=|<|>)\s*([+-]?[0-9]+)\s*$)",
      std::regex::icase);
  std::string column_expression;
  std::string column_name;
  std::optional<std::int64_t> equality;
  std::optional<std::int64_t> lower_bound;
  std::optional<std::int64_t> upper_bound;
  for (const auto& predicate : predicates) {
    std::smatch match;
    if (!std::regex_match(predicate, match, numeric_comparison)) return sql;
    const std::string predicate_column =
        UpperIdentifier(FirebirdLeafIdentifier(match[1].str()));
    const auto value = ParseSignedText(match[3].str());
    if (predicate_column.empty() || !value) return sql;
    if (column_name.empty()) {
      column_name = predicate_column;
      column_expression = TrimAscii(match[1].str());
    } else if (predicate_column != column_name) {
      return sql;
    }

    const std::string op = match[2].str();
    if (op == "=") {
      if (equality && *equality != *value) return sql;
      equality = *value;
    } else if (op == ">" || op == ">=") {
      if (op == ">" && *value == std::numeric_limits<std::int64_t>::max()) return sql;
      const std::int64_t inclusive = op == ">" ? *value + 1 : *value;
      lower_bound = lower_bound ? std::max(*lower_bound, inclusive) : inclusive;
    } else {
      if (op == "<" && *value == std::numeric_limits<std::int64_t>::min()) return sql;
      const std::int64_t inclusive = op == "<" ? *value - 1 : *value;
      upper_bound = upper_bound ? std::min(*upper_bound, inclusive) : inclusive;
    }
  }

  std::string reduced_predicate;
  if (equality) {
    if ((lower_bound && *equality < *lower_bound) ||
        (upper_bound && *equality > *upper_bound)) {
      return sql;
    }
    reduced_predicate = column_expression + " = " + std::to_string(*equality);
  } else {
    if (!lower_bound || !upper_bound || *lower_bound > *upper_bound) return sql;
    reduced_predicate = column_expression + " BETWEEN " +
                        std::to_string(*lower_bound) + " AND " +
                        std::to_string(*upper_bound);
  }

  std::string out = sql.substr(0, *where_pos + 5) + " " + reduced_predicate;
  if (predicate_end < sql.size()) out += " " + TrimAscii(sql.substr(predicate_end));
  return out;
}

std::string NormalizeFirebirdSqlForCanonical(const FirebirdBinarySessionState& state,
                                         std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(TrimAscii(sql));
  if (upper.starts_with("CREATE TABLE") || upper.starts_with("RECREATE TABLE")) {
    return NormalizeFirebirdCreateTableForCanonical(state, sql);
  }
  if (upper.starts_with("INSERT INTO")) {
    return NormalizeFirebirdInsertForCanonical(state, sql);
  }
  if (auto simple_index = NormalizeFirebirdSimpleCreateIndexForCanonical(sql);
      !simple_index.empty()) {
    return simple_index;
  }
  if (auto computed_index = ParseFirebirdComputedIndex(sql)) {
    const auto canonical_sblr = FirebirdComputedIndexToCanonical(*computed_index);
    if (!canonical_sblr.empty()) return canonical_sblr;
  }
  return NormalizeFirebirdDateTimeLiterals(
      NormalizeFirebirdRedundantNumericBoundsForCanonical(sql));
}

