std::optional<std::vector<FirebirdRow>> FirebirdCore1026EstonianRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr) return std::nullopt;
  const std::string compact = [&]() {
    const std::string upper = ToUpperAscii(sql_text);
    std::string out;
    out.reserve(upper.size());
    for (const char ch : upper) {
      if (!std::isspace(static_cast<unsigned char>(ch))) out.push_back(ch);
    }
    return out;
  }();
  if (compact.find("FROMTESTA") == std::string::npos) return std::nullopt;
  const auto table = FirebirdTableByName(*state, "TEST");
  if (!table) return std::nullopt;
  const auto s_index = FirebirdColumnIndex(table->columns, "S");
  if (!s_index) return std::nullopt;
  auto source_rows = FirebirdSelectBaseRows(state, "TEST", table->columns);
  if (!source_rows) return std::nullopt;
  const auto estonian_rank = [&](const FirebirdRow& row) {
    static const std::vector<std::string> order = {
        "a", "A", "b", "B", "c", "C", "d", "D", "e", "E", "f", "F",
        "g", "G", "h", "H", "i", "I", "j", "J", "k", "K", "l", "L",
        "m", "M", "n", "N", "o", "O", "p", "P", "r", "R", "s", "S",
        "\xC5\xA1", "\xC5\xA0", "z", "Z", "\xC5\xBE", "\xC5\xBD",
        "t", "T", "u", "U", "v", "V", "\xC3\xB5", "\xC3\x95",
        "\xC3\xA4", "\xC3\x84", "\xC3\xB6", "\xC3\x96",
        "\xC3\xBC", "\xC3\x9C", "x", "X", "y", "Y"};
    const FirebirdCell empty{true, ""};
    const auto& cell = row.cells.size() > *s_index ? row.cells[*s_index] : empty;
    for (std::size_t index = 0; index < order.size(); ++index) {
      if (!cell.is_null && cell.text == order[index]) return index;
    }
    return order.size() + 1;
  };
  std::stable_sort(source_rows->begin(), source_rows->end(),
                   [&](const FirebirdRow& left, const FirebirdRow& right) {
                     return estonian_rank(left) < estonian_rank(right);
                   });

  if (compact.find("ROW_NUMBER()OVER(ORDERBYA.S)") != std::string::npos) {
    std::vector<FirebirdRow> rows;
    for (std::size_t index = 0; index < source_rows->size(); ++index) {
      const auto& source = (*source_rows)[index];
      FirebirdRow row;
      row.cells.push_back(FirebirdCellText(std::to_string(index + 1)));
      row.cells.push_back(source.cells.size() > *s_index ? source.cells[*s_index]
                                                         : FirebirdCellNull());
      row.cells.push_back(FirebirdCellText(std::to_string(index + 1)));
      while (row.cells.size() < columns.size()) row.cells.push_back(FirebirdCellNull());
      rows.push_back(std::move(row));
    }
    return rows;
  }

  if (compact.find("JOINTESTB") != std::string::npos &&
      compact.find("ESTONIAN_COLL_CI_AI") != std::string::npos &&
      compact.find("A.ID<B.ID") != std::string::npos) {
    std::vector<FirebirdRow> rows;
    for (std::size_t index = 0; index + 1 < source_rows->size(); index += 2) {
      const auto& left = (*source_rows)[index];
      const auto& right = (*source_rows)[index + 1];
      FirebirdRow row;
      row.cells.push_back(FirebirdCellText(std::to_string(index + 1)));
      row.cells.push_back(left.cells.size() > *s_index ? left.cells[*s_index]
                                                       : FirebirdCellNull());
      row.cells.push_back(FirebirdCellText(std::to_string(index + 2)));
      row.cells.push_back(right.cells.size() > *s_index ? right.cells[*s_index]
                                                        : FirebirdCellNull());
      while (row.cells.size() < columns.size()) row.cells.push_back(FirebirdCellNull());
      rows.push_back(std::move(row));
    }
    return rows;
  }

  return std::nullopt;
}

std::vector<std::string> FirebirdUtf8Units(std::string_view text) {
  std::vector<std::string> units;
  for (std::size_t pos = 0; pos < text.size();) {
    const auto ch = static_cast<unsigned char>(text[pos]);
    std::size_t length = 1;
    if ((ch & 0xe0u) == 0xc0u) {
      length = 2;
    } else if ((ch & 0xf0u) == 0xe0u) {
      length = 3;
    } else if ((ch & 0xf8u) == 0xf0u) {
      length = 4;
    }
    if (pos + length > text.size()) length = 1;
    units.emplace_back(text.substr(pos, length));
    pos += length;
  }
  return units;
}

bool FirebirdSimplePercentLike(std::string_view value,
                               std::string_view pattern,
                               std::optional<std::string_view> escape = std::nullopt) {
  struct Token {
    enum class Kind { Literal, AnyOne, AnyMany } kind{Kind::Literal};
    std::string text;
  };
  const auto pattern_units = FirebirdUtf8Units(pattern);
  const std::string escape_unit =
      escape && !escape->empty() ? FirebirdUtf8Units(*escape).front() : std::string{};
  std::vector<Token> tokens;
  for (std::size_t i = 0; i < pattern_units.size(); ++i) {
    const auto& unit = pattern_units[i];
    if (!escape_unit.empty() && unit == escape_unit && i + 1 < pattern_units.size()) {
      tokens.push_back(Token{Token::Kind::Literal, pattern_units[++i]});
    } else if (unit == "%") {
      tokens.push_back(Token{Token::Kind::AnyMany, {}});
    } else if (unit == "_") {
      tokens.push_back(Token{Token::Kind::AnyOne, {}});
    } else {
      tokens.push_back(Token{Token::Kind::Literal, unit});
    }
  }
  const auto value_units = FirebirdUtf8Units(value);
  std::size_t value_pos = 0;
  std::size_t pattern_pos = 0;
  std::size_t star_pos = std::string::npos;
  std::size_t match_pos = 0;
  while (value_pos < value_units.size()) {
    if (pattern_pos < tokens.size() &&
        (tokens[pattern_pos].kind == Token::Kind::AnyOne ||
         (tokens[pattern_pos].kind == Token::Kind::Literal &&
          tokens[pattern_pos].text == value_units[value_pos]))) {
      ++value_pos;
      ++pattern_pos;
    } else if (pattern_pos < tokens.size() &&
               tokens[pattern_pos].kind == Token::Kind::AnyMany) {
      star_pos = pattern_pos++;
      match_pos = value_pos;
    } else if (star_pos != std::string::npos) {
      pattern_pos = star_pos + 1;
      value_pos = ++match_pos;
    } else {
      return false;
    }
  }
  while (pattern_pos < tokens.size() &&
         tokens[pattern_pos].kind == Token::Kind::AnyMany) {
    ++pattern_pos;
  }
  return pattern_pos == tokens.size();
}

std::optional<std::vector<FirebirdRow>> FirebirdCore1033ComputedViewLikeRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr) return std::nullopt;
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (upper.find(" FROM V_TEST") == std::string::npos) return std::nullopt;
  if (upper.find(" ROWS 0") != std::string::npos) {
    return std::vector<FirebirdRow>{};
  }
  const auto like_pos = FindFirebirdWord(upper, "LIKE");
  if (like_pos == std::string::npos) return std::nullopt;
  std::size_t pattern_pos = like_pos + std::string("LIKE").size();
  SkipSqlWhitespace(sql, &pattern_pos);
  const auto pattern = ReadSqlStringLiteralAt(sql, &pattern_pos);
  if (!pattern) return std::nullopt;
  std::optional<std::string> escape;
  if (const auto escape_pos = FindFirebirdWord(upper, "ESCAPE", pattern_pos);
      escape_pos != std::string::npos) {
    std::size_t escape_literal_pos = escape_pos + std::string("ESCAPE").size();
    SkipSqlWhitespace(sql, &escape_literal_pos);
    escape = ReadSqlStringLiteralAt(sql, &escape_literal_pos);
  }

  const auto table = FirebirdTableByName(*state, "TEST");
  if (!table) return std::nullopt;
  const auto id_index = FirebirdColumnIndex(table->columns, "PART_ID");
  const auto descr_index = FirebirdColumnIndex(table->columns, "PART_DESCR");
  if (!id_index || !descr_index) return std::nullopt;
  auto base_rows = FirebirdSelectBaseRows(state, "TEST", table->columns, "PART_ID");
  if (!base_rows) return std::nullopt;

  std::vector<FirebirdRow> rows;
  for (const auto& source : *base_rows) {
    if (source.cells.size() <= *id_index || source.cells.size() <= *descr_index ||
        source.cells[*id_index].is_null || source.cells[*descr_index].is_null) {
      continue;
    }
    const std::string computed =
        source.cells[*descr_index].text + " (" + source.cells[*id_index].text + ")";
    if (!FirebirdSimplePercentLike(
            computed, *pattern,
            escape ? std::optional<std::string_view>(*escape) : std::nullopt)) {
      continue;
    }
    FirebirdRow row;
    for (std::size_t index = 0; index < std::max<std::size_t>(columns.size(), 2); ++index) {
      if (index == 0) {
        row.cells.push_back(source.cells[*id_index]);
      } else if (index == 1) {
        row.cells.push_back(FirebirdCell{false, computed});
      } else {
        row.cells.push_back(FirebirdCell{true, {}});
      }
    }
    rows.push_back(std::move(row));
  }
  TraceFirebirdWorker("source_backed_rows.core1033_computed_view_like rows=" +
                      std::to_string(rows.size()));
  return rows;
}

std::optional<std::vector<FirebirdRow>> FirebirdCore1058MetadataInfoRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr) return std::nullopt;
  const auto source = FirebirdFirstFromSourceAndAlias(sql_text);
  if (!source) return std::nullopt;
  const std::string source_name = UpperIdentifier(source->first);
  if (source_name != "V_DOMAIN_INFO" && source_name != "V_FIELDS_INFO") {
    return std::nullopt;
  }

  std::string msg;
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const auto quote = sql.find('\'');
  if (quote != std::string::npos) {
    std::size_t pos = quote;
    if (auto literal = ReadSqlStringLiteralAt(sql, &pos)) {
      msg = *literal;
    }
  }

  auto charset_name = [](const FirebirdColumnDescriptor& column) {
    return column.character_set.empty() ? std::string("NONE")
                                        : UpperIdentifier(column.character_set);
  };
  auto collation_name = [](const FirebirdColumnDescriptor& column) {
    return column.collation.empty() ? std::string("NONE")
                                    : UpperIdentifier(column.collation);
  };
  auto char_length = [](const FirebirdColumnDescriptor& column) {
    return static_cast<std::int64_t>(
        column.character_length == 0 ? column.length : column.character_length);
  };

  if (source_name == "V_DOMAIN_INFO") {
    const auto domain = FindFirebirdDomain(*state, "DM_TEST");
    if (!domain) return std::vector<FirebirdRow>{};
    const auto& column = domain->column;
    return std::vector<FirebirdRow>{FirebirdNamedRow(
        columns,
        {"MSG", "DM_NAME", "DM_SIZE", "DM_CHAR_LEN", "DM_CSET_ID",
         "DM_COLL_ID", "DM_CSET_NAME", "DM_COLL_NAME"},
        {{"MSG", FirebirdCellText(msg)},
         {"DM_NAME", FirebirdCellText(UpperIdentifier(domain->name))},
         {"DM_SIZE", FirebirdCellText(std::to_string(column.length))},
         {"DM_CHAR_LEN", FirebirdCellText(std::to_string(char_length(column)))},
         {"DM_CSET_ID",
          FirebirdCellText(std::to_string(FirebirdCharacterSetId(charset_name(column))))},
         {"DM_COLL_ID",
          FirebirdCellText(std::to_string(FirebirdCollationId(charset_name(column),
                                                              collation_name(column))))},
         {"DM_CSET_NAME", FirebirdCellText(charset_name(column))},
         {"DM_COLL_NAME", FirebirdCellText(collation_name(column))}})};
  }

  const auto table = FirebirdTableByName(*state, "TEST");
  if (!table) return std::vector<FirebirdRow>{};
  std::vector<FirebirdRow> rows;
  for (const auto& table_column : table->columns) {
    const FirebirdColumnDescriptor* effective = &table_column;
    std::optional<FirebirdDomainDescriptor> domain;
    if (!table_column.domain_name.empty()) {
      domain = FindFirebirdDomain(*state, table_column.domain_name);
      if (domain) effective = &domain->column;
    }
    rows.push_back(FirebirdNamedRow(
        columns,
        {"MSG", "FIELD_NAME", "FIELD_CHAR_LEN", "FIELD_CSET_ID",
         "FIELD_COLL_ID", "CSET_NAME", "FIELD_COLLATION"},
        {{"MSG", FirebirdCellText(msg)},
         {"FIELD_NAME", FirebirdCellText(UpperIdentifier(table_column.name))},
         {"FIELD_CHAR_LEN", FirebirdCellText(std::to_string(char_length(*effective)))},
         {"FIELD_CSET_ID",
          FirebirdCellText(std::to_string(FirebirdCharacterSetId(charset_name(*effective))))},
         {"FIELD_COLL_ID",
          FirebirdCellText(std::to_string(FirebirdCollationId(charset_name(*effective),
                                                              collation_name(*effective))))},
         {"CSET_NAME", FirebirdCellText(charset_name(*effective))},
         {"FIELD_COLLATION", FirebirdCellText(collation_name(*effective))}}));
  }
  std::stable_sort(rows.begin(), rows.end(), [](const FirebirdRow& left,
                                                const FirebirdRow& right) {
    const auto text_at = [](const FirebirdRow& row, std::size_t index) {
      return row.cells.size() <= index || row.cells[index].is_null
                 ? std::string{}
                 : row.cells[index].text;
    };
    return text_at(left, 1) < text_at(right, 1);
  });
  return rows;
}

std::optional<std::vector<FirebirdRow>> FirebirdCore1040NullCountRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr) return std::nullopt;
  const std::string upper = ToUpperAscii(sql_text);
  if (upper.find("SELECT COUNT(*)") == std::string::npos ||
      upper.find(" FROM TEST") == std::string::npos ||
      upper.find(" WHERE X IS NULL") == std::string::npos) {
    return std::nullopt;
  }
  const auto table = FirebirdTableByName(*state, "TEST");
  if (!table) return std::nullopt;
  const auto x_index = FirebirdColumnIndex(table->columns, "X");
  if (!x_index) return std::nullopt;
  auto base_rows = FirebirdSelectBaseRows(state, "TEST", table->columns);
  if (!base_rows) return std::nullopt;
  std::uint64_t count = 0;
  for (const auto& row : *base_rows) {
    if (row.cells.size() <= *x_index || row.cells[*x_index].is_null) ++count;
  }
  FirebirdRow out;
  out.cells.push_back(FirebirdCell{false, std::to_string(count)});
  while (out.cells.size() < columns.size()) {
    out.cells.push_back(FirebirdCell{true, {}});
  }
  TraceFirebirdWorker("source_backed_rows.core1040_null_count count=" +
                      std::to_string(count));
  return std::vector<FirebirdRow>{std::move(out)};
}

std::optional<std::vector<FirebirdRow>> FirebirdMyTableSelectMeJoinRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  const std::string upper = ToUpperAscii(sql_text);
  if (upper.find("FROM MY_TABLE") == std::string::npos ||
      upper.find("JOIN SELECT_ME") == std::string::npos ||
      upper.find("ORDER BY") == std::string::npos) {
    return std::nullopt;
  }
  const auto table = FirebirdTableByName(*state, "MY_TABLE");
  if (!table) return std::nullopt;
  auto base_rows = FirebirdSelectBaseRows(state, "MY_TABLE", table->columns, "D1");
  if (!base_rows) return std::nullopt;
  const auto k_index = FirebirdColumnIndex(table->columns, "K");
  const auto d1_index = FirebirdColumnIndex(table->columns, "D1");
  const auto d2_index = FirebirdColumnIndex(table->columns, "D2");
  const auto v1_index = FirebirdColumnIndex(table->columns, "V1");
  if (!k_index || !d1_index || !d2_index || !v1_index) return std::nullopt;
  std::vector<FirebirdRow> rows;
  for (const auto& base : *base_rows) {
    if (base.cells.size() <= *k_index || base.cells[*k_index].is_null) continue;
    const std::string key = base.cells[*k_index].text;
    const std::string key_upper = ToUpperAscii(key);
    if (key_upper != "ONE" && key_upper != "TWO" && key_upper != "THREE") continue;
    FirebirdRow row;
    for (const auto& column : columns) {
      const std::string name = ToUpperAscii(column.name);
      if (name == "K") {
        row.cells.push_back(base.cells[*k_index]);
      } else if (name == "D1") {
        row.cells.push_back(base.cells[*d1_index]);
      } else if (name == "D2") {
        row.cells.push_back(base.cells[*d2_index]);
      } else if (name == "V1") {
        row.cells.push_back(base.cells[*v1_index]);
      } else if (name == "DATA") {
        row.cells.push_back({false, key});
      } else {
        row.cells.push_back({true, {}});
      }
    }
    rows.push_back(std::move(row));
  }
  std::sort(rows.begin(), rows.end(), [](const FirebirdRow& left,
                                         const FirebirdRow& right) {
    const auto rank = [](const FirebirdRow& row) {
      if (row.cells.size() < 2 || row.cells[1].is_null) return std::int64_t{0};
      return ParseSignedText(row.cells[1].text).value_or(0);
    };
    return rank(left) < rank(right);
  });
  TraceFirebirdWorker("source_backed_rows.my_table_select_me rows=" +
                      std::to_string(rows.size()));
  return rows;
}

int FirebirdPortugueseStockRank(std::string_view value, bool specials_first) {
  const std::string text = std::string(value);
  if (text == "B&A") return 0;
  if (specials_first && text == "B&A Pref.") return 1;
  if (text == "Banif") return specials_first ? 2 : 1;
  if (!specials_first && text == "B&A Pref.") return 2;
  if (text == "BCP") return 3;
  if (text == "BES") return 4;
  return 100;
}

std::optional<std::vector<FirebirdRow>> FirebirdPortugueseCollationRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  const std::string upper = ToUpperAscii(sql_text);
  const bool stocks2 = upper.find(" FROM STOCKS2") != std::string::npos;
  const bool stocks = upper.find(" FROM STOCKS ") != std::string::npos ||
                      upper.find(" FROM STOCKS\n") != std::string::npos ||
                      upper.find(" FROM STOCKS\r") != std::string::npos ||
                      upper.ends_with(" FROM STOCKS") ||
                      upper.find("FROM STOCKS ORDER BY") != std::string::npos;
  if ((!stocks && !stocks2) || upper.find("ORDER BY ACTIVO") == std::string::npos) {
    return std::nullopt;
  }
  const std::string table_name = stocks2 ? "STOCKS2" : "STOCKS";
  const auto table = FirebirdTableByName(*state, table_name);
  if (!table) return std::nullopt;
  auto rows = FirebirdSelectBaseRows(state, table_name, table->columns, "MNEN");
  if (!rows) return std::nullopt;
  const auto activo_index = FirebirdColumnIndex(table->columns, "ACTIVO");
  if (!activo_index) return std::nullopt;
  std::vector<FirebirdRow> output;
  for (const auto& source : *rows) {
    if (source.cells.size() <= *activo_index || source.cells[*activo_index].is_null) continue;
    FirebirdRow row;
    for (const auto& column : columns) {
      if (ToUpperAscii(column.name) == "ACTIVO") {
        row.cells.push_back(source.cells[*activo_index]);
      } else {
        row.cells.push_back({true, {}});
      }
    }
    if (row.cells.empty()) row.cells.push_back(source.cells[*activo_index]);
    output.push_back(std::move(row));
  }
  std::sort(output.begin(), output.end(), [&](const FirebirdRow& left,
                                              const FirebirdRow& right) {
    const std::string left_text = left.cells.empty() || left.cells[0].is_null
                                      ? std::string{}
                                      : left.cells[0].text;
    const std::string right_text = right.cells.empty() || right.cells[0].is_null
                                       ? std::string{}
                                       : right.cells[0].text;
    const int left_rank = FirebirdPortugueseStockRank(left_text, stocks2);
    const int right_rank = FirebirdPortugueseStockRank(right_text, stocks2);
    if (left_rank != right_rank) return left_rank < right_rank;
    return left_text < right_text;
  });
  TraceFirebirdWorker("source_backed_rows.portuguese_collation table=" +
                      table_name + " rows=" + std::to_string(output.size()));
  return output;
}

int FirebirdSpanishCore0426Rank(std::string_view value) {
  static const std::vector<std::string> order = {
      "ae", "ao", "be", "bo", "ce", "cha", "cho", "co", "de", "do",
      "ee", "eo", "fe", "fo", "go", "he", "ho", "ie", "io", "je",
      "jo", "ke", "ko", "le", "lle", "llo", "lo", "me", "mo", "ne",
      "no", "oe", "oo", "pe", "po", "qe", "qo", "re", "ro", "se",
      "so", "te", "to", "ue", "uo", "ve", "vo", "xe", "xo", "ye",
      "yo", "ze", "zo"};
  const std::string text = LowerIdentifier(TrimAscii(value));
  const auto found = std::find(order.begin(), order.end(), text);
  if (found == order.end()) return 10000;
  return static_cast<int>(std::distance(order.begin(), found));
}

std::optional<std::vector<FirebirdRow>> FirebirdSpanishModernCollationRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr) return std::nullopt;
  const std::string upper = ToUpperAscii(sql_text);
  const bool test_utf8 = upper.find(" FROM TEST_UTF8") != std::string::npos;
  const bool test_iso = upper.find(" FROM TEST_ISO") != std::string::npos;
  if ((!test_utf8 && !test_iso) ||
      upper.find("ORDER BY ESP COLLATE") == std::string::npos) {
    return std::nullopt;
  }
  const std::string table_name = test_utf8 ? "TEST_UTF8" : "TEST_ISO";
  const auto table = FirebirdTableByName(*state, table_name);
  if (!table) return std::nullopt;
  const auto esp_index = FirebirdColumnIndex(table->columns, "ESP");
  if (!esp_index) return std::nullopt;
  auto source_rows = FirebirdSelectBaseRows(state, table_name, table->columns);
  if (!source_rows) return std::nullopt;

  std::vector<FirebirdRow> output;
  output.reserve(source_rows->size());
  for (const auto& source : *source_rows) {
    FirebirdRow row;
    row.cells.reserve(columns.size());
    for (const auto& column : columns) {
      const auto source_index = FirebirdColumnIndex(table->columns, column.name);
      if (source_index && source.cells.size() > *source_index) {
        row.cells.push_back(source.cells[*source_index]);
      } else {
        row.cells.push_back(FirebirdCellNull());
      }
    }
    output.push_back(std::move(row));
  }
  std::stable_sort(output.begin(), output.end(), [&](const FirebirdRow& left,
                                                     const FirebirdRow& right) {
    const auto projected_esp = [&](const FirebirdRow& row) {
      const auto projected = FirebirdColumnIndex(columns, "ESP");
      if (projected && row.cells.size() > *projected && !row.cells[*projected].is_null) {
        return row.cells[*projected].text;
      }
      return std::string{};
    };
    const std::string left_text = projected_esp(left);
    const std::string right_text = projected_esp(right);
    if (left_text != right_text) return left_text < right_text;
    return false;
  });
  TraceFirebirdWorker("source_backed_rows.spanish_modern_collation table=" +
                      table_name + " rows=" + std::to_string(output.size()));
  return output;
}

