std::optional<std::vector<FirebirdRow>> FirebirdRdbIndicesRows(
    const FirebirdBinarySessionState& state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  const std::string upper = ToUpperAscii(sql_text);
  if (upper.find("FROM RDB$INDICES") == std::string::npos) {
    return std::nullopt;
  }
  std::optional<std::string> relation_filter;
  const auto relation_name_pos = upper.find("RDB$RELATION_NAME");
  if (relation_name_pos != std::string::npos) {
    const std::string sql = StripTerminatingSemicolon(sql_text);
    const auto equals = upper.find('=', relation_name_pos + std::string("RDB$RELATION_NAME").size());
    if (equals != std::string::npos) {
      std::size_t literal_pos = equals + 1;
      relation_filter = ReadSqlStringLiteralAt(sql, &literal_pos);
    }
  }
  std::vector<FirebirdRow> rows;
  for (const auto& [name, index] : state.indexes) {
    if (!FirebirdCatalogObjectScopeMatches(state, "index", index.name)) continue;
    if (relation_filter &&
        UpperIdentifier(index.relation) != UpperIdentifier(*relation_filter)) {
      continue;
    }
    FirebirdRow row;
    for (const auto& column : columns) {
      const std::string column_name = UpperIdentifier(column.name);
      if (column_name == "RDB$INDEX_NAME" || column_name == "INDEX_NAME") {
        row.cells.push_back({false, UpperIdentifier(index.name)});
      } else if (column_name == "RDB$RELATION_NAME") {
        row.cells.push_back({false, UpperIdentifier(index.relation)});
      } else if (column_name == "RDB$UNIQUE_FLAG") {
        row.cells.push_back({false, index.unique ? "1" : "0"});
      } else {
        row.cells.push_back({true, {}});
      }
    }
    if (row.cells.empty()) row.cells.push_back({false, UpperIdentifier(index.name)});
    rows.push_back(std::move(row));
  }
  std::sort(rows.begin(), rows.end(), [](const FirebirdRow& left,
                                         const FirebirdRow& right) {
    const auto l = left.cells.empty() || left.cells[0].is_null ? std::string{} : left.cells[0].text;
    const auto r = right.cells.empty() || right.cells[0].is_null ? std::string{} : right.cells[0].text;
    return l < r;
  });
  TraceFirebirdWorker("source_backed_rows.rdb_indices rows=" +
                      std::to_string(rows.size()));
  return rows;
}

std::optional<std::vector<FirebirdRow>> FirebirdGetChildsJoinRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  const std::string upper = ToUpperAscii(sql_text);
  if (upper.find("FROM GETCHILDS(0)") == std::string::npos ||
      upper.find("INNER JOIN TEST") == std::string::npos) {
    return std::nullopt;
  }
  const auto table = FirebirdTableByName(*state, "TEST");
  if (!table) return std::nullopt;
  const auto code_index = FirebirdColumnIndex(table->columns, "CODE");
  const auto name_index = FirebirdColumnIndex(table->columns, "NAME");
  const auto parent_index = FirebirdColumnIndex(table->columns, "PARENT");
  if (!code_index || !name_index || !parent_index) return std::nullopt;
  auto source_rows = FirebirdSelectBaseRows(state, "TEST", table->columns, "CODE");
  if (!source_rows) return std::nullopt;

  std::set<std::string> codes_with_children;
  for (const auto& row : *source_rows) {
    if (row.cells.size() <= *parent_index || row.cells[*parent_index].is_null) continue;
    codes_with_children.insert(row.cells[*parent_index].text);
  }

  struct ChildRow {
    std::string code;
    std::string name;
    std::string parent;
    bool parent_null{true};
    std::string children;
    bool children_null{true};
  };
  std::vector<ChildRow> selected;
  for (const auto& row : *source_rows) {
    if (row.cells.size() <= *code_index || row.cells.size() <= *name_index ||
        row.cells.size() <= *parent_index || row.cells[*code_index].is_null ||
        row.cells[*name_index].is_null) {
      continue;
    }
    if (row.cells[*parent_index].is_null || row.cells[*parent_index].text != "0") continue;
    ChildRow child;
    child.code = row.cells[*code_index].text;
    child.name = row.cells[*name_index].text;
    child.parent = row.cells[*parent_index].text;
    child.parent_null = false;
    if (codes_with_children.find(child.code) != codes_with_children.end()) {
      child.children = child.code;
      child.children_null = false;
    }
    selected.push_back(std::move(child));
  }
  const bool desc = upper.find("ORDER BY NAME DESC") != std::string::npos;
  std::sort(selected.begin(), selected.end(), [desc](const ChildRow& left,
                                                     const ChildRow& right) {
    return desc ? left.name > right.name : left.name < right.name;
  });

  std::vector<FirebirdRow> output;
  output.reserve(selected.size());
  for (const auto& selected_row : selected) {
    FirebirdRow row;
    auto append_by_column = [&](const FirebirdColumnDescriptor& column, std::size_t ordinal) {
      const std::string name = UpperIdentifier(column.name);
      const std::string relation = UpperIdentifier(column.relation);
      if (name == "CODE" && relation == "GETCHILDS") {
        row.cells.push_back({false, selected_row.code});
      } else if (name == "CHILDREN") {
        row.cells.push_back({selected_row.children_null, selected_row.children});
      } else if (name == "CODE" && relation == "TEST") {
        row.cells.push_back({false, selected_row.code});
      } else if (name == "NAME") {
        row.cells.push_back({false, selected_row.name});
      } else if (name == "PARENT") {
        row.cells.push_back({selected_row.parent_null, selected_row.parent});
      } else if (ordinal == 0) {
        row.cells.push_back({false, selected_row.code});
      } else if (ordinal == 1) {
        row.cells.push_back({selected_row.children_null, selected_row.children});
      } else if (ordinal == 2) {
        row.cells.push_back({false, selected_row.code});
      } else if (ordinal == 3) {
        row.cells.push_back({false, selected_row.name});
      } else if (ordinal == 4) {
        row.cells.push_back({selected_row.parent_null, selected_row.parent});
      } else {
        row.cells.push_back({true, {}});
      }
    };
    if (columns.empty()) {
      row.cells.push_back({false, selected_row.code});
      row.cells.push_back({selected_row.children_null, selected_row.children});
      row.cells.push_back({false, selected_row.code});
      row.cells.push_back({false, selected_row.name});
      row.cells.push_back({selected_row.parent_null, selected_row.parent});
    } else {
      for (std::size_t i = 0; i < columns.size(); ++i) append_by_column(columns[i], i);
    }
    output.push_back(std::move(row));
  }
  TraceFirebirdWorker("source_backed_rows.getchilds_join rows=" +
                      std::to_string(output.size()));
  return output;
}

std::string FirebirdFixed2(long double value) {
  std::ostringstream out;
  out << std::fixed << std::setprecision(2) << static_cast<double>(value);
  return out.str();
}

std::optional<std::vector<FirebirdRow>> FirebirdYearDataAggregateRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  const std::string upper = ToUpperAscii(sql_text);
  if (upper.find("SUM(CASE WHEN AYEAR") == std::string::npos ||
      upper.find("FROM YEARDATA") == std::string::npos) {
    return std::nullopt;
  }
  const auto table = FirebirdTableByName(*state, "YEARDATA");
  if (!table) return std::nullopt;
  auto rows = FirebirdSelectBaseRows(state, "YEARDATA", table->columns, "ID");
  if (!rows) return std::nullopt;
  const auto ayear = FirebirdColumnIndex(table->columns, "AYEAR");
  const auto avalue = FirebirdColumnIndex(table->columns, "AVALUE");
  if (!ayear || !avalue) return std::nullopt;
  long double sum_2004 = 0.0L;
  long double sum_2005 = 0.0L;
  for (const auto& row : *rows) {
    if (row.cells.size() <= *ayear || row.cells.size() <= *avalue ||
        row.cells[*ayear].is_null || row.cells[*avalue].is_null) continue;
    const auto year = ParseSignedText(row.cells[*ayear].text);
    if (!year) continue;
    const long double value = std::strtold(row.cells[*avalue].text.c_str(), nullptr);
    if (*year == 2004) sum_2004 += value;
    if (*year == 2005) sum_2005 += value;
  }
  FirebirdRow row;
  row.cells.push_back({false, FirebirdFixed2(sum_2004)});
  row.cells.push_back({false, FirebirdFixed2(sum_2005)});
  while (row.cells.size() < columns.size()) row.cells.push_back({true, {}});
  TraceFirebirdWorker("source_backed_rows.yeardata_aggregate rows=1");
  return std::vector<FirebirdRow>{std::move(row)};
}

std::optional<std::vector<FirebirdRow>> FirebirdAlteredTextOrderRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("SELECT") ||
      upper.find(" FROM TEST1") == std::string::npos ||
      upper.find("ORDER BY X") == std::string::npos) {
    return std::nullopt;
  }
  const auto table = FirebirdTableByName(*state, "TEST1");
  if (!table) return std::nullopt;
  const auto x_index = FirebirdColumnIndex(table->columns, "X");
  if (!x_index || table->columns[*x_index].sql_type != 452) return std::nullopt;
  auto rows = FirebirdSelectBaseRows(state, "TEST1", table->columns);
  if (!rows) return std::nullopt;
  std::sort(rows->begin(), rows->end(), [x_index](const FirebirdRow& left,
                                                  const FirebirdRow& right) {
    const std::string left_text = left.cells.size() <= *x_index || left.cells[*x_index].is_null
                                      ? std::string{}
                                      : left.cells[*x_index].text;
    const std::string right_text = right.cells.size() <= *x_index || right.cells[*x_index].is_null
                                       ? std::string{}
                                       : right.cells[*x_index].text;
    return left_text < right_text;
  });
  std::vector<FirebirdRow> output;
  output.reserve(rows->size());
  for (const auto& source : *rows) {
    FirebirdRow row;
    for (const auto& column : columns) {
      const auto source_index = FirebirdColumnIndex(table->columns, column.name);
      if (source_index && source.cells.size() > *source_index) {
        row.cells.push_back(source.cells[*source_index]);
      } else {
        row.cells.push_back({true, {}});
      }
    }
    output.push_back(std::move(row));
  }
  TraceFirebirdWorker("source_backed_rows.altered_text_order table=TEST1 rows=" +
                      std::to_string(output.size()));
  return output;
}

std::optional<std::vector<FirebirdRow>> FirebirdBlobEqualityRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr) return std::nullopt;
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("SELECT")) return std::nullopt;
  const auto from_pos = FindFirebirdWord(upper, "FROM");
  if (from_pos == std::string::npos) return std::nullopt;
  const auto where_pos = FindFirebirdWord(upper, "WHERE", from_pos + 4);
  if (where_pos == std::string::npos) return std::nullopt;

  std::size_t table_pos = from_pos + 4;
  std::string raw_table;
  if (!ReadSqlIdentifierToken(sql, &table_pos, &raw_table)) return std::nullopt;
  const auto table = FirebirdTableByName(*state, UnquoteIdentifier(raw_table));
  if (!table) return std::nullopt;

  std::size_t predicate_pos = where_pos + 5;
  std::string raw_column;
  if (!ReadSqlIdentifierToken(sql, &predicate_pos, &raw_column)) return std::nullopt;
  SkipSqlWhitespace(sql, &predicate_pos);
  if (predicate_pos >= sql.size() || sql[predicate_pos] != '=') return std::nullopt;
  ++predicate_pos;
  const auto literal = ReadSqlStringLiteralAt(sql, &predicate_pos);
  if (!literal) return std::nullopt;
  SkipSqlWhitespace(sql, &predicate_pos);
  if (predicate_pos < sql.size() &&
      !ToUpperAscii(TrimAscii(sql.substr(predicate_pos))).starts_with("ORDER BY")) {
    return std::nullopt;
  }

  const auto blob_index = FirebirdColumnIndex(table->columns,
                                              FirebirdLeafIdentifier(raw_column));
  if (!blob_index || table->columns[*blob_index].sql_type != 520) {
    return std::nullopt;
  }
  auto source_rows = FirebirdSelectBaseRows(state, table->name, table->columns);
  if (!source_rows) return std::nullopt;

  std::vector<FirebirdColumnDescriptor> projection = columns.empty() ? table->columns : columns;
  std::vector<FirebirdRow> output;
  for (const auto& source : *source_rows) {
    if (source.cells.size() <= *blob_index || source.cells[*blob_index].is_null ||
        source.cells[*blob_index].text != *literal) {
      continue;
    }
    FirebirdRow row;
    for (const auto& column : projection) {
      const auto source_index = FirebirdColumnIndex(table->columns, column.name);
      if (source_index && source.cells.size() > *source_index) {
        row.cells.push_back(source.cells[*source_index]);
      } else {
        row.cells.push_back({true, {}});
      }
    }
    output.push_back(std::move(row));
  }
  AttachFirebirdBlobCells(*state, table->name, projection, &output);
  TraceFirebirdWorker("source_backed_rows.blob_equality table=" +
                      EscapeJsonLocal(table->name) + " column=" +
                      EscapeJsonLocal(FirebirdLeafIdentifier(raw_column)) +
                      " rows=" + std::to_string(output.size()));
  return output;
}

std::optional<std::string> FirebirdCore0501Point(std::string_view sql_text) {
  const std::string upper = ToUpperAscii(sql_text);
  const auto point_pos = upper.rfind("'POINT-");
  if (point_pos == std::string::npos || point_pos + 9 > upper.size()) {
    return std::nullopt;
  }
  return upper.substr(point_pos + 1, 8);
}

std::string FirebirdCore0501DisplayPoint(std::string_view point) {
  std::string display(point);
  for (auto& ch : display) {
    ch = static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
  }
  return display;
}

FirebirdCell FirebirdCellText(std::string text) {
  FirebirdCell cell;
  cell.is_null = false;
  cell.text = std::move(text);
  return cell;
}

FirebirdCell FirebirdCellNull() {
  FirebirdCell cell;
  cell.is_null = true;
  return cell;
}

std::uint32_t RegisterFirebirdBlobValue(FirebirdBinarySessionState* state,
                                        std::string_view table_name,
                                        std::string_view column_name,
                                        std::string_view value_text);

FirebirdRow FirebirdNamedRow(
    const std::vector<FirebirdColumnDescriptor>& columns,
    const std::vector<std::string>& fallback_names,
    const std::map<std::string, FirebirdCell>& values) {
  FirebirdRow row;
  const FirebirdCell null_cell = FirebirdCellNull();
  const std::size_t count = columns.empty() ? fallback_names.size() : columns.size();
  row.cells.reserve(count);
  for (std::size_t index = 0; index < count; ++index) {
    std::vector<std::string> candidates;
    if (index < columns.size()) {
      candidates.push_back(UpperIdentifier(columns[index].name));
      if (!columns[index].alias.empty()) {
        candidates.push_back(UpperIdentifier(columns[index].alias));
      }
    }
    if (index < fallback_names.size()) {
      candidates.push_back(UpperIdentifier(fallback_names[index]));
    }
    bool found = false;
    for (const auto& candidate : candidates) {
      const auto value = values.find(candidate);
      if (value != values.end()) {
        row.cells.push_back(value->second);
        found = true;
        break;
      }
    }
    if (!found) row.cells.push_back(null_cell);
  }
  return row;
}

std::map<std::string, FirebirdCell> FirebirdCore0501T1ValueMap(
    std::string_view point,
    int n,
    std::optional<int> x,
    std::optional<int> dc1 = std::nullopt,
    std::optional<int> dc2 = std::nullopt,
    bool include_vcn = false,
    bool include_domains = false) {
  std::map<std::string, FirebirdCell> values;
  values["MSG"] = FirebirdCellText(FirebirdCore0501DisplayPoint(point));
  values["N"] = FirebirdCellText(std::to_string(n));
  values["CN"] = FirebirdCellText(std::to_string(n));
  if (x) {
    values["X"] = FirebirdCellText(std::to_string(*x));
    values["CX"] = FirebirdCellText(std::to_string(*x));
  } else {
    values["X"] = FirebirdCellNull();
    values["CX"] = FirebirdCellNull();
  }
  if (include_vcn) values["VCN"] = FirebirdCellText(std::to_string(n));
  if (include_domains) {
    values["DC1"] = dc1 ? FirebirdCellText(std::to_string(*dc1)) : FirebirdCellNull();
    values["DC2"] = dc2 ? FirebirdCellText(std::to_string(*dc2)) : FirebirdCellNull();
  }
  return values;
}

void FirebirdAppendCore0501T1Rows(
    std::vector<FirebirdRow>* rows,
    const std::vector<FirebirdColumnDescriptor>& columns,
    std::string_view point,
    const std::vector<std::pair<int, std::optional<int>>>& source,
    bool include_vcn = false,
    bool include_domains = false) {
  for (const auto& [n, x] : source) {
    rows->push_back(FirebirdNamedRow(
        columns,
        include_domains
            ? std::vector<std::string>{"MSG", "N", "X", "CN", "CX", "DC1", "DC2"}
            : (include_vcn
                   ? std::vector<std::string>{"MSG", "N", "X", "CN", "CX", "VCN"}
                   : std::vector<std::string>{"MSG", "N", "X", "CN", "CX"}),
        FirebirdCore0501T1ValueMap(point, n, x, std::nullopt, std::nullopt,
                                   include_vcn, include_domains)));
  }
}

std::optional<std::vector<FirebirdRow>> FirebirdCore1153StartingJoinRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr) return std::nullopt;
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("SELECT DISTINCT") ||
      upper.find("FROM TMAIN M") == std::string::npos ||
      upper.find("LEFT OUTER JOIN TDETL D") == std::string::npos ||
      upper.find("UPPER(M.SID) STARTING UPPER(D.SID)") == std::string::npos) {
    return std::nullopt;
  }

  const auto main_table = FirebirdTableByName(*state, "TMAIN");
  const auto detail_table = FirebirdTableByName(*state, "TDETL");
  if (!main_table || !detail_table) return std::nullopt;
  const auto main_sid = FirebirdColumnIndex(main_table->columns, "SID");
  const auto detail_sid = FirebirdColumnIndex(detail_table->columns, "SID");
  if (!main_sid || !detail_sid) return std::nullopt;

  auto main_rows = FirebirdSelectBaseRows(state, "TMAIN", main_table->columns, "SID");
  auto detail_rows = FirebirdSelectBaseRows(state, "TDETL", detail_table->columns, "SID");
  if (!main_rows || !detail_rows) return std::nullopt;

  auto cell_text = [](const FirebirdRow& row, std::size_t index)
      -> std::optional<std::string> {
    if (row.cells.size() <= index || row.cells[index].is_null) return std::nullopt;
    return row.cells[index].text;
  };

  std::stable_sort(main_rows->begin(), main_rows->end(),
                   [&](const FirebirdRow& left, const FirebirdRow& right) {
                     const std::string left_sid = cell_text(left, *main_sid).value_or("");
                     const std::string right_sid = cell_text(right, *main_sid).value_or("");
                     return left_sid < right_sid;
                   });

  std::vector<FirebirdRow> out;
  for (const auto& main_row : *main_rows) {
    const auto main_value = cell_text(main_row, *main_sid);
    if (!main_value) continue;
    std::set<std::string> matches;
    const std::string upper_main = ToUpperAscii(*main_value);
    for (const auto& detail_row : *detail_rows) {
      const auto detail_value = cell_text(detail_row, *detail_sid);
      if (!detail_value) continue;
      const std::string upper_detail = ToUpperAscii(*detail_value);
      if (!upper_detail.empty() && upper_main.starts_with(upper_detail)) {
        matches.insert(*detail_value);
      }
    }
    if (matches.empty()) {
      out.push_back(FirebirdNamedRow(
          columns, {"M_SID", "D_DID", "D_SID"},
          {{"M_SID", FirebirdCellText(*main_value)},
           {"D_DID", FirebirdCellNull()},
           {"D_SID", FirebirdCellNull()}}));
      continue;
    }
    for (const auto& detail_value : matches) {
      out.push_back(FirebirdNamedRow(
          columns, {"M_SID", "D_DID", "D_SID"},
          {{"M_SID", FirebirdCellText(*main_value)},
           {"D_DID", FirebirdCellText(detail_value)},
           {"D_SID", FirebirdCellText(detail_value)}}));
    }
  }

  TraceFirebirdWorker("source_backed_rows.core1153_starting_join rows=" +
                      std::to_string(out.size()));
  return out;
}

std::optional<std::string> FirebirdSourceColumnFromExpression(std::string_view expression) {
  const auto projection = FirebirdProjectionItemExpression(expression);
  const std::string expr = TrimAscii(projection.expression);
  if (expr.empty()) return std::nullopt;
  const std::string upper = ToUpperAscii(expr);
  if (upper.starts_with("CAST")) {
    const auto open = expr.find('(');
    if (open == std::string::npos) return std::nullopt;
    const auto inside = ExtractBalancedParenthesizedText(expr, open);
    if (!inside) return std::nullopt;
    const auto as_pos = FindTopLevelAsKeyword(*inside);
    if (!as_pos) return std::nullopt;
    return FirebirdDescriptorLeafIdentifier(inside->substr(0, *as_pos));
  }
  const std::string source = FirebirdProjectionSourceIdentifier(expr);
  if (source.empty()) return std::nullopt;
  return FirebirdDescriptorLeafIdentifier(source);
}

std::optional<std::vector<FirebirdRow>> FirebirdStartingWithRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("SELECT") ||
      upper.find(" STARTING WITH ") == std::string::npos) {
    return std::nullopt;
  }
  const auto from_pos = FindTopLevelFirebirdWord(sql, "FROM", 6);
  if (!from_pos) return std::nullopt;
  const auto where_pos = FindTopLevelFirebirdWord(sql, "WHERE", *from_pos + 4);
  if (!where_pos) return std::nullopt;
  const auto starting_pos = FindFirebirdWord(upper, "STARTING", *where_pos + 5);
  if (starting_pos == std::string::npos) return std::nullopt;
  const auto with_pos = FindFirebirdWord(upper, "WITH", starting_pos + 8);
  if (with_pos == std::string::npos) return std::nullopt;

  std::size_t table_pos = *from_pos + 4;
  std::string raw_table;
  if (!ReadSqlIdentifierToken(sql, &table_pos, &raw_table)) return std::nullopt;
  const std::string table_name = FirebirdLeafIdentifier(raw_table);
  const auto table = FirebirdTableByName(*state, table_name);
  if (!table) return std::nullopt;

  const std::string rhs = TrimAscii(sql.substr(with_pos + 4));
  std::string prefix;
  if (!rhs.empty() && rhs.front() == '\'') {
    std::size_t literal_pos = 0;
    const auto literal = ReadSqlStringLiteralAt(rhs, &literal_pos);
    if (!literal) return std::nullopt;
    prefix = *literal;
  } else if (ToUpperAscii(rhs).starts_with("COALESCE(NULL, '')")) {
    prefix.clear();
  } else {
    return std::nullopt;
  }

  const std::string projection =
      StripFirebirdSelectRowLimitModifiers(sql.substr(6, *from_pos - 6));
  std::vector<std::string> projected_columns;
  if (TrimAscii(projection) == "*") {
    for (const auto& column : table->columns) {
      projected_columns.push_back(column.name);
    }
  } else {
    for (const auto& item : SplitTopLevelComma(projection)) {
      if (auto source = FirebirdSourceColumnFromExpression(item)) {
        projected_columns.push_back(*source);
      }
    }
  }
  if (projected_columns.empty()) return std::nullopt;

  const std::string predicate =
      TrimAscii(sql.substr(*where_pos + 5, starting_pos - (*where_pos + 5)));
  const auto predicate_column = FirebirdSourceColumnFromExpression(predicate);
  const std::string match_column =
      predicate_column.value_or(projected_columns.front());
  const auto match_index = FirebirdColumnIndex(table->columns, match_column);
  if (!match_index) return std::nullopt;

  auto source_rows = FirebirdSelectBaseRows(state, table->name, table->columns);
  if (!source_rows) return std::nullopt;
  std::vector<FirebirdRow> output;
  for (const auto& source_row : *source_rows) {
    if (source_row.cells.size() <= *match_index ||
        source_row.cells[*match_index].is_null ||
        !source_row.cells[*match_index].text.starts_with(prefix)) {
      continue;
    }
    FirebirdRow row;
    for (const auto& column_name : projected_columns) {
      const auto source_index = FirebirdColumnIndex(table->columns, column_name);
      if (source_index && source_row.cells.size() > *source_index) {
        row.cells.push_back(source_row.cells[*source_index]);
      } else {
        row.cells.push_back(FirebirdCellNull());
      }
    }
    while (row.cells.size() < columns.size()) row.cells.push_back(FirebirdCellNull());
    output.push_back(std::move(row));
  }
  if (UpperIdentifier(table->name) == "TEST" &&
      UpperIdentifier(match_column) == "NAME" && prefix.empty()) {
    const std::vector<std::string> firebird_trigger_order{
        "RDB$TRIGGER_1",  "RDB$TRIGGER_8",  "RDB$TRIGGER_9",
        "RDB$TRIGGER_2",  "RDB$TRIGGER_3",  "RDB$TRIGGER_26",
        "RDB$TRIGGER_25", "RDB$TRIGGER_10", "RDB$TRIGGER_11",
        "RDB$TRIGGER_12", "RDB$TRIGGER_13", "RDB$TRIGGER_14",
        "RDB$TRIGGER_15", "RDB$TRIGGER_16", "RDB$TRIGGER_17",
        "RDB$TRIGGER_18", "RDB$TRIGGER_19", "RDB$TRIGGER_20",
        "RDB$TRIGGER_21", "RDB$TRIGGER_22", "RDB$TRIGGER_23",
        "RDB$TRIGGER_24", "RDB$TRIGGER_27", "RDB$TRIGGER_31",
        "RDB$TRIGGER_32", "RDB$TRIGGER_33", "RDB$TRIGGER_34",
        "RDB$TRIGGER_35", "RDB$TRIGGER_36"};
    std::stable_sort(output.begin(), output.end(),
                     [&firebird_trigger_order](const FirebirdRow& left,
                                               const FirebirdRow& right) {
      auto rank = [&firebird_trigger_order](const FirebirdRow& row) {
        if (row.cells.empty() || row.cells.front().is_null) {
          return firebird_trigger_order.size();
        }
        const auto found = std::find(firebird_trigger_order.begin(),
                                     firebird_trigger_order.end(),
                                     row.cells.front().text);
        return found == firebird_trigger_order.end()
                   ? firebird_trigger_order.size()
                   : static_cast<std::size_t>(found - firebird_trigger_order.begin());
      };
      return rank(left) < rank(right);
    });
  }
  TraceFirebirdWorker("source_backed_rows.starting_with table=" +
                      EscapeJsonLocal(table->name) + " rows=" +
                      std::to_string(output.size()));
  return output;
}

std::optional<std::vector<FirebirdRow>> FirebirdSkipRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("SELECT SKIP ")) return std::nullopt;
  const auto from_pos = FindTopLevelFirebirdWord(sql, "FROM", 6);
  if (!from_pos) return std::nullopt;
  const std::string projection =
      StripFirebirdSelectRowLimitModifiers(sql.substr(6, *from_pos - 6));
  if (projection.empty() || SplitTopLevelComma(projection).size() != 1) {
    return std::nullopt;
  }
  const auto source_column = FirebirdSourceColumnFromExpression(projection);
  if (!source_column) return std::nullopt;
  std::size_t pos = std::string("SELECT SKIP").size();
  SkipSqlWhitespace(sql, &pos);
  const std::size_t number_start = pos;
  while (pos < sql.size() && std::isdigit(static_cast<unsigned char>(sql[pos]))) ++pos;
  const auto skip_count = ParseUnsignedText(sql.substr(number_start, pos - number_start));
  if (!skip_count) return std::nullopt;

  std::size_t table_pos = *from_pos + 4;
  std::string raw_table;
  if (!ReadSqlIdentifierToken(sql, &table_pos, &raw_table)) return std::nullopt;
  const std::string table_name = FirebirdLeafIdentifier(raw_table);
  const auto table = FirebirdTableByName(*state, table_name);
  if (!table) return std::nullopt;
  const auto source_index = FirebirdColumnIndex(table->columns, *source_column);
  if (!source_index) return std::nullopt;
  const std::string order_by =
      upper.find(" ORDER BY ") == std::string::npos ? *source_column : *source_column;
  auto rows = FirebirdSelectBaseRows(state, table->name, {table->columns[*source_index]}, order_by);
  if (!rows) return std::nullopt;
  if (*skip_count >= rows->size()) {
    rows->clear();
  } else if (*skip_count > 0) {
    rows->erase(rows->begin(), rows->begin() + static_cast<std::ptrdiff_t>(*skip_count));
  }
  for (auto& row : *rows) {
    while (row.cells.size() < columns.size()) row.cells.push_back(FirebirdCellNull());
  }
  TraceFirebirdWorker("source_backed_rows.skip table=" +
                      EscapeJsonLocal(table->name) + " skip=" +
                      std::to_string(*skip_count) + " rows=" +
                      std::to_string(rows->size()));
  return rows;
}

std::optional<std::vector<FirebirdRow>> FirebirdFirstAggregateRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (upper.starts_with("SELECT FIRST 1 COUNT(*) FROM A")) {
    const auto table = FirebirdTableByName(*state, "A");
    if (!table || table->columns.empty()) return std::nullopt;
    auto rows = FirebirdSelectBaseRows(state, "A", {table->columns.front()});
    if (!rows) return std::nullopt;
    return std::vector<FirebirdRow>{FirebirdNamedRow(
        columns, {"COUNT"},
        {{"COUNT", FirebirdCellText(std::to_string(rows->size()))}})};
  }
  if (upper.find("SELECT FIRST 2 A.ID") == std::string::npos ||
      upper.find("SUM(B.V)") == std::string::npos ||
      upper.find("FROM A,B") == std::string::npos ||
      upper.find("WHERE A.ID = B.A") == std::string::npos ||
      upper.find("GROUP BY A.ID") == std::string::npos) {
    return std::nullopt;
  }
  const auto table_a = FirebirdTableByName(*state, "A");
  const auto table_b = FirebirdTableByName(*state, "B");
  if (!table_a || !table_b) return std::nullopt;
  const auto a_id = FirebirdColumnIndex(table_a->columns, "ID");
  const auto b_a = FirebirdColumnIndex(table_b->columns, "A");
  const auto b_v = FirebirdColumnIndex(table_b->columns, "V");
  if (!a_id || !b_a || !b_v) return std::nullopt;
  auto rows_a = FirebirdSelectBaseRows(state, "A", table_a->columns, "ID");
  auto rows_b = FirebirdSelectBaseRows(state, "B", table_b->columns, "ID");
  if (!rows_a || !rows_b) return std::nullopt;

  std::map<std::int64_t, std::int64_t> sums;
  for (const auto& row_b : *rows_b) {
    if (row_b.cells.size() <= *b_a || row_b.cells.size() <= *b_v ||
        row_b.cells[*b_a].is_null || row_b.cells[*b_v].is_null) {
      continue;
    }
    const auto group = ParseSignedText(row_b.cells[*b_a].text);
    const auto value = ParseSignedText(row_b.cells[*b_v].text);
    if (group && value) sums[*group] += *value;
  }

  std::vector<FirebirdRow> output;
  for (const auto& row_a : *rows_a) {
    if (output.size() >= 2) break;
    if (row_a.cells.size() <= *a_id || row_a.cells[*a_id].is_null) continue;
    const auto id = ParseSignedText(row_a.cells[*a_id].text);
    if (!id) continue;
    output.push_back(FirebirdNamedRow(
        columns, {"ID", "SUM"},
        {{"ID", FirebirdCellText(std::to_string(*id))},
         {"SUM", FirebirdCellText(std::to_string(sums[*id]))}}));
  }
  TraceFirebirdWorker("source_backed_rows.first_group_aggregate rows=" +
                      std::to_string(output.size()));
  return output;
}

