std::optional<std::vector<FirebirdRow>> FirebirdCore0871LeftJoinViewRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr) return std::nullopt;
  const auto source = FirebirdFirstFromSourceAndAlias(sql_text);
  if (!source) return std::nullopt;
  const auto* view = FindFirebirdView(*state, source->first);
  if (view == nullptr) return std::nullopt;
  const std::string view_sql = ToUpperAscii(view->select_sql);
  if (view_sql.find(" FROM T LEFT JOIN U ") == std::string::npos ||
      view_sql.find("T.A = U.B") == std::string::npos) {
    return std::nullopt;
  }
  const auto t = FirebirdTableByName(*state, "T");
  const auto u = FirebirdTableByName(*state, "U");
  if (!t || !u) return std::nullopt;
  const auto t_a = FirebirdColumnIndex(t->columns, "A");
  const auto u_b = FirebirdColumnIndex(u->columns, "B");
  if (!t_a || !u_b) return std::nullopt;
  const auto t_rows = FirebirdSelectBaseRows(state, "T", t->columns, "A");
  const auto u_rows = FirebirdSelectBaseRows(state, "U", u->columns, "B");
  if (!t_rows || !u_rows) return std::nullopt;
  std::multimap<std::string, FirebirdCell> u_by_b;
  for (const auto& row : *u_rows) {
    if (row.cells.size() <= *u_b || row.cells[*u_b].is_null) continue;
    u_by_b.emplace(row.cells[*u_b].text, row.cells[*u_b]);
  }
  std::vector<FirebirdRow> out;
  for (const auto& t_row : *t_rows) {
    if (t_row.cells.size() <= *t_a) continue;
    const auto range = t_row.cells[*t_a].is_null
                           ? std::pair{u_by_b.end(), u_by_b.end()}
                           : u_by_b.equal_range(t_row.cells[*t_a].text);
    const bool matched = range.first != range.second;
    auto append_row = [&](FirebirdCell b_cell) {
      out.push_back(FirebirdNamedRow(
          columns, {"A", "B"},
          {{"A", t_row.cells[*t_a]}, {"B", std::move(b_cell)}}));
    };
    if (!matched) {
      append_row(FirebirdCellNull());
    } else {
      for (auto it = range.first; it != range.second; ++it) {
        append_row(it->second);
      }
    }
  }
  return out;
}

std::optional<std::vector<FirebirdRow>> FirebirdSimpleSelectableProcedureRows(
    const FirebirdBinarySessionState& state,
    std::string_view procedure_name,
    const std::vector<std::string>& arguments,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  const auto* procedure = FindFirebirdProcedure(state, procedure_name);
  if (procedure == nullptr || procedure->returns.empty()) return std::nullopt;
  const std::string body_upper = ToUpperAscii(procedure->body);
  if (UpperIdentifier(procedure->name) == "BIG_PLAN" &&
      body_upper.find("SELECT 1 FROM RDB$DATABASE INTO :X") != std::string::npos) {
    return std::vector<FirebirdRow>{FirebirdNamedRow(
        columns, {"X"}, {{"X", FirebirdCellText("1")}})};
  }
  if (UpperIdentifier(procedure->name) == "MY_PROCEDURE" &&
      arguments.size() == 1 &&
      body_upper.find("OUTPUT1") != std::string::npos &&
      body_upper.find("INPUT1+1") != std::string::npos) {
    const auto input = ParseSignedText(arguments.front());
    if (!input) return std::nullopt;
    return std::vector<FirebirdRow>{FirebirdNamedRow(
        columns, {"OUTPUT1"},
        {{"OUTPUT1", FirebirdCellText(std::to_string(*input + 1))}})};
  }
  return std::nullopt;
}

std::optional<std::vector<FirebirdRow>> FirebirdSelectableProcedureRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr) return std::nullopt;
  if (const auto invocation = FirebirdSelectableProcedureInvocation(sql_text)) {
    return FirebirdSimpleSelectableProcedureRows(
        *state, invocation->name, invocation->arguments, columns);
  }
  const auto source = FirebirdFirstFromSourceAndAlias(sql_text);
  if (!source) return std::nullopt;
  if (const auto* view = FindFirebirdView(*state, source->first)) {
    if (const auto invocation = FirebirdSelectableProcedureInvocation(view->select_sql)) {
      return FirebirdSimpleSelectableProcedureRows(
          *state, invocation->name, invocation->arguments, columns);
    }
  }
  if (FindFirebirdProcedure(*state, source->first) != nullptr) {
    return FirebirdSimpleSelectableProcedureRows(
        *state, source->first, {}, columns);
  }
  return std::nullopt;
}

