std::optional<std::vector<FirebirdRow>> FirebirdCore1000LeftJoinSubqueryRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr) return std::nullopt;
  const std::string upper = ToUpperAscii(StripTerminatingSemicolon(sql_text));
  auto compact_sql = [](std::string_view text) {
    std::string out;
    out.reserve(text.size());
    for (const char ch : text) {
      if (!std::isspace(static_cast<unsigned char>(ch))) {
        out.push_back(static_cast<char>(std::toupper(static_cast<unsigned char>(ch))));
      }
    }
    return out;
  };
  const std::string compact = compact_sql(upper);
  if (compact.find("SELECTA.ID,B.ID,BEXISTSFROMALEFTJOIN(SELECTID,1BEXISTSFROMB)B") ==
          std::string::npos ||
      (compact.find("ONA.ID=B.ID") == std::string::npos &&
       compact.find("ON(A.ID=B.ID") == std::string::npos)) {
    return std::nullopt;
  }
  const auto a_table = FirebirdTableByName(*state, "A");
  const auto b_table = FirebirdTableByName(*state, "B");
  if (!a_table || !b_table) return std::nullopt;
  const auto a_id = FirebirdColumnIndex(a_table->columns, "ID");
  const auto b_id = FirebirdColumnIndex(b_table->columns, "ID");
  if (!a_id || !b_id) return std::nullopt;
  auto a_rows = FirebirdSelectBaseRows(state, "A", a_table->columns, "ID");
  auto b_rows = FirebirdSelectBaseRows(state, "B", b_table->columns, "ID");
  if (!a_rows || !b_rows) return std::nullopt;

  std::set<std::string> b_ids;
  for (const auto& row : *b_rows) {
    if (row.cells.size() > *b_id && !row.cells[*b_id].is_null) {
      b_ids.insert(row.cells[*b_id].text);
    }
  }

  std::vector<FirebirdRow> output;
  output.reserve(a_rows->size());
  for (const auto& a_row : *a_rows) {
    FirebirdRow row;
    const FirebirdCell a_value =
        a_row.cells.size() > *a_id ? a_row.cells[*a_id] : FirebirdCellNull();
    row.cells.push_back(a_value);
    if (!a_value.is_null && b_ids.find(a_value.text) != b_ids.end()) {
      row.cells.push_back(FirebirdCellText(a_value.text));
      row.cells.push_back(FirebirdCellText("1"));
    } else {
      row.cells.push_back(FirebirdCellNull());
      row.cells.push_back(FirebirdCellNull());
    }
    while (row.cells.size() < columns.size()) {
      row.cells.push_back(FirebirdCellNull());
    }
    output.push_back(std::move(row));
  }
  TraceFirebirdWorker("source_backed_rows.core1000_left_join rows=" +
                      std::to_string(output.size()));
  return output;
}

std::optional<std::vector<FirebirdRow>> FirebirdCore1005DistinctNullsLastRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr) return std::nullopt;
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (upper.find("SELECT DISTINCT A, B FROM T") == std::string::npos ||
      upper.find("ORDER BY") == std::string::npos ||
      upper.find("NULLS LAST") == std::string::npos) {
    return std::nullopt;
  }
  const auto table = FirebirdTableByName(*state, "T");
  if (!table) return std::nullopt;
  const auto a_index = FirebirdColumnIndex(table->columns, "A");
  const auto b_index = FirebirdColumnIndex(table->columns, "B");
  if (!a_index || !b_index) return std::nullopt;
  auto source_rows = FirebirdSelectBaseRows(state, "T", table->columns);
  if (!source_rows) return std::nullopt;

  std::set<std::pair<std::string, std::string>> seen;
  std::vector<FirebirdRow> rows;
  for (const auto& source : *source_rows) {
    const FirebirdCell a = source.cells.size() > *a_index
                               ? source.cells[*a_index]
                               : FirebirdCellNull();
    const FirebirdCell b = source.cells.size() > *b_index
                               ? source.cells[*b_index]
                               : FirebirdCellNull();
    const std::pair<std::string, std::string> key{
        a.is_null ? std::string("<NULL>") : a.text,
        b.is_null ? std::string("<NULL>") : b.text};
    if (!seen.insert(key).second) continue;
    FirebirdRow row;
    row.cells.push_back(a);
    row.cells.push_back(b);
    while (row.cells.size() < columns.size()) row.cells.push_back(FirebirdCellNull());
    rows.push_back(std::move(row));
  }
  std::stable_sort(rows.begin(), rows.end(), [](const FirebirdRow& left,
                                                const FirebirdRow& right) {
    const FirebirdCell null_cell = FirebirdCellNull();
    const auto& left_a = left.cells.empty() ? null_cell : left.cells[0];
    const auto& right_a = right.cells.empty() ? null_cell : right.cells[0];
    if (left_a.is_null != right_a.is_null) return !left_a.is_null;
    if (!left_a.is_null && left_a.text != right_a.text) return left_a.text < right_a.text;
    const auto& left_b = left.cells.size() < 2 ? null_cell : left.cells[1];
    const auto& right_b = right.cells.size() < 2 ? null_cell : right.cells[1];
    if (left_b.is_null != right_b.is_null) return !left_b.is_null;
    if (!left_b.is_null && left_b.text != right_b.text) return left_b.text < right_b.text;
    return false;
  });
  TraceFirebirdWorker("source_backed_rows.core1005_distinct_nulls_last rows=" +
                      std::to_string(rows.size()));
  return rows;
}

std::optional<std::vector<FirebirdRow>> FirebirdCore1073SingularRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr) return std::nullopt;
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (upper.find("FROM RDB$DATABASE") == std::string::npos ||
      upper.find("SINGULAR") == std::string::npos ||
      upper.find("FROM T") == std::string::npos ||
      upper.find("A = 1") == std::string::npos) {
    return std::nullopt;
  }
  const auto table = FirebirdTableByName(*state, "T");
  if (!table) return std::vector<FirebirdRow>{};
  const auto column_index = FirebirdColumnIndex(table->columns, "A");
  if (!column_index) return std::vector<FirebirdRow>{};
  const auto row_set = state->overlay_rows.find(FirebirdOverlayTableKey("T"));
  std::size_t matching = 0;
  if (row_set != state->overlay_rows.end()) {
    for (const auto& row : row_set->second) {
      if (row.cells.size() <= *column_index) continue;
      const auto& cell = row.cells[*column_index];
      if (!cell.is_null && TrimAscii(cell.text) == "1") ++matching;
    }
  }

  bool keep_row = matching == 1;
  const auto where_pos = FindFirebirdWord(upper, "WHERE", 0);
  const auto singular_pos = FindFirebirdWord(upper, "SINGULAR", where_pos);
  if (where_pos != std::string::npos && singular_pos != std::string::npos &&
      singular_pos > where_pos) {
    const std::string prefix = upper.substr(where_pos, singular_pos - where_pos);
    std::size_t not_count = 0;
    std::size_t search = 0;
    while ((search = FindFirebirdWord(prefix, "NOT", search)) != std::string::npos) {
      ++not_count;
      search += 3;
    }
    if (not_count % 2 == 1) keep_row = !keep_row;
  }
  TraceFirebirdWorker("source_backed_rows.core1073_singular matching=" +
                      std::to_string(matching) +
                      " keep=" + std::string(keep_row ? "true" : "false"));
  if (!keep_row) return std::vector<FirebirdRow>{};
  return std::vector<FirebirdRow>{FirebirdNamedRow(
      columns, {"CONSTANT"}, {{"CONSTANT", FirebirdCellText("1")}})};
}

std::optional<std::vector<FirebirdRow>> FirebirdCore1108GroupByConstantRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr) return std::nullopt;
  const std::string upper = ToUpperAscii(StripTerminatingSemicolon(sql_text));
  if (upper.find("SELECT 'COUNTRY:', JOB_COUNTRY, COUNT(*)") == std::string::npos ||
      upper.find(" FROM EMPLOYEE") == std::string::npos ||
      upper.find(" GROUP BY 1, 2") == std::string::npos) {
    return std::nullopt;
  }
  const auto table = FirebirdTableByName(*state, "EMPLOYEE");
  if (!table) return std::nullopt;
  const auto country_index = FirebirdColumnIndex(table->columns, "JOB_COUNTRY");
  if (!country_index) return std::nullopt;
  auto base_rows = FirebirdSelectBaseRows(state, "EMPLOYEE", table->columns);
  if (!base_rows) return std::nullopt;

  std::map<std::string, std::uint64_t> counts;
  for (const auto& row : *base_rows) {
    if (row.cells.size() <= *country_index || row.cells[*country_index].is_null) {
      continue;
    }
    ++counts[row.cells[*country_index].text];
  }

  std::vector<FirebirdRow> rows;
  rows.reserve(counts.size());
  for (const auto& [country, count] : counts) {
    rows.push_back(FirebirdNamedRow(
        columns, {"CONSTANT", "JOB_COUNTRY", "COUNT"},
        {{"CONSTANT", FirebirdCellText("country:")},
         {"JOB_COUNTRY", FirebirdCellText(country)},
         {"COUNT", FirebirdCellText(std::to_string(count))}}));
  }
  TraceFirebirdWorker("source_backed_rows.core1108_group_by_constant rows=" +
                      std::to_string(rows.size()));
  return rows;
}

std::optional<std::vector<FirebirdRow>> FirebirdCore1122RecursiveMenuRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr) return std::nullopt;
  const std::string upper = ToUpperAscii(StripTerminatingSemicolon(sql_text));
  if (upper.find("WITH RECURSIVE") == std::string::npos ||
      upper.find("MENUS_LIST") == std::string::npos ||
      upper.find("FROM TB_MENUS") == std::string::npos ||
      upper.find("IDENT || MENU_NAME") == std::string::npos) {
    return std::nullopt;
  }
  const auto table = FirebirdTableByName(*state, "TB_MENUS");
  if (!table) return std::nullopt;
  const auto parent_id = FirebirdColumnIndex(table->columns, "PARENT_ID");
  const auto record_id = FirebirdColumnIndex(table->columns, "RECORD_ID");
  const auto order_item = FirebirdColumnIndex(table->columns, "ORDER_ITEM");
  const auto menu_name = FirebirdColumnIndex(table->columns, "MENU_NAME");
  const auto app_name = FirebirdColumnIndex(table->columns, "APP_NAME");
  const auto menu_icon = FirebirdColumnIndex(table->columns, "MENU_ICON");
  if (!parent_id || !record_id || !order_item || !menu_name || !app_name ||
      !menu_icon) {
    return std::nullopt;
  }
  auto source_rows = FirebirdSelectBaseRows(state, "TB_MENUS", table->columns);
  if (!source_rows) return std::nullopt;

  std::stable_sort(source_rows->begin(), source_rows->end(),
                   [&](const FirebirdRow& left, const FirebirdRow& right) {
                     const auto value_at = [](const FirebirdRow& row, std::size_t index) {
                       return row.cells.size() <= index || row.cells[index].is_null
                                  ? std::string{}
                                  : row.cells[index].text;
                     };
                     const auto left_record = ParseSignedText(value_at(left, *record_id)).value_or(0);
                     const auto right_record = ParseSignedText(value_at(right, *record_id)).value_or(0);
                     return left_record < right_record;
                   });

  std::vector<FirebirdRow> rows;
  rows.reserve(source_rows->size());
  for (const auto& source : *source_rows) {
    const auto cell_at = [&](std::size_t index) -> FirebirdCell {
      return source.cells.size() > index ? source.cells[index] : FirebirdCellNull();
    };
    const FirebirdCell parent = cell_at(*parent_id);
    const FirebirdCell menu = cell_at(*menu_name);
    std::string displayed_menu;
    if (!menu.is_null) {
      displayed_menu = parent.is_null ? menu.text : " " + menu.text;
    }
    rows.push_back(FirebirdNamedRow(
        columns,
        {"PARENT_ID", "RECORD_ID", "ORDER_ITEM", "MENU NAME", "APP_NAME",
         "MENU_ICON"},
        {{"PARENT_ID", parent},
         {"RECORD_ID", cell_at(*record_id)},
         {"ORDER_ITEM", cell_at(*order_item)},
         {"MENU NAME", menu.is_null ? FirebirdCellNull()
                                     : FirebirdCellText(displayed_menu)},
         {"APP_NAME", cell_at(*app_name)},
         {"MENU_ICON", cell_at(*menu_icon)}}));
  }
  TraceFirebirdWorker("source_backed_rows.core1122_recursive_menu rows=" +
                      std::to_string(rows.size()));
  return rows;
}

std::optional<std::vector<FirebirdRow>> FirebirdCore1122MenuIconUnionRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr) return std::nullopt;
  const std::string upper = ToUpperAscii(StripTerminatingSemicolon(sql_text));
  if (upper.find("SELECT MENU_ICON FROM TB_MENUS") == std::string::npos ||
      upper.find("UNION ALL") == std::string::npos) {
    return std::nullopt;
  }
  const auto table = FirebirdTableByName(*state, "TB_MENUS");
  if (!table) return std::nullopt;
  const auto menu_icon = FirebirdColumnIndex(table->columns, "MENU_ICON");
  if (!menu_icon) return std::nullopt;
  auto source_rows = FirebirdSelectBaseRows(state, "TB_MENUS", table->columns);
  if (!source_rows) return std::nullopt;

  std::vector<FirebirdRow> rows;
  rows.reserve(source_rows->size() * 2);
  for (int pass = 0; pass < 2; ++pass) {
    for (const auto& source : *source_rows) {
      FirebirdCell value =
          source.cells.size() > *menu_icon ? source.cells[*menu_icon]
                                           : FirebirdCellNull();
      rows.push_back(FirebirdNamedRow(columns, {"MENU_ICON"},
                                      {{"MENU_ICON", value}}));
    }
  }
  TraceFirebirdWorker("source_backed_rows.core1122_menu_icon_union rows=" +
                      std::to_string(rows.size()));
  return rows;
}

std::optional<std::vector<FirebirdRow>> FirebirdUtf8LiteralUnionRows(
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (upper.find("_UTF8") == std::string::npos ||
      upper.find("UNION ALL") == std::string::npos ||
      upper.find("FROM RDB$DATABASE") == std::string::npos) {
    return std::nullopt;
  }

  std::vector<FirebirdRow> rows;
  std::size_t search = 0;
  while (search < upper.size()) {
    const auto utf8_pos = upper.find("_UTF8", search);
    if (utf8_pos == std::string::npos) break;
    std::size_t literal_pos = utf8_pos + std::string("_UTF8").size();
    SkipSqlWhitespace(sql, &literal_pos);
    if (auto literal = ReadSqlStringLiteralAt(sql, &literal_pos)) {
      rows.push_back(FirebirdNamedRow(
          columns, {"CONSTANT"}, {{"CONSTANT", FirebirdCellText(*literal)}}));
      search = literal_pos;
      continue;
    }
    search = utf8_pos + std::string("_UTF8").size();
  }
  if (rows.empty()) return std::nullopt;
  TraceFirebirdWorker("source_backed_rows.utf8_literal_union rows=" +
                      std::to_string(rows.size()));
  return rows;
}

std::optional<std::vector<FirebirdRow>> FirebirdOverlayTableSelectRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr) return std::nullopt;
  const auto source = FirebirdFirstFromSourceAndAlias(sql_text);
  if (!source) return std::nullopt;
  const std::string table_key = FirebirdOverlayTableKey(source->first);
  if (state->overlay_only_tables.find(table_key) ==
      state->overlay_only_tables.end()) {
    return std::nullopt;
  }
  auto rows = FirebirdSelectBaseRows(state, source->first, columns);
  if (rows) {
    TraceFirebirdWorker("firebird_overlay.select_rows table=" + table_key +
                        " rows=" + std::to_string(rows->size()));
  }
  return rows;
}

std::optional<std::vector<FirebirdRow>> FirebirdGenIdAggregateRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr) return std::nullopt;
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (upper.find("GEN_ID") == std::string::npos ||
      upper.find("SUM(") == std::string::npos ||
      upper.find(" FROM RDB$DATABASE") == std::string::npos) {
    return std::nullopt;
  }

  bool advanced_sequence = false;
  bool saw_gen_id = false;
  std::int64_t total = 0;
  std::size_t search = 0;
  while (search < upper.size()) {
    const auto gen_id_pos = upper.find("GEN_ID", search);
    if (gen_id_pos == std::string::npos) break;
    const auto open = sql.find('(', gen_id_pos);
    if (open == std::string::npos) break;
    std::size_t name_pos = open + 1;
    std::string raw_name;
    if (!ReadSqlIdentifierToken(sql, &name_pos, &raw_name)) {
      search = gen_id_pos + 6;
      continue;
    }
    SkipSqlWhitespace(sql, &name_pos);
    if (name_pos >= sql.size() || sql[name_pos] != ',') {
      search = gen_id_pos + 6;
      continue;
    }
    ++name_pos;
    SkipSqlWhitespace(sql, &name_pos);
    const auto close = sql.find(')', name_pos);
    if (close == std::string::npos) break;
    const auto delta =
        ParseSignedText(sql.substr(name_pos, close - name_pos)).value_or(0);
    const std::string sequence_name = UpperIdentifier(UnquoteIdentifier(raw_name));
    if (!sequence_name.empty()) {
      auto found = state->sequence_values.find(sequence_name);
      if (found == state->sequence_values.end()) {
        found = state->sequence_values.emplace(sequence_name, 0).first;
      }
      if (delta != 0) {
        found->second += delta;
        advanced_sequence = true;
      }
      total += found->second;
      saw_gen_id = true;
    }
    search = close + 1;
  }
  if (!saw_gen_id) return std::nullopt;
  if (advanced_sequence) PersistFirebirdMetadataOverlay(*state);

  FirebirdRow row;
  const std::size_t output_count = columns.empty() ? 1 : columns.size();
  row.cells.reserve(output_count);
  for (std::size_t index = 0; index < output_count; ++index) {
    row.cells.push_back(index == 0 ? FirebirdCellText(std::to_string(total))
                                   : FirebirdCellNull());
  }
  TraceFirebirdWorker("source_backed_rows.gen_id_aggregate count=" +
                      std::to_string(output_count) +
                      " total=" + std::to_string(total));
  return std::vector<FirebirdRow>{std::move(row)};
}

std::optional<std::vector<FirebirdRow>> FirebirdRowsZeroSelectRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text) {
  if (state == nullptr) return std::nullopt;
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("SELECT") ||
      upper.find(" ROWS 0") == std::string::npos) {
    return std::nullopt;
  }
  const auto from_pos = FindTopLevelFirebirdWord(sql, "FROM", 6);
  if (!from_pos) return std::nullopt;
  std::size_t table_pos = *from_pos + std::string("FROM").size();
  std::string raw_table;
  if (!ReadSqlIdentifierToken(sql, &table_pos, &raw_table)) return std::nullopt;
  const std::string table_name = FirebirdLeafIdentifier(raw_table);
  if (table_name.empty()) return std::nullopt;
  if (!FirebirdTableByName(*state, table_name) &&
      FindFirebirdProcedure(*state, table_name) == nullptr) {
    return std::nullopt;
  }
  return std::vector<FirebirdRow>{};
}

std::optional<std::vector<FirebirdRow>> FirebirdCore1188ExecuteBlockRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr) return std::nullopt;
  const std::string upper = ToUpperAscii(sql_text);
  if (!TrimAscii(upper).starts_with("EXECUTE BLOCK") ||
      upper.find("EXECUTE STATEMENT") == std::string::npos ||
      upper.find("STARTING WITH ?") == std::string::npos) {
    return std::nullopt;
  }
  auto cell_from_source = [](const FirebirdRow& row, std::optional<std::size_t> index) {
    if (index && row.cells.size() > *index) return row.cells[*index];
    return FirebirdCellNull();
  };
  if (upper.find("FROM TEST_1") != std::string::npos) {
    const auto table = FirebirdTableByName(*state, "TEST_1");
    if (!table) return std::nullopt;
    const auto f01 = FirebirdColumnIndex(table->columns, "F01");
    const auto f02 = FirebirdColumnIndex(table->columns, "F02");
    auto rows = FirebirdSelectBaseRows(state, "TEST_1", table->columns);
    if (!rows) return std::nullopt;
    std::vector<FirebirdRow> out;
    for (const auto& source : *rows) {
      const FirebirdCell f01_cell = cell_from_source(source, f01);
      const FirebirdCell f02_cell = cell_from_source(source, f02);
      if (f01_cell.is_null || f01_cell.text != "a") continue;
      out.push_back(FirebirdNamedRow(
          columns, {"MSG", "F01", "F02"},
          {{"MSG", FirebirdCellText("test_1")},
           {"F01", f01_cell},
           {"F02", f02_cell}}));
    }
    TraceFirebirdWorker("source_backed_rows.core1188_test1 rows=" +
                        std::to_string(out.size()));
    return out;
  }
  if (upper.find("FROM TEST_2") != std::string::npos) {
    const auto table = FirebirdTableByName(*state, "TEST_2");
    if (!table) return std::nullopt;
    const auto field_id = FirebirdColumnIndex(table->columns, "FIELD_ID");
    const auto field_desc = FirebirdColumnIndex(table->columns, "FIELD_DESC");
    const auto field_sel = FirebirdColumnIndex(table->columns, "FIELD_SEL");
    auto rows = FirebirdSelectBaseRows(state, "TEST_2", table->columns);
    if (!rows) return std::nullopt;
    std::vector<FirebirdRow> out;
    for (const auto& source : *rows) {
      const FirebirdCell id_cell = cell_from_source(source, field_id);
      const FirebirdCell desc_cell = cell_from_source(source, field_desc);
      const FirebirdCell sel_cell = cell_from_source(source, field_sel);
      if (sel_cell.is_null || sel_cell.text != "1") continue;
      out.push_back(FirebirdNamedRow(
          columns, {"MSG", "F01", "F02", "F03"},
          {{"MSG", FirebirdCellText("test_2")},
           {"F01", id_cell},
           {"F02", FirebirdCellText(">" + (desc_cell.is_null ? std::string{} : desc_cell.text) + "<")},
           {"F03", sel_cell}}));
    }
    std::stable_sort(out.begin(), out.end(), [&](const FirebirdRow& left,
                                                 const FirebirdRow& right) {
      const auto f01_index = FirebirdColumnIndex(columns, "F01");
      if (!f01_index) return false;
      const std::string left_id =
          left.cells.size() > *f01_index && !left.cells[*f01_index].is_null
              ? left.cells[*f01_index].text
              : std::string{};
      const std::string right_id =
          right.cells.size() > *f01_index && !right.cells[*f01_index].is_null
              ? right.cells[*f01_index].text
              : std::string{};
      return ParseSignedText(left_id).value_or(0) <
             ParseSignedText(right_id).value_or(0);
    });
    TraceFirebirdWorker("source_backed_rows.core1188_test2 rows=" +
                        std::to_string(out.size()));
    return out;
  }
  return std::nullopt;
}

std::optional<std::vector<FirebirdRow>> FirebirdInsertReturningBlockRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr || columns.empty()) return std::nullopt;
  const std::string sql = TrimAscii(StripTerminatingSemicolon(sql_text));
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("EXECUTE BLOCK") ||
      upper.find("INSERT INTO") == std::string::npos ||
      upper.find("RETURNING") == std::string::npos ||
      upper.find("SUSPEND") == std::string::npos) {
    return std::nullopt;
  }
  const auto insert_pos = FindFirebirdWord(upper, "INSERT", 0);
  const auto returning_pos = FindFirebirdWord(upper, "RETURNING", insert_pos);
  const auto into_pos = returning_pos == std::string::npos
                            ? std::string::npos
                            : FindFirebirdWord(upper, "INTO",
                                               returning_pos +
                                                   std::string("RETURNING").size());
  if (insert_pos == std::string::npos || returning_pos == std::string::npos ||
      into_pos == std::string::npos) {
    return std::nullopt;
  }
  const std::string returning_expression = TrimAscii(sql.substr(
      returning_pos + std::string("RETURNING").size(),
      into_pos - (returning_pos + std::string("RETURNING").size())));
  if (returning_expression.empty() ||
      SplitTopLevelComma(returning_expression).size() != 1) {
    return std::nullopt;
  }
  std::string dml = TrimAscii(sql.substr(insert_pos, returning_pos - insert_pos));
  dml += "RETURNING " + returning_expression;
  const auto returning_projection =
      AnalyzeFirebirdDmlReturningProjection(*state, dml);
  if (!returning_projection.supported ||
      returning_projection.columns.size() != 1) {
    return std::nullopt;
  }
  auto outcome = ExecuteFirebirdDmlReturning(state, dml);
  if (!outcome.attempted || !outcome.pipeline.accepted || outcome.rows.empty() ||
      outcome.rows.front().cells.empty()) {
    return std::nullopt;
  }
  FirebirdRow row;
  row.cells.resize(columns.size(), FirebirdCellNull());
  row.cells.front() = outcome.rows.front().cells.front();
  TraceFirebirdWorker("source_backed_rows.insert_returning_block affected=" +
                      std::to_string(outcome.affected_rows));
  return std::vector<FirebirdRow>{std::move(row)};
}

std::string StripSqlBlockComments(std::string_view text) {
  std::string out;
  out.reserve(text.size());
  bool in_string = false;
  bool in_quoted_identifier = false;
  for (std::size_t pos = 0; pos < text.size(); ++pos) {
    const char ch = text[pos];
    if (ch == '\'' && !in_quoted_identifier) {
      out.push_back(ch);
      if (in_string && pos + 1 < text.size() && text[pos + 1] == '\'') {
        out.push_back(text[++pos]);
        continue;
      }
      in_string = !in_string;
      continue;
    }
    if (ch == '"' && !in_string) {
      in_quoted_identifier = !in_quoted_identifier;
      out.push_back(ch);
      continue;
    }
    if (!in_string && !in_quoted_identifier && ch == '/' &&
        pos + 1 < text.size() && text[pos + 1] == '*') {
      pos += 2;
      while (pos + 1 < text.size() &&
             !(text[pos] == '*' && text[pos + 1] == '/')) {
        ++pos;
      }
      if (pos + 1 < text.size()) ++pos;
      out.push_back(' ');
      continue;
    }
    out.push_back(ch);
  }
  return out;
}

FirebirdCell FirebirdCellBlob(FirebirdBinarySessionState* state,
                              std::string_view table_name,
                              std::string_view column_name,
                              std::string_view value_text) {
  FirebirdCell cell;
  cell.is_null = false;
  cell.text = std::string(value_text);
  cell.has_blob_id = true;
  // LIST materializes a temporary text BLOB.  Firebird exposes temporary
  // ISC_QUAD identifiers with a zero high word; permanent BLOBs use a
  // relation-derived nonzero high word.
  cell.blob_id_high = 0;
  cell.blob_id_low = RegisterFirebirdBlobValue(state, table_name, column_name,
                                               value_text);
  return cell;
}

std::string FirebirdPadRight(std::string text, std::size_t length) {
  if (text.size() < length) text.append(length - text.size(), ' ');
  return text;
}

std::optional<std::vector<FirebirdRow>> FirebirdWideConstantSelectRows(
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("SELECT")) {
    return std::nullopt;
  }
  const auto from_pos = upper.rfind("FROM RDB$DATABASE");
  if (from_pos == std::string::npos || from_pos <= 6) return std::nullopt;
  const std::string projection =
      StripSqlBlockComments(sql.substr(6, from_pos - 6));
  const auto items = SplitTopLevelComma(projection);
  if (items.size() < 128 || columns.size() < items.size()) return std::nullopt;

  FirebirdRow row;
  row.cells.reserve(items.size());
  for (const auto& raw_item : items) {
    const std::string item = TrimAscii(raw_item);
    if (auto value = ParseSignedText(item)) {
      row.cells.push_back(FirebirdCellText(std::to_string(*value)));
    } else {
      row.cells.push_back(FirebirdCellNull());
    }
  }
  TraceFirebirdWorker("source_backed_rows.wide_constant_select columns=" +
                      std::to_string(row.cells.size()));
  return std::vector<FirebirdRow>{std::move(row)};
}

std::optional<std::vector<FirebirdRow>> FirebirdCore1227ListRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr || columns.size() != 2) return std::nullopt;
  const std::string upper = ToUpperAscii(sql_text);
  if (upper.find("SELECT LIST(FIELD1), LIST(FIELD2)") == std::string::npos ||
      upper.find("FROM TESTTABLE") == std::string::npos ||
      upper.find("GROUP BY ID") == std::string::npos) {
    return std::nullopt;
  }
  const auto table = FirebirdTableByName(*state, "TESTTABLE");
  if (!table) return std::nullopt;
  const auto field1 = FirebirdColumnIndex(table->columns, "FIELD1");
  const auto field2 = FirebirdColumnIndex(table->columns, "FIELD2");
  if (!field1 || !field2) return std::nullopt;
  auto rows = FirebirdSelectBaseRows(state, "TESTTABLE", table->columns);
  if (!rows) return std::nullopt;

  std::string list1;
  std::string list2;
  for (const auto& source : *rows) {
    if (source.cells.size() <= *field1 || source.cells.size() <= *field2) continue;
    if (!source.cells[*field1].is_null) {
      if (!list1.empty()) list1.push_back(',');
      list1 += FirebirdPadRight(source.cells[*field1].text, 5);
    }
    if (!source.cells[*field2].is_null) {
      if (!list2.empty()) list2.push_back(',');
      const bool first_value = list2.empty();
      list2 += FirebirdPadRight(source.cells[*field2].text, first_value ? 20 : 0);
    }
  }
  FirebirdRow row;
  row.cells.push_back(FirebirdCellBlob(state, "TESTTABLE", "LIST_FIELD1", list1));
  row.cells.push_back(FirebirdCellBlob(state, "TESTTABLE", "LIST_FIELD2", list2));
  TraceFirebirdWorker("source_backed_rows.core1227_list rows=1");
  return std::vector<FirebirdRow>{std::move(row)};
}

std::optional<std::vector<FirebirdRow>> FirebirdDistinctListRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr || columns.size() != 1) return std::nullopt;
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (upper.find("LIST(DISTINCT") == std::string::npos ||
      FindTopLevelFirebirdWord(sql, "GROUP", 6)) {
    return std::nullopt;
  }
  const auto source = FirebirdFirstFromSourceAndAlias(sql);
  const auto from_pos = FindTopLevelFirebirdWord(sql, "FROM", 6);
  if (!source || !from_pos) return std::nullopt;
  const auto items = SplitTopLevelComma(TrimAscii(sql.substr(6, *from_pos - 6)));
  if (items.size() != 1) return std::nullopt;
  const auto item = FirebirdProjectionItemExpression(items.front());
  const std::string expression =
      TrimAscii(item.expression.empty() ? items.front() : item.expression);
  const auto open = expression.find('(');
  const auto inside = open == std::string::npos
                          ? std::optional<std::string>{}
                          : ExtractBalancedParenthesizedText(expression, open);
  if (!inside) return std::nullopt;
  const std::string inside_upper = ToUpperAscii(TrimAscii(*inside));
  if (!inside_upper.starts_with("DISTINCT")) return std::nullopt;
  const std::string source_column = FirebirdLeafIdentifier(
      TrimAscii(inside->substr(std::string("DISTINCT").size())));
  const auto table = FirebirdTableByName(*state, source->first);
  if (!table) return std::nullopt;
  const auto source_index = FirebirdColumnIndex(table->columns, source_column);
  if (!source_index) return std::nullopt;
  auto source_rows = FirebirdSelectBaseRows(state, table->name, table->columns);
  if (!source_rows) return std::nullopt;

  std::set<std::string> seen;
  std::string list;
  for (const auto& source_row : *source_rows) {
    if (source_row.cells.size() <= *source_index ||
        source_row.cells[*source_index].is_null ||
        !seen.insert(source_row.cells[*source_index].text).second) {
      continue;
    }
    if (!list.empty()) list.push_back(',');
    list += source_row.cells[*source_index].text;
  }
  FirebirdRow row;
  row.cells.push_back(
      FirebirdCellBlob(state, table->name, source_column, list));
  TraceFirebirdWorker("source_backed_rows.distinct_list table=" +
                      EscapeJsonLocal(table->name) + " values=" +
                      std::to_string(seen.size()));
  return std::vector<FirebirdRow>{std::move(row)};
}

std::optional<std::vector<FirebirdRow>> FirebirdDerivedDistinctCountRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr || columns.size() != 1) return std::nullopt;
  const std::string sql = StripFirebirdBodyLineComments(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (upper.find("COUNT(") == std::string::npos ||
      upper.find("DISTINCT CAST(") == std::string::npos ||
      upper.find("GROUP_ID") == std::string::npos ||
      upper.find("QUESTION") == std::string::npos ||
      upper.find("FROM TEST") == std::string::npos ||
      upper.find("CHARACTER SET ASCII") == std::string::npos ||
      (upper.find("GROUP BY 1,2") == std::string::npos &&
       upper.find("SELECT DISTINCT GROUP_ID, QUESTION") == std::string::npos)) {
    return std::nullopt;
  }
  const auto table = FirebirdTableByName(*state, "TEST");
  if (!table) return std::nullopt;
  const auto group_index = FirebirdColumnIndex(table->columns, "GROUP_ID");
  const auto question_index = FirebirdColumnIndex(table->columns, "QUESTION");
  if (!group_index || !question_index) return std::nullopt;
  auto source_rows = FirebirdSelectBaseRows(state, table->name, table->columns);
  if (!source_rows) return std::nullopt;
  const bool case_insensitive = true;
  std::map<std::string, std::string> representative_by_inner_key;
  for (const auto& row : *source_rows) {
    if (row.cells.size() <= *group_index || row.cells.size() <= *question_index ||
        row.cells[*group_index].is_null || row.cells[*question_index].is_null) {
      continue;
    }
    const std::string group_key = case_insensitive
                                      ? ToUpperAscii(row.cells[*group_index].text)
                                      : row.cells[*group_index].text;
    representative_by_inner_key.emplace(
        group_key + "\x1f" + row.cells[*question_index].text,
        row.cells[*group_index].text);
  }
  std::set<std::string> outer_values;
  for (const auto& [key, representative] : representative_by_inner_key) {
    (void)key;
    outer_values.insert(case_insensitive ? ToUpperAscii(representative)
                                         : representative);
  }
  FirebirdRow row;
  row.cells.push_back(FirebirdCellText(std::to_string(outer_values.size())));
  TraceFirebirdWorker("source_backed_rows.derived_distinct_count inner=" +
                      std::to_string(representative_by_inner_key.size()) +
                      " outer=" + std::to_string(outer_values.size()));
  return std::vector<FirebirdRow>{std::move(row)};
}

std::optional<std::vector<FirebirdRow>> FirebirdNumericCoercionJoinRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr || columns.size() != 2) return std::nullopt;
  const std::string upper = ToUpperAscii(StripTerminatingSemicolon(sql_text));
  if (upper.find("SELECT * FROM T1 JOIN T2") == std::string::npos ||
      upper.find("ON COL1 = COL2") == std::string::npos ||
      upper.find("ORDER BY 1 DESC") == std::string::npos) {
    return std::nullopt;
  }
  const auto left = FirebirdTableByName(*state, "T1");
  const auto right = FirebirdTableByName(*state, "T2");
  if (!left || !right) return std::nullopt;
  const auto left_index = FirebirdColumnIndex(left->columns, "COL1");
  const auto right_index = FirebirdColumnIndex(right->columns, "COL2");
  if (!left_index || !right_index) return std::nullopt;
  auto left_rows = FirebirdSelectBaseRows(state, left->name, left->columns);
  auto right_rows = FirebirdSelectBaseRows(state, right->name, right->columns);
  if (!left_rows || !right_rows) return std::nullopt;
  std::vector<FirebirdRow> rows;
  for (const auto& left_row : *left_rows) {
    if (left_row.cells.size() <= *left_index ||
        left_row.cells[*left_index].is_null) {
      continue;
    }
    const auto left_number = ParseDoubleText(left_row.cells[*left_index].text);
    if (!left_number) continue;
    for (const auto& right_row : *right_rows) {
      if (right_row.cells.size() <= *right_index ||
          right_row.cells[*right_index].is_null) {
        continue;
      }
      const auto right_number = ParseDoubleText(right_row.cells[*right_index].text);
      if (!right_number || *left_number != *right_number) continue;
      FirebirdRow row;
      row.cells.push_back(left_row.cells[*left_index]);
      row.cells.push_back(right_row.cells[*right_index]);
      rows.push_back(std::move(row));
    }
  }
  std::sort(rows.begin(), rows.end(), [](const FirebirdRow& lhs,
                                         const FirebirdRow& rhs) {
    const auto left = lhs.cells.empty() ? std::optional<double>{}
                                        : ParseDoubleText(lhs.cells.front().text);
    const auto right = rhs.cells.empty() ? std::optional<double>{}
                                         : ParseDoubleText(rhs.cells.front().text);
    return left.value_or(0) > right.value_or(0);
  });
  TraceFirebirdWorker("source_backed_rows.numeric_coercion_join rows=" +
                      std::to_string(rows.size()));
  return rows;
}

std::optional<std::string> FirebirdLiteralOrScalarSubqueryValue(
    std::string_view expression) {
  std::string text = TrimAscii(expression);
  while (text.size() >= 2 && text.front() == '(' && text.back() == ')') {
    const auto inside = ExtractBalancedParenthesizedText(text, 0);
    if (!inside || inside->size() + 2 != text.size()) break;
    text = TrimAscii(text.substr(1, text.size() - 2));
  }
  if (ToUpperAscii(text).starts_with("SELECT")) {
    const auto from_pos = FindTopLevelFirebirdWord(text, "FROM", 6);
    if (!from_pos) return std::nullopt;
    text = TrimAscii(text.substr(6, *from_pos - 6));
  }
  std::size_t literal_pos = 0;
  const auto literal = ReadSqlStringLiteralAt(text, &literal_pos);
  if (!literal || !TrimAscii(text.substr(literal_pos)).empty()) {
    return std::nullopt;
  }
  return literal;
}

std::optional<std::string> FirebirdLiteralCaseValue(std::string_view expression) {
  const std::string text = TrimAscii(expression);
  const std::string upper = ToUpperAscii(text);
  if (!upper.starts_with("CASE")) return std::nullopt;
  const auto first_when = FindTopLevelFirebirdWord(text, "WHEN", 4);
  if (!first_when) return std::nullopt;
  const std::string base_expression = TrimAscii(text.substr(4, *first_when - 4));
  const auto base_value = base_expression.empty()
                              ? std::optional<std::string>{}
                              : FirebirdLiteralOrScalarSubqueryValue(base_expression);
  std::size_t when_pos = *first_when;
  while (when_pos < text.size()) {
    const auto then_pos = FindTopLevelFirebirdWord(text, "THEN", when_pos + 4);
    if (!then_pos) return std::nullopt;
    const auto next_when = FindTopLevelFirebirdWord(text, "WHEN", *then_pos + 4);
    const auto else_pos = FindTopLevelFirebirdWord(text, "ELSE", *then_pos + 4);
    const auto end_pos = FindTopLevelFirebirdWord(text, "END", *then_pos + 4);
    std::size_t branch_end = text.size();
    for (const auto position : {next_when, else_pos, end_pos}) {
      if (position) branch_end = std::min(branch_end, *position);
    }
    const std::string condition =
        TrimAscii(text.substr(when_pos + 4, *then_pos - (when_pos + 4)));
    bool matches = false;
    if (base_value) {
      const auto when_value = FirebirdLiteralOrScalarSubqueryValue(condition);
      matches = when_value && *when_value == *base_value;
    } else {
      const auto equals = condition.find('=');
      if (equals != std::string::npos) {
        const auto left = FirebirdLiteralOrScalarSubqueryValue(
            condition.substr(0, equals));
        const auto right = FirebirdLiteralOrScalarSubqueryValue(
            condition.substr(equals + 1));
        matches = left && right && *left == *right;
      }
    }
    if (matches) {
      return FirebirdLiteralOrScalarSubqueryValue(
          text.substr(*then_pos + 4, branch_end - (*then_pos + 4)));
    }
    if (!next_when || *next_when != branch_end) break;
    when_pos = *next_when;
  }
  const auto else_pos = FindTopLevelFirebirdWord(text, "ELSE", when_pos);
  const auto end_pos = else_pos
                           ? FindTopLevelFirebirdWord(text, "END", *else_pos + 4)
                           : std::optional<std::size_t>{};
  if (!else_pos || !end_pos) return std::nullopt;
  return FirebirdLiteralOrScalarSubqueryValue(
      text.substr(*else_pos + 4, *end_pos - (*else_pos + 4)));
}

std::optional<std::vector<FirebirdRow>> FirebirdLiteralCaseRows(
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (columns.size() != 1) return std::nullopt;
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const auto from_pos = FindTopLevelFirebirdWord(sql, "FROM", 6);
  if (!from_pos) return std::nullopt;
  const auto value = FirebirdLiteralCaseValue(
      TrimAscii(sql.substr(6, *from_pos - 6)));
  if (!value) return std::nullopt;
  FirebirdRow row;
  row.cells.push_back(FirebirdCellText(*value));
  TraceFirebirdWorker("source_backed_rows.literal_case value=" +
                      EscapeJsonLocal(*value));
  return std::vector<FirebirdRow>{std::move(row)};
}

