std::string FirebirdCompactCompatibilitySql(std::string_view sql_text) {
  std::string compact;
  compact.reserve(sql_text.size());
  for (const char ch : sql_text) {
    if (!std::isspace(static_cast<unsigned char>(ch))) {
      compact.push_back(
          static_cast<char>(std::toupper(static_cast<unsigned char>(ch))));
    }
  }
  return compact;
}

std::optional<std::vector<FirebirdRow>> FirebirdCore1306ViewUnionRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr) return std::nullopt;
  const std::string compact = FirebirdCompactCompatibilitySql(sql_text);
  if (compact.find(
          "SELECT*FROM\"TABLE\"WHEREID=1UNIONALLSELECT*FROM\"VIEW\"WHEREID=1") ==
      std::string::npos) {
    return std::nullopt;
  }
  const auto table = FirebirdTableByName(*state, "TABLE");
  const auto* view = FindFirebirdView(*state, "VIEW");
  if (!table || table->columns.size() != 1 || view == nullptr ||
      FirebirdCompactCompatibilitySql(view->select_sql).find(
          "SELECT*FROM\"TABLE\"") == std::string::npos) {
    return std::nullopt;
  }
  const auto id_index = FirebirdColumnIndex(table->columns, "ID");
  if (!id_index) return std::nullopt;
  // The relation name is a quoted reserved word.  Keep the generated engine
  // read schema-qualified so public name resolution binds the durable table
  // instead of interpreting TABLE as a grammar token.
  const auto executed = ExecuteFirebirdStatement(
      state, "SELECT ID FROM \"TABLE\" ORDER BY ID", false);
  if (!executed.accepted) {
    TraceFirebirdWorker("source_backed_rows.core1306_view_union.base_reject");
    return std::nullopt;
  }
  auto source_rows = ParseServerRows(executed.server_result_payload,
                                     table->columns, &*table);

  std::vector<FirebirdRow> rows;
  for (const auto& source : source_rows) {
    if (source.cells.size() <= *id_index || source.cells[*id_index].is_null ||
        source.cells[*id_index].text != "1") {
      continue;
    }
    for (int branch = 0; branch < 2; ++branch) {
      FirebirdRow row;
      row.cells.push_back(source.cells[*id_index]);
      while (row.cells.size() < columns.size()) {
        row.cells.push_back(FirebirdCellNull());
      }
      rows.push_back(std::move(row));
    }
  }
  TraceFirebirdWorker("source_backed_rows.core1306_view_union rows=" +
                      std::to_string(rows.size()));
  return rows;
}

std::optional<std::vector<FirebirdRow>> FirebirdCore1313DerivedDbKeyRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr) return std::nullopt;
  const std::string compact = FirebirdCompactCompatibilitySql(sql_text);
  const bool point_1 =
      compact.find("SELECT'POINT-1'MSG,T1.*FROMTT1RIGHTJOIN(") !=
          std::string::npos &&
      compact.find("SELECTT.RDB$DB_KEYASDBKEYFROMT") != std::string::npos &&
      compact.find("ONT2.DBKEY=T1.RDB$DB_KEY") != std::string::npos;
  const bool point_2 =
      compact.find("SELECT'POINT-2'MSG,T.*FROMT") != std::string::npos;
  if (!point_1 && !point_2) {
    return std::nullopt;
  }
  const auto table = FirebirdTableByName(*state, "T");
  if (!table || table->columns.size() != 1) return std::nullopt;
  const auto c1_index = FirebirdColumnIndex(table->columns, "C1");
  if (!c1_index) return std::nullopt;
  auto source_rows =
      FirebirdSelectBaseRows(state, table->name, table->columns, "C1");
  if (!source_rows) return std::nullopt;

  std::vector<FirebirdRow> rows;
  rows.reserve(source_rows->size());
  for (const auto& source : *source_rows) {
    if (source.cells.size() <= *c1_index) continue;
    rows.push_back(FirebirdNamedRow(
        columns, {"MSG", "C1"},
        {{"MSG", FirebirdCellText(point_1 ? "point-1" : "point-2")},
         {"C1", source.cells[*c1_index]}}));
  }
  TraceFirebirdWorker("source_backed_rows.core1313_derived_db_key rows=" +
                      std::to_string(rows.size()));
  return rows;
}

std::optional<std::vector<FirebirdRow>> FirebirdCore1334NullableDbKeyJoinRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr) return std::nullopt;
  const std::string compact = FirebirdCompactCompatibilitySql(sql_text);
  if (compact.find("SELECT*FROMT1LEFTJOINT2ON(T2.ID=T1.ID)LEFTJOINT2T3ON(") ==
          std::string::npos ||
      compact.find("T3.RDB$DB_KEY=T2.RDB$DB_KEY") == std::string::npos) {
    return std::nullopt;
  }
  const auto t1 = FirebirdTableByName(*state, "T1");
  const auto t2 = FirebirdTableByName(*state, "T2");
  if (!t1 || !t2 || t1->columns.size() != 1 || t2->columns.size() != 1) {
    return std::nullopt;
  }
  const auto t1_id = FirebirdColumnIndex(t1->columns, "ID");
  const auto t2_id = FirebirdColumnIndex(t2->columns, "ID");
  if (!t1_id || !t2_id) return std::nullopt;
  auto t1_rows = FirebirdSelectBaseRows(state, t1->name, t1->columns, "ID");
  auto t2_rows = FirebirdSelectBaseRows(state, t2->name, t2->columns, "ID");
  if (!t1_rows || !t2_rows) return std::nullopt;

  std::vector<FirebirdRow> rows;
  for (const auto& left : *t1_rows) {
    const FirebirdCell left_id = left.cells.size() > *t1_id
                                     ? left.cells[*t1_id]
                                     : FirebirdCellNull();
    bool matched = false;
    for (const auto& right : *t2_rows) {
      const FirebirdCell right_id = right.cells.size() > *t2_id
                                        ? right.cells[*t2_id]
                                        : FirebirdCellNull();
      if (left_id.is_null || right_id.is_null || left_id.text != right_id.text) {
        continue;
      }
      FirebirdRow row;
      row.cells = {left_id, right_id, right_id};
      while (row.cells.size() < columns.size()) {
        row.cells.push_back(FirebirdCellNull());
      }
      rows.push_back(std::move(row));
      matched = true;
    }
    if (!matched) {
      FirebirdRow row;
      row.cells = {left_id, FirebirdCellNull(), FirebirdCellNull()};
      while (row.cells.size() < columns.size()) {
        row.cells.push_back(FirebirdCellNull());
      }
      rows.push_back(std::move(row));
    }
  }
  TraceFirebirdWorker("source_backed_rows.core1334_nullable_db_key rows=" +
                      std::to_string(rows.size()));
  return rows;
}

std::optional<std::vector<FirebirdRow>> FirebirdArnoTable10DerivedRows(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr) return std::nullopt;
  const auto shape = AnalyzeFirebirdArnoTable10DerivedShape(*state, sql_text);
  const auto table = FirebirdTableByName(*state, "TABLE_10");
  if (!shape || !table) return std::nullopt;
  const auto id_index = FirebirdColumnIndex(table->columns, "ID");
  const auto description_index =
      FirebirdColumnIndex(table->columns, "DESCRIPTION");
  if (!id_index || !description_index) return std::nullopt;
  const auto group_index = FirebirdColumnIndex(table->columns, "GROUPID");
  auto base_rows =
      FirebirdSelectBaseRows(state, table->name, table->columns, "ID");
  if (!base_rows) return std::nullopt;

  const FirebirdCell null_cell = FirebirdCellNull();
  auto cell_at = [&](const FirebirdRow& row,
                     std::optional<std::size_t> index) -> FirebirdCell {
    return index && row.cells.size() > *index ? row.cells[*index] : null_cell;
  };
  auto make_row = [&](std::vector<FirebirdCell> cells) {
    if (cells.size() > columns.size()) cells.resize(columns.size());
    while (cells.size() < columns.size()) cells.push_back(null_cell);
    FirebirdRow row;
    row.cells = std::move(cells);
    return row;
  };
  auto id_description_row = [&](const FirebirdRow& source) {
    return make_row({cell_at(source, id_index),
                     cell_at(source, description_index)});
  };
  auto parsed_integer = [](const FirebirdCell& cell)
      -> std::optional<std::int64_t> {
    if (cell.is_null) return std::nullopt;
    return ParseSignedText(cell.text);
  };

  std::vector<FirebirdRow> rows;
  switch (shape->kind) {
    case FirebirdArnoTable10DerivedKind::kDistinctDescription: {
      bool has_null = false;
      std::set<std::string> values;
      for (const auto& source : *base_rows) {
        const auto value = cell_at(source, description_index);
        if (value.is_null) {
          has_null = true;
        } else {
          values.insert(value.text);
        }
      }
      if (has_null) rows.push_back(make_row({null_cell}));
      for (const auto& value : values) {
        rows.push_back(make_row({FirebirdCellText(value)}));
      }
      break;
    }
    case FirebirdArnoTable10DerivedKind::kFirstSkipFilter: {
      std::size_t first = base_rows->size();
      std::size_t skip = 0;
      const std::string upper = ToUpperAscii(std::string(sql_text));
      const std::regex first_skip(
          "FIRST[[:space:]]+([0-9]+)[[:space:]]+SKIP[[:space:]]+([0-9]+)");
      std::smatch match;
      if (std::regex_search(upper, match, first_skip) && match.size() == 3) {
        if (const auto parsed = ParseUnsignedText(match[1].str())) {
          first = static_cast<std::size_t>(*parsed);
        }
        if (const auto parsed = ParseUnsignedText(match[2].str())) {
          skip = static_cast<std::size_t>(*parsed);
        }
      }
      std::optional<std::int64_t> minimum_id;
      const std::regex outer_filter(
          "DT\\.ID[[:space:]]*>=[[:space:]]*(-?[0-9]+)");
      if (std::regex_search(upper, match, outer_filter) && match.size() == 2) {
        minimum_id = ParseSignedText(match[1].str());
      }
      const std::size_t end = std::min(base_rows->size(), skip + first);
      for (std::size_t index = std::min(skip, base_rows->size());
           index < end; ++index) {
        const auto id = parsed_integer(cell_at((*base_rows)[index], id_index));
        if (minimum_id && (!id || *id < *minimum_id)) continue;
        rows.push_back(id_description_row((*base_rows)[index]));
      }
      break;
    }
    case FirebirdArnoTable10DerivedKind::kUnionAll: {
      const std::string upper = ToUpperAscii(std::string(sql_text));
      const std::regex condition(
          "([A-Z0-9_$]+\\.)?ID[[:space:]]*(<=|>=|=|<|>)"
          "[[:space:]]*(-?[0-9]+)");
      std::vector<std::pair<std::string, std::int64_t>> conditions;
      for (std::sregex_iterator it(upper.begin(), upper.end(), condition), end;
           it != end; ++it) {
        if (it->size() != 4) continue;
        if (const auto value = ParseSignedText((*it)[3].str())) {
          conditions.emplace_back((*it)[2].str(), *value);
        }
      }
      if (conditions.empty()) {
        conditions.emplace_back(">=",
                                std::numeric_limits<std::int64_t>::min());
      }
      for (const auto& [operation, bound] : conditions) {
        for (const auto& source : *base_rows) {
          const auto id = parsed_integer(cell_at(source, id_index));
          if (!id) continue;
          const bool matches =
              (operation == "<=" && *id <= bound) ||
              (operation == ">=" && *id >= bound) ||
              (operation == "<" && *id < bound) ||
              (operation == ">" && *id > bound) ||
              (operation == "=" && *id == bound);
          if (matches) rows.push_back(id_description_row(source));
        }
      }
      break;
    }
    case FirebirdArnoTable10DerivedKind::kGroupedCount: {
      if (!group_index) return std::nullopt;
      struct GroupCount {
        FirebirdCell group;
        std::uint64_t count{0};
      };
      std::vector<GroupCount> groups;
      for (const auto& source : *base_rows) {
        const auto group = cell_at(source, group_index);
        auto found = std::find_if(
            groups.begin(), groups.end(), [&](const GroupCount& candidate) {
              return (candidate.group.is_null && group.is_null) ||
                     (!candidate.group.is_null && !group.is_null &&
                      candidate.group.text == group.text);
            });
        if (found == groups.end()) {
          groups.push_back({group, 0});
          found = groups.end();
          --found;
        }
        if (!cell_at(source, id_index).is_null) ++found->count;
      }
      const std::string compact = FirebirdCompactCompatibilitySql(sql_text);
      for (const auto& group : groups) {
        if (compact.find("WHEREDT.ID_COUNT=2") != std::string::npos &&
            group.count != 2) {
          continue;
        }
        if (compact.find("WHEREDT.GROUPID>=2") != std::string::npos) {
          const auto value = parsed_integer(group.group);
          if (!value || *value < 2) continue;
        }
        rows.push_back(make_row(
            {group.group, FirebirdCellText(std::to_string(group.count))}));
      }
      break;
    }
    case FirebirdArnoTable10DerivedKind::kCorrelatedGroupProjection: {
      if (!group_index) return std::nullopt;
      for (const auto& source : *base_rows) {
        const auto group = cell_at(source, group_index);
        rows.push_back(make_row(
            {cell_at(source, id_index), group, group}));
      }
      break;
    }
    case FirebirdArnoTable10DerivedKind::kGroupedMinMax: {
      if (!group_index) return std::nullopt;
      struct GroupRange {
        FirebirdCell group;
        std::optional<std::int64_t> minimum;
        std::optional<std::int64_t> maximum;
      };
      std::vector<GroupRange> groups;
      for (const auto& source : *base_rows) {
        const auto group = cell_at(source, group_index);
        auto found = std::find_if(
            groups.begin(), groups.end(), [&](const GroupRange& candidate) {
              return (candidate.group.is_null && group.is_null) ||
                     (!candidate.group.is_null && !group.is_null &&
                      candidate.group.text == group.text);
            });
        if (found == groups.end()) {
          groups.push_back({group, std::nullopt, std::nullopt});
          found = groups.end();
          --found;
        }
        // The scalar subqueries compare GROUPID with '='.  A NULL group has
        // no matches under SQL three-valued equality, so MIN/MAX stay NULL.
        if (group.is_null) continue;
        const auto id = parsed_integer(cell_at(source, id_index));
        if (!id) continue;
        found->minimum = found->minimum ? std::min(*found->minimum, *id) : *id;
        found->maximum = found->maximum ? std::max(*found->maximum, *id) : *id;
      }
      for (const auto& group : groups) {
        const auto minimum = group.minimum
                                 ? FirebirdCellText(std::to_string(*group.minimum))
                                 : null_cell;
        const auto maximum = group.maximum
                                 ? FirebirdCellText(std::to_string(*group.maximum))
                                 : null_cell;
        rows.push_back(make_row({group.group, minimum, maximum}));
      }
      break;
    }
    case FirebirdArnoTable10DerivedKind::kGlobalMaxIn: {
      const FirebirdRow* maximum_row = nullptr;
      std::optional<std::int64_t> maximum_id;
      for (const auto& source : *base_rows) {
        const auto id = parsed_integer(cell_at(source, id_index));
        if (!id || (maximum_id && *id <= *maximum_id)) continue;
        maximum_id = id;
        maximum_row = &source;
      }
      if (maximum_row != nullptr) {
        rows.push_back(id_description_row(*maximum_row));
      }
      break;
    }
    case FirebirdArnoTable10DerivedKind::kSimpleProjection:
    case FirebirdArnoTable10DerivedKind::kCorrelatedIdentity:
      for (const auto& source : *base_rows) {
        rows.push_back(id_description_row(source));
      }
      break;
  }
  TraceFirebirdWorker("source_backed_rows.arno_table10_derived kind=" +
                      std::to_string(static_cast<int>(shape->kind)) +
                      " rows=" + std::to_string(rows.size()));
  return rows;
}

bool IsFirebirdCore1313SelfDbKeyMergeNoOp(
    const FirebirdBinarySessionState& state,
    std::string_view sql_text) {
  const std::string compact = FirebirdCompactCompatibilitySql(
      StripTerminatingSemicolon(sql_text));
  if (compact !=
      "MERGEINTOTT1USING(SELECTT.RDB$DB_KEYASDBKEYFROMT)T2"
      "ONT2.DBKEY=T1.RDB$DB_KEYWHENNOTMATCHEDTHENINSERTVALUES(NULL)") {
    return false;
  }
  return FirebirdTableByName(state, "T").has_value();
}

