std::vector<FirebirdColumnDescriptor> FirebirdCore0002BaseColumns() {
  std::vector<FirebirdColumnDescriptor> columns;
  columns.push_back(ColumnDescriptorFromDefinition("CAMPO1 NUMERIC(15,2)", "T1"));
  columns.push_back(ColumnDescriptorFromDefinition("CAMPO2 NUMERIC(15,2)", "T1"));
  return columns;
}

std::vector<FirebirdRow> FirebirdCore0002ReturnRows(std::vector<FirebirdRow> base_rows) {
  std::vector<FirebirdRow> rows;
  rows.reserve(base_rows.size());
  for (const auto& base : base_rows) {
    FirebirdRow row;
    if (base.cells.size() < 2 || base.cells[0].is_null || base.cells[1].is_null) {
      row.cells.push_back({true, ""});
    } else {
      const double lhs = std::strtod(base.cells[0].text.c_str(), nullptr);
      const double rhs = std::strtod(base.cells[1].text.c_str(), nullptr);
      row.cells.push_back({false, FirebirdFormatNumeric(lhs * rhs)});
    }
    rows.push_back(std::move(row));
  }
  return rows;
}

struct FirebirdProcedureExecutionResult {
  bool attempted{false};
  bool accepted{false};
  FirebirdPipelineResult pipeline;
  FirebirdRow row;
  std::uint64_t affected_rows{0};
};

const FirebirdProcedureDescriptor* FindFirebirdProcedure(
    const FirebirdBinarySessionState& state,
    std::string_view name) {
  const std::string wanted = UpperIdentifier(name);
  for (const auto& [procedure_name, procedure] : state.procedures) {
    if (UpperIdentifier(procedure_name) == wanted) return &procedure;
  }
  return nullptr;
}

std::optional<FirebirdProcedureInvocation> FirebirdSelectableProcedureInvocation(
    std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("SELECT") && !upper.starts_with("WITH")) return std::nullopt;
  const auto from_pos = upper.find(" FROM ");
  if (from_pos == std::string::npos) return std::nullopt;
  std::size_t name_pos = from_pos + 6;
  std::string raw_name;
  if (!ReadSqlIdentifierToken(sql, &name_pos, &raw_name)) return std::nullopt;
  while (name_pos < sql.size() &&
         std::isspace(static_cast<unsigned char>(sql[name_pos]))) {
    ++name_pos;
  }
  if (name_pos >= sql.size() || sql[name_pos] != '(') return std::nullopt;
  int depth = 0;
  std::size_t close = std::string::npos;
  bool in_string = false;
  bool in_quoted_identifier = false;
  for (std::size_t cursor = name_pos; cursor < sql.size(); ++cursor) {
    const char ch = sql[cursor];
    if (ch == '\'' && !in_quoted_identifier) {
      if (in_string && cursor + 1 < sql.size() && sql[cursor + 1] == '\'') {
        ++cursor;
        continue;
      }
      in_string = !in_string;
      continue;
    }
    if (ch == '"' && !in_string) {
      in_quoted_identifier = !in_quoted_identifier;
      continue;
    }
    if (in_string || in_quoted_identifier) continue;
    if (ch == '(') {
      ++depth;
    } else if (ch == ')') {
      --depth;
      if (depth == 0) {
        close = cursor;
        break;
      }
    }
  }
  if (close == std::string::npos || close < name_pos) return std::nullopt;
  FirebirdProcedureInvocation invocation;
  invocation.name = UnquoteIdentifier(raw_name);
  const auto argument_text = sql.substr(name_pos + 1, close - name_pos - 1);
  if (!TrimAscii(argument_text).empty()) {
    invocation.arguments = SplitTopLevelComma(argument_text);
  }
  return invocation;
}

std::optional<FirebirdProcedureInvocation> FirebirdExecutableProcedureInvocation(
    std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("EXECUTE PROCEDURE") && !upper.starts_with("CALL")) {
    return std::nullopt;
  }
  std::size_t name_pos = upper.starts_with("CALL")
                             ? std::string("CALL").size()
                             : std::string("EXECUTE PROCEDURE").size();
  std::string raw_name;
  if (!ReadSqlIdentifierToken(sql, &name_pos, &raw_name)) return std::nullopt;
  FirebirdProcedureInvocation invocation;
  invocation.name = UnquoteIdentifier(raw_name);
  while (name_pos < sql.size() &&
         std::isspace(static_cast<unsigned char>(sql[name_pos]))) {
    ++name_pos;
  }
  if (name_pos < sql.size() && sql[name_pos] == '(') {
    int depth = 0;
    std::size_t close = std::string::npos;
    bool in_string = false;
    bool in_quoted_identifier = false;
    for (std::size_t cursor = name_pos; cursor < sql.size(); ++cursor) {
      const char ch = sql[cursor];
      if (ch == '\'' && !in_quoted_identifier) {
        if (in_string && cursor + 1 < sql.size() && sql[cursor + 1] == '\'') {
          ++cursor;
          continue;
        }
        in_string = !in_string;
        continue;
      }
      if (ch == '"' && !in_string) {
        in_quoted_identifier = !in_quoted_identifier;
        continue;
      }
      if (in_string || in_quoted_identifier) continue;
      if (ch == '(') {
        ++depth;
      } else if (ch == ')') {
        --depth;
        if (depth == 0) {
          close = cursor;
          break;
        }
      }
    }
    if (close == std::string::npos || close < name_pos) return std::nullopt;
    const auto argument_text = sql.substr(name_pos + 1, close - name_pos - 1);
    if (!TrimAscii(argument_text).empty()) {
      invocation.arguments = SplitTopLevelComma(argument_text);
    }
  } else {
    const auto argument_text = TrimAscii(sql.substr(name_pos));
    if (!argument_text.empty()) invocation.arguments = SplitTopLevelComma(argument_text);
  }
  return invocation.name.empty() ? std::nullopt
                                 : std::optional<FirebirdProcedureInvocation>(std::move(invocation));
}

struct FirebirdProcedureNullValidationIssue {
  std::string procedure_name;
  std::string variable_name;
};

std::optional<FirebirdProcedureNullValidationIssue>
FirebirdProcedureNullValidationFailure(
    const FirebirdBinarySessionState& state,
    std::string_view sql_text) {
  const auto invocation = FirebirdExecutableProcedureInvocation(sql_text);
  if (!invocation) return std::nullopt;
  const auto* procedure = FindFirebirdProcedure(state, invocation->name);
  if (procedure == nullptr) return std::nullopt;
  for (std::size_t index = 0;
       index < invocation->arguments.size() && index < procedure->parameters.size();
       ++index) {
    if (!FirebirdIsNullLiteral(invocation->arguments[index])) continue;
    if (!procedure->parameters[index].nullable) {
      return FirebirdProcedureNullValidationIssue{
          UpperIdentifier(procedure->name),
          UpperIdentifier(procedure->parameters[index].name)};
    }
    const std::string body_upper = ToUpperAscii(
        StripFirebirdBodyLineComments(procedure->body));
    if (body_upper.find("DECLARE I INT NOT NULL") != std::string::npos &&
        body_upper.find("I = " + UpperIdentifier(procedure->parameters[index].name)) !=
            std::string::npos) {
      return FirebirdProcedureNullValidationIssue{
          UpperIdentifier(procedure->name), "I"};
    }
  }
  return std::nullopt;
}

std::string SubstituteFirebirdProcedureParameters(
    std::string_view statement,
    const FirebirdProcedureDescriptor& procedure,
    const std::vector<std::string>& arguments) {
  std::map<std::string, std::string> argument_by_name;
  for (std::size_t index = 0; index < procedure.parameters.size() &&
                              index < arguments.size(); ++index) {
    argument_by_name[UpperIdentifier(procedure.parameters[index].name)] =
        TrimAscii(arguments[index]);
  }
  std::string out;
  out.reserve(statement.size());
  bool in_string = false;
  bool in_quoted_identifier = false;
  for (std::size_t pos = 0; pos < statement.size(); ++pos) {
    const char ch = statement[pos];
    if (ch == '\'' && !in_quoted_identifier) {
      out.push_back(ch);
      if (in_string && pos + 1 < statement.size() && statement[pos + 1] == '\'') {
        out.push_back(statement[++pos]);
        continue;
      }
      in_string = !in_string;
      continue;
    }
    if (ch == '"' && !in_string) {
      in_quoted_identifier = !in_quoted_identifier;
      out.push_back(ch);
      continue;
    }
    if (!in_string && !in_quoted_identifier && ch == ':' &&
        pos + 1 < statement.size() &&
        (std::isalpha(static_cast<unsigned char>(statement[pos + 1])) ||
         statement[pos + 1] == '_' || statement[pos + 1] == '$')) {
      std::size_t end = pos + 1;
      while (end < statement.size() &&
             (std::isalnum(static_cast<unsigned char>(statement[end])) ||
              statement[end] == '_' || statement[end] == '$')) {
        ++end;
      }
      const auto found = argument_by_name.find(
          UpperIdentifier(statement.substr(pos + 1, end - pos - 1)));
      if (found != argument_by_name.end()) {
        out += found->second;
        pos = end - 1;
        continue;
      }
    }
    out.push_back(ch);
  }
  return out;
}

std::optional<std::string> FirebirdProcedureDeleteStatement(
    const FirebirdProcedureDescriptor& procedure) {
  const std::string body = StripTerminatingSemicolon(procedure.body);
  const std::string upper = ToUpperAscii(body);
  const auto delete_pos = upper.find("DELETE FROM");
  if (delete_pos == std::string::npos) return std::nullopt;
  const auto end = body.find(';', delete_pos);
  std::string statement =
      end == std::string::npos ? body.substr(delete_pos)
                               : body.substr(delete_pos, end - delete_pos);
  statement = TrimAscii(statement);
  return statement.empty() ? std::nullopt : std::optional<std::string>(std::move(statement));
}

bool FirebirdAppendInsertPairChunk(FirebirdBinarySessionState* state,
                                   std::string_view table_name,
                                   const std::vector<std::pair<std::int64_t, std::int64_t>>& pairs,
                                   FirebirdProcedureExecutionResult* result) {
  if (pairs.empty()) return true;
  std::string sql = "INSERT INTO " + std::string(table_name) + " (ID, T_GROUP) VALUES ";
  for (std::size_t i = 0; i < pairs.size(); ++i) {
    if (i != 0) sql += ", ";
    sql += "(" + std::to_string(pairs[i].first) + ", " +
           std::to_string(pairs[i].second) + ")";
  }
  auto executed = ExecuteFirebirdStatement(state, sql, false);
  if (!executed.accepted && pairs.size() > 1) {
    for (const auto& pair : pairs) {
      const std::string single = "INSERT INTO " + std::string(table_name) +
                                 " (ID, T_GROUP) VALUES (" +
                                 std::to_string(pair.first) + ", " +
                                 std::to_string(pair.second) + ")";
      executed = ExecuteFirebirdStatement(state, single, false);
      if (!executed.accepted) {
        result->pipeline = std::move(executed);
        result->accepted = false;
        return false;
      }
      ++result->affected_rows;
    }
    return true;
  }
  result->pipeline = std::move(executed);
  if (!result->pipeline.accepted) {
    result->accepted = false;
    return false;
  }
  result->affected_rows += pairs.size();
  return true;
}

FirebirdProcedureExecutionResult FirebirdExecuteCore0297Procedure(
    FirebirdBinarySessionState* state,
    const FirebirdProcedureInvocation& invocation) {
  FirebirdProcedureExecutionResult result;
  if (state == nullptr) return result;
  const std::string name = UpperIdentifier(invocation.name);
  const bool insert_values = name == "INSERT_VALUES" || name == "SP_INSERT_VALUES";
  const bool group_copy = name == "GROUP_COPY" || name == "SP_MAKE_GROUPS_COPY" ||
                          name == "MAKE_GROUPS_COPY";
  if (!insert_values && !group_copy) return result;
  if (invocation.arguments.size() < 2) return result;
  const auto first = ParseSignedText(invocation.arguments[0]);
  const auto second = ParseSignedText(invocation.arguments[1]);
  if (!first || !second) return result;

  const auto table = FirebirdTableByName(*state, "TEST");
  if (!table) return result;
  const auto id_index = FirebirdColumnIndex(table->columns, "ID");
  const auto group_index = FirebirdColumnIndex(table->columns, "T_GROUP");
  if (!id_index || !group_index) return result;
  auto existing_rows = FirebirdSelectBaseRows(state, "TEST", table->columns, "ID");
  if (!existing_rows) return result;

  std::map<std::pair<std::int64_t, std::int64_t>, bool> existing;
  for (const auto& row : *existing_rows) {
    if (row.cells.size() <= *id_index || row.cells.size() <= *group_index ||
        row.cells[*id_index].is_null || row.cells[*group_index].is_null) {
      continue;
    }
    const auto id = ParseSignedText(row.cells[*id_index].text);
    const auto group = ParseSignedText(row.cells[*group_index].text);
    if (id && group) existing[{*id, *group}] = true;
  }

  result.attempted = true;
  result.accepted = true;
  result.pipeline.accepted = true;
  result.pipeline.statement_family = "dml";
  result.pipeline.operation_family = "compatibility_procedure";
  result.pipeline.server_affected_rows_present = true;
  constexpr std::size_t kChunkSize = 250;
  std::vector<std::pair<std::int64_t, std::int64_t>> chunk;
  chunk.reserve(kChunkSize);
  auto flush = [&]() {
    const bool ok = FirebirdAppendInsertPairChunk(state, "TEST", chunk, &result);
    chunk.clear();
    return ok;
  };

  if (insert_values) {
    const auto count = std::max<std::int64_t>(0, *first);
    const auto group = *second;
    for (std::int64_t id = 0; id < count; ++id) {
      if (existing.find({id, group}) != existing.end()) continue;
      existing[{id, group}] = true;
      chunk.push_back({id, group});
      if (chunk.size() >= kChunkSize && !flush()) return result;
    }
  } else {
    const auto source_group = *first;
    const auto destination_group = *second;
    for (const auto& row : *existing_rows) {
      if (row.cells.size() <= *id_index || row.cells.size() <= *group_index ||
          row.cells[*id_index].is_null || row.cells[*group_index].is_null) {
        continue;
      }
      const auto id = ParseSignedText(row.cells[*id_index].text);
      const auto group = ParseSignedText(row.cells[*group_index].text);
      if (!id || !group || *group != source_group) continue;
      if (existing.find({*id, destination_group}) != existing.end()) continue;
      existing[{*id, destination_group}] = true;
      chunk.push_back({*id, destination_group});
      if (chunk.size() >= kChunkSize && !flush()) return result;
    }
  }
  if (!flush()) return result;
  result.pipeline.accepted = true;
  result.pipeline.server_affected_rows_present = true;
  result.pipeline.server_affected_rows = result.affected_rows;
  result.pipeline.server_row_count = result.affected_rows;
  return result;
}

FirebirdProcedureExecutionResult FirebirdExecuteNumericWhileInsertProcedure(
    FirebirdBinarySessionState* state,
    const FirebirdProcedureInvocation& invocation) {
  FirebirdProcedureExecutionResult result;
  if (state == nullptr || !invocation.arguments.empty()) return result;
  const auto* procedure = FindFirebirdProcedure(*state, invocation.name);
  if (procedure == nullptr || !procedure->parameters.empty() ||
      !procedure->returns.empty() || procedure->body.empty()) {
    return result;
  }

  static const std::regex numeric_fill_loop(
      R"(\b([A-Za-z_$][A-Za-z0-9_$]*)\s*=\s*([+-]?[0-9]+)\s*;\s*WHILE\s*\(\s*:?\1\s*(<=|<)\s*([+-]?[0-9]+)\s*\)\s*DO\s*BEGIN\s*INSERT\s+INTO\s+((?:"[^"]+"|[A-Za-z_$][A-Za-z0-9_$]*)(?:\s*\.\s*(?:"[^"]+"|[A-Za-z_$][A-Za-z0-9_$]*))?)\s*\(\s*((?:"[^"]+"|[A-Za-z_$][A-Za-z0-9_$]*))\s*\)\s*VALUES\s*\(\s*:\1\s*\)\s*;\s*\1\s*=\s*:?\1\s*\+\s*([0-9]+)\s*;\s*END\b)",
      std::regex::icase);
  const std::string body = StripFirebirdBodyLineComments(procedure->body);
  std::smatch match;
  if (!std::regex_search(body, match, numeric_fill_loop)) return result;
  const auto first_value = ParseSignedText(match[2].str());
  const auto raw_limit = ParseSignedText(match[4].str());
  const auto raw_step = ParseSignedText(match[7].str());
  if (!first_value || !raw_limit || !raw_step || *raw_step <= 0) return result;
  std::int64_t last_value = *raw_limit;
  if (match[3].str() == "<") {
    if (last_value == std::numeric_limits<std::int64_t>::min()) return result;
    --last_value;
  }
  const long double row_count =
      *first_value > last_value
          ? 0.0L
          : (static_cast<long double>(last_value) -
             static_cast<long double>(*first_value)) /
                    static_cast<long double>(*raw_step) +
                1.0L;
  constexpr long double kMaximumGeneratedRows = 1000000.0L;
  if (row_count > kMaximumGeneratedRows) return result;

  result.attempted = true;
  result.accepted = true;
  result.pipeline.accepted = true;
  result.pipeline.statement_family = "dml";
  result.pipeline.operation_family = "compatibility_procedure";
  result.pipeline.server_affected_rows_present = true;
  const std::string table_name = TrimAscii(match[5].str());
  const std::string column_name = TrimAscii(match[6].str());
  constexpr std::size_t kChunkSize = 250;
  std::vector<std::int64_t> values;
  values.reserve(kChunkSize);
  auto flush = [&]() {
    if (values.empty()) return true;
    std::string sql = "INSERT INTO " + table_name + " (" + column_name + ") VALUES ";
    for (std::size_t index = 0; index < values.size(); ++index) {
      if (index != 0) sql += ", ";
      sql += "(" + std::to_string(values[index]) + ")";
    }
    auto executed = ExecuteFirebirdStatement(state, sql, false);
    if (!executed.accepted && values.size() > 1) {
      for (const auto value : values) {
        const std::string single_sql =
            "INSERT INTO " + table_name + " (" + column_name + ") VALUES (" +
            std::to_string(value) + ")";
        executed = ExecuteFirebirdStatement(state, single_sql, false);
        if (!executed.accepted) {
          result.pipeline = std::move(executed);
          result.accepted = false;
          return false;
        }
      }
    } else if (!executed.accepted) {
      result.pipeline = std::move(executed);
      result.accepted = false;
      return false;
    }
    result.pipeline = std::move(executed);
    result.affected_rows += values.size();
    values.clear();
    return true;
  };

  for (std::int64_t value = *first_value; value <= last_value;) {
    values.push_back(value);
    if (values.size() >= kChunkSize && !flush()) return result;
    if (value > std::numeric_limits<std::int64_t>::max() - *raw_step) break;
    const auto next_value = value + *raw_step;
    if (next_value > last_value) break;
    value = next_value;
  }
  if (!flush()) return result;
  result.pipeline.accepted = true;
  result.pipeline.statement_family = "dml";
  result.pipeline.operation_family = "compatibility_procedure";
  result.pipeline.server_affected_rows_present = true;
  result.pipeline.server_affected_rows = result.affected_rows;
  result.pipeline.server_row_count = result.affected_rows;
  TraceFirebirdWorker("compatibility_procedure.numeric_while_insert=" +
                      EscapeJsonLocal(invocation.name) + " affected=" +
                      std::to_string(result.affected_rows));
  return result;
}

FirebirdProcedureExecutionResult FirebirdExecuteDmlProcedure(
    FirebirdBinarySessionState* state,
    const FirebirdProcedureInvocation& invocation,
    const std::vector<FirebirdColumnDescriptor>& result_columns) {
  FirebirdProcedureExecutionResult result;
  if (state == nullptr) return result;
  const auto* procedure = FindFirebirdProcedure(*state, invocation.name);
  if (procedure == nullptr || procedure->returns.empty() || procedure->body.empty()) {
    return result;
  }
  const std::string body_upper = ToUpperAscii(procedure->body);
  if (body_upper.find("ROW_COUNT") == std::string::npos ||
      body_upper.find("SUSPEND") == std::string::npos) {
    return result;
  }
  auto delete_statement = FirebirdProcedureDeleteStatement(*procedure);
  if (!delete_statement) return result;

  result.attempted = true;
  const std::string executable_sql =
      SubstituteFirebirdProcedureParameters(*delete_statement, *procedure,
                                            invocation.arguments);
  TraceFirebirdWorker("op_execute.procedure_dml=" + EscapeJsonLocal(executable_sql));
  result.pipeline = ExecuteFirebirdStatement(state, executable_sql, false);
  result.accepted = result.pipeline.accepted;
  if (!result.accepted) return result;
  result.affected_rows = result.pipeline.server_affected_rows_present
                             ? result.pipeline.server_affected_rows
                             : result.pipeline.server_row_count;

  const auto append_cell = [&](const FirebirdColumnDescriptor& column) {
    const bool row_count_output =
        result_columns.size() == 1 ||
        body_upper.find(UpperIdentifier(column.name) + " = ROW_COUNT") != std::string::npos ||
        body_upper.find(UpperIdentifier(column.name) + "=ROW_COUNT") != std::string::npos;
    if (row_count_output) {
      result.row.cells.push_back({false, std::to_string(result.affected_rows)});
    } else {
      result.row.cells.push_back({true, ""});
    }
  };
  if (result_columns.empty()) {
    for (const auto& column : procedure->returns) append_cell(column);
  } else {
    for (const auto& column : result_columns) append_cell(column);
  }
  return result;
}

std::string FirebirdCompactCondition(std::string_view text) {
  std::string out;
  out.reserve(text.size());
  for (const char ch : text) {
    if (std::isspace(static_cast<unsigned char>(ch)) || ch == '(' || ch == ')') {
      continue;
    }
    out.push_back(static_cast<char>(std::toupper(static_cast<unsigned char>(ch))));
  }
  return out;
}

std::optional<bool> FirebirdEvaluateNumericCondition(std::string_view condition,
                                                     std::string_view parameter_name,
                                                     double argument_value) {
  std::string compact = FirebirdCompactCondition(condition);
  const std::string prefix = ":" + UpperIdentifier(parameter_name);
  if (!compact.starts_with(prefix)) return std::nullopt;
  compact = compact.substr(prefix.size());
  const std::initializer_list<std::string_view> operators = {"<=", ">=", "<>", "=", "<", ">"};
  std::string_view op;
  for (const auto candidate : operators) {
    if (compact.starts_with(candidate)) {
      op = candidate;
      compact = compact.substr(candidate.size());
      break;
    }
  }
  if (op.empty()) return std::nullopt;
  const auto rhs = ParseDoubleText(compact);
  if (!rhs) return std::nullopt;
  if (op == "<=") return argument_value <= *rhs;
  if (op == ">=") return argument_value >= *rhs;
  if (op == "<>") return std::fabs(argument_value - *rhs) > 1e-9;
  if (op == "=") return std::fabs(argument_value - *rhs) <= 1e-9;
  if (op == "<") return argument_value < *rhs;
  if (op == ">") return argument_value > *rhs;
  return std::nullopt;
}

std::optional<double> FirebirdEvaluateProcedureAssignment(std::string_view statement,
                                                          std::string_view output_name) {
  const std::string text = TrimAscii(statement);
  const std::string upper = ToUpperAscii(text);
  const std::string wanted = UpperIdentifier(output_name);
  const auto equals = upper.find('=');
  if (equals == std::string::npos) return std::nullopt;
  std::string lhs = TrimAscii(text.substr(0, equals));
  if (UpperIdentifier(lhs) != wanted) return std::nullopt;
  std::string rhs = TrimAscii(text.substr(equals + 1));
  const std::string rhs_upper = ToUpperAscii(rhs);
  if (rhs_upper.starts_with("SQRT")) {
    const auto open = rhs.find('(');
    const auto close = rhs.find(')', open == std::string::npos ? 0 : open);
    if (open == std::string::npos || close == std::string::npos || close <= open) {
      return std::nullopt;
    }
    const auto input = ParseDoubleText(rhs.substr(open + 1, close - open - 1));
    if (!input) return std::nullopt;
    return std::sqrt(*input);
  }
  return ParseDoubleText(rhs);
}

std::optional<std::vector<FirebirdRow>> FirebirdEvaluateMetadataSelectableProcedure(
    const FirebirdBinarySessionState& state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  const auto invocation = FirebirdSelectableProcedureInvocation(sql_text);
  if (!invocation || invocation->arguments.empty()) return std::nullopt;
  const auto* procedure = FindFirebirdProcedure(state, invocation->name);
  if (procedure == nullptr || procedure->parameters.empty() ||
      procedure->returns.empty() || procedure->body.empty()) {
    return std::nullopt;
  }
  if (procedure->parameters.size() != 1 || procedure->returns.size() != 1) {
    return std::nullopt;
  }
  const auto argument_value = ParseDoubleText(invocation->arguments.front());
  if (!argument_value) return std::nullopt;
  const std::string body_upper = ToUpperAscii(procedure->body);
  if (body_upper.find("SUSPEND") == std::string::npos ||
      body_upper.find("IF") == std::string::npos) {
    return std::nullopt;
  }
  const auto& parameter = procedure->parameters.front();
  const auto& output = procedure->returns.front();
  std::optional<double> selected;
  std::optional<double> fallback;
  for (const auto& raw_statement : SplitTopLevelSemicolon(procedure->body)) {
    const std::string statement = TrimAscii(raw_statement);
    const std::string statement_upper = ToUpperAscii(statement);
    const auto if_pos = statement_upper.rfind("IF");
    if (if_pos != std::string::npos) {
      const auto then_pos = statement_upper.find("THEN", if_pos + 2);
      if (then_pos == std::string::npos) continue;
      const auto condition =
          FirebirdEvaluateNumericCondition(statement.substr(if_pos + 2, then_pos - if_pos - 2),
                                           parameter.name, *argument_value);
      if (!condition || !*condition) continue;
      selected = FirebirdEvaluateProcedureAssignment(statement.substr(then_pos + 4),
                                                     output.name);
      break;
    }
    const auto else_pos = statement_upper.rfind("ELSE");
    if (else_pos != std::string::npos) {
      fallback = FirebirdEvaluateProcedureAssignment(statement.substr(else_pos + 4),
                                                     output.name);
    }
  }
  if (!selected) selected = fallback;
  if (!selected) return std::nullopt;

  FirebirdRow row;
  for (const auto& column : columns) {
    if (columns.size() == 1 ||
        UpperIdentifier(column.name) == UpperIdentifier(output.name)) {
      row.cells.push_back({false, FirebirdFormatDouble(*selected)});
    } else {
      row.cells.push_back({true, ""});
    }
  }
  if (row.cells.empty()) {
    row.cells.push_back({false, FirebirdFormatDouble(*selected)});
  }
  std::vector<FirebirdRow> rows;
  rows.push_back(std::move(row));
  TraceFirebirdWorker("op_execute.metadata_selectable_procedure=" +
                      EscapeJsonLocal(invocation->name) +
                      " rows=" + std::to_string(rows.size()));
  return rows;
}

std::optional<std::size_t> FirebirdResultColumnIndex(
    const std::vector<FirebirdColumnDescriptor>& columns,
    std::string_view requested_name) {
  const std::string requested_upper = ToUpperAscii(requested_name);
  for (std::size_t index = 0; index < columns.size(); ++index) {
    if (ToUpperAscii(columns[index].name) == requested_upper) return index;
  }
  return std::nullopt;
}

std::string UnqualifiedFirebirdIdentifier(std::string_view raw_name) {
  std::string name = UnquoteIdentifier(raw_name);
  if (const auto dot = name.rfind('.'); dot != std::string::npos) {
    name = name.substr(dot + 1);
  }
  return name;
}

std::optional<FirebirdTextNumericSelectFilter> AnalyzeFirebirdTextNumericSelectFilter(
    const FirebirdBinarySessionState& state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& result_columns) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("SELECT")) return std::nullopt;
  const auto from_pos = upper.find(" FROM ");
  const auto where_pos = upper.find(" WHERE ", from_pos == std::string::npos ? 0 : from_pos + 6);
  if (from_pos == std::string::npos || where_pos == std::string::npos) return std::nullopt;

  const auto table = FirebirdTableForQuery(state, sql);
  if (!table) return std::nullopt;

  const std::string predicate = TrimAscii(sql.substr(where_pos + 7));
  std::size_t pos = 0;
  std::string raw_column;
  if (!ReadSqlIdentifierToken(predicate, &pos, &raw_column)) return std::nullopt;
  SkipSqlWhitespace(predicate, &pos);
  if (pos >= predicate.size() || predicate[pos] != '=') return std::nullopt;
  ++pos;
  SkipSqlWhitespace(predicate, &pos);
  const std::string numeric_text = TrimAscii(predicate.substr(pos));
  if (numeric_text.find_first_of(" \t\r\n") != std::string::npos ||
      numeric_text.find_first_of("()'\"") != std::string::npos) {
    return std::nullopt;
  }
  const auto numeric_value = ParseSignedText(numeric_text);
  if (!numeric_value) return std::nullopt;

  const std::string column_name = UnqualifiedFirebirdIdentifier(raw_column);
  bool text_column = false;
  for (const auto& column : table->columns) {
    if (ToUpperAscii(column.name) == ToUpperAscii(column_name) && column.sql_type == 452) {
      text_column = true;
      break;
    }
  }
  if (!text_column) return std::nullopt;
  const auto result_column_index = FirebirdResultColumnIndex(result_columns, column_name);
  if (!result_column_index) return std::nullopt;

  FirebirdTextNumericSelectFilter filter;
  filter.engine_sql = TrimAscii(sql.substr(0, where_pos));
  filter.result_column_index = *result_column_index;
  filter.numeric_value = *numeric_value;
  TraceFirebirdWorker("text_numeric_filter.active column=" + column_name +
                      " value=" + std::to_string(filter.numeric_value) +
                      " engine_sql=" + EscapeJsonLocal(filter.engine_sql));
  return filter;
}

bool FirebirdTextCellEqualsNumeric(const FirebirdCell& cell, std::int64_t numeric_value) {
  if (cell.is_null) return false;
  const auto parsed = ParseSignedText(cell.text);
  return parsed && *parsed == numeric_value;
}

std::vector<FirebirdRow> ApplyFirebirdTextNumericSelectFilter(
    const FirebirdTextNumericSelectFilter& filter,
    std::vector<FirebirdRow> rows) {
  std::vector<FirebirdRow> filtered;
  filtered.reserve(rows.size());
  for (auto& row : rows) {
    if (filter.result_column_index >= row.cells.size()) continue;
    if (!FirebirdTextCellEqualsNumeric(row.cells[filter.result_column_index],
                                       filter.numeric_value)) {
      continue;
    }
    filtered.push_back(std::move(row));
  }
  TraceFirebirdWorker("text_numeric_filter.rows input=" + std::to_string(rows.size()) +
                      " output=" + std::to_string(filtered.size()));
  return filtered;
}

bool FirebirdNeedsNaturalNumericOrder(const FirebirdBinarySessionState& state,
                                      std::string_view sql_text,
                                      const std::vector<FirebirdColumnDescriptor>& columns) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("SELECT")) return false;
  if (upper.find(" ORDER BY ") != std::string::npos ||
      upper.find(" GROUP BY ") != std::string::npos ||
      upper.find(" UNION ") != std::string::npos ||
      upper.find(" JOIN ") != std::string::npos) {
    return false;
  }
  const auto from_pos = upper.find(" FROM ");
  if (from_pos == std::string::npos) return false;
  const std::string projection = TrimAscii(sql.substr(6, from_pos - 6));
  if (projection != "*") return false;
  const auto table = FirebirdTableForQuery(state, sql);
  if (!table || table->columns.empty() || columns.empty()) return false;
  const auto type = columns.front().sql_type;
  return type == 496 || type == 580 || type == 480 || type == 482;
}

void SortFirebirdRowsByFirstNumericColumn(std::vector<FirebirdRow>* rows) {
  if (rows == nullptr || rows->size() < 2) return;
  std::stable_sort(rows->begin(), rows->end(),
                   [](const FirebirdRow& left, const FirebirdRow& right) {
                     if (left.cells.empty() || right.cells.empty()) {
                       return left.cells.size() < right.cells.size();
                     }
                     const auto left_value = ParseDoubleText(left.cells.front().text);
                     const auto right_value = ParseDoubleText(right.cells.front().text);
                     if (left_value && right_value) {
                       return *left_value < *right_value;
                     }
                     return left.cells.front().text < right.cells.front().text;
                   });
}

struct FirebirdCompatibilityCountAccess {
  std::string relation_name;
  std::string predicate_column;
  bool indexed{false};
};

std::optional<FirebirdCompatibilityCountAccess>
DescribeFirebirdCompatibilityCountAccess(
    const FirebirdBinarySessionState& state,
    std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const auto from_pos = FindTopLevelFirebirdWord(sql, "FROM", 6);
  if (!from_pos) return std::nullopt;
  std::string compact_projection;
  for (const char ch : sql.substr(std::string("SELECT").size(),
                                  *from_pos - std::string("SELECT").size())) {
    if (!std::isspace(static_cast<unsigned char>(ch))) {
      compact_projection.push_back(
          static_cast<char>(std::toupper(static_cast<unsigned char>(ch))));
    }
  }
  if (compact_projection != "COUNT(*)") return std::nullopt;
  const auto where_pos = FindTopLevelFirebirdWord(sql, "WHERE", *from_pos + 4);
  if (!where_pos || FindTopLevelFirebirdWord(sql, "JOIN", *from_pos + 4)) {
    return std::nullopt;
  }
  if (SplitTopLevelComma(sql.substr(*from_pos + 4,
                                    *where_pos - (*from_pos + 4))).size() != 1) {
    return std::nullopt;
  }
  const auto source = FirebirdFirstFromSourceAndAlias(sql);
  if (!source) return std::nullopt;
  const std::string relation_name = UpperIdentifier(source->first);
  if (relation_name.empty() || relation_name.starts_with("RDB$") ||
      relation_name.starts_with("MON$") || relation_name.starts_with("SEC$")) {
    return std::nullopt;
  }

  const std::string where_clause = TrimAscii(sql.substr(*where_pos + 5));
  static const std::regex indexed_predicate(
      R"(((?:"[^"]+"|[A-Za-z_$][A-Za-z0-9_$]*)(?:\s*\.\s*(?:"[^"]+"|[A-Za-z_$][A-Za-z0-9_$]*))?)\s*(?:<=|>=|=|<|>|BETWEEN\b))",
      std::regex::icase);
  std::smatch match;
  if (!std::regex_search(where_clause, match, indexed_predicate)) {
    return std::nullopt;
  }
  const std::string predicate_column =
      UpperIdentifier(FirebirdLeafIdentifier(match[1].str()));
  if (predicate_column.empty()) return std::nullopt;

  FirebirdCompatibilityCountAccess access;
  access.relation_name = relation_name;
  access.predicate_column = predicate_column;
  for (const auto& [index_name, index] : state.indexes) {
    (void)index_name;
    if (!index.active ||
        UpperIdentifier(index.relation) != access.relation_name) {
      continue;
    }
    const auto key_columns = FirebirdIndexKeyColumns(index);
    if (!key_columns.empty() && key_columns.front() == access.predicate_column) {
      access.indexed = true;
      break;
    }
  }
  return access.indexed
             ? std::optional<FirebirdCompatibilityCountAccess>(std::move(access))
             : std::nullopt;
}

std::uint16_t EnsureFirebirdCompatibilityRelationId(
    FirebirdBinarySessionState* state,
    std::string_view relation_name) {
  if (state == nullptr) return 0;
  const std::string key = UpperIdentifier(relation_name);
  if (const auto found = state->relation_id_by_name.find(key);
      found != state->relation_id_by_name.end()) {
    return found->second;
  }
  if (state->next_user_relation_id < 128) state->next_user_relation_id = 128;
  const std::uint16_t relation_id = state->next_user_relation_id;
  if (relation_id == 0) return 0;
  state->relation_id_by_name[key] = relation_id;
  if (state->next_user_relation_id !=
      std::numeric_limits<std::uint16_t>::max()) {
    ++state->next_user_relation_id;
  }
  return relation_id;
}

void ConfigureFirebirdCompatibilityCountAccess(
    FirebirdBinarySessionState* state,
    FirebirdRemoteHandle* statement,
    std::string_view accepted_sql) {
  if (statement == nullptr) return;
  statement->compatibility_relation_id = 0;
  statement->compatibility_indexed_access = false;
  statement->compatibility_count_access = false;
  statement->compatibility_access_recorded = false;
  if (state == nullptr) return;
  const auto access =
      DescribeFirebirdCompatibilityCountAccess(*state, accepted_sql);
  if (!access) return;
  const auto relation_id =
      EnsureFirebirdCompatibilityRelationId(state, access->relation_name);
  if (relation_id == 0) return;
  statement->compatibility_relation_id = relation_id;
  statement->compatibility_indexed_access = access->indexed;
  statement->compatibility_count_access = true;
}

void RecordFirebirdCompatibilityCountAccess(
    FirebirdBinarySessionState* state,
    FirebirdRemoteHandle* statement,
    const std::vector<FirebirdRow>& engine_rows) {
  if (state == nullptr || statement == nullptr ||
      !statement->compatibility_count_access ||
      statement->compatibility_access_recorded || engine_rows.empty() ||
      engine_rows.front().cells.empty() || engine_rows.front().cells.front().is_null) {
    return;
  }
  const auto count = ParseSignedText(engine_rows.front().cells.front().text);
  if (!count || *count < 0) return;
  statement->compatibility_access_recorded = true;
  if (*count == 0) return;
  auto& counters =
      state->relation_access_counters[statement->compatibility_relation_id];
  auto& destination = statement->compatibility_indexed_access
                          ? counters.indexed_reads
                          : counters.sequential_reads;
  const auto increment = static_cast<std::uint64_t>(*count);
  destination = increment > std::numeric_limits<std::uint64_t>::max() - destination
                    ? std::numeric_limits<std::uint64_t>::max()
                    : destination + increment;
}

FirebirdPipelineResult ExecuteFirebirdStatement(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    bool cursor_requested) {
  if (state != nullptr && state->execution_call_context != nullptr) {
    const auto* selected = FirebirdExecutionTransactionSelector(
        *state, state->execution_call_context->wire_transaction_id);
    if (selected != nullptr &&
        FirebirdTransactionSelectorsEqual(
            *selected, state->execution_call_context->selector)) {
      return ExecuteFirebirdStatement(
          state, sql_text, cursor_requested,
          state->execution_call_context->selector);
    }
  }
  FirebirdPipelineResult result;
  result.accepted = false;
  result.messages.diagnostics.push_back(
      scratchbird::parser::ipc::MakeDiagnostic(
          "FIREBIRD.TRANSACTION.SELECTOR_REQUIRED", "ERROR",
          "Firebird execution requires an explicit bound wire transaction handle.",
          "sbp_firebird.worker_session"));
  TraceFirebirdWorker(
      "firebird_direct_route.reject=exact_transaction_selector_required sql=" +
      EscapeJsonLocal(sql_text));
  (void)state;
  (void)cursor_requested;
  return result;
}

FirebirdPipelineResult ExecuteFirebirdStatement(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    bool cursor_requested,
    std::uint32_t transaction_id) {
  if (state == nullptr) {
    return ExecuteFirebirdStatement(state, sql_text, cursor_requested);
  }
  const auto* transaction =
      FirebirdExecutionTransactionSelector(*state, transaction_id);
  if (transaction == nullptr) {
    return ExecuteFirebirdStatement(state, sql_text, cursor_requested);
  }
  return ExecuteFirebirdStatement(state, sql_text, cursor_requested,
                                  *transaction);
}

FirebirdPipelineResult ExecuteFirebirdStatement(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    bool cursor_requested,
    const scratchbird::parser::ipc::ParserTransactionSelector& transaction) {
  EnsureFirebirdExecutionSession(state);
  const std::string original_sql = StripTerminatingSemicolon(sql_text);
  const std::string original_upper = ToUpperAscii(TrimAscii(original_sql));
  if (original_upper.starts_with("INSERT INTO")) {
    if (auto overlay_result = ExecuteFirebirdOverlayInsert(state, original_sql)) {
      return *overlay_result;
    }
  }
  if (original_upper.starts_with("COMMENT ON GENERATOR ")) {
    if (auto overlay_result = ExecuteFirebirdCommentOnGenerator(state, original_sql)) {
      return *overlay_result;
    }
  }
  if (original_upper.starts_with("UPDATE ")) {
    if (auto overlay_result =
            ExecuteFirebirdOverlayNullFillUpdate(state, original_sql)) {
      return *overlay_result;
    }
    if (auto overlay_result =
            ExecuteFirebirdOverlayCopyUpdate(state, original_sql)) {
      return *overlay_result;
    }
  }
  if (original_upper.starts_with("DROP INDEX")) {
    if (auto overlay_result = ExecuteFirebirdOverlayDropIndex(state, original_sql)) {
      return *overlay_result;
    }
  }
  if (original_upper.starts_with("ALTER INDEX")) {
    if (auto overlay_result = ExecuteFirebirdOverlayAlterIndex(state, original_sql)) {
      return *overlay_result;
    }
  }
  const auto dropped_table = FirebirdDropTableName(original_sql);
  if (dropped_table) {
    const std::string table_key = FirebirdOverlayTableKey(*dropped_table);
    if (state->overlay_only_tables.find(table_key) !=
        state->overlay_only_tables.end()) {
      RecordFirebirdDropTable(state, original_sql);
      return FirebirdOverlayAcceptedResult(0);
    }
  }
  std::optional<FirebirdTableDescriptor> recreated_table;
  if (original_upper.starts_with("RECREATE TABLE")) {
    FirebirdTableDescriptor parsed_recreated_table;
    (void)NormalizeFirebirdCreateTableForCanonical(*state, original_sql, &parsed_recreated_table);
    if (!parsed_recreated_table.name.empty()) {
      recreated_table = parsed_recreated_table;
    }
    if (recreated_table && state->tables.find(recreated_table->name) != state->tables.end()) {
      const std::string drop_sql = "DROP TABLE " + recreated_table->name;
      TraceFirebirdWorker("canonical_sblr_route.recreate_table_prelude=" +
                          EscapeJsonLocal(drop_sql));
      auto drop_result =
          state->execution_session->RunStatement(drop_sql, transaction,
                                                 true, false, 0, false,
                                                 state->database_default_charset,
                                                 state->current_attachment_charset);
      if (!drop_result.accepted) {
        TraceFirebirdWorker("canonical_sblr_route.recreate_table_drop_reject=" +
                            scratchbird::parser::ipc::MessageVectorToJson(
                                drop_result.messages));
        return drop_result;
      }
      state->tables.erase(recreated_table->name);
      for (auto it = state->indexes.begin(); it != state->indexes.end();) {
        if (UpperIdentifier(it->second.relation) == UpperIdentifier(recreated_table->name)) {
          it = state->indexes.erase(it);
        } else {
          ++it;
        }
      }
      PersistFirebirdMetadataOverlay(*state);
    }
  }
  if (original_upper.starts_with("UPDATE ")) {
    if (const auto before_update =
            FirebirdBeforeUpdateCurrentContext(*state, original_sql)) {
      const std::string base_statement = original_sql;
      TraceFirebirdWorker("firebird_direct_route.input=" + EscapeJsonLocal(sql_text));
      (void)EnsureFirebirdRouteAuthenticated(
          state, "firebird_direct_route.before_update_base");
      auto result =
          state->execution_session->RunStatement(base_statement, transaction,
                                                 true, cursor_requested, 0,
                                                 false,
                                                 state->database_default_charset,
                                                 state->current_attachment_charset);
      if (!result.accepted) {
        TraceFirebirdWorker("firebird_direct_route.reject=" +
                            scratchbird::parser::ipc::MessageVectorToJson(result.messages));
        return result;
      }
      const std::uint64_t changed =
          result.server_affected_rows_present ? result.server_affected_rows
                                              : result.server_row_count;
      if (changed == 0) return result;
      for (const auto& [column_name, literal_value] : before_update->assignments) {
        std::string audit_sql = "UPDATE " + before_update->table_name +
                                " SET " + column_name + " = " + literal_value;
        if (!before_update->tail_clause.empty()) {
          audit_sql += " " + before_update->tail_clause;
        }
        TraceFirebirdWorker("firebird_direct_route.before_update_audit=" +
                            EscapeJsonLocal(audit_sql));
        auto audit_result =
            state->execution_session->RunStatement(audit_sql, transaction,
                                                   true, false, 0, false,
                                                   state->database_default_charset,
                                                   state->current_attachment_charset);
        if (!audit_result.accepted) {
          TraceFirebirdWorker("firebird_direct_route.before_update_audit_reject=" +
                              scratchbird::parser::ipc::MessageVectorToJson(
                                  audit_result.messages));
          return audit_result;
        }
      }
      return result;
    }
  }
  TraceFirebirdWorker("firebird_direct_route.input=" + EscapeJsonLocal(sql_text));
  (void)EnsureFirebirdRouteAuthenticated(state, "firebird_direct_route");
  auto result =
      state->execution_session->RunStatement(original_sql, transaction,
                                             true, cursor_requested, 0, false,
                                             state->database_default_charset,
                                             state->current_attachment_charset);
  if (!result.accepted) {
    TraceFirebirdWorker("firebird_direct_route.reject=" +
                        scratchbird::parser::ipc::MessageVectorToJson(result.messages));
    const std::string diagnostic =
        scratchbird::parser::ipc::MessageVectorToJson(result.messages);
    if (recreated_table &&
        diagnostic.find("CATALOG.OBJECT.DUPLICATE_NAME") != std::string::npos) {
      const std::string table_key = FirebirdOverlayTableKey(recreated_table->name);
      state->tables[recreated_table->name] = *recreated_table;
      state->overlay_only_tables.insert(table_key);
      state->overlay_rows[table_key].clear();
      for (auto it = state->indexes.begin(); it != state->indexes.end();) {
        if (UpperIdentifier(it->second.relation) == UpperIdentifier(recreated_table->name)) {
          it = state->indexes.erase(it);
        } else {
          ++it;
        }
      }
      PersistFirebirdMetadataOverlay(*state);
      TraceFirebirdWorker("firebird_overlay.recreate_table table=" + table_key);
      return FirebirdOverlayAcceptedResult(0);
    }
  } else {
    if (result.procedural_block_route.recognized()) {
      // RunStatement admits this route only after validating the exact neutral
      // procedural result kind, zero rows, and a nil cursor.  Keep a positive
      // wire-level breadcrumb so direct op_exec_immediate QA cases cannot be
      // mistaken for the legacy API-behavior fallback.
      TraceFirebirdWorker(
          "firebird_direct_route.engine_procedural_block_path=" +
          std::string(FirebirdBoundedExecuteBlockRouteName(
              result.procedural_block_route.kind)) +
          " zero_yield=true parser_overlay=none");
    }
    if (dropped_table) {
      RecordFirebirdDropTable(state, original_sql);
    }
    if (recreated_table) {
      const std::string table_key = FirebirdOverlayTableKey(recreated_table->name);
      state->overlay_only_tables.erase(table_key);
      state->overlay_rows.erase(table_key);
    }
  }
  return result;
}

FirebirdPipelineResult ExecuteFirebirdGeneratedUuidInsertSelect(
    FirebirdBinarySessionState* state,
    const FirebirdGeneratedUuidInsertSelect& info) {
  FirebirdPipelineResult aggregate;
  aggregate.accepted = true;
  aggregate.statement_family = "dml";
  aggregate.operation_family = "insert_select";
  aggregate.server_affected_rows_present = true;
  aggregate.server_affected_rows = 0;
  for (std::uint64_t row = 1; row <= info.row_count; ++row) {
    const std::string sql = "INSERT INTO " + info.table_name + " (" + info.columns.front() +
                            ") VALUES (" +
                            FirebirdCanonicalStringLiteral(FirebirdGeneratedUuidText(row)) + ")";
    auto executed = ExecuteFirebirdStatement(state, sql, false);
    if (!executed.accepted) {
      TraceFirebirdWorker("generated_uuid_insert_select.reject row=" + std::to_string(row) +
                          " sql=" + EscapeJsonLocal(sql));
      return executed;
    }
    aggregate = std::move(executed);
    aggregate.accepted = true;
    aggregate.server_affected_rows_present = true;
    aggregate.server_affected_rows = row;
    aggregate.server_row_count = row;
  }
  return aggregate;
}

std::string PipelineDiagnosticJson(const FirebirdPipelineResult& result,
                                   std::string_view operation) {
  std::string code = FirstDiagnosticCode(result.messages);
  if (code.empty()) code = "FIREBIRD.SBLR.EXECUTION_REJECTED";
  return "{\"ok\":false,\"wire_operation\":\"" + std::string(operation) + "\","
         "\"diagnostic_code\":\"" + EscapeJsonLocal(code) + "\","
         "\"runtime_policy\":\"scratchbird_server_admission_required\"}";
}

std::string FirebirdTransactionAuthorityDiagnostic(
    std::string_view operation,
    std::string_view diagnostic_code,
    std::string_view runtime_policy) {
  return "{\"ok\":false,\"wire_operation\":\"" + std::string(operation) +
         "\",\"diagnostic_code\":\"" + std::string(diagnostic_code) +
         "\",\"parser_transaction_finality_authority\":false,"
         "\"runtime_policy\":\"" + std::string(runtime_policy) + "\"}";
}

bool FirebirdTransactionSelectorsEqual(
    const scratchbird::parser::ipc::ParserTransactionSelector& left,
    const scratchbird::parser::ipc::ParserTransactionSelector& right) {
  return left.local_transaction_id == right.local_transaction_id &&
         left.transaction_uuid == right.transaction_uuid;
}

bool FirebirdExecutionTransactionBindingIsActive(
    const FirebirdExecutionTransactionBinding& binding) {
  return binding.lifecycle == FirebirdExecutionTransactionLifecycle::kActive &&
         binding.selector.present();
}

const scratchbird::parser::ipc::ParserTransactionSelector*
FirebirdExecutionTransactionSelector(
    const FirebirdBinarySessionState& state,
    std::uint32_t transaction_id) {
  const auto found = state.execution_transactions.find(transaction_id);
  if (found == state.execution_transactions.end() ||
      !FirebirdExecutionTransactionBindingIsActive(found->second)) {
    return nullptr;
  }
  return &found->second.selector;
}

bool FirebirdActiveTransactionSelectorMatches(
    const FirebirdBinarySessionState& state,
    const scratchbird::parser::ipc::ParserTransactionSelector& selector) {
  if (!selector.present() || !state.execution_transaction_route_usable ||
      state.execution_session == nullptr || !state.execution_authenticated) {
    return false;
  }
  for (const auto& [wire_id, binding] : state.execution_transactions) {
    (void)wire_id;
    if (FirebirdExecutionTransactionBindingIsActive(binding) &&
        FirebirdTransactionSelectorsEqual(binding.selector, selector)) {
      return true;
    }
  }
  return false;
}

bool FirebirdStatementHasCursorState(const FirebirdRemoteHandle& statement) {
  return !statement.cursor_uuid.empty() ||
         statement.cursor_owner_selector.present() ||
         statement.cursor_route_stale || !statement.buffered_rows.empty() ||
         !statement.end_of_cursor;
}

void DiscardFirebirdStatementCursorData(FirebirdRemoteHandle* statement) {
  if (statement == nullptr) return;
  statement->cursor_uuid.clear();
  statement->buffered_rows.clear();
  statement->next_row_index = 0;
  statement->end_of_cursor = true;
  statement->data.clear();
  statement->buffered_fetch_error_status.clear();
  statement->buffered_fetch_error_response.clear();
  statement->compatibility_fetch_profile.clear();
  statement->compatibility_fetch_compressed = false;
  statement->compatibility_relation_id = 0;
  statement->compatibility_indexed_access = false;
  statement->compatibility_count_access = false;
  statement->compatibility_access_recorded = false;
}

void ClearFirebirdStatementCursorRoute(FirebirdRemoteHandle* statement) {
  if (statement == nullptr) return;
  DiscardFirebirdStatementCursorData(statement);
  statement->cursor_owner_selector = {};
  statement->cursor_route_stale = false;
}

void ClearFirebirdStatementPreparedRoute(FirebirdRemoteHandle* statement) {
  if (statement == nullptr) return;
  statement->prepared_statement_uuid.clear();
  statement->prepare_transaction_selector = {};
  statement->prepared_statement_stale = false;
  statement->parser_local_metadata_only = false;
  statement->parser_local_transaction_control = false;
  statement->parser_local_procedure_call = false;
  statement->engine_routine_route_kind =
      FirebirdBoundedProcedureRouteKind::kUnsupported;
  statement->engine_procedural_route_kind =
      FirebirdBoundedExecuteBlockKind::kUnsupported;
  statement->engine_scalar_projection_route = {};
  statement->engine_global_count_projection_route = {};
  statement->engine_global_avg_projection_route = {};
  statement->engine_global_avg_projection_result_kind =
      FirebirdGlobalAvgResultKind::kUnsupported;
  statement->engine_global_aggregate_view_create_route = {};
  statement->engine_global_aggregate_view_select_route = {};
  statement->engine_global_aggregate_view_result_kind =
      FirebirdGlobalAvgResultKind::kUnsupported;
  statement->engine_global_aggregate_view_result_alias.clear();
  statement->engine_relation_projection_view_create_route = {};
  statement->engine_relation_projection_view_create_v2_route = {};
  statement->engine_relation_projection_view_delete_v2_route = {};
  statement->engine_relation_projection_view_select_route = {};
  statement->engine_relation_projection_view_outputs.clear();
  statement->engine_relation_projection_view_uuid.clear();
  statement->engine_relation_projection_view_descriptor_uuid.clear();
  statement->engine_relation_projection_view_descriptor_generation = 0;
  statement->catalog_projection_route = {};
  statement->catalog_relation_uuid.clear();
  statement->catalog_relation_descriptor_uuid.clear();
  statement->catalog_relation_descriptor_generation = 0;
  statement->firebird_virtual_catalog_projection = false;
  statement->prepared_recreate_table = false;
  statement->prepared_recreate_table_name.clear();
  statement->prepared_recreate_table_quoted = false;
}

void ClearFirebirdStatementPreparationDescriptor(
    FirebirdRemoteHandle* statement) {
  if (statement == nullptr) return;
  statement->descriptor_json =
      "{\"ok\":false,\"runtime_policy\":\"statement_unprepared\"}";
  statement->sql_text.clear();
  statement->translated_sql.clear();
  statement->plan_text.clear();
  statement->detailed_plan_text.clear();
  statement->result_columns.clear();
  statement->input_parameters.clear();
  statement->engine_scalar_projection_route = {};
  statement->engine_global_count_projection_route = {};
  statement->engine_global_avg_projection_route = {};
  statement->engine_global_avg_projection_result_kind =
      FirebirdGlobalAvgResultKind::kUnsupported;
  statement->engine_global_aggregate_view_create_route = {};
  statement->engine_global_aggregate_view_select_route = {};
  statement->engine_global_aggregate_view_result_kind =
      FirebirdGlobalAvgResultKind::kUnsupported;
  statement->engine_global_aggregate_view_result_alias.clear();
  statement->engine_relation_projection_view_create_route = {};
  statement->engine_relation_projection_view_create_v2_route = {};
  statement->engine_relation_projection_view_delete_v2_route = {};
  statement->engine_relation_projection_view_select_route = {};
  statement->engine_relation_projection_view_outputs.clear();
  statement->engine_relation_projection_view_uuid.clear();
  statement->engine_relation_projection_view_descriptor_uuid.clear();
  statement->engine_relation_projection_view_descriptor_generation = 0;
  statement->result_column_count = 0;
  statement->statement_type = 5;
  statement->last_affected_rows = 0;
  statement->last_affected_rows_present = false;
}

// FIREBIRD_CORE_0076_PREPARED_METADATA_TRANSFER_GUARD_BEGIN
bool FirebirdStatementUsesPreparedMetadataTransferV1(
    const FirebirdBinarySessionState& state,
    const FirebirdRemoteHandle& statement) {
  // This is only a parser-side retention decision for the exact bounded
  // invocation.  The server decides whether its opaque prepared record is
  // transferable and retains all metadata snapshot/version authority.
  return statement.engine_routine_route_kind ==
             FirebirdBoundedProcedureRouteKind::kInvokeLiteralIntegerPair &&
         !statement.prepared_statement_uuid.empty() &&
         statement.prepare_transaction_selector.present() &&
         state.execution_session != nullptr &&
         state.execution_authenticated &&
         state.execution_session->session()
             .prepared_metadata_transfer_v1_negotiated;
}
// FIREBIRD_CORE_0076_PREPARED_METADATA_TRANSFER_GUARD_END

void RetireFirebirdStatementRoutesForFinalizedSelector(
    FirebirdBinarySessionState* state,
    const scratchbird::parser::ipc::ParserTransactionSelector& selector) {
  if (state == nullptr || !selector.present()) return;
  for (auto& handle : state->handles) {
    if (handle.kind != "statement") continue;
    if (!handle.prepared_statement_uuid.empty() &&
        handle.prepare_transaction_selector.present() &&
        FirebirdTransactionSelectorsEqual(handle.prepare_transaction_selector,
                                          selector)) {
      // Retaining publishes a replacement under the same Firebird wire id.
      // Never rewrite this immutable prepare selector to the replacement.
      if (FirebirdStatementUsesPreparedMetadataTransferV1(*state, handle)) {
        // D__trans finality does not retire the server-owned immutable
        // metadata binding.  Keep only the opaque prepared UUID; M__trans is
        // still selected independently at execute.
        TraceFirebirdWorker(
            "prepared_metadata_transfer_v1.finalized_prepare_selector="
            "retained_opaque_prepared_uuid");
      } else {
        handle.prepared_statement_stale = true;
      }
    }
    if (handle.cursor_owner_selector.present() &&
        FirebirdTransactionSelectorsEqual(handle.cursor_owner_selector,
                                          selector)) {
      DiscardFirebirdStatementCursorData(&handle);
      handle.cursor_route_stale = true;
    }
  }
}

void RetireAllFirebirdPreparedAndCursorRoutes(
    FirebirdBinarySessionState* state) {
  if (state == nullptr) return;
  for (auto& handle : state->handles) {
    if (handle.kind != "statement") continue;
    if (!handle.prepared_statement_uuid.empty()) {
      handle.prepared_statement_stale = true;
    }
    if (FirebirdStatementHasCursorState(handle)) {
      DiscardFirebirdStatementCursorData(&handle);
      handle.cursor_route_stale = true;
    }
  }
}

struct FirebirdStatementRouteCloseResult {
  std::optional<std::string> diagnostic;
  bool quarantine_route{false};
};

template <typename CloseResult>
bool FirebirdStatementCloseRequiresRouteQuarantine(
    const CloseResult& closed) {
  return closed.route_fatal || closed.outcome_unknown ||
         closed.caller_cleanup_required;
}

FirebirdStatementRouteCloseResult CloseFirebirdStatementCursor(
    FirebirdBinarySessionState* state,
    FirebirdRemoteHandle* statement,
    std::string_view operation,
    bool reject_stale_owner) {
  if (state == nullptr || statement == nullptr ||
      !FirebirdStatementHasCursorState(*statement)) {
    return {};
  }
  const bool stale_owner = statement->cursor_route_stale ||
                           !statement->cursor_owner_selector.present() ||
                           !FirebirdActiveTransactionSelectorMatches(
                               *state, statement->cursor_owner_selector);
  if (stale_owner) {
    if (!reject_stale_owner) {
      ClearFirebirdStatementCursorRoute(statement);
      return {};
    }
    // A deterministic stale-owner refusal must not discard the identity that
    // the Firebird client may retry or explicitly release later.
    return {FirebirdTransactionAuthorityDiagnostic(
                operation, "FIREBIRD.DSQL.CURSOR_TRANSACTION_RETIRED",
                "fail_closed_cursor_owner_selector_stale"),
            false};
  }

  const std::string cursor_uuid = statement->cursor_uuid;
  if (cursor_uuid.empty()) {
    ClearFirebirdStatementCursorRoute(statement);
    return {};
  }
  const auto closed =
      state->execution_session->CloseCursorOnRoute(cursor_uuid);
  const bool quarantine_route =
      FirebirdStatementCloseRequiresRouteQuarantine(closed);
  if (closed.accepted && !quarantine_route) {
    ClearFirebirdStatementCursorRoute(statement);
    return {};
  }
  std::string code = closed.outcome_unknown
                         ? "PARSER_SERVER_IPC.OUTCOME_UNKNOWN"
                         : FirstDiagnosticCode(closed.messages);
  if (code.empty()) code = "FIREBIRD.DSQL.CURSOR_CLOSE_REJECTED";
  return {FirebirdTransactionAuthorityDiagnostic(
              operation, code,
              closed.outcome_unknown
                  ? "fail_closed_neutral_cursor_close_outcome_unknown"
                  : quarantine_route
                  ? "fail_closed_neutral_cursor_close_route_unavailable"
                  : "fail_closed_neutral_cursor_close_rejected"),
          quarantine_route};
}

FirebirdStatementRouteCloseResult CloseFirebirdStatementPreparedRoute(
    FirebirdBinarySessionState* state,
    FirebirdRemoteHandle* statement,
    std::string_view operation) {
  if (state == nullptr || statement == nullptr ||
      statement->prepared_statement_uuid.empty()) {
    return {};
  }
  if (state->execution_session == nullptr ||
      !state->execution_authenticated) {
    return {FirebirdTransactionAuthorityDiagnostic(
                operation,
                "FIREBIRD.DSQL.PREPARED_CLOSE_ROUTE_REQUIRED",
                "fail_closed_neutral_prepared_close_route_required"),
            false};
  }

  // The neutral close is session-owned and bound to this negotiated physical
  // route.  Do not consult the immutable prepare selector: it may already have
  // been finalized, and this operation neither executes SBLR nor owns
  // transaction finality.
  const auto closed = state->execution_session->ClosePreparedSblrOnRoute(
      statement->prepared_statement_uuid);
  const bool quarantine_route =
      FirebirdStatementCloseRequiresRouteQuarantine(closed);
  if (closed.accepted && !quarantine_route) return {};
  std::string code = closed.outcome_unknown
                         ? "PARSER_SERVER_IPC.OUTCOME_UNKNOWN"
                         : FirstDiagnosticCode(closed.messages);
  if (code.empty()) code = "FIREBIRD.DSQL.PREPARED_CLOSE_REJECTED";
  return {FirebirdTransactionAuthorityDiagnostic(
              operation, code,
              closed.outcome_unknown
                  ? "fail_closed_neutral_prepared_close_outcome_unknown"
                  : quarantine_route
                  ? "fail_closed_neutral_prepared_close_route_unavailable"
                  : "fail_closed_neutral_prepared_close_rejected"),
          quarantine_route};
}

std::vector<FirebirdColumnDescriptor>
DescribeFirebirdCatalogProjectionColumns(
    const FirebirdBinarySessionState& state,
    const FirebirdCatalogProjectionRoute& route) {
  std::vector<FirebirdColumnDescriptor> columns;
  if (!route.is_select()) return columns;
  FirebirdCatalogProjectionSqlDaProfile profile;
  profile.database_default_charset_id = static_cast<std::uint16_t>(
      FirebirdCharacterSetId(state.database_default_charset));
  profile.database_default_charset_max_bytes_per_character =
      static_cast<std::uint16_t>(
          FirebirdCharacterSetMaxBytes(state.database_default_charset));
  profile.statement_charset_id = static_cast<std::uint16_t>(
      FirebirdCharacterSetId(state.current_attachment_charset));
  profile.statement_charset_max_bytes_per_character =
      static_cast<std::uint16_t>(
          FirebirdCharacterSetMaxBytes(state.current_attachment_charset));

  const auto described =
      DescribeFirebirdCatalogProjectionSqlDa(route, profile);
  if (!described.ok) {
    TraceFirebirdWorker(
        "catalog_projection.sqlda_rejected diagnostic=" +
        EscapeJsonLocal(described.diagnostic));
    return columns;
  }
  const auto fetch_message = BuildFirebirdCatalogProjectionFetchBlr(
      described.columns, state.database_sql_dialect);
  if (!fetch_message.ok) {
    TraceFirebirdWorker(
        "catalog_projection.fetch_blr_rejected diagnostic=" +
        EscapeJsonLocal(fetch_message.diagnostic));
    return columns;
  }
  TraceFirebirdWorker(
      "catalog_projection.sqlda_exact=true columns=" +
      std::to_string(described.columns.size()) +
      " message_length=" + std::to_string(fetch_message.message_length) +
      " database_charset=" +
      EscapeJsonLocal(state.database_default_charset) +
      " statement_charset=" +
      EscapeJsonLocal(state.current_attachment_charset));
  columns.reserve(described.columns.size());
  for (const auto& source : described.columns) {
    FirebirdColumnDescriptor column;
    column.name = source.field_name;
    column.alias = source.alias_name;
    column.source_name = source.field_name;
    column.relation = source.relation_name;
    column.sql_type = source.sql_type;
    column.length = source.length;
    column.scale = source.scale;
    column.subtype = source.subtype;
    column.nullable = source.nullable;
    if (column.sql_type == 448 || column.sql_type == 452) {
      // Firebird exposes the text charset through SQLDA sqlsubtype. Keep the
      // separately modeled BLR charset identifier as the fallback while the
      // exact SQLDA helper remains the presentation authority.
      if (column.subtype == 0 && source.charset_id != 0) {
        column.subtype = source.charset_id;
      }
      const std::uint32_t max_bytes =
          source.charset_id == profile.statement_charset_id &&
                  source.relation_name.empty()
              ? profile.statement_charset_max_bytes_per_character
              : source.charset_id == profile.database_default_charset_id &&
                        source.field_name == "FIELD_TYPE"
                    ? profile.database_default_charset_max_bytes_per_character
                    : source.charset_id == 4 ? 4u : 1u;
      column.character_length =
          std::max<std::uint32_t>(1, column.length / std::max(1u, max_bytes));
    }
    columns.push_back(std::move(column));
  }
  return columns;
}

std::vector<FirebirdRow> FirebirdCatalogProjectionRows(
    const FirebirdCatalogProjectionRenderResult& rendered) {
  std::vector<FirebirdRow> rows;
  if (!rendered.ok) return rows;
  rows.reserve(rendered.rows.size());
  for (const auto& source : rendered.rows) {
    FirebirdRow row;
    row.cells.reserve(source.cells.size());
    for (const auto& cell : source.cells) {
      row.cells.push_back(
          FirebirdCell{!cell.has_value(), cell.value_or(std::string{})});
    }
    rows.push_back(std::move(row));
  }
  return rows;
}

FirebirdPipelineResult PrepareFirebirdStatementOnExactRoute(
    FirebirdBinarySessionState* state,
    FirebirdRemoteHandle* statement,
    std::uint32_t transaction_id) {
  FirebirdPipelineResult rejected;
  const auto* selector = state == nullptr
                             ? nullptr
                             : FirebirdExecutionTransactionSelector(
                                   *state, transaction_id);
  if (state == nullptr || statement == nullptr || selector == nullptr ||
      state->execution_session == nullptr) {
    rejected.messages.diagnostics.push_back(
        scratchbird::parser::ipc::MakeDiagnostic(
            "FIREBIRD.TRANSACTION.SELECTOR_REQUIRED", "ERROR",
            "Prepared Firebird lowering requires an exact active engine transaction selector.",
            "sbp_firebird.worker"));
    return rejected;
  }

  const auto catalog_rebind_route =
      FirebirdCatalogProjectionRouteForExactRebind(
          statement->catalog_projection_route);
  auto prepared = statement->catalog_projection_route.recognized()
                      ? state->execution_session->PrepareCatalogProjection(
                            catalog_rebind_route, *selector)
                      : state->execution_session->PrepareStatement(
                            statement->sql_text, *selector,
                            state->database_default_charset,
                            state->current_attachment_charset);
  if (!prepared.accepted) return prepared;
  if (prepared.prepared_statement_uuid.empty()) {
    prepared.accepted = false;
    prepared.messages.diagnostics.push_back(
        scratchbird::parser::ipc::MakeDiagnostic(
            "FIREBIRD.DSQL.PREPARED_UUID_MISSING", "ERROR",
            "The neutral prepare route did not publish an opaque prepared statement identity.",
            "sbp_firebird.worker"));
    return prepared;
  }
  statement->prepared_statement_uuid = prepared.prepared_statement_uuid;
  statement->prepare_transaction_selector = *selector;
  statement->prepared_statement_stale = false;
  statement->engine_procedural_route_kind =
      prepared.procedural_block_route.kind;
  if (statement->engine_global_count_projection_route.recognized()) {
    if (!prepared.global_count_projection_route.recognized()) {
      prepared.accepted = false;
      prepared.messages.diagnostics.push_back(
          scratchbird::parser::ipc::MakeDiagnostic(
              "FIREBIRD.AGGREGATE.BOUND_ROUTE_REQUIRED", "ERROR",
              "The neutral prepare result omitted the exact bound Firebird global COUNT route.",
              "sbp_firebird.worker"));
      return prepared;
    }
    statement->engine_global_count_projection_route =
        prepared.global_count_projection_route;
  }
  if (statement->engine_global_avg_projection_route.recognized()) {
    if (!prepared.global_avg_projection_route.recognized() ||
        prepared.global_avg_projection_result_kind ==
            FirebirdGlobalAvgResultKind::kUnsupported) {
      prepared.accepted = false;
      prepared.messages.diagnostics.push_back(
          scratchbird::parser::ipc::MakeDiagnostic(
              "FIREBIRD.AGGREGATE.BOUND_ROUTE_REQUIRED", "ERROR",
              "The neutral prepare result omitted the exact bound Firebird global AVG route and result descriptor.",
              "sbp_firebird.worker"));
      return prepared;
    }
    statement->engine_global_avg_projection_route =
        prepared.global_avg_projection_route;
    statement->engine_global_avg_projection_result_kind =
        prepared.global_avg_projection_result_kind;
    auto avg_columns = DescribeFirebirdGlobalAvgProjectionRoute(
        statement->engine_global_avg_projection_route,
        statement->engine_global_avg_projection_result_kind);
    if (avg_columns.size() != 1) {
      prepared.accepted = false;
      prepared.messages.diagnostics.push_back(
          scratchbird::parser::ipc::MakeDiagnostic(
              "FIREBIRD.AGGREGATE.RESULT_DESCRIPTOR_REQUIRED", "ERROR",
              "The bound Firebird AVG route did not produce one exact nullable SQLDA result descriptor.",
              "sbp_firebird.worker"));
      return prepared;
    }
    statement->result_columns = std::move(avg_columns);
    statement->result_column_count = 1;
  }
  if (statement->engine_global_aggregate_view_create_route.recognized() &&
      !prepared.global_aggregate_view_create_route.recognized()) {
    prepared.accepted = false;
    prepared.messages.diagnostics.push_back(
        scratchbird::parser::ipc::MakeDiagnostic(
            "FIREBIRD.AGGREGATE_VIEW.BOUND_CREATE_ROUTE_REQUIRED", "ERROR",
            "The neutral prepare result omitted the exact bound Firebird aggregate-view create route.",
            "sbp_firebird.worker"));
    return prepared;
  }
  if (statement->engine_relation_projection_view_create_route.recognized() &&
      !prepared.relation_projection_view_create_route.recognized()) {
    prepared.accepted = false;
    prepared.messages.diagnostics.push_back(
        scratchbird::parser::ipc::MakeDiagnostic(
            "FIREBIRD.RELATION_VIEW.BOUND_CREATE_ROUTE_REQUIRED", "ERROR",
            "The neutral prepare result omitted the exact bound Firebird relation-projection view create route.",
            "sbp_firebird.worker"));
    return prepared;
  }
  if (statement->engine_relation_projection_view_create_v2_route.recognized() &&
      !prepared.relation_projection_view_create_v2_route.recognized()) {
    prepared.accepted = false;
    prepared.messages.diagnostics.push_back(
        scratchbird::parser::ipc::MakeDiagnostic(
            "FIREBIRD.RELATION_VIEW.V2.BOUND_CREATE_ROUTE_REQUIRED", "ERROR",
            "The neutral prepare result omitted the exact bound Firebird V2 direct-column view create route.",
            "sbp_firebird.worker"));
    return prepared;
  }
  if (statement->engine_relation_projection_view_delete_v2_route.recognized() &&
      !prepared.relation_projection_view_delete_v2_route.recognized()) {
    prepared.accepted = false;
    prepared.messages.diagnostics.push_back(
        scratchbird::parser::ipc::MakeDiagnostic(
            "FIREBIRD.RELATION_VIEW.V2.BOUND_DELETE_ROUTE_REQUIRED", "ERROR",
            "The neutral prepare result omitted the exact table-first/public-view-bound Firebird V2 delete route.",
            "sbp_firebird.worker"));
    return prepared;
  }
  if (statement->engine_relation_projection_view_select_route.recognized()) {
    if (!prepared.relation_projection_view_select_route.recognized() ||
        prepared.relation_projection_view_outputs.size() != 2u ||
        prepared.relation_projection_view_uuid.empty() ||
        prepared.relation_projection_view_descriptor_uuid.empty() ||
        prepared.relation_projection_view_descriptor_generation == 0 ||
        (!statement->engine_relation_projection_view_uuid.empty() &&
         statement->engine_relation_projection_view_uuid !=
             prepared.relation_projection_view_uuid) ||
        (!statement->engine_relation_projection_view_descriptor_uuid.empty() &&
         statement->engine_relation_projection_view_descriptor_uuid !=
             prepared.relation_projection_view_descriptor_uuid) ||
        (statement->engine_relation_projection_view_descriptor_generation !=
             0 &&
         statement->engine_relation_projection_view_descriptor_generation !=
             prepared.relation_projection_view_descriptor_generation) ||
        (!statement->engine_relation_projection_view_outputs.empty() &&
         !SameFirebirdRelationProjectionViewOutputs(
             statement->engine_relation_projection_view_outputs,
             prepared.relation_projection_view_outputs))) {
      prepared.accepted = false;
      prepared.messages.diagnostics.push_back(
          scratchbird::parser::ipc::MakeDiagnostic(
              "FIREBIRD.RELATION_VIEW.BOUND_SELECT_ROUTE_REQUIRED", "ERROR",
              "The neutral prepare result omitted or changed the exact engine-semantic relation-view output descriptors.",
              "sbp_firebird.worker"));
      return prepared;
    }
    statement->engine_relation_projection_view_select_route =
        prepared.relation_projection_view_select_route;
    statement->engine_relation_projection_view_outputs =
        prepared.relation_projection_view_outputs;
    statement->engine_relation_projection_view_uuid =
        prepared.relation_projection_view_uuid;
    statement->engine_relation_projection_view_descriptor_uuid =
        prepared.relation_projection_view_descriptor_uuid;
    statement->engine_relation_projection_view_descriptor_generation =
        prepared.relation_projection_view_descriptor_generation;
    auto view_columns = DescribeFirebirdRelationProjectionViewOutputs(
        statement->engine_relation_projection_view_select_route,
        statement->engine_relation_projection_view_outputs);
    if (view_columns.size() != 2u ||
        view_columns[0].sql_type != 496 || view_columns[0].length != 4u ||
        view_columns[1].sql_type != 496 || view_columns[1].length != 4u ||
        view_columns[1].nullable) {
      prepared.accepted = false;
      prepared.messages.diagnostics.push_back(
          scratchbird::parser::ipc::MakeDiagnostic(
              "FIREBIRD.RELATION_VIEW.RESULT_DESCRIPTOR_REQUIRED", "ERROR",
              "The persisted relation view did not produce exactly two engine-described SQL_LONG(4) SQLDA outputs.",
              "sbp_firebird.worker"));
      return prepared;
    }
    statement->result_columns = std::move(view_columns);
    statement->result_column_count = 2;
  }
  if (statement->engine_global_aggregate_view_select_route.recognized()) {
    if (!prepared.global_aggregate_view_select_route.recognized() ||
        prepared.global_aggregate_view_result_kind !=
            FirebirdGlobalAvgResultKind::kNullableInt64 ||
        prepared.global_aggregate_view_result_alias.empty() ||
        (!statement->engine_global_aggregate_view_result_alias.empty() &&
         statement->engine_global_aggregate_view_result_alias !=
             prepared.global_aggregate_view_result_alias)) {
      prepared.accepted = false;
      prepared.messages.diagnostics.push_back(
          scratchbird::parser::ipc::MakeDiagnostic(
              "FIREBIRD.AGGREGATE_VIEW.BOUND_SELECT_ROUTE_REQUIRED", "ERROR",
              "The neutral prepare result omitted the exact engine-semantic aggregate-view result descriptor.",
              "sbp_firebird.worker"));
      return prepared;
    }
    statement->engine_global_aggregate_view_select_route =
        prepared.global_aggregate_view_select_route;
    statement->engine_global_aggregate_view_result_kind =
        prepared.global_aggregate_view_result_kind;
    statement->engine_global_aggregate_view_result_alias =
        prepared.global_aggregate_view_result_alias;
    const auto presentation_route =
        FirebirdGlobalAggregateViewAvgPresentationRoute(
            statement->engine_global_aggregate_view_select_route,
            statement->engine_global_aggregate_view_result_alias,
            statement->engine_global_aggregate_view_result_kind);
    auto view_columns = DescribeFirebirdGlobalAvgProjectionRoute(
        presentation_route,
        statement->engine_global_aggregate_view_result_kind);
    if (view_columns.size() != 1 || view_columns.front().sql_type != 580 ||
        view_columns.front().length != 8 ||
        !view_columns.front().nullable) {
      prepared.accepted = false;
      prepared.messages.diagnostics.push_back(
          scratchbird::parser::ipc::MakeDiagnostic(
              "FIREBIRD.AGGREGATE_VIEW.RESULT_DESCRIPTOR_REQUIRED", "ERROR",
              "The bound aggregate view did not produce one nullable SQL_INT64(8) SQLDA descriptor.",
              "sbp_firebird.worker"));
      return prepared;
    }
    statement->result_columns = std::move(view_columns);
    statement->result_column_count = 1;
  }
  if (statement->catalog_projection_route.recognized()) {
    statement->catalog_projection_route = prepared.catalog_projection_route;
    statement->catalog_relation_uuid = prepared.catalog_relation_uuid;
    statement->catalog_relation_descriptor_uuid =
        prepared.catalog_relation_descriptor_uuid;
    statement->catalog_relation_descriptor_generation =
        prepared.catalog_relation_descriptor_generation;
  }
  return prepared;
}

FirebirdPipelineResult ExecuteFirebirdPreparedStatementOnExactRoute(
    FirebirdBinarySessionState* state,
    FirebirdRemoteHandle* statement,
    const scratchbird::parser::ipc::ParserTransactionSelector& selected,
    bool cursor_requested) {
  FirebirdPipelineResult result;
  auto reject = [&](std::string code, std::string message) {
    result.accepted = false;
    result.messages.diagnostics.push_back(
        scratchbird::parser::ipc::MakeDiagnostic(
            std::move(code), "ERROR", std::move(message),
            "sbp_firebird.worker"));
    return result;
  };
  if (state == nullptr || statement == nullptr ||
      state->execution_session == nullptr ||
      statement->prepared_statement_uuid.empty() ||
      !statement->prepare_transaction_selector.present()) {
    return reject(
        "FIREBIRD.DSQL.PREPARED_HANDLE_REQUIRED",
        "Firebird execution requires an opaque neutral prepared statement identity.");
  }
  if (statement->prepared_statement_stale) {
    return reject(
        "FIREBIRD.DSQL.PREPARED_STATEMENT_STALE",
        "The Firebird prepared statement belongs to a finalized or retired engine transaction.");
  }
  const bool transferable_prepared_metadata =
      FirebirdStatementUsesPreparedMetadataTransferV1(*state, *statement);
  if (!selected.present() ||
      (!FirebirdTransactionSelectorsEqual(
           statement->prepare_transaction_selector, selected) &&
       !transferable_prepared_metadata)) {
    return reject(
        "FIREBIRD.DSQL.PREPARED_TRANSACTION_SELECTOR_MISMATCH",
        "The Firebird execute transaction does not match the immutable prepare transaction selector.");
  }

  const auto executed = state->execution_session->ExecutePreparedSblrRouted(
      statement->prepared_statement_uuid, selected, {}, {}, cursor_requested);
  result.accepted = executed.accepted;
  result.server_execution = executed;
  result.server_row_count = executed.row_count;
  result.server_affected_rows = executed.affected_rows;
  result.server_affected_rows_present = executed.affected_rows_present;
  result.server_cursor_uuid = executed.cursor_uuid;
  result.server_result_payload = executed.row_packet;
  result.messages = executed.messages;
  if (!executed.selected_transaction_present ||
      !executed.selected_transaction.present() ||
      !FirebirdTransactionSelectorsEqual(executed.selected_transaction,
                                         selected)) {
    statement->prepared_statement_stale = true;
    result.accepted = false;
    result.messages.diagnostics.push_back(
        scratchbird::parser::ipc::MakeDiagnostic(
            "FIREBIRD.DSQL.PREPARED_SELECTED_SELECTOR_MISMATCH", "ERROR",
            "The neutral prepared execution result did not echo the exact selected transaction.",
            "sbp_firebird.worker"));
    return result;
  }
  if (!executed.accepted) {
    const std::string code = FirstDiagnosticCode(executed.messages);
    if (code.find("PREPARED_STATEMENT_STALE") != std::string::npos ||
        code.find("PREPARED_TRANSACTION_SELECTOR_MISMATCH") !=
            std::string::npos) {
      statement->prepared_statement_stale = true;
    }
    return result;
  }
  return result;
}

std::optional<std::string> SelectFirebirdExecutionTransaction(
    FirebirdBinarySessionState* state,
    std::uint32_t transaction_id,
    std::string_view operation) {
  if (state == nullptr || transaction_id == 0) {
    return FirebirdTransactionAuthorityDiagnostic(
        operation, "FIREBIRD.TRANSACTION.HANDLE_REQUIRED",
        "fail_closed_engine_transaction_handle_required");
  }
  const auto found = state->execution_transactions.find(transaction_id);
  if (found == state->execution_transactions.end()) {
    return FirebirdTransactionAuthorityDiagnostic(
        operation, "FIREBIRD.TRANSACTION.ENGINE_BINDING_REQUIRED",
        "fail_closed_unbound_wire_transaction_handle");
  }
  if (!state->execution_transaction_route_usable ||
      state->execution_session == nullptr ||
      !state->execution_authenticated ||
      !FirebirdExecutionTransactionBindingIsActive(found->second)) {
    return FirebirdTransactionAuthorityDiagnostic(
        operation, "FIREBIRD.TRANSACTION.ENGINE_IDENTITY_MISMATCH",
        "fail_closed_stale_or_aliased_engine_transaction_identity");
  }
  return std::nullopt;
}

class FirebirdExecutionCallScope {
 public:
  FirebirdExecutionCallScope(FirebirdBinarySessionState* state,
                             std::uint32_t transaction_id)
      : state_(state) {
    if (state_ == nullptr || transaction_id == 0 ||
        state_->execution_call_context != nullptr) {
      return;
    }
    const auto* selector =
        FirebirdExecutionTransactionSelector(*state_, transaction_id);
    if (selector == nullptr) return;
    context_.wire_transaction_id = transaction_id;
    context_.selector = *selector;
    state_->execution_call_context = &context_;
  }

  FirebirdExecutionCallScope(const FirebirdExecutionCallScope&) = delete;
  FirebirdExecutionCallScope& operator=(const FirebirdExecutionCallScope&) =
      delete;

  ~FirebirdExecutionCallScope() {
    if (state_ != nullptr && state_->execution_call_context == &context_) {
      state_->execution_call_context = nullptr;
    }
  }

  [[nodiscard]] bool active() const {
    return state_ != nullptr && state_->execution_call_context == &context_ &&
           context_.selector.present();
  }

 private:
  FirebirdBinarySessionState* state_{nullptr};
  FirebirdExecutionCallContext context_;
};

std::string FirebirdTransactionPolicyDiagnosticJson(
    std::string_view operation,
    const FirebirdTransactionPolicyDiagnostic& diagnostic) {
  const std::string code = diagnostic.scratchbird_code.empty()
                               ? "FIREBIRD.TRANSACTION.POLICY_REJECTED"
                               : diagnostic.scratchbird_code;
  std::string json = FirebirdTransactionAuthorityDiagnostic(
      operation, code, "fail_closed_firebird_transaction_policy_rejected");
  json.insert(json.size() - 1,
              ",\"input_offset\":" +
                  std::to_string(diagnostic.input_offset) +
                  ",\"sql_code\":" + std::to_string(diagnostic.sql_code));
  return json;
}

std::string FirebirdExecutionOutcomeDiagnosticJson(
    std::string_view operation,
    const scratchbird::parser::ipc::ServerExecutionResult& result,
    std::string_view fallback_code,
    std::string_view runtime_policy) {
  std::string code = result.transaction_diagnostic_code;
  if (code.empty()) code = FirstDiagnosticCode(result.messages);
  if (code.empty()) code = std::string(fallback_code);
  return FirebirdTransactionAuthorityDiagnostic(operation, code, runtime_policy);
}

void RetireAllFirebirdWireTransactionHandles(
    FirebirdBinarySessionState* state) {
  if (state == nullptr) return;
  RetireAllFirebirdPreparedAndCursorRoutes(state);
  std::set<std::uint32_t> transaction_ids;
  for (auto& [wire_id, binding] : state->execution_transactions) {
    binding.lifecycle = FirebirdExecutionTransactionLifecycle::kFinalityUnknown;
    transaction_ids.insert(wire_id);
  }
  for (const auto& handle : state->handles) {
    if (handle.kind == "transaction") transaction_ids.insert(handle.id);
  }
  state->execution_transactions.clear();
  for (const auto transaction_id : transaction_ids) {
    RemoveHandlesByParent(state, transaction_id);
    (void)RemoveHandle(state, transaction_id);
  }
}

bool FirebirdPrepareRequiresRouteQuarantine(
    const FirebirdPipelineResult& prepared) {
  return prepared.server_prepare.outcome_unknown ||
         prepared.server_prepare.caller_cleanup_required;
}

bool FirebirdPreparedExecuteRequiresRouteQuarantine(
    const FirebirdPipelineResult& executed,
    const scratchbird::parser::ipc::ParserTransactionSelector& selected) {
  const auto& server = executed.server_execution;
  return server.finality_state ==
             scratchbird::parser::ipc::ParserTransactionFinality::kUnknown ||
         !server.selected_transaction_present ||
         !server.selected_transaction.present() ||
         !FirebirdTransactionSelectorsEqual(server.selected_transaction,
                                            selected);
}

void QuarantineFirebirdPreparedPhysicalRoute(
    FirebirdBinarySessionState* state,
    std::string_view operation,
    std::string_view reason) {
  if (state == nullptr) return;
  state->execution_transaction_route_usable = false;
  RetireAllFirebirdWireTransactionHandles(state);
  if (const auto cleanup_diagnostic =
          DisconnectFirebirdExecutionSession(state, operation)) {
    TraceFirebirdWorker(std::string(operation) +
                        ".prepared_route_quarantine_disconnect_reject=" +
                        EscapeJsonLocal(*cleanup_diagnostic));
  }
  // Destroying the neutral client closes its dedicated physical V2 channel
  // even when the disconnect acknowledgement itself is unavailable.
  state->execution_authenticated = false;
  state->execution_session.reset();
  TraceFirebirdWorker(std::string(operation) +
                      ".prepared_route_quarantined reason=" +
                      EscapeJsonLocal(reason));
}

std::optional<std::string> StartFirebirdExecutionTransaction(
    FirebirdBinarySessionState* state,
    std::uint32_t transaction_id,
    const FirebirdTransactionPolicy& policy,
    std::string_view operation) {
  if (state == nullptr || transaction_id == 0) {
    return FirebirdTransactionAuthorityDiagnostic(
        operation, "FIREBIRD.TRANSACTION.HANDLE_REQUIRED",
        "fail_closed_engine_transaction_handle_required");
  }
  if (!EnsureFirebirdRouteAuthenticated(
          state, "firebird_wire_transaction_begin")) {
    return FirebirdTransactionAuthorityDiagnostic(
        operation, "FIREBIRD.TRANSACTION.ENGINE_ROUTE_REQUIRED",
        "fail_closed_engine_mga_transaction_route_required");
  }
  const auto begun = state->execution_session->BeginAdditional(policy);
  if (!begun.accepted) {
    if (begun.finality_state ==
        scratchbird::parser::ipc::ParserTransactionFinality::kUnknown) {
      state->execution_transaction_route_usable = false;
      RetireAllFirebirdWireTransactionHandles(state);
      if (const auto cleanup_diagnostic =
              DisconnectFirebirdExecutionSession(state, operation)) {
        TraceFirebirdWorker(std::string(operation) +
                            ".begin_unknown_cleanup_reject=" +
                            EscapeJsonLocal(*cleanup_diagnostic));
      }
    }
    return FirebirdExecutionOutcomeDiagnosticJson(
        operation, begun, "FIREBIRD.TRANSACTION.BEGIN_REJECTED",
        begun.finality_state ==
                scratchbird::parser::ipc::ParserTransactionFinality::kUnknown
            ? "fail_closed_begin_outcome_unknown_route_retired"
            : "fail_closed_engine_transaction_begin_rejected");
  }
  if (!begun.selected_transaction_present ||
      !begun.selected_transaction.present()) {
    state->execution_transaction_route_usable = false;
    RetireAllFirebirdWireTransactionHandles(state);
    (void)DisconnectFirebirdExecutionSession(state, operation);
    return FirebirdTransactionAuthorityDiagnostic(
        operation, "FIREBIRD.TRANSACTION.ENGINE_IDENTITY_MISSING",
        "fail_closed_unpublishable_begin_route_retired");
  }
  const FirebirdExecutionTransactionBinding binding{
      begun.selected_transaction,
      FirebirdExecutionTransactionLifecycle::kActive};
  const auto initial = state->execution_session->InitialTransactionSelector();
  if (initial.present() &&
      (binding.selector.local_transaction_id == initial.local_transaction_id ||
       binding.selector.transaction_uuid == initial.transaction_uuid)) {
    state->execution_transaction_route_usable = false;
    RetireAllFirebirdWireTransactionHandles(state);
    (void)DisconnectFirebirdExecutionSession(state, operation);
    return FirebirdTransactionAuthorityDiagnostic(
        operation, "FIREBIRD.TRANSACTION.ENGINE_IDENTITY_ALIAS",
        "fail_closed_begin_additional_alias_route_retired");
  }
  bool aliases_existing = false;
  for (const auto& [wire_id, existing] : state->execution_transactions) {
    (void)wire_id;
    if (existing.selector.local_transaction_id ==
            binding.selector.local_transaction_id ||
        existing.selector.transaction_uuid ==
            binding.selector.transaction_uuid) {
      aliases_existing = true;
      break;
    }
  }
  if (aliases_existing) {
    state->execution_transaction_route_usable = false;
    RetireAllFirebirdWireTransactionHandles(state);
    (void)DisconnectFirebirdExecutionSession(state, operation);
    return FirebirdTransactionAuthorityDiagnostic(
        operation, "FIREBIRD.TRANSACTION.ENGINE_IDENTITY_ALIAS",
        "fail_closed_begin_additional_alias_route_retired");
  }
  state->execution_transactions.emplace(transaction_id, binding);
  return std::nullopt;
}

std::optional<std::string> FinishFirebirdTransaction(
    FirebirdBinarySessionState* state,
    std::uint32_t transaction_id,
    bool commit,
    bool retaining,
    std::string_view operation) {
  if (const auto diagnostic =
          SelectFirebirdExecutionTransaction(state, transaction_id, operation)) {
    return diagnostic;
  }
  auto& binding = state->execution_transactions.at(transaction_id);
  const auto finalized_selector = binding.selector;
  binding.lifecycle =
      FirebirdExecutionTransactionLifecycle::kFinalityInProgress;
  const auto finished = commit
                            ? (retaining
                                   ? state->execution_session
                                         ->CommitRetainingTransaction(
                                             finalized_selector)
                                   : state->execution_session->CommitTransaction(
                                         finalized_selector))
                            : (retaining
                                   ? state->execution_session
                                         ->RollbackRetainingTransaction(
                                             finalized_selector)
                                   : state->execution_session->RollbackTransaction(
                                         finalized_selector));
  TraceFirebirdWorker(std::string(operation) + ".canonical_sblr_finish.accepted=" +
                      (finished.accepted ? "true" : "false") +
                      " retaining=" + (retaining ? "true" : "false") +
                      " operation_id=" +
                      EscapeJsonLocal(finished.operation_id) +
                      " outcome=" +
                      EscapeJsonLocal(finished.transaction_outcome_detail));

  const bool selected_matches =
      finished.selected_transaction_present &&
      FirebirdTransactionSelectorsEqual(finished.selected_transaction,
                                        finalized_selector);
  const bool finalized_matches =
      finished.finalized_transaction_present &&
      FirebirdTransactionSelectorsEqual(finished.finalized_transaction,
                                        finalized_selector);
  const bool operation_matches =
      finished.operation_id ==
      (commit ? "transaction.commit" : "transaction.rollback");
  auto finality = finished.finality_state;
  if (!selected_matches || !operation_matches ||
      (finality ==
           scratchbird::parser::ipc::ParserTransactionFinality::kKnownApplied &&
       !finalized_matches)) {
    finality = scratchbird::parser::ipc::ParserTransactionFinality::kUnknown;
  }

  if (finality ==
      scratchbird::parser::ipc::ParserTransactionFinality::kKnownNotApplied) {
    binding.lifecycle = FirebirdExecutionTransactionLifecycle::kActive;
    return FirebirdExecutionOutcomeDiagnosticJson(
        operation, finished,
        "FIREBIRD.TRANSACTION.FINALITY_KNOWN_NOT_APPLIED",
        "engine_finality_known_not_applied_wire_handle_retained");
  }

  if (finality !=
      scratchbird::parser::ipc::ParserTransactionFinality::kKnownApplied) {
    binding.lifecycle = FirebirdExecutionTransactionLifecycle::kFinalityUnknown;
    state->execution_transaction_route_usable = false;
    RetireAllFirebirdWireTransactionHandles(state);
    if (const auto cleanup_diagnostic =
            DisconnectFirebirdExecutionSession(state, operation)) {
      TraceFirebirdWorker(std::string(operation) +
                          ".unknown_finality_cleanup_reject=" +
                          EscapeJsonLocal(*cleanup_diagnostic));
    }
    return FirebirdTransactionAuthorityDiagnostic(
        operation, "FIREBIRD.TRANSACTION.FINALITY_OUTCOME_UNKNOWN",
        "fail_closed_all_wire_handles_retired_engine_route_unusable_no_retry");
  }

  RetireFirebirdStatementRoutesForFinalizedSelector(state,
                                                    finalized_selector);
  state->execution_transactions.erase(transaction_id);
  if (retaining) {
    const auto& replacement = finished.replacement_transaction;
    const bool replacement_is_distinct =
        finished.replacement_transaction_present && replacement.present() &&
        finished.replacement_reason ==
            scratchbird::parser::ipc::ParserTransactionReplacementReason::kRetaining &&
        replacement.local_transaction_id !=
            finalized_selector.local_transaction_id &&
        replacement.transaction_uuid != finalized_selector.transaction_uuid;
    if (!replacement_is_distinct) {
      RemoveHandlesByParent(state, transaction_id);
      (void)RemoveHandle(state, transaction_id);
      return FirebirdTransactionAuthorityDiagnostic(
          operation, "FIREBIRD.TRANSACTION.RETAINING_REPLACEMENT_UNAVAILABLE",
          "engine_finality_applied_wire_handle_retired");
    }
    const auto initial =
        state->execution_session->InitialTransactionSelector();
    bool replacement_alias =
        initial.present() &&
        (initial.local_transaction_id == replacement.local_transaction_id ||
         initial.transaction_uuid == replacement.transaction_uuid);
    for (const auto& [wire_id, existing] : state->execution_transactions) {
      if (wire_id != transaction_id &&
          (existing.selector.local_transaction_id ==
               replacement.local_transaction_id ||
           existing.selector.transaction_uuid ==
               replacement.transaction_uuid)) {
        replacement_alias = true;
        break;
      }
    }
    if (replacement_alias) {
      state->execution_transaction_route_usable = false;
      RetireAllFirebirdWireTransactionHandles(state);
      (void)DisconnectFirebirdExecutionSession(state, operation);
      return FirebirdTransactionAuthorityDiagnostic(
          operation, "FIREBIRD.TRANSACTION.RETAINING_REPLACEMENT_ALIAS",
          "engine_finality_applied_all_wire_handles_retired_route_unusable");
    }
    state->execution_transactions[transaction_id] = {
        replacement, FirebirdExecutionTransactionLifecycle::kActive};
    if (finished.accepted) return std::nullopt;
    return FirebirdExecutionOutcomeDiagnosticJson(
        operation, finished,
        "FIREBIRD.TRANSACTION.FINALITY_APPLIED_SECONDARY_FAILURE",
        "engine_finality_applied_replacement_published_secondary_failure");
  }
  if (finished.accepted) return std::nullopt;
  RemoveHandlesByParent(state, transaction_id);
  (void)RemoveHandle(state, transaction_id);
  return FirebirdExecutionOutcomeDiagnosticJson(
      operation, finished,
      "FIREBIRD.TRANSACTION.FINALITY_APPLIED_SECONDARY_FAILURE",
      "engine_finality_applied_wire_handle_retired_secondary_failure");
}

std::optional<std::string> RollbackFirebirdExecutionTransactionsForParent(
    FirebirdBinarySessionState* state,
    std::uint32_t parent_id,
    std::string_view operation) {
  std::vector<std::uint32_t> transaction_ids;
  for (const auto& handle : state->handles) {
    if (handle.kind == "transaction" &&
        (parent_id == 0 || handle.parent_id == parent_id)) {
      transaction_ids.push_back(handle.id);
    }
  }
  std::optional<std::string> first_diagnostic;
  for (const auto transaction_id : transaction_ids) {
    if (const auto diagnostic = FinishFirebirdTransaction(
            state, transaction_id, false, false, operation)) {
      if (!first_diagnostic) first_diagnostic = diagnostic;
      TraceFirebirdWorker(std::string(operation) +
                          ".rollback_handle_reject transaction_id=" +
                          std::to_string(transaction_id) + " diagnostic=" +
                          EscapeJsonLocal(*diagnostic));
      continue;
    }
    FinalizeFirebirdRestoreDescriptors(state, transaction_id, false);
    RemoveHandlesByParent(state, transaction_id);
    (void)RemoveHandle(state, transaction_id);
  }
  return first_diagnostic;
}

bool IsLastFirebirdAttachmentHandle(
    const FirebirdBinarySessionState& state,
    std::uint32_t releasing_handle_id) {
  for (const auto& handle : state.handles) {
    if (handle.id == releasing_handle_id) continue;
    if (handle.kind == "database" || handle.kind == "database_create" ||
        handle.kind == "service") {
      return false;
    }
  }
  return true;
}

std::optional<std::string> DisconnectFirebirdExecutionSession(
    FirebirdBinarySessionState* state,
    std::string_view operation) {
  if (state == nullptr || state->execution_session == nullptr ||
      !state->execution_authenticated) {
    return std::nullopt;
  }
  scratchbird::parser::ipc::MessageVectorSet messages;
  if (!state->execution_session->DisconnectSession(&messages)) {
    std::string code = FirstDiagnosticCode(messages);
    if (code.empty()) code = "FIREBIRD.TRANSACTION.SESSION_DISCONNECT_REJECTED";
    TraceFirebirdWorker(std::string(operation) + ".session_disconnect.reject=" +
                        scratchbird::parser::ipc::MessageVectorToJson(messages));
    return FirebirdTransactionAuthorityDiagnostic(
        operation, code, "fail_closed_engine_session_cleanup_required");
  }
  state->execution_authenticated = false;
  state->execution_transactions.clear();
  TraceFirebirdWorker(std::string(operation) +
                      ".engine_session_disconnect.accepted=true");
  return std::nullopt;
}

struct FirebirdExecutionSessionCleanupGuard {
  FirebirdBinarySessionState* state{nullptr};

  ~FirebirdExecutionSessionCleanupGuard() {
    if (state == nullptr) return;
    if (const auto diagnostic = RollbackFirebirdExecutionTransactionsForParent(
            state, 0, "connection_cleanup")) {
      TraceFirebirdWorker("connection_cleanup.rollback_reject=" +
                          EscapeJsonLocal(*diagnostic));
    }
    if (const auto diagnostic =
            DisconnectFirebirdExecutionSession(state, "connection_cleanup")) {
      TraceFirebirdWorker("connection_cleanup.session_disconnect_reject=" +
                          EscapeJsonLocal(*diagnostic));
    }
  }
};

std::string FirebirdAttachDescriptorJson(std::uint32_t opcode,
                                         const FirebirdAttachRequest& request,
                                         std::uint32_t handle_id,
                                         const ParameterBufferDecodeResult& decoded) {
  const bool service = opcode == 82;
  const std::string wire_operation =
      service ? "op_service_attach" : (opcode == 20 ? "op_create" : "op_attach");
  return std::string("{\"ok\":true,\"wire_operation\":\"") +
         wire_operation +
         "\",\"object_handle\":" + std::to_string(handle_id) +
         ",\"client_object_id\":" + std::to_string(request.object_id) +
         ",\"database_name\":\"" + BytesToJsonString(request.file_name) +
         "\",\"parameter_buffer_kind\":\"" + (service ? "SPB" : "DPB") +
         "\",\"parameter_buffer\":" + decoded.json +
         "," + FirebirdWireLifecycleMappingJson(wire_operation) +
         "\"real_firebird_file_effects\":false,"
         "\"reference_engine_sql_executed\":false,"
         "\"runtime_policy\":\"emulated_session_handle_admitted\"}";
}

std::string FirebirdBufferFailureJson(std::uint32_t opcode,
                                      const ParameterBufferDecodeResult& decoded) {
  return std::string("{\"ok\":false,\"wire_operation\":\"") +
         (opcode == 82 ? "op_service_attach" : (opcode == 20 ? "op_create" : "op_attach")) +
         "\",\"parameter_buffer\":" + decoded.json +
         ",\"runtime_policy\":\"fail_closed_parameter_buffer\"}";
}

std::string FirebirdServiceStartJson(const FirebirdInfoRequest& request,
                                     const ParameterBufferDecodeResult& decoded) {
  return "{\"ok\":true,\"wire_operation\":\"op_service_start\","
         "\"object_handle\":" + std::to_string(request.object_id) + ","
         "\"incarnation\":" + std::to_string(request.incarnation) + ","
         "\"parameter_buffer_kind\":\"SPB\","
         "\"parameter_buffer\":" + decoded.json + ","
         "\"runtime_policy\":\"emulated_service_action_admitted\"}";
}

std::string FirebirdServiceInfoJson(const FirebirdInfoRequest& request,
                                    const FirebirdRemoteHandle& handle) {
  return "{\"ok\":true,\"wire_operation\":\"op_service_info\","
         "\"object_handle\":" + std::to_string(request.object_id) + ","
         "\"handle_kind\":\"" + EscapeJsonLocal(handle.kind) + "\","
         "\"request_items_length\":" + std::to_string(request.items.size()) + ","
         "\"recv_items_length\":" + std::to_string(request.recv_items.size()) + ","
         "\"buffer_length\":" + std::to_string(request.buffer_length) + ","
         "\"emulated_service_report\":true,"
         "\"runtime_policy\":\"emulated_service_info_descriptor\"}";
}

std::vector<std::uint8_t> FirebirdServiceSysdbaRightsRequiredPacket(
    std::uint32_t object_id,
    std::string_view operation) {
  const auto status = FirebirdStatusVectorWithInterpreted(
      kIscNoPriv, {"You must have SYSDBA rights at this server"}, "28000");
  return FirebirdResponsePacket(
      object_id,
      "{\"ok\":false,\"wire_operation\":\"" + std::string(operation) + "\","
      "\"diagnostic_code\":\"FIREBIRD.SERVICE.SYSDBA_RIGHTS_REQUIRED\","
      "\"runtime_policy\":\"service_log_requires_sysdba\"}",
      status);
}

struct FirebirdPrepareStatementRequest {
  std::uint32_t transaction_id{0};
  std::uint32_t statement_id{0};
  std::uint32_t sql_dialect{0};
  std::vector<std::uint8_t> sql_text;
  std::vector<std::uint8_t> items;
  std::uint32_t buffer_length{0};
  std::vector<std::uint8_t> exec_immediate2_out_blr;
  std::uint32_t exec_immediate2_out_message_number{0};
};

struct FirebirdSqlDataRequest {
  std::uint32_t statement_id{0};
  std::uint32_t transaction_id{0};
  std::vector<std::uint8_t> blr;
  std::uint32_t message_number{0};
  std::uint32_t message_count{0};
  std::vector<std::vector<std::string>> decoded_messages;
  std::vector<std::uint8_t> out_blr;
  std::uint32_t out_message_number{0};
};

struct FirebirdFreeStatementRequest {
  std::uint32_t statement_id{0};
  std::uint32_t option{0};
};

struct FirebirdTransactionRequest {
  std::uint32_t database_id{0};
  std::vector<std::uint8_t> parameter_buffer;
};

struct FirebirdBlobRequest {
  std::uint32_t transaction_id{0};
  std::uint32_t blob_id_high{0};
  std::uint32_t blob_id_low{0};
  std::vector<std::uint8_t> parameter_buffer;
};

struct FirebirdSegmentRequest {
  std::uint32_t blob_id{0};
  std::uint32_t segment_length{0};
  std::vector<std::uint8_t> segment;
};

struct FirebirdEventRequest {
  std::uint32_t database_id{0};
  std::vector<std::uint8_t> items;
  std::uint32_t ast{0};
  std::uint32_t argument{0};
  std::uint32_t client_event_id{0};
};

struct FirebirdCompileRequest {
  std::uint32_t database_id{0};
  std::vector<std::uint8_t> blr;
};

struct FirebirdClassicDataRequest {
  std::uint32_t request_id{0};
  std::uint32_t incarnation{0};
  std::uint32_t transaction_id{0};
  std::uint32_t message_number{0};
  std::uint32_t message_count{0};
};

bool ReadFirebirdClassicMessagePayloadValues(
    int fd,
    const std::vector<std::uint8_t>& blr,
    std::uint32_t message_number,
    std::vector<std::string>* trace_args,
    std::vector<std::string>* values);
bool ReadFirebirdPackedMessagePayloadValues(
    int fd,
    const std::vector<std::uint8_t>& blr,
    std::uint32_t message_number,
    std::vector<std::string>* trace_args,
    std::vector<std::string>* values);

bool ReadFirebirdCompileRequestBody(int fd, FirebirdCompileRequest* request) {
  if (!ReadXdrU32(fd, &request->database_id) ||
      !ReadXdrString(fd, &request->blr)) {
    return false;
  }
  request->database_id &= 0xffffu;
  return true;
}

bool ReadFirebirdClassicDataHeader(int fd, FirebirdClassicDataRequest* request) {
  if (!ReadXdrU32(fd, &request->request_id) ||
      !ReadXdrU32(fd, &request->incarnation) ||
      !ReadXdrU32(fd, &request->transaction_id) ||
      !ReadXdrU32(fd, &request->message_number) ||
      !ReadXdrU32(fd, &request->message_count)) {
    return false;
  }
  request->request_id &= 0xffffu;
  request->incarnation &= 0xffffu;
  request->transaction_id &= 0xffffu;
  request->message_number &= 0xffffu;
  request->message_count &= 0xffffu;
  return true;
}

bool ReadFirebirdPrepareStatementBody(int fd, FirebirdPrepareStatementRequest* request) {
  if (!ReadXdrU32(fd, &request->transaction_id) ||
      !ReadXdrU32(fd, &request->statement_id) ||
      !ReadXdrU32(fd, &request->sql_dialect) ||
      !ReadXdrString(fd, &request->sql_text, kMaxFirebirdWorkerSqlString) ||
      !ReadXdrString(fd, &request->items) ||
      !ReadXdrU32(fd, &request->buffer_length)) {
    return false;
  }
  request->transaction_id &= 0xffffu;
  request->statement_id &= 0xffffu;
  request->sql_dialect &= 0xffffu;
  return true;
}

bool ReadFirebirdSqlDataBody(int fd,
                             bool with_transaction,
                             bool with_output,
                             FirebirdSqlDataRequest* request,
                             bool read_input_payload = true,
                             bool protocol13_packed = false) {
  if (!ReadXdrU32(fd, &request->statement_id)) return false;
  if (with_transaction && !ReadXdrU32(fd, &request->transaction_id)) return false;
  if (!ReadXdrString(fd, &request->blr) ||
      !ReadXdrU32(fd, &request->message_number) ||
      !ReadXdrU32(fd, &request->message_count)) {
    return false;
  }
  request->decoded_messages.clear();
  request->message_number &= 0xffffu;
  request->message_count &= 0xffffu;
  if (read_input_payload && request->message_count != 0) {
    for (std::uint32_t i = 0; i < request->message_count; ++i) {
      std::vector<std::string> trace_args;
      std::vector<std::string> values;
      const bool read_ok =
          protocol13_packed
              ? ReadFirebirdPackedMessagePayloadValues(
                    fd, request->blr, request->message_number,
                    &trace_args, &values)
              : ReadFirebirdClassicMessagePayloadValues(
                    fd, request->blr, request->message_number,
                    &trace_args, &values);
      if (!read_ok) {
        return false;
      }
      request->decoded_messages.push_back(std::move(values));
      TraceFirebirdWorker("op_execute.input_payload index=" + std::to_string(i) +
                          " trace_items=" + std::to_string(trace_args.size()));
    }
  }
  if (with_output &&
      (!ReadXdrString(fd, &request->out_blr) ||
       !ReadXdrU32(fd, &request->out_message_number))) {
    return false;
  }
  return true;
}

bool ReadFirebirdSqlDataBody(int fd, bool with_transaction, FirebirdSqlDataRequest* request) {
  return ReadFirebirdSqlDataBody(fd, with_transaction, false, request, true, false);
}

bool ReadFirebirdFreeStatementBody(int fd, FirebirdFreeStatementRequest* request) {
  return ReadXdrU32(fd, &request->statement_id) &&
         ReadXdrU32(fd, &request->option);
}

bool ReadFirebirdTransactionBody(int fd, FirebirdTransactionRequest* request) {
  return ReadXdrU32(fd, &request->database_id) &&
         ReadXdrString(fd, &request->parameter_buffer);
}

bool ReadFirebirdBlobBody(int fd, bool has_parameter_buffer, FirebirdBlobRequest* request) {
  if (has_parameter_buffer && !ReadXdrString(fd, &request->parameter_buffer)) return false;
  return ReadXdrU32(fd, &request->transaction_id) &&
         ReadXdrU32(fd, &request->blob_id_high) &&
         ReadXdrU32(fd, &request->blob_id_low);
}

bool ReadFirebirdSegmentBody(int fd, FirebirdSegmentRequest* request) {
  return ReadXdrU32(fd, &request->blob_id) &&
         ReadXdrU32(fd, &request->segment_length) &&
         ReadXdrString(fd, &request->segment);
}

bool ReadFirebirdEventBody(int fd, bool cancel_only, FirebirdEventRequest* request) {
  if (!ReadXdrU32(fd, &request->database_id)) return false;
  if (cancel_only) return ReadXdrU32(fd, &request->client_event_id);
  return ReadXdrString(fd, &request->items) &&
         ReadXdrU32(fd, &request->ast) &&
         ReadXdrU32(fd, &request->argument) &&
         ReadXdrU32(fd, &request->client_event_id);
}

