std::vector<std::uint8_t> FirebirdResponsePacket(
    std::uint32_t object_id,
    std::string_view response_data,
    const std::vector<std::uint8_t>& encoded_status_vector) {
  std::vector<std::uint8_t> out;
  AppendXdrU32(&out, 9);  // op_response
  AppendXdrU32(&out, object_id);
  AppendXdrU32(&out, 0);  // blob id high
  AppendXdrU32(&out, 0);  // blob id low
  AppendXdrString(&out, response_data);
  out.insert(out.end(), encoded_status_vector.begin(), encoded_status_vector.end());
  return out;
}

std::vector<std::uint8_t> FirebirdResponsePacket(
    std::uint32_t object_id,
    std::uint32_t blob_id_high,
    std::uint32_t blob_id_low,
    std::string_view response_data,
    const std::vector<std::uint8_t>& encoded_status_vector) {
  std::vector<std::uint8_t> out;
  AppendXdrU32(&out, 9);  // op_response
  AppendXdrU32(&out, object_id);
  AppendXdrU32(&out, blob_id_high);
  AppendXdrU32(&out, blob_id_low);
  AppendXdrString(&out, response_data);
  out.insert(out.end(), encoded_status_vector.begin(), encoded_status_vector.end());
  return out;
}

std::vector<std::uint8_t> FirebirdResponsePacket(
    std::uint32_t object_id,
    std::string_view response_data,
    const std::vector<std::uint32_t>& status_vector) {
  std::vector<std::uint8_t> encoded;
  for (const auto token : status_vector) AppendXdrU32(&encoded, token);
  return FirebirdResponsePacket(object_id, response_data, encoded);
}

