std::optional<std::string> FirebirdInvalidStringToIntegerCastLiteral(
    std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (upper.find(" FROM RDB$DATABASE") == std::string::npos ||
      upper.find("CAST") == std::string::npos) {
    return std::nullopt;
  }

  std::size_t search = 0;
  while (search < sql.size()) {
    const auto cast_pos = FindFirebirdWord(upper, "CAST", search);
    if (cast_pos == std::string::npos) break;
    const auto open = sql.find('(', cast_pos + 4);
    if (open == std::string::npos) break;
    std::size_t literal_pos = open + 1;
    SkipSqlWhitespace(sql, &literal_pos);
    const auto literal = ReadSqlStringLiteralAt(sql, &literal_pos);
    if (!literal) {
      search = cast_pos + 4;
      continue;
    }
    SkipSqlWhitespace(sql, &literal_pos);
    const auto as_pos = FindFirebirdWord(upper, "AS", literal_pos);
    if (as_pos == std::string::npos) {
      search = cast_pos + 4;
      continue;
    }
    std::size_t type_pos = as_pos + 2;
    std::string raw_type;
    if (!ReadSqlIdentifierToken(sql, &type_pos, &raw_type)) {
      search = cast_pos + 4;
      continue;
    }
    const std::string type = UpperIdentifier(raw_type);
    if (type != "INTEGER" && type != "INT") {
      search = cast_pos + 4;
      continue;
    }

    const bool has_comma = literal->find(',') != std::string::npos;
    const bool parses_as_double = ParseDoubleText(*literal).has_value();
    if (has_comma || !parses_as_double) return literal;
    search = cast_pos + 4;
  }
  return std::nullopt;
}

std::vector<std::uint8_t> FirebirdInvalidStringToIntegerCastStatus(
    std::string_view literal) {
  std::vector<std::uint8_t> status;
  AppendFirebirdStatusInt(&status, kIscArgGds, kIscConvertError);
  AppendFirebirdStatusText(&status, kIscArgString, literal);
  AppendFirebirdStatusText(&status, kIscArgSqlState, "22018");
  AppendXdrU32(&status, kIscArgEnd);
  return status;
}

std::string FirebirdInvalidStringToIntegerCastResponseJson(
    std::string_view literal,
    std::string_view operation) {
  return "{\"ok\":false,\"wire_operation\":\"" + std::string(operation) + "\","
         "\"diagnostic_code\":\"FIREBIRD.STRING_TO_INTEGER.CONVERSION_ERROR\","
         "\"sqlstate\":\"22018\","
         "\"literal\":\"" + EscapeJsonLocal(literal) + "\"}";
}

bool ApplyFirebirdInvalidStringToIntegerCastFetchError(
    FirebirdRemoteHandle* statement,
    std::string_view operation) {
  if (statement == nullptr) return false;
  const auto literal = FirebirdInvalidStringToIntegerCastLiteral(statement->sql_text);
  if (!literal) return false;
  statement->buffered_rows.clear();
  statement->next_row_index = 0;
  statement->buffered_fetch_error_status =
      FirebirdInvalidStringToIntegerCastStatus(*literal);
  statement->buffered_fetch_error_response =
      FirebirdInvalidStringToIntegerCastResponseJson(*literal, operation);
  statement->end_of_cursor = false;
  TraceFirebirdWorker("op_execute.invalid_string_to_integer_cast literal=" +
                      EscapeJsonLocal(*literal));
  return true;
}

