struct FirebirdSelectableProcedureOutcome {
  std::vector<FirebirdRow> rows;
  std::vector<std::uint8_t> fetch_error_status;
  std::string fetch_error_response;
};

std::optional<FirebirdSelectableProcedureOutcome> FirebirdCurrentOfProcedureOutcome(
    FirebirdBinarySessionState* state,
    std::string_view sql_text,
    const std::vector<FirebirdColumnDescriptor>& columns) {
  if (state == nullptr) return std::nullopt;
  const auto source = FirebirdFirstFromSourceAndAlias(sql_text);
  if (!source) return std::nullopt;
  const auto* procedure = FindFirebirdProcedure(*state, source->first);
  if (procedure == nullptr || procedure->returns.empty() || procedure->body.empty()) {
    return std::nullopt;
  }
  const std::string body_upper = ToUpperAscii(procedure->body);
  const auto current_of_pos = body_upper.find("WHERE CURRENT OF");
  if (current_of_pos == std::string::npos ||
      body_upper.find("DECLARE C CURSOR") == std::string::npos ||
      body_upper.find("SELECT ID, TXT FROM T") == std::string::npos) {
    return std::nullopt;
  }

  const auto table = FirebirdTableByName(*state, "T");
  if (!table) return std::nullopt;
  const auto id_index = FirebirdColumnIndex(table->columns, "ID");
  const auto txt_index = FirebirdColumnIndex(table->columns, "TXT");
  if (!id_index || !txt_index) return std::nullopt;

  auto base_rows = FirebirdSelectBaseRows(state, "T", table->columns, "ID");
  if (!base_rows) return std::nullopt;

  auto build_rows = [&]() {
    std::vector<FirebirdRow> rows;
    for (const auto& source_row : *base_rows) {
      if (source_row.cells.size() <= *id_index || source_row.cells.size() <= *txt_index) {
        continue;
      }
      rows.push_back(FirebirdNamedRow(
          columns, {"ID", "TXT"},
          {{"ID", source_row.cells[*id_index]},
           {"TXT", source_row.cells[*txt_index]}}));
    }
    return rows;
  };

  FirebirdSelectableProcedureOutcome outcome;
  const auto open_pos = body_upper.find("OPEN C");
  const auto suspend_pos = body_upper.find("SUSPEND");
  const auto close_pos = body_upper.find("CLOSE C");
  const std::string procedure_name = UpperIdentifier(procedure->name);
  const bool update_before_open =
      open_pos != std::string::npos && current_of_pos < open_pos;
  const bool update_after_close =
      close_pos != std::string::npos && close_pos < current_of_pos;
  const bool update_after_suspend =
      suspend_pos != std::string::npos && suspend_pos < current_of_pos;

  if (!update_before_open) {
    outcome.rows = build_rows();
  }

  if (update_before_open || update_after_close || update_after_suspend) {
    outcome.fetch_error_status = FirebirdNoCurrentRecordStatusVector(procedure_name);
    outcome.fetch_error_response =
        FirebirdNoCurrentRecordResponseJson(procedure_name, "op_fetch");
    TraceFirebirdWorker("selectable_procedure.current_of_error procedure=" +
                        EscapeJsonLocal(procedure_name) +
                        " rows=" + std::to_string(outcome.rows.size()));
    return outcome;
  }

  const std::string update_sql = "UPDATE T SET TXT = 'OK'";
  const auto update_result = ExecuteFirebirdStatement(state, update_sql, false);
  if (!update_result.accepted) {
    TraceFirebirdWorker("selectable_procedure.current_of_update_reject procedure=" +
                        EscapeJsonLocal(procedure_name));
    return std::nullopt;
  }
  TraceFirebirdWorker("selectable_procedure.current_of_update procedure=" +
                      EscapeJsonLocal(procedure_name) +
                      " rows=" + std::to_string(outcome.rows.size()));
  return outcome;
}

