bool FirebirdProcedureHasUnusedNavigationalPlan(std::string_view sql_text) {
  const std::string upper = ToUpperAscii(
      StripFirebirdBodyLineComments(StripTerminatingSemicolon(sql_text)));
  return IsFirebirdCreateProcedureStatement(sql_text) &&
         upper.find("PLAN (TEST ORDER TEST_F01)") != std::string::npos &&
         upper.find("ORDER BY") == std::string::npos;
}

