struct FirebirdForeignKeyValidationIssue {
  std::string child_table;
  std::string parent_table;
  bool parent_table_missing{false};
};

bool FirebirdIdentifierVectorsEqual(const std::vector<std::string>& lhs,
                                    const std::vector<std::string>& rhs) {
  if (lhs.size() != rhs.size()) return false;
  for (std::size_t index = 0; index < lhs.size(); ++index) {
    if (UpperIdentifier(FirebirdLeafIdentifier(lhs[index])) !=
        UpperIdentifier(FirebirdLeafIdentifier(rhs[index]))) {
      return false;
    }
  }
  return true;
}

bool FirebirdTableHasUniqueColumnSet(const FirebirdTableDescriptor& table,
                                     const std::vector<std::string>& columns) {
  if (columns.empty()) return false;
  for (const auto& unique_columns : table.unique_column_sets) {
    if (FirebirdIdentifierVectorsEqual(unique_columns, columns)) return true;
  }
  if (columns.size() == 1) {
    const auto column_index = FirebirdColumnIndex(table.columns, columns.front());
    return column_index && (table.columns[*column_index].primary_key ||
                            table.columns[*column_index].unique_key);
  }
  return false;
}

std::optional<FirebirdForeignKeyValidationIssue>
AnalyzeFirebirdForeignKeyMissingUniqueParent(
    const FirebirdBinarySessionState& state,
    std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  const bool create_table = upper.starts_with("CREATE TABLE") ||
                            upper.starts_with("RECREATE TABLE");
  if (!create_table || upper.find("REFERENCES") == std::string::npos) {
    return std::nullopt;
  }
  std::size_t table_pos = upper.starts_with("RECREATE TABLE")
                              ? std::string("RECREATE TABLE").size()
                              : std::string("CREATE TABLE").size();
  std::string raw_child_table;
  if (!ReadSqlIdentifierToken(sql, &table_pos, &raw_child_table)) return std::nullopt;
  const std::string child_table = UpperIdentifier(FirebirdLeafIdentifier(raw_child_table));
  const auto open = sql.find('(', table_pos);
  const auto close = open == std::string::npos ? std::string::npos : sql.rfind(')');
  if (open == std::string::npos || close == std::string::npos || close <= open) {
    return std::nullopt;
  }
  FirebirdTableDescriptor pending_child_table;
  (void)NormalizeFirebirdCreateTableForCanonical(
      state, sql_text, &pending_child_table);
  for (const auto& raw_definition :
       SplitTopLevelComma(sql.substr(open + 1, close - open - 1))) {
    const std::string definition = TrimAscii(raw_definition);
    const std::string def_upper = ToUpperAscii(definition);
    const auto fk_pos = def_upper.find("FOREIGN KEY");
    const auto references_pos = def_upper.find("REFERENCES");
    if (references_pos == std::string::npos) continue;
    std::vector<std::string> parent_columns;
    std::size_t parent_pos = references_pos + std::string("REFERENCES").size();
    std::string raw_parent_table;
    if (!ReadSqlIdentifierToken(definition, &parent_pos, &raw_parent_table)) continue;
    const std::string parent_table_name = FirebirdLeafIdentifier(raw_parent_table);
    SkipSqlWhitespace(definition, &parent_pos);
    if (parent_pos < definition.size() && definition[parent_pos] == '(') {
      const auto parent_column_text =
          ExtractBalancedParenthesizedText(definition, parent_pos);
      if (parent_column_text) {
        for (const auto& raw_column : SplitTopLevelComma(*parent_column_text)) {
          const std::string column = FirebirdLeafIdentifier(raw_column);
          if (!column.empty()) parent_columns.push_back(column);
        }
      }
    }
    if (parent_columns.empty() && fk_pos != std::string::npos) {
      parent_columns = FirebirdIdentifierListFromFirstParentheses(
          definition.substr(fk_pos));
    }
    const std::string parent_table_key =
        UpperIdentifier(FirebirdLeafIdentifier(parent_table_name));
    if (parent_table_key == child_table) {
      if (!parent_columns.empty() &&
          !FirebirdTableHasUniqueColumnSet(pending_child_table,
                                           parent_columns)) {
        return FirebirdForeignKeyValidationIssue{
            child_table,
            parent_table_key,
            false};
      }
      continue;
    }
    const auto parent_table = FirebirdTableByName(state, parent_table_name);
    if (!parent_table) {
      return FirebirdForeignKeyValidationIssue{
          child_table,
          parent_table_key,
          true};
    }
    if (parent_columns.empty()) continue;
    if (!FirebirdTableHasUniqueColumnSet(*parent_table, parent_columns)) {
      return FirebirdForeignKeyValidationIssue{
          child_table,
          UpperIdentifier(FirebirdLeafIdentifier(parent_table_name)),
          false};
    }
  }
  return std::nullopt;
}

std::vector<std::uint8_t> FirebirdForeignKeyMissingUniqueParentResponsePacket(
    const FirebirdForeignKeyValidationIssue& issue,
    std::string_view operation) {
  const std::string response =
      "{\"ok\":false,\"wire_operation\":\"" + std::string(operation) + "\","
      "\"diagnostic_code\":\"" +
      std::string(issue.parent_table_missing
                      ? "FIREBIRD.DDL.FOREIGN_KEY_PARENT_NOT_FOUND"
                      : "FIREBIRD.DDL.FOREIGN_KEY_PARENT_NOT_UNIQUE") +
      "\","
      "\"sqlstate\":\"42000\","
      "\"child_table\":\"" + EscapeJsonLocal(issue.child_table) + "\","
      "\"parent_table\":\"" + EscapeJsonLocal(issue.parent_table) + "\"}";
  return FirebirdResponsePacket(
      0, response,
      FirebirdNoMetaUpdateResponseStatus(
          "CREATE TABLE " + issue.child_table + " failed",
          issue.parent_table_missing
              ? "Table " + issue.parent_table + " not found"
              : "could not find UNIQUE or PRIMARY KEY constraint in table " +
                    issue.parent_table + " with specified columns",
          "42000"));
}

bool IsFirebirdCore0507AmbiguousOrderBy(std::string_view sql_text) {
  const std::string upper = ToUpperAscii(StripTerminatingSemicolon(sql_text));
  return upper.find("SET PLANONLY") == std::string::npos &&
         upper.find("RDB$RELATIONS R") != std::string::npos &&
         upper.find("RDB$RELATION_CONSTRAINTS RC") != std::string::npos &&
         upper.find("ORDER BY RDB$RELATION_NAME") != std::string::npos;
}

