  AppendFirebirdStatusInt(&status, kIscArgGds, kIscDsqlError);
  AppendFirebirdStatusInt(&status, kIscArgGds, kIscSqlErr);
  AppendFirebirdStatusInt(&status, 4, static_cast<std::uint32_t>(static_cast<std::int32_t>(-104)));
  AppendFirebirdStatusText(&status, kIscArgInterpreted, message);
  AppendFirebirdStatusText(&status, kIscArgSqlState, "42000");
  AppendXdrU32(&status, kIscArgEnd);
  return FirebirdResponsePacket(0, response, status);
