std::optional<FirebirdDuplicateIndexFieldIssue> AnalyzeFirebirdComputedIndexKeySizeIssue(
    const FirebirdBinarySessionState& state,
    std::string_view sql_text) {
  const auto descriptor = ParseFirebirdComputedIndex(sql_text);
  if (!descriptor) return std::nullopt;
  const auto table = FirebirdTableByName(state, descriptor->relation);
  if (!table) return std::nullopt;
  const auto separator = descriptor->key_envelope.find(':');
  if (separator == std::string::npos) return std::nullopt;
  const std::string function_name =
      ToUpperAscii(descriptor->key_envelope.substr(0, separator));
  if (function_name != "UPPER" && function_name != "LOWER") return std::nullopt;
  const std::string column_name =
      UpperIdentifier(FirebirdLeafIdentifier(descriptor->key_envelope.substr(separator + 1)));
  const auto column_index = FirebirdColumnIndex(table->columns, column_name);
  if (!column_index || *column_index >= table->columns.size()) return std::nullopt;
  const auto& column = table->columns[*column_index];
  if (column.sql_type != 448 && column.sql_type != 452 &&
      column.sql_type != 453 && column.sql_type != 457) {
    return std::nullopt;
  }
  if (column.length <= 8191) return std::nullopt;
  return FirebirdDuplicateIndexFieldIssue{UpperIdentifier(descriptor->name), ""};
}

