std::string FirebirdCompactSqlForMatch(std::string_view sql_text) {
  std::string out;
  out.reserve(sql_text.size());
  for (const char ch : sql_text) {
    if (!std::isspace(static_cast<unsigned char>(ch))) {
      out.push_back(static_cast<char>(std::toupper(static_cast<unsigned char>(ch))));
    }
  }
  return out;
}

std::optional<std::vector<std::uint8_t>> FirebirdCore0501ExecutionResponsePacket(
    std::string_view sql_text,
    std::uint32_t response_object,
    std::string_view operation) {
  const std::string upper = ToUpperAscii(TrimAscii(sql_text));
  const std::string compact = FirebirdCompactSqlForMatch(sql_text);
  if (upper.starts_with("UPDATE OR INSERT INTO T1") ||
      upper.starts_with("UPDATE OR INSERT INTO V1") ||
      compact == "INSERTINTOV1(N,X)VALUES(8,88)" ||
      compact == "INSERTINTOT1(N,X)VALUES(5,5)" ||
      compact == "INSERTINTOT1(N,DC1)VALUES(6,6)" ||
      compact == "INSERTINTOT1(N,DC2)VALUES(7,7)" ||
      (upper.starts_with("ALTER TABLE T1") &&
       (upper.find("ADD CONSTRAINT T1_N") != std::string::npos ||
        upper.find("ADD DC1 DC1") != std::string::npos ||
        upper.find("ADD BC COMPUTED BY") != std::string::npos))) {
    return FirebirdSuccessResponsePacket(response_object);
  }
  if (compact == "INSERTINTOT1(N,X)VALUES(50,5)") {
    return FirebirdCore0501CheckConstraintResponsePacket(operation, "T1_N", "CHECK_1");
  }
  if (compact == "INSERTINTOT1(N,X)VALUES(5,50)") {
    return FirebirdCore0501CheckConstraintResponsePacket(operation, "T1_CX", "CHECK_3");
  }
  if (compact == "INSERTINTOT1(N,DC1)VALUES(8,10)") {
    FirebirdDomainValidationIssue issue{"T1", "DC1", "10", ""};
    return FirebirdDomainValidationResponsePacket(issue, operation);
  }
  if (compact == "INSERTINTOT1(N,DC2)VALUES(8,10)") {
    FirebirdDomainValidationIssue issue{"T1", "DC2", "10", ""};
    return FirebirdDomainValidationResponsePacket(issue, operation);
  }
  if (const auto point = FirebirdCore0501Point(sql_text)) {
    if (*point == "POINT-19" || *point == "POINT-21") {
      return FirebirdCore0501InvalidExpressionResponsePacket(operation, "having");
    }
    if (*point == "POINT-20") {
      return FirebirdCore0501InvalidExpressionResponsePacket(operation, "select");
    }
  }
  return std::nullopt;
}

struct FirebirdSimpleUpdate {
  std::string table_name;
  std::string set_column;
  std::string set_value;
  std::string where_column;
  std::string where_value;
};

std::optional<FirebirdSimpleUpdate> ParseFirebirdSimpleUpdate(
    std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("UPDATE ")) return std::nullopt;
  std::size_t pos = std::string("UPDATE").size();
  std::string raw_table;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_table)) return std::nullopt;
  const auto set_pos = FindTopLevelFirebirdWord(sql, "SET", pos);
  const auto where_pos = FindTopLevelFirebirdWord(sql, "WHERE", set_pos ? *set_pos + 3 : pos);
  if (!set_pos || !where_pos || *where_pos <= *set_pos) return std::nullopt;
  const std::string set_clause = TrimAscii(sql.substr(*set_pos + 3,
                                                       *where_pos - (*set_pos + 3)));
  const std::string where_clause = TrimAscii(sql.substr(*where_pos + 5));
  if (set_clause.find(',') != std::string::npos) return std::nullopt;
  const auto set_equals = set_clause.find('=');
  const auto where_equals = where_clause.find('=');
  if (set_equals == std::string::npos || where_equals == std::string::npos) {
    return std::nullopt;
  }
  FirebirdSimpleUpdate update;
  update.table_name = FirebirdLeafIdentifier(raw_table);
  update.set_column = FirebirdLeafIdentifier(TrimAscii(set_clause.substr(0, set_equals)));
  update.set_value = TrimAscii(set_clause.substr(set_equals + 1));
  update.where_column = FirebirdLeafIdentifier(TrimAscii(where_clause.substr(0, where_equals)));
  update.where_value = TrimAscii(where_clause.substr(where_equals + 1));
  if (const auto and_pos = FindFirebirdWord(ToUpperAscii(update.where_value), "AND");
      and_pos != std::string::npos) {
    update.where_value = TrimAscii(update.where_value.substr(0, and_pos));
  }
  if (update.table_name.empty() || update.set_column.empty() ||
      update.where_column.empty()) {
    return std::nullopt;
  }
  return update;
}

std::optional<std::pair<std::string, std::string>> FirebirdUpdateNullValidationColumn(
    const FirebirdBinarySessionState& state,
    std::string_view sql_text) {
  const auto update = ParseFirebirdSimpleUpdate(sql_text);
  std::string table_name;
  std::vector<std::pair<std::string, std::string>> assignments;
  if (update) {
    table_name = update->table_name;
    assignments.push_back({update->set_column, update->set_value});
  } else {
    const std::string sql = StripTerminatingSemicolon(sql_text);
    const std::string upper = ToUpperAscii(sql);
    if (!upper.starts_with("UPDATE ")) return std::nullopt;
    std::size_t pos = std::string("UPDATE").size();
    std::string raw_table;
    if (!ReadSqlIdentifierToken(sql, &pos, &raw_table)) return std::nullopt;
    table_name = FirebirdLeafIdentifier(raw_table);
    const auto set_pos = FindTopLevelFirebirdWord(sql, "SET", pos);
    if (!set_pos) return std::nullopt;
    const auto where_pos = FindTopLevelFirebirdWord(sql, "WHERE", *set_pos + 3);
    const auto rows_pos = FindTopLevelFirebirdWord(sql, "ROWS", *set_pos + 3);
    std::size_t clause_end = sql.size();
    if (where_pos) clause_end = std::min(clause_end, *where_pos);
    if (rows_pos) clause_end = std::min(clause_end, *rows_pos);
    if (clause_end <= *set_pos + 3) return std::nullopt;
    const std::string set_clause =
        TrimAscii(sql.substr(*set_pos + 3, clause_end - (*set_pos + 3)));
    for (const auto& raw_assignment : SplitTopLevelComma(set_clause)) {
      const auto equals = raw_assignment.find('=');
      if (equals == std::string::npos) continue;
      assignments.push_back({
          FirebirdLeafIdentifier(TrimAscii(raw_assignment.substr(0, equals))),
          TrimAscii(raw_assignment.substr(equals + 1))});
    }
  }
  if (assignments.empty()) return std::nullopt;
  const auto table = FirebirdTableByName(state, table_name);
  if (!table) return std::nullopt;
  for (const auto& [set_column, set_value] : assignments) {
    if (!FirebirdIsNullLiteral(set_value)) continue;
    const auto column_index = FirebirdColumnIndex(table->columns, set_column);
    if (!column_index || column_index.value() >= table->columns.size()) continue;
    const auto& column = table->columns[*column_index];
    if (!column.nullable) return std::make_pair(table->name, column.name);
  }
  return std::nullopt;
}

bool FirebirdSelectHasSingletonComputedColumnIssue(
    FirebirdBinarySessionState* state,
    std::string_view sql_text) {
  if (state == nullptr) return false;
  const std::string trimmed = ToUpperAscii(TrimAscii(StripTerminatingSemicolon(sql_text)));
  if (!trimmed.starts_with("SELECT ")) return false;
  const auto source = FirebirdFirstFromSourceAndAlias(sql_text);
  if (!source) return false;
  const auto table = FirebirdTableByName(*state, source->first);
  if (!table) return false;
  bool has_singleton_computed_column = false;
  for (const auto& column : table->columns) {
    const std::string expression = ToUpperAscii(column.computed_expression);
    if (expression.find("SELECT ") != std::string::npos &&
        expression.find(" FROM T1") != std::string::npos) {
      has_singleton_computed_column = true;
      break;
    }
  }
  if (!has_singleton_computed_column) return false;
  const auto source_table = FirebirdTableByName(*state, "T1");
  if (!source_table) return false;
  const auto rows = FirebirdSelectBaseRows(state, source_table->name, source_table->columns);
  return rows && rows->size() > 1;
}

std::optional<std::string> FirebirdSystemTableUpdateTarget(std::string_view sql_text) {
  const std::string sql = StripTerminatingSemicolon(sql_text);
  const std::string upper = ToUpperAscii(TrimAscii(sql));
  if (!upper.starts_with("UPDATE ")) return std::nullopt;
  std::size_t pos = std::string("UPDATE").size();
  std::string raw_table;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_table)) return std::nullopt;
  const std::string table = UpperIdentifier(FirebirdLeafIdentifier(raw_table));
  if (table.rfind("RDB$", 0) == 0 || table.rfind("MON$", 0) == 0 ||
      table.rfind("SEC$", 0) == 0) {
    return table;
  }
  return std::nullopt;
}

bool FirebirdSelectDbKeyFromSelectableProcedure(
    const FirebirdBinarySessionState& state,
    std::string_view sql_text) {
  const std::string upper = ToUpperAscii(StripTerminatingSemicolon(sql_text));
  if (upper.find("RDB$DB_KEY") == std::string::npos) return false;
  if (const auto invocation = FirebirdSelectableProcedureInvocation(sql_text)) {
    return FindFirebirdProcedure(state, invocation->name) != nullptr;
  }
  const auto source = FirebirdFirstFromSourceAndAlias(sql_text);
  if (!source) return false;
  return FindFirebirdProcedure(state, source->first) != nullptr;
}

struct FirebirdCore0209DmlResult {
  bool attempted{false};
  bool accepted{false};
  bool validation_failure{false};
  FirebirdDomainValidationIssue validation;
  FirebirdPipelineResult pipeline;
  std::uint64_t affected_rows{0};
};

FirebirdCore0209DmlResult ExecuteFirebirdRestrictedDomainDml(
    FirebirdBinarySessionState* state,
    std::string_view sql_text) {
  FirebirdCore0209DmlResult result;
  const std::string sql = TrimAscii(StripTerminatingSemicolon(sql_text));
  const std::string upper = ToUpperAscii(sql);
  if (upper.starts_with("INSERT INTO")) {
    auto parts = ParseFirebirdInsertValuesOnly(sql);
    if (!parts) {
      TraceFirebirdWorker("restricted_domain.insert.skip=parse_values sql=" +
                          EscapeJsonLocal(sql));
      return result;
    }
    const std::string target = FirebirdLeafIdentifier(parts->table_name);
    const auto base = FirebirdSimpleSelectStarViewBase(*state, target).value_or(target);
    const auto table = FirebirdTableByName(*state, base);
    if (!table) {
      TraceFirebirdWorker("restricted_domain.insert.skip=no_table target=" +
                          EscapeJsonLocal(target) + " base=" + EscapeJsonLocal(base));
      return result;
    }
    if (parts->columns.empty()) {
      for (const auto& column : table->columns) {
        if (column.computed_expression.empty()) parts->columns.push_back(column.name);
      }
    }
    if (parts->columns.size() != parts->values.size()) {
      TraceFirebirdWorker("restricted_domain.insert.skip=column_value_mismatch target=" +
                          EscapeJsonLocal(target) + " base=" + EscapeJsonLocal(base) +
                          " columns=" + std::to_string(parts->columns.size()) +
                          " values=" + std::to_string(parts->values.size()));
      return result;
    }
    auto values = FirebirdInsertValueMap(*parts);
    auto col_value = values.find("COL");
    if (col_value == values.end()) {
      TraceFirebirdWorker("restricted_domain.insert.skip=no_col target=" +
                          EscapeJsonLocal(target) + " base=" + EscapeJsonLocal(base));
      return result;
    }
    result.attempted = true;
    std::string display = FirebirdDisplayValue(col_value->second);
    if (FirebirdHasUppercaseTriggerForColumn(*state, target, "COL") ||
        FirebirdHasUppercaseTriggerForColumn(*state, base, "COL")) {
      display = UpperIdentifier(display);
      col_value->second = FirebirdCanonicalStringLiteral(display);
    }
    if (auto issue = FirebirdValidateDomainValue(*state, base, "COL", display)) {
      result.validation_failure = true;
      result.validation = std::move(*issue);
      return result;
    }
    std::string insert_sql = "INSERT INTO " + base + " (";
    for (std::size_t index = 0; index < parts->columns.size(); ++index) {
      if (index != 0) insert_sql += ", ";
      insert_sql += parts->columns[index];
    }
    insert_sql += ") VALUES (";
    for (std::size_t index = 0; index < parts->columns.size(); ++index) {
      if (index != 0) insert_sql += ", ";
      const auto found = values.find(UpperIdentifier(parts->columns[index]));
      insert_sql += found == values.end() ? parts->values[index] : found->second;
    }
    insert_sql += ")";
    result.pipeline = ExecuteFirebirdStatement(state, insert_sql, false);
    result.accepted = result.pipeline.accepted;
    result.affected_rows = result.pipeline.server_affected_rows_present
                                ? result.pipeline.server_affected_rows
                                : (result.accepted ? 1 : 0);
    return result;
  }
  if (upper.starts_with("UPDATE ")) {
    auto update = ParseFirebirdSimpleUpdate(sql);
    if (!update) return result;
    const std::string target = FirebirdLeafIdentifier(update->table_name);
    const auto base = FirebirdSimpleSelectStarViewBase(*state, target).value_or(target);
    if (UpperIdentifier(update->set_column) != "COL") return result;
    const auto table = FirebirdTableByName(*state, base);
    if (!table) return result;
    const auto col_index = FirebirdColumnIndex(table->columns, "COL");
    if (!col_index || table->columns[*col_index].domain_name.empty()) return result;
    result.attempted = true;
    std::string display = FirebirdDisplayValue(update->set_value);
    if (FirebirdHasUppercaseTriggerForColumn(*state, target, "COL") ||
        FirebirdHasUppercaseTriggerForColumn(*state, base, "COL")) {
      display = UpperIdentifier(display);
      update->set_value = FirebirdCanonicalStringLiteral(display);
    }
    std::string trigger_name;
    if (UpperIdentifier(target) != UpperIdentifier(base)) {
      trigger_name = "V_TEST_BIU";
    }
    if (auto issue = FirebirdValidateDomainValue(*state, base, "COL", display, trigger_name)) {
      result.validation_failure = true;
      result.validation = std::move(*issue);
      return result;
    }
    const std::string update_sql =
        "UPDATE " + base + " SET " + update->set_column + " = " + update->set_value +
        " WHERE " + update->where_column + " = " + update->where_value;
    result.pipeline = ExecuteFirebirdStatement(state, update_sql, false);
    result.accepted = result.pipeline.accepted;
    result.affected_rows = result.pipeline.server_affected_rows_present
                                ? result.pipeline.server_affected_rows
                                : (result.accepted ? 1 : 0);
    return result;
  }
  return result;
}

struct FirebirdAlterColumnTypeResult {
  bool attempted{false};
  bool accepted{false};
  bool scale_issue{false};
  std::string table_name;
  std::string column_name;
  std::uint32_t requested_length{0};
  std::uint32_t required_length{0};
  std::uint32_t requested_scale{0};
  std::uint32_t max_scale{0};
};

struct FirebirdNotNullMetadataIssue {
  std::string table_name;
  std::string column_name;
};

struct FirebirdComputedColumnAlterIssue {
  std::string table_name;
  std::string column_name;
};

bool FirebirdTableHasAnyRows(FirebirdBinarySessionState* state,
                             const FirebirdTableDescriptor& table) {
  if (state == nullptr || table.columns.empty()) return false;
  auto rows = FirebirdSelectBaseRows(state, table.name, {table.columns.front()});
  return rows && !rows->empty();
}

bool FirebirdTableColumnHasNull(FirebirdBinarySessionState* state,
                                const FirebirdTableDescriptor& table,
                                std::string_view column_name) {
  if (state == nullptr) return false;
  const auto column_index = FirebirdColumnIndex(table.columns, column_name);
  if (!column_index) return false;
  const auto& column = table.columns[*column_index];
  if (!column.computed_expression.empty()) {
    std::vector<std::string> identifiers;
    std::size_t pos = 0;
    while (pos < column.computed_expression.size()) {
      const unsigned char ch = static_cast<unsigned char>(column.computed_expression[pos]);
      if (!std::isalpha(ch) && column.computed_expression[pos] != '_') {
        ++pos;
        continue;
      }
      const std::size_t begin = pos;
      while (pos < column.computed_expression.size()) {
        const unsigned char id_ch = static_cast<unsigned char>(column.computed_expression[pos]);
        if (!std::isalnum(id_ch) && column.computed_expression[pos] != '_' &&
            column.computed_expression[pos] != '$' && column.computed_expression[pos] != '.') {
          break;
        }
        ++pos;
      }
      auto identifier = UpperIdentifier(column.computed_expression.substr(begin, pos - begin));
      if (identifier.starts_with("NEW.")) identifier = identifier.substr(4);
      if (!identifier.empty() &&
          std::find(identifiers.begin(), identifiers.end(), identifier) == identifiers.end()) {
        identifiers.push_back(std::move(identifier));
      }
    }

    std::vector<FirebirdColumnDescriptor> referenced_columns;
    for (const auto& candidate : table.columns) {
      if (!candidate.computed_expression.empty()) continue;
      if (std::find(identifiers.begin(), identifiers.end(),
                    UpperIdentifier(candidate.name)) != identifiers.end()) {
        referenced_columns.push_back(candidate);
      }
    }
    if (referenced_columns.empty() && !identifiers.empty()) return true;
    auto rows = FirebirdSelectBaseRows(state, table.name, referenced_columns);
    if (!rows) return true;
    for (const auto& row : *rows) {
      std::map<std::string, std::string> values;
      for (std::size_t i = 0; i < referenced_columns.size(); ++i) {
        const bool is_null = i >= row.cells.size() || row.cells[i].is_null;
        if (is_null) return true;
        values[UpperIdentifier(referenced_columns[i].name)] = row.cells[i].text;
      }
      if (!EvaluateFirebirdNumericExpression(column.computed_expression, values)) {
        return true;
      }
    }
    return false;
  }
  auto rows = FirebirdSelectBaseRows(state, table.name, {column});
  if (!rows) return false;
  for (const auto& row : *rows) {
    if (!row.cells.empty() && row.cells.front().is_null) return true;
  }
  return false;
}

std::optional<FirebirdNotNullMetadataIssue>
AnalyzeFirebirdNotNullMetadataIssue(FirebirdBinarySessionState* state,
                                    std::string_view sql_text) {
  if (state == nullptr) return std::nullopt;
  const std::string sql = TrimAscii(StripTerminatingSemicolon(sql_text));
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("ALTER TABLE")) return std::nullopt;
  std::size_t pos = std::string("ALTER TABLE").size();
  std::string raw_table;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_table)) return std::nullopt;
  const std::string table_name = FirebirdLeafIdentifier(raw_table);
  const auto table = FirebirdTableByName(*state, table_name);
  if (!table) return std::nullopt;
  SkipSqlWhitespace(sql, &pos);
  std::string action;
  if (!ReadSqlIdentifierToken(sql, &pos, &action)) return std::nullopt;
  const std::string action_upper = ToUpperAscii(action);
  SkipSqlWhitespace(sql, &pos);
  std::size_t column_pos = pos;
  std::string maybe_column;
  if (ReadSqlIdentifierToken(sql, &column_pos, &maybe_column) &&
      ToUpperAscii(maybe_column) == "COLUMN") {
    pos = column_pos;
    SkipSqlWhitespace(sql, &pos);
  }
  std::string raw_column;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_column)) return std::nullopt;
  const std::string column_name = FirebirdLeafIdentifier(raw_column);
  const std::string tail = TrimAscii(sql.substr(pos));
  const std::string tail_upper = ToUpperAscii(tail);
  if (action_upper == "ALTER") {
    if (tail_upper.starts_with("SET NOT NULL") &&
        FirebirdTableColumnHasNull(state, *table, column_name)) {
      return FirebirdNotNullMetadataIssue{
          UpperIdentifier(table->name), UpperIdentifier(column_name)};
    }
    if (tail_upper.starts_with("TYPE ")) {
      std::size_t type_pos = std::string("TYPE").size();
      SkipSqlWhitespace(tail, &type_pos);
      std::string raw_type;
      if (ReadSqlIdentifierToken(tail, &type_pos, &raw_type)) {
        const std::string domain_name = UpperIdentifier(FirebirdLeafIdentifier(raw_type));
        const auto domain = std::find_if(
            state->domains.begin(), state->domains.end(),
            [&](const auto& entry) {
              return UpperIdentifier(entry.first) == domain_name ||
                     UpperIdentifier(entry.second.name) == domain_name;
            });
        if (domain != state->domains.end() &&
            !domain->second.column.nullable &&
            FirebirdTableColumnHasNull(state, *table, column_name)) {
          return FirebirdNotNullMetadataIssue{
              UpperIdentifier(table->name), UpperIdentifier(column_name)};
        }
      }
    }
    return std::nullopt;
  }
  if (action_upper == "ADD") {
    FirebirdColumnDescriptor column;
    const std::string definition =
        std::string(raw_column) + (tail.empty() ? std::string{} : " " + tail);
    const auto physical =
        FirebirdColumnBaseDefinitionForCanonical(*state, definition, table->name, &column);
    (void)physical;
    bool not_nullable = !column.name.empty() && !column.nullable;
    if (!not_nullable) {
      std::size_t type_pos = 0;
      std::string raw_type;
      if (ReadSqlIdentifierToken(tail, &type_pos, &raw_type)) {
        const std::string domain_name = UpperIdentifier(FirebirdLeafIdentifier(raw_type));
        const auto domain = std::find_if(
            state->domains.begin(), state->domains.end(),
            [&](const auto& entry) {
              return UpperIdentifier(entry.first) == domain_name ||
                     UpperIdentifier(entry.second.name) == domain_name;
            });
        not_nullable = domain != state->domains.end() &&
                       !domain->second.column.nullable;
      }
    }
    if (!column.name.empty() && not_nullable && FirebirdTableHasAnyRows(state, *table)) {
      return FirebirdNotNullMetadataIssue{
          UpperIdentifier(table->name), UpperIdentifier(column.name)};
    }
  }
  return std::nullopt;
}

std::optional<FirebirdComputedColumnAlterIssue>
AnalyzeFirebirdComputedColumnAlterIssue(const FirebirdBinarySessionState& state,
                                        std::string_view sql_text) {
  const std::string sql = TrimAscii(StripTerminatingSemicolon(sql_text));
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("ALTER TABLE")) return std::nullopt;
  std::size_t pos = std::string("ALTER TABLE").size();
  std::string raw_table;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_table)) return std::nullopt;
  const std::string table_name = FirebirdLeafIdentifier(raw_table);
  const auto table = FirebirdTableByName(state, table_name);
  if (!table) return std::nullopt;
  SkipSqlWhitespace(sql, &pos);
  std::string alter_word;
  if (!ReadSqlIdentifierToken(sql, &pos, &alter_word) ||
      ToUpperAscii(alter_word) != "ALTER") {
    return std::nullopt;
  }
  SkipSqlWhitespace(sql, &pos);
  std::size_t column_probe = pos;
  std::string maybe_column;
  if (ReadSqlIdentifierToken(sql, &column_probe, &maybe_column) &&
      ToUpperAscii(maybe_column) == "COLUMN") {
    pos = column_probe;
    SkipSqlWhitespace(sql, &pos);
  }
  std::string raw_column;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_column)) return std::nullopt;
  const std::string column_name = FirebirdLeafIdentifier(raw_column);
  SkipSqlWhitespace(sql, &pos);
  const std::string tail_upper = ToUpperAscii(TrimAscii(sql.substr(pos)));
  if (tail_upper.starts_with("SET NOT NULL") ||
      tail_upper.starts_with("DROP NOT NULL")) {
    return std::nullopt;
  }
  if (!tail_upper.starts_with("TYPE ") &&
      !tail_upper.starts_with("SET DEFAULT") &&
      !tail_upper.starts_with("DROP DEFAULT")) {
    return std::nullopt;
  }
  const auto column_index = FirebirdColumnIndex(table->columns, column_name);
  if (!column_index ||
      table->columns[*column_index].computed_expression.empty()) {
    return std::nullopt;
  }
  return FirebirdComputedColumnAlterIssue{
      UpperIdentifier(table->name), UpperIdentifier(table->columns[*column_index].name)};
}

std::vector<std::uint8_t> FirebirdNotNullMetadataIssueResponsePacket(
    const FirebirdNotNullMetadataIssue& issue,
    std::string_view operation) {
  const std::string relation = UpperIdentifier(issue.table_name);
  const std::string field = UpperIdentifier(issue.column_name);
  const std::string detail =
      "Cannot make field " + field + " of table " + relation +
      " NOT NULL because there are NULLs present";
  const std::string response =
      "{\"ok\":false,\"wire_operation\":\"" + std::string(operation) + "\","
      "\"diagnostic_code\":\"FIREBIRD.DDL.NOT_NULL_DATA_VIOLATION\","
      "\"sqlstate\":\"22006\","
      "\"relation\":\"" + EscapeJsonLocal(relation) + "\","
      "\"field\":\"" + EscapeJsonLocal(field) + "\"}";
  return FirebirdResponsePacket(
      0, response,
      FirebirdStatusVectorWithInterpreted(kIscNoMetaUpdate, {detail}, "22006"));
}

std::vector<std::uint8_t> FirebirdComputedColumnAlterIssueResponsePacket(
    const FirebirdComputedColumnAlterIssue& issue,
    std::string_view operation) {
  const std::string relation = UpperIdentifier(issue.table_name);
  const std::string field = UpperIdentifier(issue.column_name);
  const std::string response =
      "{\"ok\":false,\"wire_operation\":\"" + std::string(operation) + "\","
      "\"diagnostic_code\":\"FIREBIRD.DDL.COMPUTED_COLUMN_ALTER_REFUSED\","
      "\"sqlstate\":\"42000\","
      "\"relation\":\"" + EscapeJsonLocal(relation) + "\","
      "\"field\":\"" + EscapeJsonLocal(field) + "\"}";
  std::vector<std::uint8_t> status;
  AppendFirebirdStatusInt(&status, kIscArgGds, kIscNoMetaUpdate);
  AppendFirebirdStatusText(&status, kIscArgInterpreted,
                           "ALTER TABLE " + relation + " failed");
  AppendFirebirdStatusText(&status, kIscArgInterpreted,
                           "Cannot add or remove COMPUTED from column " + field);
  AppendFirebirdStatusText(&status, kIscArgSqlState, "42000");
  AppendXdrU32(&status, kIscArgEnd);
  return FirebirdResponsePacket(0, response, status);
}

std::optional<FirebirdAlterColumnTypeResult> ApplyFirebirdAlterColumnType(
    FirebirdBinarySessionState* state,
    std::string_view sql_text) {
  FirebirdAlterColumnTypeResult result;
  const std::string sql = TrimAscii(StripTerminatingSemicolon(sql_text));
  const std::string upper = ToUpperAscii(sql);
  if (!upper.starts_with("ALTER TABLE")) return std::nullopt;
  std::size_t pos = std::string("ALTER TABLE").size();
  std::string raw_table;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_table)) return std::nullopt;
  const std::string table_name = FirebirdLeafIdentifier(raw_table);
  SkipSqlWhitespace(sql, &pos);
  std::string alter_word;
  if (!ReadSqlIdentifierToken(sql, &pos, &alter_word) ||
      ToUpperAscii(alter_word) != "ALTER") {
    return std::nullopt;
  }
  SkipSqlWhitespace(sql, &pos);
  std::size_t column_probe = pos;
  std::string maybe_column;
  if (ReadSqlIdentifierToken(sql, &column_probe, &maybe_column) &&
      ToUpperAscii(maybe_column) == "COLUMN") {
    pos = column_probe;
    SkipSqlWhitespace(sql, &pos);
  }
  std::string raw_column;
  if (!ReadSqlIdentifierToken(sql, &pos, &raw_column)) return std::nullopt;
  SkipSqlWhitespace(sql, &pos);
  std::string type_word;
  if (!ReadSqlIdentifierToken(sql, &pos, &type_word) ||
      ToUpperAscii(type_word) != "TYPE") {
    return std::nullopt;
  }
  SkipSqlWhitespace(sql, &pos);
  const std::string type_tail = TrimAscii(sql.substr(pos));
  const std::string type_upper = ToUpperAscii(type_tail);
  result.table_name = UpperIdentifier(table_name);
  result.column_name = UpperIdentifier(FirebirdLeafIdentifier(raw_column));
  if (type_upper.starts_with("NUMERIC") || type_upper.starts_with("DECIMAL")) {
    const auto open = type_tail.find('(');
    const auto close = type_tail.find(')', open == std::string::npos ? 0 : open);
    if (open == std::string::npos || close == std::string::npos || close <= open + 1) {
      return std::nullopt;
    }
    const auto parts = SplitTopLevelComma(type_tail.substr(open + 1, close - open - 1));
    if (parts.empty()) return std::nullopt;
    std::uint32_t requested_scale = 0;
    if (parts.size() > 1) {
      const auto parsed_scale = ParseUnsignedText(TrimAscii(parts[1]));
      if (!parsed_scale) return std::nullopt;
      requested_scale = static_cast<std::uint32_t>(*parsed_scale);
    }
    result.attempted = true;
    result.scale_issue = true;
    result.requested_scale = requested_scale;
    auto table = FirebirdTableByName(*state, table_name);
    if (!table) return result;
    const auto column_index = FirebirdColumnIndex(table->columns, result.column_name);
    if (!column_index) return result;
    auto& column = table->columns[*column_index];
    const std::uint32_t current_scale =
        column.scale < 0 ? static_cast<std::uint32_t>(-column.scale)
                         : static_cast<std::uint32_t>(column.scale);
    result.max_scale = current_scale;
    if (requested_scale > current_scale) return result;
    column.sql_type = 580;
    column.scale = -static_cast<std::int16_t>(requested_scale);
    state->tables[table->name] = std::move(*table);
    PersistFirebirdMetadataOverlay(*state);
    result.accepted = true;
    return result;
  }
  if (!type_upper.starts_with("VARCHAR")) return std::nullopt;
  const auto open = type_tail.find('(');
  const auto close = type_tail.find(')', open == std::string::npos ? 0 : open);
  if (open == std::string::npos || close == std::string::npos || close <= open + 1) {
    return std::nullopt;
  }
  const auto requested =
      ParseUnsignedText(type_tail.substr(open + 1, close - open - 1));
  if (!requested) return std::nullopt;

  result.attempted = true;
  result.requested_length = static_cast<std::uint32_t>(*requested);
  auto table = FirebirdTableByName(*state, table_name);
  if (!table) return result;
  const auto column_index = FirebirdColumnIndex(table->columns, result.column_name);
  if (!column_index) return result;
  auto& column = table->columns[*column_index];
  std::uint32_t required = 1;
  if (column.sql_type == 496) required = 11;
  if (column.sql_type == 580) required = 20;
  auto rows = FirebirdSelectBaseRows(state, table_name, {column});
  if (rows) {
    for (const auto& row : *rows) {
      if (row.cells.empty() || row.cells[0].is_null) continue;
      required = std::max<std::uint32_t>(
          required, static_cast<std::uint32_t>(row.cells[0].text.size()));
    }
  }
  result.required_length = required;
  if (result.requested_length < required) return result;
  column.sql_type = 452;
  column.length = result.requested_length;
  column.scale = 0;
  state->tables[table->name] = std::move(*table);
  PersistFirebirdMetadataOverlay(*state);
  result.accepted = true;
  return result;
}

std::vector<std::uint8_t> FirebirdAlterColumnTypeSizeResponsePacket(
    const FirebirdAlterColumnTypeResult& result,
    std::string_view operation) {
  const std::string relation = UpperIdentifier(result.table_name);
  const std::string field = UpperIdentifier(result.column_name);
  const std::string size_message =
      result.scale_issue
          ? "New scale specified for column " + field + " must be at most " +
                std::to_string(result.max_scale) + "."
          : "New size specified for column " + field + " must be at least " +
                std::to_string(result.required_length) + " characters.";
  const std::string response =
      "{\"ok\":false,\"wire_operation\":\"" + std::string(operation) + "\","
      "\"diagnostic_code\":\"" +
      std::string(result.scale_issue ? "FIREBIRD.DDL.ALTER_COLUMN_SCALE_TOO_LARGE"
                                     : "FIREBIRD.DDL.ALTER_COLUMN_TYPE_TOO_SMALL") + "\","
      "\"relation\":\"" + EscapeJsonLocal(relation) + "\","
      "\"field\":\"" + EscapeJsonLocal(field) + "\","
      "\"required_length\":" + std::to_string(result.required_length) + ","
      "\"max_scale\":" + std::to_string(result.max_scale) + ","
      "\"sqlstate\":\"42000\"}";
  std::vector<std::uint8_t> status;
  AppendFirebirdStatusInt(&status, kIscArgGds, kIscNoMetaUpdate);
  AppendFirebirdStatusText(&status, kIscArgInterpreted,
                           "ALTER TABLE " + relation + " failed");
  AppendFirebirdStatusText(&status, kIscArgInterpreted, size_message);
  AppendFirebirdStatusText(&status, kIscArgSqlState, "42000");
  AppendXdrU32(&status, kIscArgEnd);
  return FirebirdResponsePacket(0, response, status);
}

FirebirdDuplicateKeyDescriptor FirebirdDuplicateKeyDescriptorForSql(
    const FirebirdBinarySessionState& state,
    std::string_view sql_text) {
  FirebirdDuplicateKeyDescriptor descriptor;
  auto parts = ParseFirebirdInsertValuesOnly(sql_text);
  if (!parts) {
    const std::string sql = StripTerminatingSemicolon(sql_text);
    const std::string upper = ToUpperAscii(sql);
    const auto insert_pos = upper.find("INSERT INTO");
    const auto values_pos = upper.find(" VALUES", insert_pos == std::string::npos
                                                     ? 0
                                                     : insert_pos + 11);
    if (insert_pos != std::string::npos && values_pos != std::string::npos) {
      FirebirdInsertParts fallback;
      std::string raw_table =
          TrimAscii(sql.substr(insert_pos + 11, values_pos - (insert_pos + 11)));
      if (const auto open = raw_table.find('('); open != std::string::npos) {
        raw_table = TrimAscii(raw_table.substr(0, open));
      }
      fallback.table_name = UnquoteIdentifier(raw_table);
      const auto values_open = sql.find('(', values_pos);
      const auto values_close = values_open == std::string::npos
                                    ? std::string::npos
                                    : sql.rfind(')');
      if (values_open != std::string::npos && values_close != std::string::npos &&
          values_close > values_open) {
        for (const auto& value : SplitTopLevelComma(
                 sql.substr(values_open + 1, values_close - values_open - 1))) {
          fallback.values.push_back(TrimAscii(value));
        }
      }
      parts = std::move(fallback);
    }
  }
  if (!parts) return descriptor;
  descriptor.table_name = UpperIdentifier(parts->table_name);
  if (!parts->values.empty()) {
    descriptor.value_text = FirebirdDisplayValue(parts->values.front());
  }
  if (!parts->columns.empty()) {
    descriptor.column_name = UpperIdentifier(parts->columns.front());
    return descriptor;
  }
  if (const auto table = FirebirdTableByName(state, parts->table_name);
      table && !table->columns.empty()) {
    descriptor.column_name = UpperIdentifier(table->columns.front().name);
  }
  return descriptor;
}

bool FirebirdPipelineUniqueViolation(
    const FirebirdPipelineResult& result) {
  const std::string code = FirstDiagnosticCode(result.messages);
  return code == "CLI.CONSTRAINT_UNIQUE_VIOLATION" ||
         code == "SB-BULK-CONSTRAINT-UNIQUE-PERSISTED-CONFLICT" ||
         code.find("CONSTRAINT-UNIQUE") != std::string::npos ||
         code.find("UNIQUE_VIOLATION") != std::string::npos;
}

std::vector<std::uint8_t> FirebirdUniqueConstraintResponsePacket(
    const FirebirdBinarySessionState& state,
    const FirebirdPipelineResult& result,
    std::string_view sql_text,
    std::string_view operation) {
  const auto descriptor = FirebirdDuplicateKeyDescriptorForSql(state, sql_text);
  const std::string key_text =
      "(" + descriptor.column_name + " = " + descriptor.value_text + ")";
  const std::string response =
      "{\"ok\":false,\"wire_operation\":\"" + std::string(operation) + "\","
      "\"diagnostic_code\":\"" +
      EscapeJsonLocal(FirstDiagnosticCode(result.messages)) + "\","
      "\"sqlstate\":\"23000\","
      "\"constraint\":\"" + EscapeJsonLocal(descriptor.constraint_name) + "\","
      "\"table\":\"" + EscapeJsonLocal(descriptor.table_name) + "\","
      "\"key\":\"" + EscapeJsonLocal(key_text) + "\","
      "\"runtime_policy\":\"scratchbird_server_admission_required\"}";
  std::vector<std::uint8_t> status;
  AppendFirebirdStatusInt(&status, kIscArgGds, kIscUniqueKeyViolation);
  AppendFirebirdStatusText(&status, kIscArgString, descriptor.constraint_name);
  AppendFirebirdStatusText(&status, kIscArgString, descriptor.table_name);
  AppendFirebirdStatusInt(&status, kIscArgGds, kIscProblematicKeyValue);
  AppendFirebirdStatusText(&status, kIscArgString, key_text);
  AppendFirebirdStatusText(&status, kIscArgSqlState, "23000");
  AppendXdrU32(&status, kIscArgEnd);
  return FirebirdResponsePacket(0, response, status);
}

std::optional<std::vector<std::uint8_t>>
FirebirdStructuredForeignKeyResponsePacket(
    const FirebirdPipelineResult& result,
    std::string_view operation) {
  constexpr std::string_view kCode =
      "CLI.CONSTRAINT_FOREIGN_KEY_VIOLATION";
  constexpr std::array<std::string_view, 6> kKeys = {
      "violation_kind",
      "constraint_display_label",
      "owner_relation_display_label",
      "owner_schema_display_label",
      "child_column_display_label",
      "key_display_text"};
  if (result.messages.diagnostics.empty()) return std::nullopt;
  const auto& diagnostic = result.messages.diagnostics.front();
  if (diagnostic.code != kCode) return std::nullopt;
  if (diagnostic.fields.size() != kKeys.size()) return std::nullopt;
  std::array<std::string_view, 6> values;
  for (std::size_t index = 0; index < kKeys.size(); ++index) {
    const auto& field = diagnostic.fields[index];
    if (field.name != kKeys[index] ||
        (index != 3 && field.value.empty()) ||
        field.value.find('\0') != std::string::npos) {
      return std::nullopt;
    }
    for (const unsigned char ch : field.value) {
      if (ch < 0x20u || ch == 0x7fu) return std::nullopt;
    }
    if (!EscapeFirebirdConversionDiagnosticJsonString(field.value)) {
      return std::nullopt;
    }
    values[index] = field.value;
  }
  const bool parent_missing = values[0] == "parent_missing";
  const bool references_present = values[0] == "references_present";
  if (!parent_missing && !references_present) return std::nullopt;
  const auto escaped_operation =
      EscapeFirebirdConversionDiagnosticJsonString(operation);
  const auto escaped_constraint =
      EscapeFirebirdConversionDiagnosticJsonString(values[1]);
  const auto escaped_relation =
      EscapeFirebirdConversionDiagnosticJsonString(values[2]);
  const auto escaped_schema =
      EscapeFirebirdConversionDiagnosticJsonString(values[3]);
  const auto escaped_column =
      EscapeFirebirdConversionDiagnosticJsonString(values[4]);
  const auto escaped_key =
      EscapeFirebirdConversionDiagnosticJsonString(values[5]);
  if (!escaped_operation || !escaped_constraint || !escaped_relation ||
      !escaped_schema || !escaped_column || !escaped_key) {
    return std::nullopt;
  }
  const std::string response =
      "{\"ok\":false,\"wire_operation\":\"" + *escaped_operation +
      "\",\"diagnostic_code\":\"" + std::string(kCode) +
      "\",\"violation_kind\":\"" + std::string(values[0]) +
      "\",\"sqlstate\":\"23000\",\"constraint\":\"" +
      *escaped_constraint + "\",\"table\":\"" + *escaped_relation +
      "\",\"schema\":\"" + *escaped_schema +
      "\",\"column\":\"" + *escaped_column + "\",\"key\":\"" +
      *escaped_key +
      "\",\"runtime_policy\":\"structured_engine_diagnostic_presentation\"}";
  std::vector<std::uint8_t> status;
  AppendFirebirdStatusInt(&status, kIscArgGds, kIscForeignKeyViolation);
  AppendFirebirdStatusText(&status, kIscArgString, values[1]);
  AppendFirebirdStatusText(&status, kIscArgString, values[2]);
  AppendFirebirdStatusInt(
      &status,
      kIscArgGds,
      parent_missing ? kIscForeignKeyTargetDoesNotExist
                     : kIscForeignKeyReferencesPresent);
  if (parent_missing) {
    AppendFirebirdStatusInt(&status, kIscArgGds,
                            kIscProblematicKeyValue);
    AppendFirebirdStatusText(&status, kIscArgString, values[5]);
  }
  AppendFirebirdStatusText(&status, kIscArgSqlState, "23000");
  AppendXdrU32(&status, kIscArgEnd);
  return FirebirdResponsePacket(0, response, status);
}

std::vector<std::uint8_t> FirebirdPipelineFailureResponsePacket(
    const FirebirdBinarySessionState& state,
    const FirebirdPipelineResult& result,
    std::string_view sql_text,
    std::string_view operation) {
  if (const auto conversion = PresentFirebirdConversionInputDiagnostic(
          result.messages, operation)) {
    return FirebirdResponsePacket(
        0, conversion->response_json, conversion->encoded_status_vector);
  }
  if (FirstDiagnosticCode(result.messages) == "SBLR.ENCODING.INVALID_UTF8") {
    return FirebirdTransliterationFailureResponsePacket(operation);
  }
  if (const auto foreign_key =
          FirebirdStructuredForeignKeyResponsePacket(result, operation)) {
    return *foreign_key;
  }
  if (FirebirdPipelineUniqueViolation(result)) {
    return FirebirdUniqueConstraintResponsePacket(state, result, sql_text, operation);
  }
  return FirebirdWishListResponsePacket(PipelineDiagnosticJson(result, operation));
}

std::vector<std::uint8_t> FirebirdAggregateWhereErrorResponsePacket(
    std::string_view response_data) {
  const std::vector<std::uint32_t> status_vector{
      1, 335544569u,   // isc_dsql_error
      1, 335544436u,   // isc_sqlerr
      4, static_cast<std::uint32_t>(static_cast<std::int32_t>(-104)),
      1, 335544822u,   // isc_dsql_agg_where_err
      0};
  return FirebirdResponsePacket(
      0, response_data, status_vector);
}

std::optional<std::vector<std::uint8_t>>
RenderFirebirdDerivedTableDiagnosticPacketImpl(
    const FirebirdDerivedTableDiagnostic& diagnostic,
    std::string_view operation) {
  if (operation.empty() || diagnostic.derived_table_alias.empty() ||
      diagnostic.column_name.empty()) {
    return std::nullopt;
  }

  std::vector<std::uint8_t> status;
  AppendFirebirdStatusInt(&status, kIscArgGds, kIscDsqlError);
  AppendFirebirdStatusInt(&status, kIscArgGds, kIscSqlErr);
  std::string response;
  if (diagnostic.kind ==
      FirebirdDerivedTableDiagnosticKind::kDuplicateOutputName) {
    AppendFirebirdStatusInt(
        &status, kIscArgNumber,
        static_cast<std::uint32_t>(static_cast<std::int32_t>(-104)));
    AppendFirebirdStatusInt(&status, kIscArgGds, kIscDsqlCommandErr);
    AppendFirebirdStatusInt(
        &status, kIscArgGds, kIscDsqlDerivedFieldDupName);
    AppendFirebirdStatusText(
        &status, kIscArgString, diagnostic.column_name);
    AppendFirebirdStatusText(
        &status, kIscArgString, diagnostic.derived_table_alias);
    AppendFirebirdStatusText(&status, kIscArgSqlState, "42000");
    response =
        "{\"ok\":false,\"wire_operation\":\"" +
        EscapeJsonLocal(operation) +
        "\",\"diagnostic_code\":\"FIREBIRD.DSQL.DERIVED_FIELD_DUP_NAME\"," +
        "\"sqlstate\":\"42000\",\"sqlcode\":\"-104\"," +
        "\"column\":\"" + EscapeJsonLocal(diagnostic.column_name) +
        "\",\"derived_table\":\"" +
        EscapeJsonLocal(diagnostic.derived_table_alias) + "\"}";
  } else if (diagnostic.kind ==
             FirebirdDerivedTableDiagnosticKind::kIllegalOuterReference) {
    if (diagnostic.qualified_field_name.empty() ||
        diagnostic.outer_relation_alias.empty() || diagnostic.line == 0 ||
        diagnostic.column == 0 ||
        diagnostic.line > std::numeric_limits<std::uint32_t>::max() ||
        diagnostic.column > std::numeric_limits<std::uint32_t>::max()) {
      return std::nullopt;
    }
    AppendFirebirdStatusInt(
        &status, kIscArgNumber,
        static_cast<std::uint32_t>(static_cast<std::int32_t>(-206)));
    AppendFirebirdStatusInt(&status, kIscArgGds, kIscDsqlFieldErr);
    AppendFirebirdStatusInt(&status, kIscArgGds, kIscRandom);
    AppendFirebirdStatusText(
        &status, kIscArgString, diagnostic.qualified_field_name);
    AppendFirebirdStatusInt(&status, kIscArgGds, kIscDsqlLineColError);
    AppendFirebirdStatusInt(
        &status, kIscArgNumber,
        static_cast<std::uint32_t>(diagnostic.line));
    AppendFirebirdStatusInt(
        &status, kIscArgNumber,
        static_cast<std::uint32_t>(diagnostic.column));
    AppendFirebirdStatusText(&status, kIscArgSqlState, "42S22");
    response =
        "{\"ok\":false,\"wire_operation\":\"" +
        EscapeJsonLocal(operation) +
        "\",\"diagnostic_code\":\"FIREBIRD.DSQL.DERIVED_OUTER_REFERENCE\"," +
        "\"sqlstate\":\"42S22\",\"sqlcode\":\"-206\"," +
        "\"field\":\"" +
        EscapeJsonLocal(diagnostic.qualified_field_name) +
        "\",\"derived_table\":\"" +
        EscapeJsonLocal(diagnostic.derived_table_alias) + "\"," +
        "\"line\":" + std::to_string(diagnostic.line) +
        ",\"column\":" + std::to_string(diagnostic.column) + "}";
  } else {
    return std::nullopt;
  }
  AppendXdrU32(&status, kIscArgEnd);
  return FirebirdResponsePacket(0, response, status);
}

std::optional<std::string_view> FirebirdParserOperationForOpcode(
    std::uint32_t opcode) {
  switch (opcode) {
    case 64:
      return "op_exec_immediate";
    case 68:
      return "op_prepare_statement";
    case 75:
      return "op_exec_immediate2";
    default:
      return std::nullopt;
  }
}

std::vector<std::uint8_t> FirebirdEmptyInputResponsePacket(
    std::string_view operation);

std::optional<std::vector<std::uint8_t>>
DispatchFirebirdParserFailurePacketForOpcodeImpl(
    std::uint32_t opcode,
    const ParseResult& parsed) {
  if (parsed.ok) return std::nullopt;
  const auto operation = FirebirdParserOperationForOpcode(opcode);
  if (!operation) return std::nullopt;

  if (parsed.message_vector_json.find("FIREBIRD.PARSE.EMPTY_INPUT") !=
      std::string::npos) {
    return FirebirdEmptyInputResponsePacket(*operation);
  }
  if (parsed.derived_table_diagnostic) {
    if (auto derived = RenderFirebirdDerivedTableDiagnosticPacketImpl(
            *parsed.derived_table_diagnostic, *operation)) {
      return derived;
    }
  }
  if (parsed.message_vector_json.find("FIREBIRD.DSQL.AGGREGATE_WHERE") !=
      std::string::npos) {
    return FirebirdAggregateWhereErrorResponsePacket(
        parsed.message_vector_json);
  }
  return FirebirdWishListResponsePacket(parsed.message_vector_json);
}

std::vector<std::uint8_t> FirebirdEmptyInputResponsePacket(
    std::string_view operation) {
  const std::string response =
      "{\"ok\":false,\"wire_operation\":\"" + std::string(operation) + "\","
      "\"diagnostic_code\":\"FIREBIRD.PARSE.EMPTY_INPUT\","
      "\"sqlstate\":\"42000\","
      "\"runtime_policy\":\"firebird_empty_statement_refused\"}";
  std::vector<std::uint8_t> status;
  AppendFirebirdStatusInt(&status, kIscArgGds, kIscDsqlError);
  AppendFirebirdStatusInt(&status, kIscArgGds, kIscSqlErr);
  AppendFirebirdStatusInt(
      &status, kIscArgNumber,
      static_cast<std::uint32_t>(static_cast<std::int32_t>(-104)));
  AppendFirebirdStatusInt(&status, kIscArgGds, kIscCommandEndErr2);
  AppendFirebirdStatusInt(&status, kIscArgNumber, 1);
  AppendFirebirdStatusInt(&status, kIscArgNumber, 1);
  AppendFirebirdStatusText(&status, kIscArgSqlState, "42000");
  AppendXdrU32(&status, kIscArgEnd);
  return FirebirdResponsePacket(0, response, status);
}

std::vector<std::uint8_t> FirebirdTooManyContextsResponsePacket(
    std::string_view operation) {
  const std::string response =
      "{\"ok\":false,\"wire_operation\":\"" + std::string(operation) + "\","
      "\"diagnostic_code\":\"FIREBIRD.DSQL.TOO_MANY_CONTEXTS\","
      "\"sqlstate\":\"54001\","
      "\"runtime_policy\":\"firebird_set_operation_context_limit\"}";
  std::vector<std::uint8_t> status;
  AppendFirebirdStatusInt(&status, kIscArgGds, 335544569u);  // isc_dsql_error
  AppendFirebirdStatusText(
      &status, kIscArgInterpreted,
      "Too many Contexts of Relation/Procedure/Views. Maximum allowed is 256");
  AppendFirebirdStatusText(&status, kIscArgSqlState, "54001");
  AppendXdrU32(&status, kIscArgEnd);
  return FirebirdResponsePacket(0, response, status);
}

std::vector<std::uint8_t> FirebirdStatusResponsePacket(std::uint32_t status_code,
                                                       std::string_view response_data) {
  return FirebirdResponsePacket(0, response_data, FirebirdStatusVector(status_code));
}

std::vector<std::uint8_t> FirebirdFetchEofPacket() {
  std::vector<std::uint8_t> out;
  AppendXdrU32(&out, 66);   // op_fetch_response
  AppendXdrU32(&out, 100);  // EOF/no row status
  AppendXdrU32(&out, 0);    // no messages
  return out;
}

std::vector<std::uint8_t> FirebirdFetchEndOfBatchPacket() {
  std::vector<std::uint8_t> out;
  AppendXdrU32(&out, 66);  // op_fetch_response
  AppendXdrU32(&out, 0);   // end of this fetch batch, cursor may continue
  AppendXdrU32(&out, 0);   // no messages
  return out;
}

std::vector<std::uint8_t> FirebirdClassicRequestSendPacket(
    const FirebirdClassicDataRequest& request,
    std::uint32_t message_count = 0) {
  std::vector<std::uint8_t> out;
  AppendXdrU32(&out, 25);  // op_send
  AppendXdrU32(&out, request.request_id);
  AppendXdrU32(&out, request.incarnation);
  AppendXdrU32(&out, request.transaction_id);
  AppendXdrU32(&out, request.message_number);
  AppendXdrU32(&out, message_count);
  return out;
}

std::vector<std::uint8_t> FirebirdPiggybackResponsePacket(
    std::uint32_t message_number,
    const std::vector<std::uint8_t>& encoded_status_vector) {
  std::vector<std::uint8_t> out;
  AppendXdrU32(&out, 72);  // op_response_piggyback
  AppendXdrU32(&out, message_number);
  AppendXdrU32(&out, 0);  // blob id high
  AppendXdrU32(&out, 0);  // blob id low
  AppendXdrString(&out, {});
  out.insert(out.end(), encoded_status_vector.begin(), encoded_status_vector.end());
  return out;
}

std::vector<std::uint8_t> FirebirdClassicShortRowPacket(
    const FirebirdClassicDataRequest& request,
    std::int16_t value,
    std::uint32_t message_count = 1) {
  auto out = FirebirdClassicRequestSendPacket(request, message_count);
  AppendXdrU32(&out, static_cast<std::uint32_t>(static_cast<std::int32_t>(value)));
  return out;
}

std::vector<std::uint8_t> FirebirdClassicShortCStringRowPacket(
    const FirebirdClassicDataRequest& request,
    std::int16_t flag,
    std::string_view value,
    std::uint32_t message_count = 1) {
  auto out = FirebirdClassicRequestSendPacket(request, message_count);
  AppendXdrU32(&out, static_cast<std::uint32_t>(static_cast<std::int32_t>(flag)));
  AppendXdrClassicCString(&out, value, 253);
  return out;
}

std::vector<std::uint8_t> FirebirdClassicDatabaseCharsetRowPacket(
    const FirebirdClassicDataRequest& request,
    std::uint16_t charset_length,
    std::uint16_t collation_length,
    bool row_present,
    std::string_view charset_name,
    std::string_view default_collation,
    std::uint32_t message_count = 0) {
  auto out = FirebirdClassicRequestSendPacket(request, message_count);
  AppendXdrU32(&out, row_present ? 1u : 0u);  // FOR-loop row-present flag.
  AppendXdrU32(&out, 0);  // RDB$DEFAULT_COLLATE_NAME null indicator.
  AppendXdrClassicCString(
      &out, row_present ? charset_name : std::string_view{}, charset_length);
  AppendXdrClassicCString(
      &out, row_present ? default_collation : std::string_view{}, collation_length);
  return out;
}

std::vector<std::uint8_t> FirebirdClassicCharsetRowPacket(
    const FirebirdClassicDataRequest& request,
    std::int16_t charset_id,
    std::string_view charset_name,
    std::uint32_t message_count = 1,
    bool include_payload = true) {
  auto out = FirebirdClassicRequestSendPacket(request, message_count);
  if (!include_payload) {
    AppendXdrU32(&out, 0);  // Embedded SQL FOR-loop row-present flag: EOF.
    AppendXdrU32(&out, 0);
    AppendXdrClassicCString(&out, {}, 253);
    return out;
  }
  AppendXdrU32(&out, 1);  // Embedded SQL FOR-loop row-present flag.
  AppendXdrU32(&out, static_cast<std::uint32_t>(static_cast<std::int32_t>(charset_id)));
  AppendXdrClassicCString(&out, charset_name, 253);
  return out;
}

std::vector<std::uint8_t> FirebirdClassicCharsetIdRowPacket(
    const FirebirdClassicDataRequest& request,
    std::int16_t row_present,
    std::int16_t charset_id,
    std::uint32_t message_count = 1) {
  auto out = FirebirdClassicRequestSendPacket(request, message_count);
  AppendXdrU32(&out, static_cast<std::uint32_t>(static_cast<std::int32_t>(row_present)));
  AppendXdrU32(&out, static_cast<std::uint32_t>(static_cast<std::int32_t>(charset_id)));
  return out;
}

std::vector<std::uint8_t> FirebirdClassicGeneratorNameRowPacket(
    const FirebirdClassicDataRequest& request,
    std::string_view generator_name,
    std::uint32_t message_count = 1,
    bool include_payload = true,
    bool row_present = true) {
  auto out = FirebirdClassicRequestSendPacket(request, message_count);
  if (!include_payload) return out;
  AppendXdrU32(&out, row_present ? 1u : 0u);
  AppendXdrU32(&out, 0);  // RDB$SYSTEM_FLAG null flag
  AppendXdrU32(&out, 0);  // RDB$SYSTEM_FLAG value
  AppendXdrClassicCString(&out, generator_name, 253);
  return out;
}

std::vector<std::uint8_t> FirebirdClassicGeneratorDetailRowPacket(
    const FirebirdClassicDataRequest& request,
    std::int64_t initial_value,
    std::int16_t increment,
    std::uint32_t message_count = 1,
    bool include_payload = true,
    bool row_present = true) {
  auto out = FirebirdClassicRequestSendPacket(request, message_count);
  if (!include_payload) return out;
  const auto raw = static_cast<std::uint64_t>(row_present ? initial_value : 0);
  AppendXdrU32(&out, static_cast<std::uint32_t>((raw >> 32) & 0xffffffffu));
  AppendXdrU32(&out, static_cast<std::uint32_t>(raw & 0xffffffffu));
  AppendXdrU32(&out, row_present ? 0u : 1u);  // RDB$INITIAL_VALUE null flag.
  AppendXdrU32(&out, static_cast<std::uint32_t>(
                         static_cast<std::int32_t>(row_present ? increment : 0)));
  AppendXdrU32(&out, row_present ? 1u : 0u);  // Embedded SQL FOR-loop row flag.
  return out;
}

std::vector<std::uint8_t> FirebirdClassicInt64RowPacket(
    const FirebirdClassicDataRequest& request,
    std::int64_t value,
    std::uint32_t message_count = 1) {
  auto out = FirebirdClassicRequestSendPacket(request, message_count);
  const auto raw = static_cast<std::uint64_t>(value);
  AppendXdrU32(&out, static_cast<std::uint32_t>((raw >> 32) & 0xffffffffu));
  AppendXdrU32(&out, static_cast<std::uint32_t>(raw & 0xffffffffu));
  return out;
}

std::vector<std::uint8_t> FirebirdClassicFieldValidationSourceRowPacket(
    const FirebirdClassicDataRequest& request,
    std::uint32_t blob_id_low,
    std::string_view field_name,
    std::uint32_t message_count = 1) {
  auto out = FirebirdClassicRequestSendPacket(request, message_count);
  AppendXdrU32(&out, 0x80);  // blob id high, matching dynamic SQL blob cells
  AppendXdrU32(&out, blob_id_low);
  AppendXdrU32(&out, 1);     // generated FOR-loop row-present flag
  AppendXdrClassicCString(&out, field_name, 253);
  return out;
}

std::uint16_t ReadLeU16Local(const std::vector<std::uint8_t>& buffer,
                             std::size_t offset) {
  return static_cast<std::uint16_t>(buffer[offset]) |
         static_cast<std::uint16_t>(
             static_cast<std::uint16_t>(buffer[offset + 1]) << 8);
}

bool SkipFirebirdClassicMessageSlot(const std::vector<std::uint8_t>& blr,
                                    std::size_t* offset,
                                    std::uint8_t* slot_opcode) {
  if (*offset >= blr.size()) return false;
  *slot_opcode = blr[(*offset)++];
  switch (*slot_opcode) {
    case 7:   // blr_short
    case 8:   // blr_long
    case 9:   // blr_quad
    case 16:  // blr_int64
    case 26:  // blr_int128
      if (*offset + 1 > blr.size()) return false;
      *offset += 1;
      return true;
    case 14:  // blr_text
    case 37:  // blr_varying
    case 40:  // blr_cstring
      if (*offset + 2 > blr.size()) return false;
      *offset += 2;
      return true;
    case 15:  // blr_text2
    case 17:  // blr_blob2
    case 38:  // blr_varying2
    case 41:  // blr_cstring2
      if (*offset + 4 > blr.size()) return false;
      *offset += 4;
      return true;
    case 10:  // blr_float
    case 11:  // blr_d_float
    case 12:  // blr_sql_date
    case 13:  // blr_sql_time
    case 23:  // blr_bool
    case 24:  // blr_dec64
    case 25:  // blr_dec128
    case 27:  // blr_double
    case 28:  // blr_sql_time_tz
    case 29:  // blr_timestamp_tz
    case 30:  // blr_ex_time_tz
    case 31:  // blr_ex_timestamp_tz
    case 35:  // blr_timestamp
    case 45:  // blr_blob_id
      return true;
    default:
      return false;
  }
}

struct FirebirdClassicMessageSlot {
  std::uint8_t opcode{0};
  std::uint16_t length{0};
};

bool ReadFirebirdClassicMessageSlot(const std::vector<std::uint8_t>& blr,
                                    std::size_t* offset,
                                    FirebirdClassicMessageSlot* slot) {
  if (*offset >= blr.size()) return false;
  slot->opcode = blr[(*offset)++];
  slot->length = 0;
  switch (slot->opcode) {
    case 7:   // blr_short
    case 8:   // blr_long
    case 9:   // blr_quad
    case 16:  // blr_int64
    case 26:  // blr_int128
      if (*offset + 1 > blr.size()) return false;
      *offset += 1;
      return true;
    case 14:  // blr_text
    case 37:  // blr_varying
    case 40:  // blr_cstring
      if (*offset + 2 > blr.size()) return false;
      slot->length = ReadLeU16Local(blr, *offset);
      *offset += 2;
      return true;
    case 15:  // blr_text2
    case 38:  // blr_varying2
    case 41:  // blr_cstring2
      if (*offset + 4 > blr.size()) return false;
      slot->length = ReadLeU16Local(blr, *offset + 2);
      *offset += 4;
      return true;
    case 17:  // blr_blob2
      if (*offset + 4 > blr.size()) return false;
      *offset += 4;
      return true;
    case 10:  // blr_float
    case 11:  // blr_d_float
    case 12:  // blr_sql_date
    case 13:  // blr_sql_time
    case 23:  // blr_bool
    case 24:  // blr_dec64
    case 25:  // blr_dec128
    case 27:  // blr_double
    case 28:  // blr_sql_time_tz
    case 29:  // blr_timestamp_tz
    case 30:  // blr_ex_time_tz
    case 31:  // blr_ex_timestamp_tz
    case 35:  // blr_timestamp
    case 45:  // blr_blob_id
      return true;
    default:
      return false;
  }
}

bool FirebirdClassicMessageSlots(const std::vector<std::uint8_t>& blr,
                                 std::uint32_t message_number,
                                 std::vector<FirebirdClassicMessageSlot>* slots) {
  slots->clear();
  if (blr.size() < 5) return false;
  std::size_t offset = 1;
  if (offset < blr.size() && blr[offset] == 2) {  // blr_begin
    ++offset;
  }
  while (offset + 4 <= blr.size() && blr[offset] == 4) {  // blr_message
    ++offset;
    const auto current_message_number = static_cast<std::uint32_t>(blr[offset++]);
    const auto slot_count = ReadLeU16Local(blr, offset);
    offset += 2;
    std::vector<FirebirdClassicMessageSlot> current_slots;
    current_slots.reserve(slot_count);
    for (std::uint16_t slot_index = 0; slot_index < slot_count; ++slot_index) {
      FirebirdClassicMessageSlot slot;
      if (!ReadFirebirdClassicMessageSlot(blr, &offset, &slot)) {
        return false;
      }
      current_slots.push_back(slot);
    }
    if (current_message_number == message_number) {
      *slots = std::move(current_slots);
      return true;
    }
  }
  return false;
}

bool AppendFirebirdClassicZeroSlot(std::vector<std::uint8_t>* out,
                                   const FirebirdClassicMessageSlot& slot) {
  switch (slot.opcode) {
    case 7:   // blr_short
    case 8:   // blr_long
    case 10:  // blr_float
    case 12:  // blr_sql_date
    case 13:  // blr_sql_time
    case 23:  // blr_bool
      AppendXdrU32(out, 0);
      return true;
    case 9:   // blr_quad
    case 11:  // blr_d_float
    case 16:  // blr_int64
    case 24:  // blr_dec64
    case 27:  // blr_double
    case 28:  // blr_sql_time_tz
    case 30:  // blr_ex_time_tz
    case 35:  // blr_timestamp
    case 45:  // blr_blob_id
      AppendXdrU32(out, 0);
      AppendXdrU32(out, 0);
      return true;
    case 25:  // blr_dec128
    case 26:  // blr_int128
      AppendXdrU32(out, 0);
      AppendXdrU32(out, 0);
      AppendXdrU32(out, 0);
      AppendXdrU32(out, 0);
      return true;
    case 29:  // blr_timestamp_tz
    case 31:  // blr_ex_timestamp_tz
      AppendXdrU32(out, 0);
      AppendXdrU32(out, 0);
      AppendXdrU32(out, 0);
      return true;
    case 14:  // blr_text
    case 15:  // blr_text2
      AppendXdrFixedText(out, {}, slot.length);
      return true;
    case 37:  // blr_varying
    case 38:  // blr_varying2
    case 40:  // blr_cstring
    case 41:  // blr_cstring2
      AppendXdrString(out, {});
      return true;
    case 17:  // blr_blob2
      AppendXdrU32(out, 0);
      AppendXdrU32(out, 0);
      return true;
    default:
      return false;
  }
}

std::vector<std::uint8_t> FirebirdClassicZeroMessagePacket(
    const FirebirdClassicDataRequest& request,
    const std::vector<std::uint8_t>& blr,
    std::uint32_t message_count = 0) {
  auto out = FirebirdClassicRequestSendPacket(request, message_count);
  std::vector<FirebirdClassicMessageSlot> slots;
  if (!FirebirdClassicMessageSlots(blr, request.message_number, &slots)) {
    return {};
  }
  for (const auto& slot : slots) {
    if (!AppendFirebirdClassicZeroSlot(&out, slot)) {
      return {};
    }
  }
  return out;
}

std::uint32_t FirebirdClassicShortOutputMessageNumber(
    const std::vector<std::uint8_t>& blr,
    std::uint32_t fallback) {
  if (blr.size() < 5) return fallback;
  std::size_t offset = 1;
  if (offset < blr.size() && blr[offset] == 2) {  // blr_begin
    ++offset;
  }
  while (offset + 4 <= blr.size() && blr[offset] == 4) {  // blr_message
    ++offset;
    const auto message_number = static_cast<std::uint32_t>(blr[offset++]);
    const auto slot_count = ReadLeU16Local(blr, offset);
    offset += 2;
    std::uint8_t first_slot_opcode = 0;
    for (std::uint16_t slot = 0; slot < slot_count; ++slot) {
      std::uint8_t slot_opcode = 0;
      if (!SkipFirebirdClassicMessageSlot(blr, &offset, &slot_opcode)) {
        return fallback;
      }
      if (slot == 0) first_slot_opcode = slot_opcode;
    }
    if (slot_count > 0 && first_slot_opcode == 7) {  // blr_short
      return message_number;
    }
  }
  return fallback;
}

std::uint32_t FirebirdClassicTwoShortOutputMessageNumber(
    const std::vector<std::uint8_t>& blr,
    std::uint32_t fallback) {
  if (blr.size() < 5) return fallback;
  std::size_t offset = 1;
  if (offset < blr.size() && blr[offset] == 2) {  // blr_begin
    ++offset;
  }
  while (offset + 4 <= blr.size() && blr[offset] == 4) {  // blr_message
    ++offset;
    const auto message_number = static_cast<std::uint32_t>(blr[offset++]);
    const auto slot_count = ReadLeU16Local(blr, offset);
    offset += 2;
    std::vector<FirebirdClassicMessageSlot> slots;
    slots.reserve(slot_count);
    for (std::uint16_t slot = 0; slot < slot_count; ++slot) {
      FirebirdClassicMessageSlot current;
      if (!ReadFirebirdClassicMessageSlot(blr, &offset, &current)) {
        return fallback;
      }
      slots.push_back(current);
    }
    if (slots.size() == 2 && slots[0].opcode == 7 && slots[1].opcode == 7) {
      return message_number;
    }
  }
  return fallback;
}

std::int16_t FirebirdCharacterSetId(std::string_view charset_name) {
  const std::string name = UpperIdentifier(TrimAscii(charset_name));
  if (name == "NONE") return 0;
  if (name == "OCTETS") return 1;
  if (name == "ASCII") return 2;
  if (name == "UNICODE_FSS") return 3;
  if (name == "UTF8") return 4;
  if (name == "WIN1251") return 52;
  if (name == "WIN1252") return 53;
  if (name == "WIN1257") return 60;
  if (name == "GBK") return 67;
  return 4;
}

std::int16_t FirebirdCollationId(std::string_view charset_name,
                                 std::string_view collation_name) {
  const std::string charset = UpperIdentifier(TrimAscii(charset_name));
  const std::string collation = UpperIdentifier(TrimAscii(collation_name));
  if (collation.empty()) return 0;
  if (charset == "UTF8") {
    if (collation == "UNICODE") return 0;
    if (collation == "UNICODE_CI") return 3;
    if (collation == "UNICODE_CI_AI") return 4;
  }
  if (charset == "GBK") {
    if (collation == "GBK") return 0;
    if (collation == "GBK_UNICODE") return 1;
  }
  if (charset == "WIN1252") {
    if (collation == "WIN1252") return 0;
    if (collation == "PXW_INTL") return 1;
    if (collation == "PXW_INTL850") return 2;
    if (collation == "PXW_NORDAN4") return 3;
    if (collation == "PXW_SPAN") return 4;
    if (collation == "PXW_SWEDFIN") return 5;
  }
  if (charset == "WIN1257") {
    if (collation == "WIN1257") return 0;
    if (collation == "WIN1257_EE") return 1;
    if (collation == "WIN1257_LT") return 2;
    if (collation == "WIN1257_LV") return 3;
  }
  if (charset == "WIN1251") {
    if (collation == "WIN1251") return 0;
    if (collation == "PXW_CYRL") return 1;
  }
  return 0;
}

bool FirebirdClassicHasLeadingShortStringMessage(
    const std::vector<std::uint8_t>& blr) {
  if (blr.size() < 5) return false;
  std::size_t offset = 1;
  if (offset < blr.size() && blr[offset] == 2) {  // blr_begin
    ++offset;
  }
  while (offset + 4 <= blr.size() && blr[offset] == 4) {  // blr_message
    ++offset;
    ++offset;  // message number
    const auto slot_count = ReadLeU16Local(blr, offset);
    offset += 2;
    std::vector<FirebirdClassicMessageSlot> slots;
    slots.reserve(slot_count);
    for (std::uint16_t slot = 0; slot < slot_count; ++slot) {
      FirebirdClassicMessageSlot current;
      if (!ReadFirebirdClassicMessageSlot(blr, &offset, &current)) {
        return false;
      }
      slots.push_back(current);
    }
    if (slots.size() >= 2 && slots[0].opcode == 7 &&
        (slots[1].opcode == 14 || slots[1].opcode == 15 ||
         slots[1].opcode == 37 || slots[1].opcode == 38 ||
         slots[1].opcode == 40 || slots[1].opcode == 41)) {
      return true;
    }
  }
  return false;
}

bool FirebirdClassicHasSingleShortMessage(const std::vector<std::uint8_t>& blr) {
  if (blr.size() < 5) return false;
  std::size_t offset = 1;
  if (offset < blr.size() && blr[offset] == 2) {  // blr_begin
    ++offset;
  }
  while (offset + 4 <= blr.size() && blr[offset] == 4) {  // blr_message
    ++offset;
    ++offset;  // message number
    const auto slot_count = ReadLeU16Local(blr, offset);
    offset += 2;
    std::vector<FirebirdClassicMessageSlot> slots;
    slots.reserve(slot_count);
    for (std::uint16_t slot = 0; slot < slot_count; ++slot) {
      FirebirdClassicMessageSlot current;
      if (!ReadFirebirdClassicMessageSlot(blr, &offset, &current)) {
        return false;
      }
      slots.push_back(current);
    }
    if (slots.size() == 1 && slots[0].opcode == 7) return true;
  }
  return false;
}

bool FirebirdBlrContainsToken(const std::vector<std::uint8_t>& blr,
                              std::string_view token) {
  if (token.empty() || blr.size() < token.size()) return false;
  return std::search(blr.begin(), blr.end(), token.begin(), token.end()) != blr.end();
}

std::optional<std::size_t> FirebirdClassicBodyOffsetAfterMessages(
    const std::vector<std::uint8_t>& blr) {
  if (blr.size() < 5) return std::nullopt;
  std::size_t offset = 1;
  if (offset < blr.size() && blr[offset] == 2) {  // blr_begin
    ++offset;
  }
  while (offset + 4 <= blr.size() && blr[offset] == 4) {  // blr_message
    ++offset;
    ++offset;  // message number
    const auto slot_count = ReadLeU16Local(blr, offset);
    offset += 2;
    for (std::uint16_t slot_index = 0; slot_index < slot_count; ++slot_index) {
      FirebirdClassicMessageSlot slot;
      if (!ReadFirebirdClassicMessageSlot(blr, &offset, &slot)) {
        return std::nullopt;
      }
    }
  }
  return offset;
}

bool FirebirdClassicRequestBodyContainsOpcode(const std::vector<std::uint8_t>& blr,
                                              std::uint8_t opcode) {
  const auto body_offset = FirebirdClassicBodyOffsetAfterMessages(blr);
  if (!body_offset || *body_offset >= blr.size()) return false;
  return std::find(blr.begin() + static_cast<std::ptrdiff_t>(*body_offset),
                   blr.end(), opcode) != blr.end();
}

bool FirebirdBlrContainsByteSequence(const std::vector<std::uint8_t>& blr,
                                     std::initializer_list<std::uint8_t> pattern) {
  if (pattern.size() == 0 || blr.size() < pattern.size()) return false;
  return std::search(blr.begin(), blr.end(), pattern.begin(), pattern.end()) != blr.end();
}

bool IsFirebirdClassicStoreWithoutOutput(const std::vector<std::uint8_t>& blr) {
  constexpr std::uint8_t kBlrReceive = 12;
  constexpr std::uint8_t kBlrSend = 14;
  constexpr std::uint8_t kBlrStore = 15;
  constexpr std::uint8_t kBlrStore2 = 19;
  const bool generated_store_receive =
      FirebirdBlrContainsByteSequence(blr, {kBlrReceive, 0, kBlrStore}) ||
      FirebirdBlrContainsByteSequence(blr, {kBlrReceive, 0, kBlrStore2});
  if (generated_store_receive) {
    return true;
  }
  return (FirebirdClassicRequestBodyContainsOpcode(blr, kBlrStore) ||
          FirebirdClassicRequestBodyContainsOpcode(blr, kBlrStore2)) &&
         !FirebirdClassicRequestBodyContainsOpcode(blr, kBlrSend);
}

std::vector<std::string> FirebirdClassicCStringArgs(
    const std::vector<std::string>& classic_args) {
  std::vector<std::string> values;
  for (const auto& arg : classic_args) {
    constexpr std::string_view prefix = "cstring:";
    if (!std::string_view(arg).starts_with(prefix)) continue;
    values.push_back(TrimAscii(arg.substr(prefix.size())));
  }
  return values;
}

bool FirebirdRestoreUserRelationName(std::string_view relation_name) {
  const std::string name = UpperIdentifier(TrimAscii(relation_name));
  if (name.empty()) return false;
  if (name.starts_with("RDB$") || name.starts_with("MON$") ||
      name.starts_with("SEC$") || name.starts_with("SQL$")) {
    return false;
  }
  return true;
}

FirebirdColumnDescriptor FirebirdRestoreIntegerColumn(std::string name,
                                                      std::string relation) {
  FirebirdColumnDescriptor column;
  column.name = std::move(name);
  column.relation = std::move(relation);
  column.sql_type = 496;
  column.length = 4;
  column.nullable = true;
  return column;
}

std::string FirebirdRestoreCharacterSetName(std::int16_t character_set_id) {
  switch (character_set_id) {
    case 0:
      return "NONE";
    case 1:
      return "OCTETS";
    case 2:
      return "ASCII";
    case 3:
      return "UNICODE_FSS";
    case 4:
      return "UTF8";
    case 52:
      return "WIN1251";
    case 53:
      return "WIN1252";
    case 60:
      return "WIN1257";
    case 67:
      return "GBK";
    default:
      return "NONE";
  }
}

std::uint32_t FirebirdRestoreSqlType(std::int16_t field_type) {
  switch (field_type) {
    case 7:   // blr_short
      return 500;
    case 10:  // blr_float
      return 482;
    case 12:  // blr_sql_date
      return 570;
    case 13:  // blr_sql_time
      return 560;
    case 14:  // blr_text
    case 37:  // blr_varying
      return 452;
    case 16:  // blr_int64
      return 580;
    case 27:  // blr_double
      return 480;
    case 35:  // blr_timestamp
      return 510;
    case 261:  // blr_blob
      return 520;
    case 8:    // blr_long
    default:
      return 496;
  }
}

bool MaterializeFirebirdRestoreFieldStore(
    FirebirdBinarySessionState* state,
    std::uint32_t transaction_id,
    const std::vector<std::uint8_t>& blr,
    const std::vector<std::string>& classic_args) {
  if (state == nullptr || transaction_id == 0 ||
      !FirebirdBlrContainsToken(blr, "RDB$FIELDS") ||
      FirebirdBlrContainsToken(blr, "RDB$RELATION_FIELDS") ||
      !FirebirdBlrContainsToken(blr, "RDB$FIELD_NAME") ||
      !FirebirdBlrContainsToken(blr, "RDB$FIELD_TYPE")) {
    return false;
  }

  const std::string field_name = UpperIdentifier(
      FirebirdClassicCStringSlotArg(classic_args, 56).value_or(""));
  if (field_name.empty()) return false;

  FirebirdColumnDescriptor column;
  column.name = field_name;
  column.domain_name = field_name;
  column.sql_type = FirebirdRestoreSqlType(
      FirebirdClassicShortSlotArg(classic_args, 13).value_or(8));
  column.length = static_cast<std::uint32_t>(std::max<std::int16_t>(
      1, FirebirdClassicShortSlotArg(classic_args, 12).value_or(4)));
  column.character_length = static_cast<std::uint32_t>(
      std::max<std::int16_t>(
          0, FirebirdClassicShortSlotArg(classic_args, 24).value_or(0)));
  column.scale = FirebirdClassicShortSlotArg(classic_args, 52).value_or(0);
  column.subtype = FirebirdClassicShortSlotArg(classic_args, 48).value_or(0);
  column.nullable =
      FirebirdClassicShortSlotArg(classic_args, 36).value_or(0) == 0;
  if (column.sql_type == 452) {
    const auto character_set_id =
        FirebirdClassicShortSlotArg(classic_args, 50).value_or(0);
    column.character_set = FirebirdRestoreCharacterSetName(character_set_id);
    column.subtype = character_set_id;
    column.collation = FirebirdDefaultCollationNameForCharset(
        *state, column.character_set);
    if (column.character_length == 0) {
      const auto max_bytes = FirebirdCharacterSetMaxBytes(column.character_set);
      column.character_length =
          std::max<std::uint32_t>(1, column.length / std::max(1u, max_bytes));
    }
  }
  state->pending_restore_fields[transaction_id][field_name] = column;
  TraceFirebirdWorker("firebird_restore.field_staged field=" + field_name +
                      " transaction=" + std::to_string(transaction_id) +
                      " sql_type=" + std::to_string(column.sql_type) +
                      " length=" + std::to_string(column.length) +
                      " character_length=" +
                      std::to_string(column.character_length));
  return true;
}

bool MaterializeFirebirdRestoreRelationStore(
    FirebirdBinarySessionState* state,
    std::uint32_t transaction_id,
    const std::vector<std::uint8_t>& blr,
    const std::vector<std::string>& classic_args) {
  if (state == nullptr || transaction_id == 0) return false;
  if (!FirebirdBlrContainsToken(blr, "RDB$RELATIONS") ||
      !FirebirdBlrContainsToken(blr, "RDB$RELATION_NAME") ||
      FirebirdBlrContainsToken(blr, "RDB$RELATION_FIELDS") ||
      FirebirdBlrContainsToken(blr, "RDB$INDICES") ||
      FirebirdBlrContainsToken(blr, "RDB$RELATION_CONSTRAINTS")) {
    return false;
  }
  std::string relation_name =
      UpperIdentifier(FirebirdClassicCStringSlotArg(classic_args, 22).value_or(""));
  if (!FirebirdRestoreUserRelationName(relation_name)) {
    const auto cstrings = FirebirdClassicCStringArgs(classic_args);
    relation_name.clear();
    for (auto it = cstrings.rbegin(); it != cstrings.rend(); ++it) {
      if (FirebirdRestoreUserRelationName(*it)) {
        relation_name = UpperIdentifier(*it);
        break;
      }
    }
  }
  if (relation_name.empty()) return false;
  auto& table = state->pending_restore_tables[transaction_id][relation_name];
  const bool changed = table.name.empty();
  table.name = relation_name;
  TraceFirebirdWorker("firebird_restore.relation_staged table=" + relation_name +
                      " transaction=" + std::to_string(transaction_id));
  return changed;
}

bool MaterializeFirebirdRestoreViewRelationStore(
    FirebirdBinarySessionState* state,
    const std::vector<std::uint8_t>& blr,
    const std::vector<std::string>& classic_args) {
  if (state == nullptr) return false;
  if (!FirebirdBlrContainsToken(blr, "RDB$VIEW_RELATIONS") ||
      !FirebirdBlrContainsToken(blr, "RDB$VIEW_NAME")) {
    return false;
  }
  const std::string view_name =
      UpperIdentifier(FirebirdClassicCStringSlotArg(classic_args, 4).value_or(""));
  if (!FirebirdRestoreUserRelationName(view_name)) return false;

  const bool existed = state->views.find(view_name) != state->views.end();
  auto& view = state->views[view_name];
  if (view.name.empty()) view.name = view_name;
  if (auto table_it = state->tables.find(view_name);
      table_it != state->tables.end()) {
    if (view.columns.empty()) {
      view.columns = std::move(table_it->second.columns);
    }
    state->tables.erase(table_it);
  }
  view.columns.erase(
      std::remove_if(view.columns.begin(), view.columns.end(),
                     [](const FirebirdColumnDescriptor& column) {
                       return UpperIdentifier(column.name) == "NAME" &&
                              column.domain_name.empty() &&
                              column.base_field.empty() &&
                              column.default_value.empty() &&
                              column.computed_expression.empty() &&
                              !column.primary_key &&
                              !column.unique_key &&
                              !column.is_array &&
                              column.sql_type == 496 &&
                              column.length == 4;
                     }),
      view.columns.end());
  TraceFirebirdWorker("firebird_restore.view_relation_materialized view=" +
                      view_name);
  return !existed;
}

bool MaterializeFirebirdRestoreRelationFieldStore(
    FirebirdBinarySessionState* state,
    std::uint32_t transaction_id,
    const std::vector<std::uint8_t>& blr,
    const std::vector<std::string>& classic_args) {
  if (state == nullptr || transaction_id == 0) return false;
  if (!FirebirdBlrContainsToken(blr, "RDB$RELATION_FIELDS") ||
      !FirebirdBlrContainsToken(blr, "RDB$RELATION_NAME") ||
      !FirebirdBlrContainsToken(blr, "RDB$FIELD_NAME")) {
    return false;
  }
  const std::string relation_name =
      UpperIdentifier(FirebirdClassicCStringSlotArg(classic_args, 31).value_or(""));
  const std::string field_name =
      UpperIdentifier(FirebirdClassicCStringSlotArg(classic_args, 37).value_or(""));
  if (!FirebirdRestoreUserRelationName(relation_name) || field_name.empty()) {
    return false;
  }
  const std::string field_source =
      UpperIdentifier(FirebirdClassicCStringSlotArg(classic_args, 38).value_or(""));
  FirebirdColumnDescriptor column =
      FirebirdRestoreIntegerColumn(field_name, relation_name);
  if (const auto field = state->restore_field_descriptors.find(field_source);
      field != state->restore_field_descriptors.end()) {
    column = field->second;
    column.name = field_name;
    column.relation = relation_name;
  }
  column.domain_name = field_source;
  const auto field_position = FirebirdClassicShortSlotArg(classic_args, 30);
  if (FirebirdClassicShortSlotArg(classic_args, 27).value_or(1) == 0) {
    column.base_field =
        UpperIdentifier(FirebirdClassicCStringSlotArg(classic_args, 32).value_or(""));
  }
  const std::string base_field = column.base_field;

  auto upsert_column = [&](std::vector<FirebirdColumnDescriptor>* columns) {
    const auto target_position =
        field_position && *field_position >= 0
            ? std::optional<std::size_t>(
                  static_cast<std::size_t>(*field_position))
            : std::nullopt;
    auto existing = std::find_if(
        columns->begin(), columns->end(), [&](const FirebirdColumnDescriptor& value) {
          return UpperIdentifier(value.name) == field_name;
        });
    if (existing == columns->end()) {
      const std::size_t insert_position =
          target_position
              ? std::min<std::size_t>(*target_position, columns->size())
              : columns->size();
      columns->insert(columns->begin() +
                          static_cast<std::ptrdiff_t>(insert_position),
                      column);
      return true;
    }
    std::size_t existing_position =
        static_cast<std::size_t>(existing - columns->begin());
    *existing = column;
    if (target_position && existing_position != *target_position) {
      FirebirdColumnDescriptor reordered = std::move((*columns)[existing_position]);
      columns->erase(columns->begin() +
                     static_cast<std::ptrdiff_t>(existing_position));
      std::size_t insert_position =
          std::min<std::size_t>(*target_position, columns->size());
      columns->insert(columns->begin() +
                          static_cast<std::ptrdiff_t>(insert_position),
                      std::move(reordered));
    }
    return true;
  };

  if (auto view_it = state->views.find(relation_name);
      view_it != state->views.end()) {
    const bool changed = upsert_column(&view_it->second.columns);
    TraceFirebirdWorker("firebird_restore.relation_field_materialized view=" +
                        relation_name + " field=" + field_name +
                        " base=" + base_field);
    return changed;
  }
  if (auto transaction = state->pending_restore_tables.find(transaction_id);
      transaction != state->pending_restore_tables.end()) {
    if (auto table_it = transaction->second.find(relation_name);
        table_it != transaction->second.end()) {
      const bool changed = upsert_column(&table_it->second.columns);
      TraceFirebirdWorker("firebird_restore.relation_field_staged table=" +
                          relation_name + " field=" + field_name +
                          " source=" + field_source + " base=" + base_field +
                          " transaction=" + std::to_string(transaction_id));
      return changed;
    }
  }
  if (auto table_it = state->tables.find(relation_name);
      table_it != state->tables.end()) {
    const bool changed = upsert_column(&table_it->second.columns);
    TraceFirebirdWorker("firebird_restore.relation_field_materialized_existing table=" +
                        relation_name + " field=" + field_name +
                        " source=" + field_source + " base=" + base_field);
    return changed;
  }
  return false;
}

std::optional<std::pair<std::size_t, std::string>> FirebirdClassicCStringSlotValue(
    std::string_view arg) {
  constexpr std::string_view prefix = "cstring_slot_";
  if (!arg.starts_with(prefix)) return std::nullopt;
  const auto colon = arg.find(':', prefix.size());
  if (colon == std::string_view::npos) return std::nullopt;
  const auto slot = ParseUnsignedText(arg.substr(prefix.size(),
                                                colon - prefix.size()));
  if (!slot) return std::nullopt;
  return std::pair<std::size_t, std::string>(
      static_cast<std::size_t>(*slot), std::string(arg.substr(colon + 1)));
}

std::optional<std::pair<std::size_t, std::string>> FirebirdClassicShortSlotValue(
    std::string_view arg) {
  constexpr std::string_view prefix = "short_slot_";
  if (!arg.starts_with(prefix)) return std::nullopt;
  const auto colon = arg.find(':', prefix.size());
  if (colon == std::string_view::npos) return std::nullopt;
  const auto slot = ParseUnsignedText(arg.substr(prefix.size(),
                                                colon - prefix.size()));
  if (!slot) return std::nullopt;
  const auto value = ParseSignedText(arg.substr(colon + 1));
  if (!value) return std::nullopt;
  return std::pair<std::size_t, std::string>(
      static_cast<std::size_t>(*slot), std::to_string(*value));
}

bool MaterializeFirebirdRestoreUserTableRowStore(
    FirebirdBinarySessionState* state,
    const std::vector<std::uint8_t>& blr,
    const std::vector<std::string>& classic_args,
    std::optional<FirebirdPipelineResult>* engine_result) {
  if (state == nullptr || classic_args.empty()) return false;

  const FirebirdTableDescriptor* table = nullptr;
  std::string table_key;
  std::size_t longest_name = 0;
  for (const auto& [name, descriptor] : state->tables) {
    const std::string candidate_key = FirebirdOverlayTableKey(name);
    if (candidate_key.empty() ||
        state->restore_engine_tables.find(candidate_key) ==
            state->restore_engine_tables.end() ||
        !FirebirdRestoreUserRelationName(name) ||
        !FirebirdBlrContainsToken(blr, name) ||
        name.size() < longest_name) {
      continue;
    }
    table = &descriptor;
    table_key = candidate_key;
    longest_name = name.size();
  }
  if (table == nullptr || table->columns.empty()) return false;

  std::map<std::size_t, std::string> cstrings;
  std::map<std::size_t, std::int64_t> shorts;
  for (const auto& arg : classic_args) {
    if (auto value = FirebirdClassicCStringSlotValue(arg)) {
      cstrings[value->first] = value->second;
    } else if (auto value = FirebirdClassicShortSlotValue(arg)) {
      shorts[value->first] = ParseSignedText(value->second).value_or(0);
    }
  }

  FirebirdRow row;
  row.cells.resize(table->columns.size(), FirebirdCellNull());
  bool populated = false;
  for (std::size_t column_index = 0;
       column_index < table->columns.size(); ++column_index) {
    const std::size_t value_slot = column_index * 2;
    const std::size_t null_slot = value_slot + 1;
    if (const auto null_value = shorts.find(null_slot);
        null_value != shorts.end() && null_value->second != 0) {
      populated = true;
      continue;
    }
    if (const auto value = cstrings.find(value_slot); value != cstrings.end()) {
      row.cells[column_index] = FirebirdCellText(value->second);
      populated = true;
      continue;
    }
    if (const auto value = shorts.find(value_slot); value != shorts.end()) {
      row.cells[column_index] = FirebirdCellText(std::to_string(value->second));
      populated = true;
    }
  }
  if (!populated) return false;

  std::string insert_sql = "INSERT INTO " + RenderCanonicalIdentifier(table->name) + " (";
  for (std::size_t index = 0; index < table->columns.size(); ++index) {
    if (index != 0) insert_sql += ", ";
    insert_sql += RenderCanonicalIdentifier(table->columns[index].name);
  }
  insert_sql += ") VALUES (";
  for (std::size_t index = 0; index < table->columns.size(); ++index) {
    if (index != 0) insert_sql += ", ";
    insert_sql += FirebirdCellSqlLiteral(row.cells[index], table->columns[index]);
  }
  insert_sql += ")";
  auto executed = ExecuteFirebirdStatement(state, insert_sql, false);
  if (engine_result != nullptr) *engine_result = executed;
  TraceFirebirdWorker("firebird_restore.user_row_engine_routed table=" +
                      table_key + " accepted=" +
                      (executed.accepted ? "true" : "false") +
                      " sql=" + EscapeJsonLocal(insert_sql));
  return true;
}

std::optional<FirebirdPipelineResult>
FlushFirebirdPendingRestoreTables(FirebirdBinarySessionState* state,
                                  std::uint32_t transaction_id) {
  if (state == nullptr) return std::nullopt;
  const auto pending = state->pending_restore_tables.find(transaction_id);
  if (pending == state->pending_restore_tables.end()) return std::nullopt;

  std::optional<FirebirdPipelineResult> last_result;
  for (const auto& [name, table] : pending->second) {
    if (table.columns.empty()) {
      TraceFirebirdWorker("firebird_restore.table_flush_skipped_empty table=" + name +
                          " transaction=" + std::to_string(transaction_id));
      continue;
    }
    std::string create_sql = "CREATE TABLE " + RenderCanonicalIdentifier(table.name) + " (";
    for (std::size_t index = 0; index < table.columns.size(); ++index) {
      if (index != 0) create_sql += ", ";
      const auto& column = table.columns[index];
      create_sql += RenderCanonicalIdentifier(column.name) + " " +
                    FirebirdColumnCanonicalType(column);
      if (!column.nullable) create_sql += " NOT NULL";
    }
    create_sql += ")";
    last_result = ExecuteFirebirdStatement(state, create_sql, false);
    TraceFirebirdWorker("firebird_restore.table_engine_routed table=" + name +
                        " transaction=" + std::to_string(transaction_id) +
                        " accepted=" +
                        (last_result->accepted ? "true" : "false") +
                        " sql=" + EscapeJsonLocal(create_sql));
    if (!last_result->accepted) return last_result;
  }
  return last_result;
}

void FinalizeFirebirdRestoreDescriptors(FirebirdBinarySessionState* state,
                                        std::uint32_t transaction_id,
                                        bool commit) {
  if (state == nullptr) return;
  if (!commit) {
    state->pending_restore_fields.erase(transaction_id);
    state->pending_restore_tables.erase(transaction_id);
    TraceFirebirdWorker("firebird_restore.pending_discarded transaction=" +
                        std::to_string(transaction_id));
    return;
  }

  bool metadata_changed = false;
  if (auto fields = state->pending_restore_fields.find(transaction_id);
      fields != state->pending_restore_fields.end()) {
    for (auto& [name, column] : fields->second) {
      state->restore_field_descriptors[name] = std::move(column);
      metadata_changed = true;
    }
    state->pending_restore_fields.erase(fields);
  }
  if (auto tables = state->pending_restore_tables.find(transaction_id);
      tables != state->pending_restore_tables.end()) {
    for (auto& [name, table] : tables->second) {
      if (table.columns.empty()) continue;
      state->tables[name] = table;
      state->restore_engine_tables.insert(FirebirdOverlayTableKey(name));
      RecordFirebirdCreatorTablePrivileges(state, name);
      metadata_changed = true;
    }
    state->pending_restore_tables.erase(tables);
  }
  if (metadata_changed) PersistFirebirdMetadataOverlay(*state);
  TraceFirebirdWorker("firebird_restore.pending_finalized transaction=" +
                      std::to_string(transaction_id) + " commit=true");
}

