bool IsFirebirdRuntimeV5SystemFunctionNameScan(
    const std::vector<std::uint8_t>& blr) {
  if (blr.size() != 223 ||
      !FirebirdBlrContainsToken(blr, "RDB$FUNCTIONS") ||
      !FirebirdBlrContainsToken(blr, "RDB$FUNCTION_NAME") ||
      !FirebirdBlrContainsToken(blr, "RDB$PACKAGE_NAME") ||
      !FirebirdBlrContainsToken(blr, "RDB$VALID_BLR") ||
      !FirebirdBlrContainsToken(blr, "RDB$SYSTEM_FLAG")) {
    return false;
  }
  std::vector<FirebirdClassicMessageSlot> input_slots;
  std::vector<FirebirdClassicMessageSlot> output_slots;
  return FirebirdClassicMessageSlots(blr, 0, &input_slots) &&
         input_slots.size() == 1 && input_slots[0].opcode == 7 &&
         FirebirdClassicMessageSlots(blr, 1, &output_slots) &&
         output_slots.size() == 6 && output_slots[0].opcode == 7 &&
         output_slots[1].opcode == 7 && output_slots[2].opcode == 7 &&
         output_slots[3].opcode == 7 && output_slots[4].opcode == 40 &&
         output_slots[4].length == 253 && output_slots[5].opcode == 40 &&
         output_slots[5].length == 253;
}

bool FirebirdBlrContainsLongLiteralOne(
    const std::vector<std::uint8_t>& blr) {
  static constexpr std::array<std::uint8_t, 7> kLongLiteralOne{
      0x15, 0x08, 0x00, 0x01, 0x00, 0x00, 0x00};
  return std::search(blr.begin(), blr.end(), kLongLiteralOne.begin(),
                     kLongLiteralOne.end()) != blr.end();
}

bool IsFirebirdRuntimeV5SystemProcedureNameScan(
    const std::vector<std::uint8_t>& blr) {
  if (blr.size() != 223 ||
      !FirebirdBlrContainsToken(blr, "RDB$PROCEDURES") ||
      !FirebirdBlrContainsToken(blr, "RDB$PROCEDURE_NAME") ||
      !FirebirdBlrContainsToken(blr, "RDB$PACKAGE_NAME") ||
      !FirebirdBlrContainsToken(blr, "RDB$VALID_BLR") ||
      !FirebirdBlrContainsToken(blr, "RDB$SYSTEM_FLAG") ||
      FirebirdBlrContainsToken(blr, "RDB$PROCEDURE_PARAMETERS") ||
      !FirebirdBlrContainsLongLiteralOne(blr)) {
    return false;
  }
  std::vector<FirebirdClassicMessageSlot> slots;
  if (!FirebirdClassicMessageSlots(blr, 0, &slots) || slots.size() != 8) {
    return false;
  }
  for (std::size_t index = 0; index < 6; ++index) {
    if (slots[index].opcode != 7) return false;
  }
  return (slots[6].opcode == 40 || slots[6].opcode == 41) &&
         (slots[7].opcode == 40 || slots[7].opcode == 41) &&
         slots[6].length == 253 && slots[7].length == 253;
}

