bool IsFirebirdRuntimeV5SystemCollationScan(
    const std::vector<std::uint8_t>& blr) {
  if (blr.size() != 360 || !IsFirebirdRuntimeCollationScan(blr) ||
      !FirebirdBlrContainsToken(blr, "RDB$SPECIFIC_ATTRIBUTES") ||
      !FirebirdBlrContainsToken(blr, "RDB$COLLATION_ATTRIBUTES") ||
      !FirebirdBlrContainsToken(blr, "RDB$SYSTEM_FLAG") ||
      !FirebirdBlrContainsToken(blr, "RDB$BASE_COLLATION_NAME")) {
    return false;
  }
  std::vector<FirebirdClassicMessageSlot> slots;
  if (!FirebirdClassicMessageSlots(blr, 0, &slots) || slots.size() != 11 ||
      slots[0].opcode != 9) {
    return false;
  }
  for (std::size_t index = 1; index <= 7; ++index) {
    if (slots[index].opcode != 7) return false;
  }
  return slots[8].opcode == 40 && slots[8].length == 253 &&
         slots[9].opcode == 40 && slots[9].length == 253 &&
         slots[10].opcode == 40 && slots[10].length == 253;
}

bool ReadFirebirdClassicCStringArgument(int fd, std::string* value) {
  std::uint32_t length = 0;
  if (!ReadXdrU32(fd, &length)) return false;
  if (length > 4096) return false;
  std::vector<std::uint8_t> bytes(length);
  if (length != 0 && !ReadBytes(fd, bytes.data(), bytes.size())) return false;
  const auto padding = (4u - (length & 3u)) & 3u;
  std::uint8_t ignored[4]{};
  if (padding != 0 && !ReadBytes(fd, ignored, padding)) return false;
  value->assign(bytes.begin(), bytes.end());
  return true;
}

bool ReadFirebirdClassicCStringArgumentTrace(int fd,
                                             std::string* value,
                                             std::string_view context) {
  std::uint32_t length = 0;
  if (!ReadXdrU32(fd, &length)) return false;
  TraceFirebirdWorker(std::string("classic_cstring.length context=") +
                      std::string(context) + " length=" + std::to_string(length));
  if (length > 4096) return false;
  std::vector<std::uint8_t> bytes(length);
  if (length != 0 && !ReadBytes(fd, bytes.data(), bytes.size())) return false;
  const auto padding = (4u - (length & 3u)) & 3u;
  std::uint8_t ignored[4]{};
  if (padding != 0 && !ReadBytes(fd, ignored, padding)) return false;
  value->assign(bytes.begin(), bytes.end());
  return true;
}

bool ReadFirebirdClassicShortArgument(int fd, std::int16_t* value) {
  std::uint32_t raw = 0;
  if (!ReadXdrU32(fd, &raw)) return false;
  *value = static_cast<std::int16_t>(static_cast<std::int32_t>(raw));
  return true;
}

std::string FirebirdTrimRightSpaces(std::string value);

bool ReadFirebirdClassicFixedOpaque(int fd, std::uint32_t length) {
  constexpr std::uint32_t kMaxClassicOpaque = 64u * 1024u;
  if (length > kMaxClassicOpaque) return false;
  std::vector<std::uint8_t> bytes(length);
  if (length != 0 && !ReadBytes(fd, bytes.data(), bytes.size())) return false;
  const auto padding = (4u - (length & 3u)) & 3u;
  std::uint8_t ignored[4]{};
  return padding == 0 || ReadBytes(fd, ignored, padding);
}

bool ReadFirebirdClassicFixedOpaqueValue(int fd,
                                         std::uint32_t length,
                                         std::string* value) {
  constexpr std::uint32_t kMaxClassicOpaque = 64u * 1024u;
  if (length > kMaxClassicOpaque) return false;
  std::vector<std::uint8_t> bytes(length);
  if (length != 0 && !ReadBytes(fd, bytes.data(), bytes.size())) return false;
  const auto padding = (4u - (length & 3u)) & 3u;
  std::uint8_t ignored[4]{};
  if (padding != 0 && !ReadBytes(fd, ignored, padding)) return false;
  value->assign(bytes.begin(), bytes.end());
  return true;
}

bool ReadFirebirdClassicDiscardU32s(int fd, std::uint32_t count) {
  std::uint32_t ignored = 0;
  for (std::uint32_t i = 0; i < count; ++i) {
    if (!ReadXdrU32(fd, &ignored)) return false;
  }
  return true;
}

std::uint32_t FirebirdReadableByteCount(int fd) {
  int count = 0;
  if (::ioctl(fd, FIONREAD, &count) != 0 || count < 0) return 0;
  return static_cast<std::uint32_t>(count);
}

std::uint32_t FirebirdClassicSlotMinimumWireBytes(
    const FirebirdClassicMessageSlot& slot) {
  switch (slot.opcode) {
    case 7:   // blr_short
    case 8:   // blr_long
    case 10:  // blr_float
    case 12:  // blr_sql_date
    case 13:  // blr_sql_time
    case 23:  // blr_bool
      return 4;
    case 9:   // blr_quad
    case 11:  // blr_d_float
    case 16:  // blr_int64
    case 24:  // blr_dec64
    case 27:  // blr_double
    case 28:  // blr_sql_time_tz
    case 30:  // blr_ex_time_tz
    case 35:  // blr_timestamp
    case 45:  // blr_blob_id
      return 8;
    case 29:  // blr_timestamp_tz
    case 31:  // blr_ex_timestamp_tz
      return 12;
    case 25:  // blr_dec128
    case 26:  // blr_int128
      return 16;
    case 14:  // blr_text
    case 15:  // blr_text2
      return (static_cast<std::uint32_t>(slot.length) + 3u) & ~3u;
    case 17:  // blr_blob2
      return 8;
    case 37:  // blr_varying
    case 38:  // blr_varying2
    case 40:  // blr_cstring
    case 41:  // blr_cstring2
      return 4;
    default:
      return 0;
  }
}

bool ReadFirebirdClassicMessagePayload(int fd,
                                       const std::vector<std::uint8_t>& blr,
                                       std::uint32_t message_number,
                                       std::vector<std::string>* trace_args) {
  std::vector<FirebirdClassicMessageSlot> slots;
  if (!FirebirdClassicMessageSlots(blr, message_number, &slots)) return false;
  std::uint32_t cstring_count = 0;
  for (std::size_t slot_index = 0; slot_index < slots.size(); ++slot_index) {
    const auto& slot = slots[slot_index];
    TraceFirebirdWorker("generic_payload.slot index=" + std::to_string(slot_index) +
                        " opcode=" + std::to_string(slot.opcode) +
                        " length=" + std::to_string(slot.length));
    switch (slot.opcode) {
      case 7:   // blr_short
      {
        std::int16_t value = 0;
        if (!ReadFirebirdClassicShortArgument(fd, &value)) return false;
        trace_args->push_back("short:" + std::to_string(value));
        trace_args->push_back("short_slot_" + std::to_string(slot_index) + ":" +
                              std::to_string(value));
        break;
      }
      case 8:   // blr_long
      case 10:  // blr_float
      case 12:  // blr_sql_date
      case 13:  // blr_sql_time
      case 23:  // blr_bool
        if (!ReadFirebirdClassicDiscardU32s(fd, 1)) return false;
        break;
      case 9:   // blr_quad
      case 11:  // blr_d_float
      case 16:  // blr_int64
      case 24:  // blr_dec64
      case 27:  // blr_double
      case 35:  // blr_timestamp
      case 45:  // blr_blob_id
        if (!ReadFirebirdClassicDiscardU32s(fd, 2)) return false;
        break;
      case 26:  // blr_int128
      case 25:  // blr_dec128
        if (!ReadFirebirdClassicDiscardU32s(fd, 4)) return false;
        break;
      case 28:  // blr_sql_time_tz
      case 30:  // blr_ex_time_tz
        if (!ReadFirebirdClassicDiscardU32s(fd, 2)) return false;
        break;
      case 29:  // blr_timestamp_tz
      case 31:  // blr_ex_timestamp_tz
        if (!ReadFirebirdClassicDiscardU32s(fd, 3)) return false;
        break;
      case 14:  // blr_text
      case 15:  // blr_text2
        if (!ReadFirebirdClassicFixedOpaque(fd, slot.length)) return false;
        break;
      case 37:  // blr_varying
      case 38:  // blr_varying2
      case 40:  // blr_cstring
      case 41: {  // blr_cstring2
        std::string text;
        if (!ReadFirebirdClassicCStringArgumentTrace(
                fd, &text, "generic_slot_" + std::to_string(slot_index))) {
          return false;
        }
        trace_args->push_back("cstring_slot_" + std::to_string(slot_index) + ":" +
                              FirebirdTrimRightSpaces(text));
        if (cstring_count < 3) {
          trace_args->push_back("cstring:" + FirebirdTrimRightSpaces(std::move(text)));
        }
        ++cstring_count;
        break;
      }
      case 17:  // blr_blob2
        if (!ReadFirebirdClassicDiscardU32s(fd, 2)) return false;
        break;
      default:
        return false;
    }
  }
  trace_args->push_back("generic_payload_slots:" + std::to_string(slots.size()));
  return true;
}

bool ReadFirebirdClassicMessagePayloadValues(
    int fd,
    const std::vector<std::uint8_t>& blr,
    std::uint32_t message_number,
    std::vector<std::string>* trace_args,
    std::vector<std::string>* values) {
  std::vector<FirebirdClassicMessageSlot> slots;
  if (!FirebirdClassicMessageSlots(blr, message_number, &slots)) return false;
  for (std::size_t slot_index = 0; slot_index < slots.size(); ++slot_index) {
    const auto& slot = slots[slot_index];
    TraceFirebirdWorker("value_payload.slot index=" + std::to_string(slot_index) +
                        " opcode=" + std::to_string(slot.opcode) +
                        " length=" + std::to_string(slot.length));
    switch (slot.opcode) {
      case 7: {  // blr_short
        std::int16_t value = 0;
        if (!ReadFirebirdClassicShortArgument(fd, &value)) return false;
        trace_args->push_back("short:" + std::to_string(value));
        values->push_back(std::to_string(value));
        break;
      }
      case 8: {  // blr_long
        std::uint32_t raw = 0;
        if (!ReadXdrU32(fd, &raw)) return false;
        const auto value = static_cast<std::int32_t>(raw);
        trace_args->push_back("long:" + std::to_string(value));
        values->push_back(std::to_string(value));
        break;
      }
      case 16: {  // blr_int64
        std::uint32_t hi = 0;
        std::uint32_t lo = 0;
        if (!ReadXdrU32(fd, &hi) || !ReadXdrU32(fd, &lo)) return false;
        const auto bits = (static_cast<std::uint64_t>(hi) << 32) |
                          static_cast<std::uint64_t>(lo);
        const auto value = static_cast<std::int64_t>(bits);
        trace_args->push_back("int64:" + std::to_string(value));
        values->push_back(std::to_string(value));
        break;
      }
      case 10:  // blr_float
      case 12:  // blr_sql_date
      case 13:  // blr_sql_time
      case 23:  // blr_bool
        if (!ReadFirebirdClassicDiscardU32s(fd, 1)) return false;
        break;
      case 9:   // blr_quad
      case 11:  // blr_d_float
      case 24:  // blr_dec64
      case 27:  // blr_double
      case 35:  // blr_timestamp
      case 45:  // blr_blob_id
      case 28:  // blr_sql_time_tz
      case 30:  // blr_ex_time_tz
        if (!ReadFirebirdClassicDiscardU32s(fd, 2)) return false;
        break;
      case 29:  // blr_timestamp_tz
      case 31:  // blr_ex_timestamp_tz
        if (!ReadFirebirdClassicDiscardU32s(fd, 3)) return false;
        break;
      case 25:  // blr_dec128
      case 26:  // blr_int128
        if (!ReadFirebirdClassicDiscardU32s(fd, 4)) return false;
        break;
      case 14:  // blr_text
      case 15: {  // blr_text2
        std::string text;
        if (!ReadFirebirdClassicFixedOpaqueValue(fd, slot.length, &text)) return false;
        const std::string trimmed = FirebirdTrimRightSpaces(std::move(text));
        trace_args->push_back("text:" + trimmed);
        values->push_back(FirebirdCanonicalStringLiteral(trimmed));
        break;
      }
      case 37:  // blr_varying
      case 38:  // blr_varying2
      case 40:  // blr_cstring
      case 41: {  // blr_cstring2
        std::string text;
        if (!ReadFirebirdClassicCStringArgumentTrace(
                fd, &text, "value_slot_" + std::to_string(slot_index))) {
          return false;
        }
        const std::string trimmed = FirebirdTrimRightSpaces(std::move(text));
        trace_args->push_back("cstring:" + trimmed);
        values->push_back(FirebirdCanonicalStringLiteral(trimmed));
        break;
      }
      case 17:  // blr_blob2
        if (!ReadFirebirdClassicDiscardU32s(fd, 2)) return false;
        break;
      default:
        return false;
    }
  }
  trace_args->push_back("value_payload_slots:" + std::to_string(slots.size()));
  return true;
}

bool ReadFirebirdPackedMessagePayloadValues(
    int fd,
    const std::vector<std::uint8_t>& blr,
    std::uint32_t message_number,
    std::vector<std::string>* trace_args,
    std::vector<std::string>* values) {
  std::vector<FirebirdClassicMessageSlot> slots;
  if (!FirebirdClassicMessageSlots(blr, message_number, &slots)) return false;
  std::vector<FirebirdClassicMessageSlot> logical_slots;
  for (std::size_t index = 0; index < slots.size(); ++index) {
    logical_slots.push_back(slots[index]);
    if (index + 1 < slots.size() && slots[index + 1].opcode == 7) {
      ++index;  // Protocol 13 replaces the legacy short null-indicator slot.
    }
  }
  std::string null_bitmap;
  if (!ReadFirebirdClassicFixedOpaqueValue(
          fd, static_cast<std::uint32_t>((logical_slots.size() + 7u) / 8u),
          &null_bitmap)) {
    return false;
  }
  for (std::size_t index = 0; index < logical_slots.size(); ++index) {
    const auto& slot = logical_slots[index];
    const bool is_null = index / 8u < null_bitmap.size() &&
                         (static_cast<unsigned char>(null_bitmap[index / 8u]) &
                          static_cast<unsigned char>(1u << (index & 7u))) != 0;
    TraceFirebirdWorker("packed_value_payload.slot index=" +
                        std::to_string(index) + " opcode=" +
                        std::to_string(slot.opcode) + " null=" +
                        (is_null ? "true" : "false"));
    if (is_null) {
      values->push_back("NULL");
      trace_args->push_back("null");
      continue;
    }
    switch (slot.opcode) {
      case 7: {
        std::int16_t value = 0;
        if (!ReadFirebirdClassicShortArgument(fd, &value)) return false;
        values->push_back(std::to_string(value));
        trace_args->push_back("short:" + std::to_string(value));
        break;
      }
      case 8: {
        std::uint32_t raw = 0;
        if (!ReadXdrU32(fd, &raw)) return false;
        const auto value = static_cast<std::int32_t>(raw);
        values->push_back(std::to_string(value));
        trace_args->push_back("long:" + std::to_string(value));
        break;
      }
      case 16: {
        std::uint32_t hi = 0;
        std::uint32_t lo = 0;
        if (!ReadXdrU32(fd, &hi) || !ReadXdrU32(fd, &lo)) return false;
        const auto bits = (static_cast<std::uint64_t>(hi) << 32) |
                          static_cast<std::uint64_t>(lo);
        const auto value = static_cast<std::int64_t>(bits);
        values->push_back(std::to_string(value));
        trace_args->push_back("int64:" + std::to_string(value));
        break;
      }
      case 14:
      case 15: {
        std::string text;
        if (!ReadFirebirdClassicFixedOpaqueValue(fd, slot.length, &text)) return false;
        text = FirebirdTrimRightSpaces(std::move(text));
        values->push_back(FirebirdCanonicalStringLiteral(text));
        trace_args->push_back("text:" + text);
        break;
      }
      case 37:
      case 38:
      case 40:
      case 41: {
        std::string text;
        if (!ReadFirebirdClassicCStringArgumentTrace(
                fd, &text, "packed_value_slot_" + std::to_string(index))) {
          return false;
        }
        text = FirebirdTrimRightSpaces(std::move(text));
        values->push_back(FirebirdCanonicalStringLiteral(text));
        trace_args->push_back("cstring:" + text);
        break;
      }
      case 10:
      case 12:
      case 13:
      case 23:
        if (!ReadFirebirdClassicDiscardU32s(fd, 1)) return false;
        values->push_back("0");
        trace_args->push_back("scalar:0");
        break;
      case 9:
      case 11:
      case 17:
      case 24:
      case 27:
      case 28:
      case 30:
      case 35:
      case 45:
        if (!ReadFirebirdClassicDiscardU32s(fd, 2)) return false;
        values->push_back("0");
        trace_args->push_back("wide_scalar:0");
        break;
      case 29:
      case 31:
        if (!ReadFirebirdClassicDiscardU32s(fd, 3)) return false;
        values->push_back("0");
        trace_args->push_back("triple_scalar:0");
        break;
      case 25:
      case 26:
        if (!ReadFirebirdClassicDiscardU32s(fd, 4)) return false;
        values->push_back("0");
        trace_args->push_back("quad_scalar:0");
        break;
      default:
        return false;
    }
  }
  trace_args->push_back("packed_value_payload_slots:" +
                        std::to_string(logical_slots.size()));
  return true;
}

bool ReadFirebirdExecImmediate2Body(int fd, FirebirdPrepareStatementRequest* request) {
  std::vector<std::uint8_t> input_blr;
  std::vector<std::uint8_t> output_blr;
  std::uint32_t input_message_number = 0;
  std::uint32_t input_message_count = 0;
  std::uint32_t output_message_number = 0;
  if (!ReadXdrString(fd, &input_blr) ||
      !ReadXdrU32(fd, &input_message_number) ||
      !ReadXdrU32(fd, &input_message_count)) {
    return false;
  }
  input_message_number &= 0xffffu;
  input_message_count &= 0xffffu;
  if (input_message_count != 0) {
    std::vector<std::string> trace_args;
    for (std::uint32_t i = 0; i < input_message_count; ++i) {
      if (!ReadFirebirdClassicMessagePayload(
              fd, input_blr, input_message_number, &trace_args)) {
        return false;
      }
    }
    TraceFirebirdWorker("op_exec_immediate2.input_payload_count=" +
                        std::to_string(input_message_count) +
                        " trace_items=" + std::to_string(trace_args.size()));
  }
  if (!ReadXdrString(fd, &output_blr) ||
      !ReadXdrU32(fd, &output_message_number)) {
    return false;
  }
  output_message_number &= 0xffffu;
  TraceFirebirdWorker("op_exec_immediate2.envelope in_blr_len=" +
                      std::to_string(input_blr.size()) +
                      " in_message=" + std::to_string(input_message_number) +
                      " in_count=" + std::to_string(input_message_count) +
                      " out_blr_len=" + std::to_string(output_blr.size()) +
                      " out_message=" + std::to_string(output_message_number));
  if (!ReadFirebirdPrepareStatementBody(fd, request)) return false;
  request->exec_immediate2_out_blr = std::move(output_blr);
  request->exec_immediate2_out_message_number = output_message_number;
  return true;
}

std::string FirebirdTrimRightSpaces(std::string value) {
  while (!value.empty() && value.back() == ' ') value.pop_back();
  return value;
}

bool WriteFirebirdShortFlagBatch(int fd,
                                 const FirebirdClassicDataRequest& request,
                                 FirebirdRemoteHandle* classic_request,
                                 std::size_t row_count,
                                 bool piggyback,
                                 std::string_view trace_name) {
  if (piggyback) {
    if (!WritePacket(fd, FirebirdPiggybackResponsePacket(
                             request.message_number, FirebirdStatusVector(0)))) {
      return false;
    }
  }

  // Firebird's generated FOR-loop receives a short row/EOF flag.  The
  // protocol's p_data_messages=0 marks the final buffered row for this
  // receive call; it is not a standalone EOF packet.  When there are no rows
  // left, return a flag-0 payload as the final packet.
  bool emitted_row = false;
  while (classic_request->next_row_index < row_count) {
    const bool last_row = classic_request->next_row_index + 1 == row_count;
    if (!WritePacket(fd, FirebirdClassicShortRowPacket(
                             request, 1, last_row ? 0 : 1))) {
      return false;
    }
    ++classic_request->next_row_index;
    emitted_row = true;
    if (last_row) break;
  }
  if (!emitted_row && classic_request->next_row_index == row_count) {
    if (!WritePacket(fd, FirebirdClassicShortRowPacket(request, 0, 0))) {
      return false;
    }
    ++classic_request->next_row_index;
  } else if (classic_request->next_row_index > row_count &&
      !WritePacket(fd, FirebirdClassicShortRowPacket(request, 0, 0))) {
    return false;
  }
  TraceFirebirdWorker(std::string("classic_request.") + std::string(trace_name) +
                      ".rows=" + std::to_string(row_count) + " eof_sent=true");
  return true;
}

std::vector<std::uint8_t> FirebirdClassicRelationRowPacket(
    const FirebirdClassicDataRequest& request,
    const std::vector<FirebirdClassicMessageSlot>& slots,
    std::string_view relation_name,
    std::uint32_t message_count = 1) {
  auto out = FirebirdClassicRequestSendPacket(request, message_count);
  if (slots.size() != 7 ||
      !(slots[0].opcode == 9 || slots[0].opcode == 45) ||
      !(slots[1].opcode == 40 || slots[1].opcode == 41) ||
      slots[2].opcode != 7 || slots[3].opcode != 7 ||
      slots[4].opcode != 7 || slots[5].opcode != 7 ||
      slots[6].opcode != 23) {
    return {};
  }
  AppendXdrU32(&out, 0);  // RDB$VIEW_BLR blob high.
  AppendXdrU32(&out, 0);  // RDB$VIEW_BLR blob low.
  AppendXdrClassicCString(&out, {}, slots[1].length == 0 ? 253 : slots[1].length);
  AppendXdrU32(&out, 1);  // generated row-present flag.
  AppendXdrU32(&out, 1);  // RDB$VIEW_BLR null flag.
  AppendXdrU32(&out, 1);  // RDB$EXTERNAL_FILE null flag.
  AppendXdrU32(&out, 1);  // RDB$SQL_SECURITY null flag.
  AppendXdrU32(&out, 0);  // RDB$SQL_SECURITY value carrier.
  return out;
}

std::int16_t FirebirdRdbFieldTypeFromSqlType(const FirebirdColumnDescriptor& column) {
  switch (column.sql_type) {
    case 452:
      return 37;   // blr_varying
    case 480:
      return 27;   // blr_double
    case 482:
      return 10;   // blr_float
    case 510:
      return 35;   // blr_timestamp
    case 520:
      return 261;  // blr_blob
    case 560:
      return 13;   // blr_sql_time
    case 570:
      return 12;   // blr_sql_date
    case 580:
      return 16;   // blr_int64
    case 500:
      return 7;    // blr_short
    case 496:
    default:
      return 8;    // blr_long
  }
}

std::vector<std::uint8_t> FirebirdClassicShowTableFieldRowPacket(
    const FirebirdClassicDataRequest& request,
    const std::vector<FirebirdClassicMessageSlot>& slots,
    const FirebirdColumnDescriptor& column,
    std::size_t ordinal,
    std::optional<std::uint32_t> computed_source_blob,
    std::uint32_t message_count = 1) {
  auto out = FirebirdClassicRequestSendPacket(request, message_count);
  if (slots.size() != 28) return {};
  auto append_short = [&](std::int32_t value) {
    AppendXdrU32(&out, static_cast<std::uint32_t>(value));
  };
  auto append_blob = [&](std::uint32_t low) {
    AppendXdrU32(&out, low == 0 ? 0u : 0x80u);
    AppendXdrU32(&out, low);
  };

  append_blob(0);                                      // RDB$VALIDATION_SOURCE
  append_blob(0);                                      // RFR.RDB$DEFAULT_SOURCE
  append_blob(0);                                      // FLD.RDB$DEFAULT_SOURCE
  append_blob(computed_source_blob.value_or(0));       // RDB$COMPUTED_SOURCE
  append_blob(computed_source_blob ? computed_source_blob.value() : 0);  // COMPUTED_BLR
  append_short(1);                                     // generated row-present flag
  append_short(1);                                     // validation source null
  append_short(1);                                     // relation default null
  append_short(1);                                     // field default null
  append_short(0);                                     // identity type carrier
  append_short(1);                                     // generator name null
  append_short(1);                                     // base field null
  append_short(column.nullable ? 0 : 1);               // RFR.RDB$NULL_FLAG
  append_short(0);                                     // FLD.RDB$NULL_FLAG
  append_short(0);                                     // segment length
  append_short(column.scale);                          // field scale
  append_short(0);                                     // field precision
  append_short(column.subtype);                        // field subtype
  append_short(FirebirdRdbFieldTypeFromSqlType(column));
  append_short(computed_source_blob ? 0 : 1);          // computed source null
  append_short(computed_source_blob ? 0 : 1);          // computed BLR null
  append_short(column.is_array ? 0 : 1);               // dimensions null
  append_short(column.is_array ? 1 : 0);               // dimensions
  append_short(0);                                     // system flag
  AppendXdrClassicCString(&out, UpperIdentifier(column.name), slots[24].length);
  AppendXdrClassicCString(&out, "RDB$" + std::to_string(ordinal + 1),
                          slots[25].length);
  AppendXdrClassicCString(&out, {}, slots[26].length);
  AppendXdrClassicCString(&out, {}, slots[27].length);
  return out;
}

std::vector<std::uint8_t> FirebirdClassicRelationConstraintRowPacket(
    const FirebirdClassicDataRequest& request,
    const std::vector<FirebirdClassicMessageSlot>& slots,
    const FirebirdRelationConstraintDescriptor& constraint,
    std::uint32_t message_count = 1) {
  auto out = FirebirdClassicRequestSendPacket(request, message_count);
  if (slots.size() != 4 ||
      !(slots[0].opcode == 40 || slots[0].opcode == 41) ||
      slots[1].opcode != 7 ||
      !(slots[2].opcode == 40 || slots[2].opcode == 41) ||
      !(slots[3].opcode == 40 || slots[3].opcode == 41)) {
    return {};
  }
  AppendXdrClassicCString(&out, constraint.constraint_type,
                          slots[0].length == 0 ? 12 : slots[0].length);
  AppendXdrU32(&out, 1);  // generated FOR-loop row-present flag.
  AppendXdrClassicCString(&out, constraint.constraint_name,
                          slots[2].length == 0 ? 253 : slots[2].length);
  AppendXdrClassicCString(&out, constraint.index_name,
                          slots[3].length == 0 ? 253 : slots[3].length);
  return out;
}

bool WriteFirebirdRelationConstraintsBatch(
    int fd,
    FirebirdBinarySessionState* state,
    const FirebirdClassicDataRequest& request,
    FirebirdRemoteHandle* classic_request,
    std::string_view relation_name,
    bool piggyback,
    std::string_view trace_name) {
  std::vector<FirebirdClassicMessageSlot> slots;
  if (!FirebirdClassicMessageSlots(classic_request->data, request.message_number, &slots)) {
    return false;
  }
  const auto constraints = FirebirdRelationConstraints(*state, relation_name);
  if (piggyback) {
    if (!WritePacket(fd, FirebirdPiggybackResponsePacket(
                             request.message_number, FirebirdStatusVector(0)))) {
      return false;
    }
  }
  bool emitted_row = false;
  while (classic_request->next_row_index < constraints.size()) {
    const auto row_index = classic_request->next_row_index;
    const bool last_row = row_index + 1 >= constraints.size();
    const auto row_packet = FirebirdClassicRelationConstraintRowPacket(
        request, slots, constraints[row_index], last_row ? 0 : 1);
    if (row_packet.empty() || !WritePacket(fd, row_packet)) return false;
    ++classic_request->next_row_index;
    emitted_row = true;
    TraceFirebirdWorker(std::string("classic_request.") + std::string(trace_name) +
                        ".row=" + std::to_string(row_index) +
                        " constraint=" + constraints[row_index].constraint_name);
    if (last_row) break;
  }
  if (!emitted_row) {
    const auto zero_message =
        FirebirdClassicZeroMessagePacket(request, classic_request->data, 0);
    if (zero_message.empty() || !WritePacket(fd, zero_message)) return false;
    ++classic_request->next_row_index;
    TraceFirebirdWorker(std::string("classic_request.") + std::string(trace_name) +
                        ".eof=true");
  }
  return true;
}

std::vector<std::uint8_t> FirebirdClassicIndexByNameRowPacket(
    const FirebirdClassicDataRequest& request,
    const std::vector<FirebirdClassicMessageSlot>& slots,
    std::string_view index_name,
    std::uint32_t message_count = 1) {
  auto out = FirebirdClassicRequestSendPacket(request, message_count);
  if (slots.size() != 4 ||
      slots[0].opcode != 7 || slots[1].opcode != 7 ||
      slots[2].opcode != 7 ||
      !(slots[3].opcode == 40 || slots[3].opcode == 41)) {
    return {};
  }
  AppendXdrU32(&out, 1);  // generated FOR-loop row-present flag.
  AppendXdrU32(&out, 1);  // RDB$INDEX_TYPE null flag: ordinary ascending index.
  AppendXdrU32(&out, 0);  // RDB$INDEX_TYPE value carrier.
  AppendXdrClassicCString(&out, UpperIdentifier(index_name),
                          slots[3].length == 0 ? 253 : slots[3].length);
  return out;
}

bool WriteFirebirdIndexByNameBatch(int fd,
                                   FirebirdBinarySessionState* state,
                                   const FirebirdClassicDataRequest& request,
                                   FirebirdRemoteHandle* classic_request,
                                   std::string_view index_name,
                                   bool piggyback,
                                   std::string_view trace_name) {
  std::vector<FirebirdClassicMessageSlot> slots;
  if (!FirebirdClassicMessageSlots(classic_request->data, request.message_number, &slots)) {
    return false;
  }
  const bool exists = FirebirdIndexByName(*state, index_name).has_value();
  if (piggyback) {
    if (!WritePacket(fd, FirebirdPiggybackResponsePacket(
                             request.message_number, FirebirdStatusVector(0)))) {
      return false;
    }
  }
  if (!exists) {
    const auto zero_message =
        FirebirdClassicZeroMessagePacket(request, classic_request->data, 0);
    if (zero_message.empty() || !WritePacket(fd, zero_message)) return false;
    ++classic_request->next_row_index;
    TraceFirebirdWorker(std::string("classic_request.") + std::string(trace_name) +
                        ".rows=0 eof_sent=true");
    return true;
  }
  if (classic_request->next_row_index == 0) {
    const auto row_packet = FirebirdClassicIndexByNameRowPacket(
        request, slots, index_name, 0);
    if (row_packet.empty() || !WritePacket(fd, row_packet)) return false;
    ++classic_request->next_row_index;
  } else {
    const auto zero_message =
        FirebirdClassicZeroMessagePacket(request, classic_request->data, 0);
    if (zero_message.empty() || !WritePacket(fd, zero_message)) return false;
    ++classic_request->next_row_index;
  }
  TraceFirebirdWorker(std::string("classic_request.") + std::string(trace_name) +
                      ".rows=1 eof_sent=true");
  return true;
}

bool WriteFirebirdShowTableFieldsBatch(int fd,
                                       FirebirdBinarySessionState* state,
                                       const FirebirdClassicDataRequest& request,
                                       FirebirdRemoteHandle* classic_request,
                                       std::string_view relation_name,
                                       bool piggyback,
                                       std::string_view trace_name) {
  std::vector<FirebirdClassicMessageSlot> slots;
  if (!FirebirdClassicMessageSlots(classic_request->data, request.message_number, &slots)) {
    return false;
  }
  const auto table = FirebirdTableByName(*state, relation_name);
  const std::vector<FirebirdColumnDescriptor> columns =
      table ? table->columns : std::vector<FirebirdColumnDescriptor>{};
  if (piggyback) {
    if (!WritePacket(fd, FirebirdPiggybackResponsePacket(
                             request.message_number, FirebirdStatusVector(0)))) {
      return false;
    }
  }
  bool emitted_row = false;
  while (classic_request->next_row_index < columns.size()) {
    const auto row_index = classic_request->next_row_index;
    const auto& column = columns[row_index];
    std::optional<std::uint32_t> computed_blob;
    if (!column.computed_expression.empty()) {
      computed_blob = RegisterFirebirdBlobValue(
          state, relation_name, column.name,
          "(" + TrimAscii(column.computed_expression) + ")");
    }
    const bool last_row = row_index + 1 >= columns.size();
    const auto row_packet = FirebirdClassicShowTableFieldRowPacket(
        request, slots, column, row_index, computed_blob, last_row ? 0 : 1);
    if (row_packet.empty() || !WritePacket(fd, row_packet)) return false;
    ++classic_request->next_row_index;
    emitted_row = true;
    TraceFirebirdWorker(std::string("classic_request.") + std::string(trace_name) +
                        ".row=" + std::to_string(row_index));
    if (last_row) break;
  }
  if (!emitted_row) {
    const auto zero_message =
        FirebirdClassicZeroMessagePacket(request, classic_request->data, 0);
    if (zero_message.empty() || !WritePacket(fd, zero_message)) return false;
    ++classic_request->next_row_index;
    TraceFirebirdWorker(std::string("classic_request.") + std::string(trace_name) +
                        ".eof=true");
  }
  return true;
}

bool WriteFirebirdRelationExistsBatch(int fd,
                                      const FirebirdClassicDataRequest& request,
                                      FirebirdRemoteHandle* classic_request,
                                      bool relation_exists,
                                      std::string_view relation_name,
                                      bool piggyback,
                                      std::string_view trace_name) {
  std::vector<FirebirdClassicMessageSlot> slots;
  if (!FirebirdClassicMessageSlots(classic_request->data, request.message_number, &slots)) {
    return false;
  }
  if (slots.size() == 1 && slots[0].opcode == 7) {
    return WriteFirebirdShortFlagBatch(
        fd, request, classic_request, relation_exists ? 1 : 0, piggyback, trace_name);
  }
  if (piggyback) {
    if (!WritePacket(fd, FirebirdPiggybackResponsePacket(
                             request.message_number, FirebirdStatusVector(0)))) {
      return false;
    }
  }
  if (!relation_exists) {
    const auto zero_message =
        FirebirdClassicZeroMessagePacket(request, classic_request->data, 0);
    if (zero_message.empty() || !WritePacket(fd, zero_message)) return false;
    TraceFirebirdWorker(std::string("classic_request.") + std::string(trace_name) +
                        ".rows=0 eof_sent=true");
    return true;
  }
  if (classic_request->next_row_index == 0) {
    const auto row_packet = FirebirdClassicRelationRowPacket(
        request, slots, relation_name, 0);
    if (row_packet.empty() || !WritePacket(fd, row_packet)) return false;
    ++classic_request->next_row_index;
  } else {
    const auto zero_message =
        FirebirdClassicZeroMessagePacket(request, classic_request->data, 0);
    if (zero_message.empty() || !WritePacket(fd, zero_message)) return false;
    ++classic_request->next_row_index;
  }
  TraceFirebirdWorker(std::string("classic_request.") + std::string(trace_name) +
                      ".rows=1 eof_sent=true");
  return true;
}

bool WriteFirebirdRuntimeOdsProbeBatch(int fd,
                                       const FirebirdClassicDataRequest& request,
                                       FirebirdRemoteHandle* classic_request,
                                       bool piggyback) {
  return WriteFirebirdShortFlagBatch(
      fd, request, classic_request, 2, piggyback, "runtime_ods_system_flag_probe");
}

bool WriteFirebirdClassicZeroReceiveMessage(
    int fd,
    const FirebirdClassicDataRequest& request,
    const std::vector<std::uint8_t>& blr,
    std::string_view trace_name,
    bool piggyback = false) {
  if (piggyback &&
      !WritePacket(fd, FirebirdPiggybackResponsePacket(
                           request.message_number, FirebirdStatusVector(0)))) {
    return false;
  }
  auto zero_message = FirebirdClassicZeroMessagePacket(request, blr, 0);
  if (zero_message.empty()) {
    return false;
  }
  TraceFirebirdWorker(std::string("classic_request.") + std::string(trace_name) +
                      ".zero_message_number=" +
                      std::to_string(request.message_number));
  return WritePacket(fd, zero_message);
}

bool WriteFirebirdShortCStringBatch(int fd,
                                    const FirebirdClassicDataRequest& request,
                                    FirebirdRemoteHandle* classic_request,
                                    const std::vector<std::string>& values,
                                    bool piggyback,
                                    std::string_view trace_name) {
  if (piggyback) {
    if (!WritePacket(fd, FirebirdPiggybackResponsePacket(
                             request.message_number, FirebirdStatusVector(0)))) {
      return false;
    }
  }

  bool emitted_row = false;
  while (classic_request->next_row_index < values.size()) {
    const bool last_row = classic_request->next_row_index + 1 == values.size();
    if (!WritePacket(fd, FirebirdClassicShortCStringRowPacket(
                             request, 1, values[classic_request->next_row_index],
                             last_row ? 0 : 1))) {
      return false;
    }
    ++classic_request->next_row_index;
    emitted_row = true;
    if (last_row) break;
  }
  if (!emitted_row && classic_request->next_row_index == values.size()) {
    if (!WritePacket(fd, FirebirdClassicShortCStringRowPacket(request, 0, {}, 0))) {
      return false;
    }
    ++classic_request->next_row_index;
  } else if (classic_request->next_row_index > values.size() &&
             !WritePacket(fd, FirebirdClassicShortCStringRowPacket(request, 0, {}, 0))) {
    return false;
  }

  TraceFirebirdWorker(std::string("classic_request.") + std::string(trace_name) +
                      ".rows=" + std::to_string(values.size()) + " eof_sent=true");
  return true;
}

std::vector<std::uint8_t> FirebirdClassicSystemFunctionNameRowPacket(
    const FirebirdClassicDataRequest& request,
    const std::vector<FirebirdClassicMessageSlot>& slots,
    std::string_view qualified_name,
    std::uint32_t message_count = 1) {
  if (slots.size() != 6 || slots[0].opcode != 7 ||
      slots[1].opcode != 7 || slots[2].opcode != 7 ||
      slots[3].opcode != 7 || slots[4].opcode != 40 ||
      slots[4].length != 253 || slots[5].opcode != 40 ||
      slots[5].length != 253) {
    return {};
  }
  const auto separator = qualified_name.rfind('.');
  if (separator == std::string_view::npos || separator == 0 ||
      separator + 1 == qualified_name.size()) {
    return {};
  }
  const auto package_name = qualified_name.substr(0, separator);
  const auto function_name = qualified_name.substr(separator + 1);
  auto out = FirebirdClassicRequestSendPacket(request, message_count);
  AppendXdrU32(&out, 1);  // Generated FOR-loop row-present flag.
  AppendXdrU32(&out, 0);  // RDB$PACKAGE_NAME null flag.
  AppendXdrU32(&out, 0);  // RDB$VALID_BLR null flag.
  AppendXdrU32(&out, 1);  // RDB$VALID_BLR.
  AppendXdrClassicCString(&out, package_name, slots[4].length);
  AppendXdrClassicCString(&out, function_name, slots[5].length);
  return out;
}

bool WriteFirebirdSystemFunctionNameRowsBatch(
    int fd,
    const FirebirdClassicDataRequest& request,
    FirebirdRemoteHandle* classic_request,
    const std::vector<std::string>& rows,
    bool piggyback,
    std::string_view trace_name) {
  if (piggyback &&
      !WritePacket(fd, FirebirdPiggybackResponsePacket(
                           request.message_number, FirebirdStatusVector(0)))) {
    return false;
  }
  std::vector<FirebirdClassicMessageSlot> slots;
  if (!FirebirdClassicMessageSlots(classic_request->data,
                                   request.message_number, &slots)) {
    return false;
  }
  bool emitted_row = false;
  while (classic_request->next_row_index < rows.size()) {
    const auto row_index = classic_request->next_row_index;
    const bool last_row = row_index + 1 == rows.size();
    const auto packet = FirebirdClassicSystemFunctionNameRowPacket(
        request, slots, rows[row_index], last_row ? 0 : 1);
    if (packet.empty() || !WritePacket(fd, packet)) return false;
    emitted_row = true;
    TraceFirebirdWorker(std::string("classic_request.") +
                        std::string(trace_name) + ".row=" +
                        std::to_string(row_index) + " function=" +
                        EscapeJsonLocal(rows[row_index]));
    ++classic_request->next_row_index;
    if (last_row) break;
  }
  if (!emitted_row && classic_request->next_row_index == rows.size()) {
    const auto zero_message =
        FirebirdClassicZeroMessagePacket(request, classic_request->data, 0);
    if (zero_message.empty() || !WritePacket(fd, zero_message)) return false;
    ++classic_request->next_row_index;
  } else if (classic_request->next_row_index > rows.size()) {
    const auto zero_message =
        FirebirdClassicZeroMessagePacket(request, classic_request->data, 0);
    if (zero_message.empty() || !WritePacket(fd, zero_message)) return false;
  }
  TraceFirebirdWorker(std::string("classic_request.") +
                      std::string(trace_name) + ".rows=" +
                      std::to_string(rows.size()) + " eof_sent=true");
  return true;
}

bool WriteFirebirdDatabaseCharsetBatch(
    int fd,
    const FirebirdClassicDataRequest& request,
    FirebirdRemoteHandle* classic_request,
    std::string_view charset_name,
    std::string_view default_collation,
    bool piggyback,
    std::string_view trace_name) {
  std::vector<FirebirdClassicMessageSlot> slots;
  if (!FirebirdClassicMessageSlots(
          classic_request->data, request.message_number, &slots) ||
      slots.size() != 4 || slots[0].opcode != 7 || slots[1].opcode != 7 ||
      !(slots[2].opcode == 40 || slots[2].opcode == 41) ||
      !(slots[3].opcode == 40 || slots[3].opcode == 41)) {
    return false;
  }
  if (piggyback &&
      !WritePacket(fd, FirebirdPiggybackResponsePacket(
                           request.message_number, FirebirdStatusVector(0)))) {
    return false;
  }
  const bool row_present = classic_request->next_row_index == 0;
  const auto packet = FirebirdClassicDatabaseCharsetRowPacket(
      request, slots[2].length, slots[3].length, row_present,
      charset_name, default_collation, 0);
  if (packet.empty() || !WritePacket(fd, packet)) return false;
  ++classic_request->next_row_index;
  TraceFirebirdWorker(std::string("classic_request.") + std::string(trace_name) +
                      ".rows=1 eof_sent=true message_slots=4 row_present=" +
                      (row_present ? "true" : "false"));
  return true;
}

std::vector<std::string> FirebirdUserDomainNames(
    const FirebirdBinarySessionState& state) {
  std::vector<std::string> names;
  names.reserve(state.domains.size());
  for (const auto& [name, domain] : state.domains) {
    (void)name;
    if (!FirebirdCatalogObjectScopeMatches(state, "domain", domain.name)) {
      continue;
    }
    names.push_back(UpperIdentifier(domain.name));
  }
  std::sort(names.begin(), names.end());
  return names;
}

std::vector<FirebirdExceptionDescriptor> FirebirdUserExceptions(
    const FirebirdBinarySessionState& state) {
  std::vector<FirebirdExceptionDescriptor> rows;
  rows.reserve(state.exceptions.size());
  for (const auto& [name, exception] : state.exceptions) {
    (void)name;
    if (!FirebirdCatalogObjectScopeMatches(state, "exception", exception.name)) {
      continue;
    }
    rows.push_back(exception);
  }
  std::sort(rows.begin(), rows.end(),
            [](const FirebirdExceptionDescriptor& left,
               const FirebirdExceptionDescriptor& right) {
              return UpperIdentifier(left.name) < UpperIdentifier(right.name);
            });
  return rows;
}

std::vector<std::uint8_t> FirebirdClassicExceptionRowPacket(
    const FirebirdClassicDataRequest& request,
    const std::vector<FirebirdClassicMessageSlot>& slots,
    const FirebirdExceptionDescriptor& exception,
    std::uint32_t message_count = 1) {
  if (slots.size() != 4 ||
      !(slots[0].opcode == 40 || slots[0].opcode == 41) ||
      slots[1].opcode != 7 || slots[2].opcode != 7 ||
      !(slots[3].opcode == 40 || slots[3].opcode == 41)) {
    return {};
  }
  auto out = FirebirdClassicRequestSendPacket(request, message_count);
  AppendXdrClassicCString(&out, exception.message,
                          slots[0].length == 0 ? 1024 : slots[0].length);
  AppendXdrU32(&out, 1);  // Generated FOR-loop row-present flag.
  AppendXdrU32(&out, exception.message.empty() ? 1u : 0u);
  AppendXdrClassicCString(&out, UpperIdentifier(exception.name),
                          slots[3].length == 0 ? 253 : slots[3].length);
  return out;
}

