std::vector<FirebirdTriggerDescriptor> FirebirdUserTriggers(
    const FirebirdBinarySessionState& state,
    bool relation_triggers) {
  std::vector<FirebirdTriggerDescriptor> rows;
  rows.reserve(state.triggers.size());
  for (const auto& [name, trigger] : state.triggers) {
    (void)name;
    if (!FirebirdCatalogObjectScopeMatches(state, "trigger", trigger.name)) {
      continue;
    }
    const bool has_relation = !TrimAscii(trigger.relation).empty();
    if (has_relation != relation_triggers) continue;
    rows.push_back(trigger);
  }
  std::sort(rows.begin(), rows.end(),
            [relation_triggers](const FirebirdTriggerDescriptor& left,
                                const FirebirdTriggerDescriptor& right) {
              if (relation_triggers) {
                const auto left_relation = UpperIdentifier(left.relation);
                const auto right_relation = UpperIdentifier(right.relation);
                if (left_relation != right_relation) {
                  return left_relation < right_relation;
                }
              }
              return UpperIdentifier(left.name) < UpperIdentifier(right.name);
            });
  return rows;
}

std::vector<std::uint8_t> FirebirdClassicTriggerRowPacket(
    const FirebirdClassicDataRequest& request,
    const std::vector<FirebirdClassicMessageSlot>& slots,
    const FirebirdTriggerDescriptor& trigger,
    std::uint32_t message_count = 1) {
  auto out = FirebirdClassicRequestSendPacket(request, message_count);
  if (slots.size() == 5 &&
      slots[0].opcode == 7 && slots[1].opcode == 7 &&
      slots[2].opcode == 7 && slots[3].opcode == 7 &&
      (slots[4].opcode == 40 || slots[4].opcode == 41)) {
    AppendXdrU32(&out, 1);  // generated FOR-loop row-present flag.
    AppendXdrU32(&out, 0);  // RDB$VALID_BLR null flag.
    AppendXdrU32(&out, 1);  // RDB$VALID_BLR.
    AppendXdrU32(&out, 0);  // RDB$SYSTEM_FLAG.
    AppendXdrClassicCString(&out, UpperIdentifier(trigger.name),
                            slots[4].length == 0 ? 253 : slots[4].length);
    return out;
  }
  if (slots.size() == 7 &&
      slots[0].opcode == 7 && slots[1].opcode == 7 &&
      slots[2].opcode == 7 && slots[3].opcode == 7 &&
      slots[4].opcode == 7 &&
      (slots[5].opcode == 40 || slots[5].opcode == 41) &&
      (slots[6].opcode == 40 || slots[6].opcode == 41)) {
    AppendXdrU32(&out, 1);  // generated FOR-loop row-present flag.
    AppendXdrU32(&out, 0);  // RDB$VALID_BLR null flag.
    AppendXdrU32(&out, 1);  // RDB$VALID_BLR.
    AppendXdrU32(&out, 0);  // RDB$SYSTEM_FLAG.
    AppendXdrU32(&out, trigger.relation.empty() ? 1u : 0u);
    AppendXdrClassicCString(&out, UpperIdentifier(trigger.name),
                            slots[5].length == 0 ? 253 : slots[5].length);
    AppendXdrClassicCString(&out, UpperIdentifier(trigger.relation),
                            slots[6].length == 0 ? 253 : slots[6].length);
    return out;
  }
  return {};
}

