std::vector<FirebirdProcedureDescriptor> FirebirdUserProcedures(
    const FirebirdBinarySessionState& state) {
  std::vector<FirebirdProcedureDescriptor> rows;
  rows.reserve(state.procedures.size());
  for (const auto& [name, procedure] : state.procedures) {
    (void)name;
    if (!FirebirdCatalogObjectScopeMatches(state, "procedure", procedure.name)) {
      continue;
    }
    rows.push_back(procedure);
  }
  std::sort(rows.begin(), rows.end(),
            [](const FirebirdProcedureDescriptor& left,
               const FirebirdProcedureDescriptor& right) {
              return UpperIdentifier(left.name) < UpperIdentifier(right.name);
            });
  return rows;
}

std::string FirebirdProcedureCatalogSource(
    const FirebirdProcedureDescriptor& procedure) {
  const auto as_pos = FindTopLevelFirebirdWord(procedure.body, "AS", 0);
  if (!as_pos) return TrimAscii(procedure.body);
  return TrimAscii(procedure.body.substr(*as_pos + std::string_view("AS").size()));
}

std::vector<std::uint8_t> FirebirdClassicProcedureDetailRowPacket(
    const FirebirdClassicDataRequest& request,
    const std::vector<FirebirdClassicMessageSlot>& slots,
    const FirebirdProcedureDescriptor& procedure,
    std::uint32_t source_blob_id_low,
    std::uint32_t message_count = 1) {
  if (slots.size() != 10 ||
      !(slots[0].opcode == 9 || slots[0].opcode == 45) ||
      !(slots[1].opcode == 40 || slots[1].opcode == 41) ||
      slots[2].opcode != 7 || slots[3].opcode != 7 ||
      slots[4].opcode != 7 || slots[5].opcode != 7 ||
      slots[6].opcode != 7 || slots[7].opcode != 23 ||
      !(slots[8].opcode == 40 || slots[8].opcode == 41) ||
      !(slots[9].opcode == 40 || slots[9].opcode == 41)) {
    return {};
  }
  auto out = FirebirdClassicRequestSendPacket(request, message_count);
  AppendXdrU32(&out, source_blob_id_low == 0 ? 0u : 0x80u);
  AppendXdrU32(&out, source_blob_id_low);
  AppendXdrClassicCString(&out, {}, slots[1].length == 0 ? 256 : slots[1].length);
  AppendXdrU32(&out, 1);                              // generated row-present flag.
  AppendXdrU32(&out, source_blob_id_low == 0 ? 1u : 0u);  // source null flag.
  AppendXdrU32(&out, 1);                              // engine name null flag.
  AppendXdrU32(&out, 1);                              // SQL SECURITY null flag.
  AppendXdrU32(&out, 1);                              // entrypoint null flag.
  AppendXdrU32(&out, 0);                              // SQL SECURITY carrier.
  AppendXdrClassicCString(&out, {},
                          slots[8].length == 0 ? 253 : slots[8].length);
  AppendXdrClassicCString(&out, UpperIdentifier(procedure.name),
                          slots[9].length == 0 ? 253 : slots[9].length);
  return out;
}

bool WriteFirebirdProcedureDetailBatch(
    int fd,
    FirebirdBinarySessionState* state,
    const FirebirdClassicDataRequest& request,
    FirebirdRemoteHandle* classic_request,
    const FirebirdProcedureDescriptor* procedure,
    bool piggyback,
    std::string_view trace_name) {
  if (piggyback &&
      !WritePacket(fd, FirebirdPiggybackResponsePacket(
                           request.message_number, FirebirdStatusVector(0)))) {
    return false;
  }
  std::vector<FirebirdClassicMessageSlot> slots;
  if (!FirebirdClassicMessageSlots(classic_request->data, request.message_number,
                                   &slots)) {
    return false;
  }
  const std::size_t row_count = procedure == nullptr ? 0 : 1;
  bool emitted_row = false;
  if (procedure != nullptr && classic_request->next_row_index == 0) {
    const std::string source = FirebirdProcedureCatalogSource(*procedure);
    const std::uint32_t source_blob_id =
        source.empty()
            ? 0
            : RegisterFirebirdBlobValue(state, "RDB$PROCEDURES",
                                        "RDB$PROCEDURE_SOURCE", source);
    const auto packet = FirebirdClassicProcedureDetailRowPacket(
        request, slots, *procedure, source_blob_id, 0);
    if (packet.empty() || !WritePacket(fd, packet)) return false;
    emitted_row = true;
    ++classic_request->next_row_index;
    TraceFirebirdWorker(std::string("classic_request.") +
                        std::string(trace_name) + ".procedure=" +
                        EscapeJsonLocal(procedure->name) +
                        " source_blob_id=" + std::to_string(source_blob_id));
  }
  if (!emitted_row && classic_request->next_row_index == row_count) {
    const auto zero_message =
        FirebirdClassicZeroMessagePacket(request, classic_request->data, 0);
    if (zero_message.empty() || !WritePacket(fd, zero_message)) return false;
    ++classic_request->next_row_index;
  } else if (classic_request->next_row_index > row_count) {
    const auto zero_message =
        FirebirdClassicZeroMessagePacket(request, classic_request->data, 0);
    if (zero_message.empty() || !WritePacket(fd, zero_message)) return false;
  }
  TraceFirebirdWorker(std::string("classic_request.") + std::string(trace_name) +
                      ".rows=" + std::to_string(row_count) +
                      " eof_sent=true");
  return true;
}

struct FirebirdClassicProcedureParameterRow {
  const FirebirdColumnDescriptor* column{nullptr};
  std::int16_t parameter_type{0};
  std::size_t ordinal{0};
};

std::vector<std::uint8_t> FirebirdClassicProcedureParameterRowPacket(
    const FirebirdClassicDataRequest& request,
    const std::vector<FirebirdClassicMessageSlot>& slots,
    const FirebirdClassicProcedureParameterRow& row,
    std::uint32_t message_count = 1) {
  if (row.column == nullptr || slots.size() != 27 ||
      !(slots[0].opcode == 9 || slots[0].opcode == 45) ||
      !(slots[1].opcode == 9 || slots[1].opcode == 45)) {
    return {};
  }
  for (std::size_t index = 2; index <= 22; ++index) {
    if (slots[index].opcode != 7) return {};
  }
  for (std::size_t index = 23; index <= 26; ++index) {
    if (!(slots[index].opcode == 40 || slots[index].opcode == 41)) return {};
  }

  const auto& column = *row.column;
  const bool character_value = column.sql_type == 452;
  const bool have_charset = character_value && !column.character_set.empty();
  const bool have_character_length = character_value && column.character_length != 0;
  const bool have_field_collation = character_value && !column.collation.empty();
  const std::string field_source =
      column.domain_name.empty()
          ? "RDB$" + std::to_string(row.ordinal + 1)
          : UpperIdentifier(column.domain_name);
  auto out = FirebirdClassicRequestSendPacket(request, message_count);
  auto append_short = [&](std::int32_t value) {
    AppendXdrU32(&out, static_cast<std::uint32_t>(value));
  };
  AppendXdrU32(&out, 0);  // FLD.RDB$DEFAULT_SOURCE blob high.
  AppendXdrU32(&out, 0);  // FLD.RDB$DEFAULT_SOURCE blob low.
  AppendXdrU32(&out, 0);  // PRM.RDB$DEFAULT_SOURCE blob high.
  AppendXdrU32(&out, 0);  // PRM.RDB$DEFAULT_SOURCE blob low.
  append_short(1);        // generated row-present flag.
  append_short(1);        // field default source null flag.
  append_short(have_charset ? 0 : 1);
  append_short(have_charset ? FirebirdCharacterSetId(column.character_set) : 0);
  append_short(have_character_length ? 0 : 1);
  append_short(have_character_length ? column.character_length : 0);
  append_short(column.scale);
  append_short(0);  // field precision.
  append_short(column.subtype);
  append_short(FirebirdRdbFieldTypeFromSqlType(column));
  append_short(0);  // field system flag.
  append_short(have_field_collation ? 0 : 1);
  append_short(have_field_collation
                   ? FirebirdCollationId(column.character_set, column.collation)
                   : 0);
  append_short(1);  // PRM.RDB$FIELD_NAME null flag.
  append_short(1);  // PRM.RDB$RELATION_NAME null flag.
  append_short(1);  // PRM.RDB$COLLATION_ID null flag.
  append_short(0);  // PRM.RDB$COLLATION_ID carrier.
  append_short(1);  // PRM.RDB$DEFAULT_SOURCE null flag.
  append_short(0);  // PRM.RDB$PARAMETER_MECHANISM null flag.
  append_short(0);  // normal parameter mechanism.
  append_short(row.parameter_type);
  AppendXdrClassicCString(&out, UpperIdentifier(column.name),
                          slots[23].length == 0 ? 253 : slots[23].length);
  AppendXdrClassicCString(&out, {},
                          slots[24].length == 0 ? 253 : slots[24].length);
  AppendXdrClassicCString(&out, {},
                          slots[25].length == 0 ? 253 : slots[25].length);
  AppendXdrClassicCString(&out, field_source,
                          slots[26].length == 0 ? 253 : slots[26].length);
  return out;
}

bool WriteFirebirdProcedureParameterRowsBatch(
    int fd,
    const FirebirdClassicDataRequest& request,
    FirebirdRemoteHandle* classic_request,
    const FirebirdProcedureDescriptor* procedure,
    bool piggyback,
    std::string_view trace_name) {
  if (piggyback &&
      !WritePacket(fd, FirebirdPiggybackResponsePacket(
                           request.message_number, FirebirdStatusVector(0)))) {
    return false;
  }
  std::vector<FirebirdClassicMessageSlot> slots;
  if (!FirebirdClassicMessageSlots(classic_request->data, request.message_number,
                                   &slots)) {
    return false;
  }
  std::vector<FirebirdClassicProcedureParameterRow> rows;
  if (procedure != nullptr) {
    rows.reserve(procedure->parameters.size() + procedure->returns.size());
    for (const auto& column : procedure->parameters) {
      rows.push_back({&column, 0, rows.size()});
    }
    for (const auto& column : procedure->returns) {
      rows.push_back({&column, 1, rows.size()});
    }
  }
  bool emitted_row = false;
  while (classic_request->next_row_index < rows.size()) {
    const auto row_index = classic_request->next_row_index;
    const bool last_row = row_index + 1 == rows.size();
    const auto packet = FirebirdClassicProcedureParameterRowPacket(
        request, slots, rows[row_index], last_row ? 0 : 1);
    if (packet.empty() || !WritePacket(fd, packet)) return false;
    emitted_row = true;
    TraceFirebirdWorker(std::string("classic_request.") +
                        std::string(trace_name) + ".row=" +
                        std::to_string(row_index) + " parameter=" +
                        EscapeJsonLocal(rows[row_index].column->name) +
                        " parameter_type=" +
                        std::to_string(rows[row_index].parameter_type));
    ++classic_request->next_row_index;
    if (last_row) break;
  }
  if (!emitted_row && classic_request->next_row_index == rows.size()) {
    const auto zero_message =
        FirebirdClassicZeroMessagePacket(request, classic_request->data, 0);
    if (zero_message.empty() || !WritePacket(fd, zero_message)) return false;
    ++classic_request->next_row_index;
  } else if (classic_request->next_row_index > rows.size()) {
    const auto zero_message =
        FirebirdClassicZeroMessagePacket(request, classic_request->data, 0);
    if (zero_message.empty() || !WritePacket(fd, zero_message)) return false;
  }
  TraceFirebirdWorker(std::string("classic_request.") + std::string(trace_name) +
                      ".rows=" + std::to_string(rows.size()) +
                      " eof_sent=true");
  return true;
}

std::vector<std::uint8_t> FirebirdClassicProcedureNameRowPacket(
    const FirebirdClassicDataRequest& request,
    const std::vector<FirebirdClassicMessageSlot>& slots,
    const FirebirdProcedureDescriptor& procedure,
    std::uint32_t message_count = 1) {
  if (slots.size() != 8 ||
      slots[0].opcode != 7 || slots[1].opcode != 7 ||
      slots[2].opcode != 7 || slots[3].opcode != 7 ||
      slots[4].opcode != 7 || slots[5].opcode != 7 ||
      !(slots[6].opcode == 40 || slots[6].opcode == 41) ||
      !(slots[7].opcode == 40 || slots[7].opcode == 41)) {
    return {};
  }
  auto out = FirebirdClassicRequestSendPacket(request, message_count);
  AppendXdrU32(&out, 1);  // generated FOR-loop row-present flag.
  AppendXdrU32(&out, 1);  // RDB$PACKAGE_NAME null flag.
  AppendXdrU32(&out, 0);  // RDB$VALID_BLR null flag.
  AppendXdrU32(&out, 1);  // RDB$VALID_BLR.
  AppendXdrU32(&out, 0);  // RDB$SYSTEM_FLAG null flag.
  AppendXdrU32(&out, 0);  // RDB$SYSTEM_FLAG.
  AppendXdrClassicCString(&out, {},
                          slots[6].length == 0 ? 253 : slots[6].length);
  AppendXdrClassicCString(&out, UpperIdentifier(procedure.name),
                          slots[7].length == 0 ? 253 : slots[7].length);
  return out;
}

bool WriteFirebirdProcedureNameRowsBatch(
    int fd,
    const FirebirdClassicDataRequest& request,
    FirebirdRemoteHandle* classic_request,
    const std::vector<FirebirdProcedureDescriptor>& rows,
    bool piggyback,
    std::string_view trace_name) {
  if (piggyback) {
    if (!WritePacket(fd, FirebirdPiggybackResponsePacket(
                             request.message_number, FirebirdStatusVector(0)))) {
      return false;
    }
  }
  std::vector<FirebirdClassicMessageSlot> slots;
  if (!FirebirdClassicMessageSlots(classic_request->data, request.message_number,
                                   &slots)) {
    return false;
  }
  bool emitted_row = false;
  while (classic_request->next_row_index < rows.size()) {
    const auto row_index = classic_request->next_row_index;
    const bool last_row = row_index + 1 == rows.size();
    const auto packet = FirebirdClassicProcedureNameRowPacket(
        request, slots, rows[row_index], last_row ? 0 : 1);
    if (packet.empty() || !WritePacket(fd, packet)) return false;
    emitted_row = true;
    TraceFirebirdWorker(std::string("classic_request.") + std::string(trace_name) +
                        ".row=" + std::to_string(row_index) +
                        " procedure=" + EscapeJsonLocal(rows[row_index].name));
    ++classic_request->next_row_index;
    if (last_row) break;
  }
  if (!emitted_row && classic_request->next_row_index == rows.size()) {
    const auto zero_message =
        FirebirdClassicZeroMessagePacket(request, classic_request->data, 0);
    if (zero_message.empty() || !WritePacket(fd, zero_message)) return false;
    ++classic_request->next_row_index;
  } else if (classic_request->next_row_index > rows.size()) {
    const auto zero_message =
        FirebirdClassicZeroMessagePacket(request, classic_request->data, 0);
    if (zero_message.empty() || !WritePacket(fd, zero_message)) return false;
  }
  TraceFirebirdWorker(std::string("classic_request.") + std::string(trace_name) +
                      ".rows=" + std::to_string(rows.size()) +
                      " eof_sent=true");
  return true;
}

