std::vector<FirebirdSystemObjectNameRow> FirebirdUserRoleNameRows(
    const FirebirdBinarySessionState& state) {
  std::vector<FirebirdSystemObjectNameRow> rows;
  rows.reserve(state.roles.size());
  for (const auto& role : state.roles) {
    if (!role.active ||
        !FirebirdSecurityScopeMatches(role.scope, state.emulation_security_scope)) {
      continue;
    }
    rows.push_back({UpperIdentifier(role.name), 0});
  }
  std::sort(rows.begin(), rows.end(),
            [](const auto& lhs, const auto& rhs) {
              return lhs.name < rhs.name;
            });
  rows.erase(std::unique(rows.begin(), rows.end(),
                         [](const auto& lhs, const auto& rhs) {
                           return lhs.name == rhs.name;
                         }),
             rows.end());
  return rows;
}

std::vector<std::uint8_t> FirebirdClassicSystemObjectNameRowPacket(
    const FirebirdClassicDataRequest& request,
    const std::vector<FirebirdClassicMessageSlot>& slots,
    const FirebirdSystemObjectNameRow& row,
    std::uint32_t message_count = 1) {
  if (slots.size() != 4 ||
      slots[0].opcode != 7 || slots[1].opcode != 7 ||
      slots[2].opcode != 7 ||
      !(slots[3].opcode == 40 || slots[3].opcode == 41)) {
    return {};
  }
  auto out = FirebirdClassicRequestSendPacket(request, message_count);
  AppendXdrU32(&out, 1);  // generated FOR-loop row-present flag.
  AppendXdrU32(&out, 0);  // RDB$SYSTEM_FLAG null flag.
  AppendXdrU32(&out, static_cast<std::uint32_t>(row.system_flag));
  AppendXdrClassicCString(&out, row.name,
                          slots[3].length == 0 ? 253 : slots[3].length);
  return out;
}

