std::vector<FirebirdCollationDescriptor> FirebirdUserCollations(
    const FirebirdBinarySessionState& state) {
  std::vector<FirebirdCollationDescriptor> rows;
  rows.reserve(state.collations.size());
  for (const auto& [name, descriptor] : state.collations) {
    (void)name;
    rows.push_back(descriptor);
  }
  std::sort(rows.begin(), rows.end(),
            [](const FirebirdCollationDescriptor& lhs,
               const FirebirdCollationDescriptor& rhs) {
              return UpperIdentifier(lhs.name) < UpperIdentifier(rhs.name);
            });
  return rows;
}

