std::vector<std::uint8_t> FirebirdClassicCollationRowPacket(
    const FirebirdClassicDataRequest& request,
    const std::vector<FirebirdClassicMessageSlot>& slots,
    const FirebirdCollationDescriptor& row,
    std::uint32_t specific_attributes_blob_id,
    std::uint32_t message_count = 1) {
  auto out = FirebirdClassicRequestSendPacket(request, message_count);
  if (slots.size() != 11 ||
      !(slots[0].opcode == 9 || slots[0].opcode == 45) ||
      slots[1].opcode != 7 || slots[2].opcode != 7 ||
      slots[3].opcode != 7 || slots[4].opcode != 7 ||
      slots[5].opcode != 7 || slots[6].opcode != 7 ||
      slots[7].opcode != 7 ||
      !(slots[8].opcode == 40 || slots[8].opcode == 41) ||
      !(slots[9].opcode == 40 || slots[9].opcode == 41) ||
      !(slots[10].opcode == 40 || slots[10].opcode == 41)) {
    return {};
  }

  AppendXdrU32(&out, 0);  // RDB$SPECIFIC_ATTRIBUTES blob high.
  AppendXdrU32(&out, specific_attributes_blob_id);
  // RDB$SPECIFIC_ATTRIBUTES blob low.
  AppendXdrU32(&out, 1);  // Embedded FOR-loop row-present flag.
  AppendXdrU32(&out, specific_attributes_blob_id == 0 ? 1u : 0u);
  // RDB$SPECIFIC_ATTRIBUTES null flag.
  AppendXdrU32(&out, 0);  // RDB$COLLATION_ATTRIBUTES null flag.
  AppendXdrU32(&out, static_cast<std::uint32_t>(
                         static_cast<std::int32_t>(row.attributes)));
  AppendXdrU32(&out, row.base_collation.empty() ? 1u : 0u);
  // RDB$BASE_COLLATION_NAME null flag.
  AppendXdrU32(&out, 0);  // RDB$SYSTEM_FLAG null flag.
  AppendXdrU32(&out, static_cast<std::uint32_t>(
                         static_cast<std::int32_t>(row.system_flag)));
  AppendXdrClassicCString(&out, row.name, slots[8].length == 0 ? 253 : slots[8].length);
  AppendXdrClassicCString(&out, row.character_set,
                          slots[9].length == 0 ? 253 : slots[9].length);
  AppendXdrClassicCString(&out, row.base_collation,
                          slots[10].length == 0 ? 253 : slots[10].length);
  return out;
}

bool WriteFirebirdCollationRowsBatch(int fd,
                                     FirebirdBinarySessionState* state,
                                     const FirebirdClassicDataRequest& request,
                                     FirebirdRemoteHandle* classic_request,
                                     bool include_system_collations,
                                     bool piggyback,
                                     std::string_view trace_name) {
  std::vector<FirebirdClassicMessageSlot> slots;
  if (!FirebirdClassicMessageSlots(
          classic_request->data, request.message_number, &slots)) {
    return false;
  }
  if (state == nullptr) return false;
  auto rows = FirebirdUserCollations(*state);
  if (include_system_collations) {
    const auto& system_rows = FirebirdV5SystemCollationRows();
    rows.insert(rows.end(), system_rows.begin(), system_rows.end());
    std::sort(rows.begin(), rows.end(),
              [](const auto& lhs, const auto& rhs) {
                const auto lhs_name = UpperIdentifier(lhs.name);
                const auto rhs_name = UpperIdentifier(rhs.name);
                if (lhs_name != rhs_name) return lhs_name < rhs_name;
                return lhs.system_flag > rhs.system_flag;
              });
    rows.erase(std::unique(rows.begin(), rows.end(),
                           [](const auto& lhs, const auto& rhs) {
                             return UpperIdentifier(lhs.name) ==
                                    UpperIdentifier(rhs.name);
                           }),
               rows.end());
  }
  if (piggyback) {
    if (!WritePacket(fd, FirebirdPiggybackResponsePacket(
                             request.message_number, FirebirdStatusVector(0)))) {
      return false;
    }
  }
  bool emitted_row = false;
  while (classic_request->next_row_index < rows.size()) {
    const auto row_index = classic_request->next_row_index;
    const bool last_row = row_index + 1 >= rows.size();
    std::uint32_t specific_attributes_blob_id = 0;
    if (!rows[row_index].specific_attributes.empty() &&
        !ToUpperAscii(rows[row_index].specific_attributes)
             .starts_with("COLL-VERSION=")) {
      specific_attributes_blob_id = RegisterFirebirdBlobValue(
          state, "RDB$COLLATIONS", "RDB$SPECIFIC_ATTRIBUTES",
          rows[row_index].specific_attributes);
    }
    const auto packet = FirebirdClassicCollationRowPacket(
        request, slots, rows[row_index], specific_attributes_blob_id,
        last_row ? 0 : 1);
    if (packet.empty() || !WritePacket(fd, packet)) return false;
    ++classic_request->next_row_index;
    emitted_row = true;
    TraceFirebirdWorker(std::string("classic_request.") +
                        std::string(trace_name) + ".row=" +
                        std::to_string(row_index) + " collation=" +
                        EscapeJsonLocal(rows[row_index].name));
    if (last_row) break;
  }
  if (!emitted_row) {
    const auto zero_message =
        FirebirdClassicZeroMessagePacket(request, classic_request->data, 0);
    if (zero_message.empty() || !WritePacket(fd, zero_message)) return false;
    ++classic_request->next_row_index;
  }
  return true;
}

std::vector<std::uint8_t> FirebirdClassicShortNullableCStringRowPacket(
    const FirebirdClassicDataRequest& request,
    std::int16_t flag,
    std::int16_t null_flag,
    std::string_view value,
    std::uint32_t message_count = 1) {
  auto out = FirebirdClassicRequestSendPacket(request, message_count);
  AppendXdrU32(&out, static_cast<std::uint32_t>(static_cast<std::int32_t>(flag)));
  AppendXdrU32(&out, static_cast<std::uint32_t>(static_cast<std::int32_t>(null_flag)));
  AppendXdrClassicCString(&out, value, 253);
  return out;
}

bool WriteFirebirdShortNullableCStringBatch(
    int fd,
    const FirebirdClassicDataRequest& request,
    FirebirdRemoteHandle* classic_request,
    const std::vector<std::string>& values,
    bool piggyback,
    std::string_view trace_name) {
  if (piggyback) {
    if (!WritePacket(fd, FirebirdPiggybackResponsePacket(
                             request.message_number, FirebirdStatusVector(0)))) {
      return false;
    }
  }

  bool emitted_row = false;
  while (classic_request->next_row_index < values.size()) {
    const bool last_row = classic_request->next_row_index + 1 == values.size();
    if (!WritePacket(fd, FirebirdClassicShortNullableCStringRowPacket(
                             request, 1, 0,
                             values[classic_request->next_row_index],
                             last_row ? 0 : 1))) {
      return false;
    }
    ++classic_request->next_row_index;
    emitted_row = true;
    if (last_row) break;
  }
  if (!emitted_row && classic_request->next_row_index == values.size()) {
    if (!WritePacket(fd, FirebirdClassicShortNullableCStringRowPacket(
                             request, 0, 1, {}, 0))) {
      return false;
    }
    ++classic_request->next_row_index;
  } else if (classic_request->next_row_index > values.size() &&
             !WritePacket(fd, FirebirdClassicShortNullableCStringRowPacket(
                              request, 0, 1, {}, 0))) {
    return false;
  }

  TraceFirebirdWorker(std::string("classic_request.") + std::string(trace_name) +
                      ".rows=" + std::to_string(values.size()) + " eof_sent=true");
  return true;
}

std::vector<std::uint8_t> FirebirdClassicPrivilegeRowPacket(
    const FirebirdClassicDataRequest& request,
    const std::vector<FirebirdClassicMessageSlot>& slots,
    const FirebirdPrivilegeRow& row,
    std::uint32_t message_count = 1) {
  auto out = FirebirdClassicRequestSendPacket(request, message_count);
  if (slots.size() == 6) {
    AppendXdrU32(&out, 1);  // row-present flag
    AppendXdrU32(&out, 0);  // grantor null flag
    AppendXdrU32(&out, static_cast<std::uint32_t>(
                           static_cast<std::int32_t>(row.grant_option)));
    AppendXdrU32(&out, static_cast<std::uint32_t>(
                           static_cast<std::int32_t>(row.user_type)));
    AppendXdrClassicCString(&out, row.grantee, 253);
    AppendXdrClassicCString(&out, row.grantor, 253);
    return out;
  }
  if (slots.size() == 7) {
    AppendXdrU32(&out, 1);  // row-present flag
    AppendXdrU32(&out, row.field_name.empty() ? 1 : 0);
    AppendXdrU32(&out, static_cast<std::uint32_t>(
                           static_cast<std::int32_t>(row.grant_option)));
    AppendXdrClassicCString(&out, row.grantee, 253);
    AppendXdrClassicCString(&out, row.field_name, 253);
    AppendXdrClassicCString(&out, row.object_name, 253);
    AppendXdrClassicCString(&out, row.grantor, 253);
    return out;
  }
  if (slots.size() == 9) {
    AppendXdrU32(&out, 1);  // row-present flag
    AppendXdrU32(&out, static_cast<std::uint32_t>(
                           static_cast<std::int32_t>(row.user_type)));
    AppendXdrU32(&out, row.field_name.empty() ? 1 : 0);
    AppendXdrU32(&out, 0);  // grant option is present
    AppendXdrU32(&out, static_cast<std::uint32_t>(
                           static_cast<std::int32_t>(row.grant_option)));
    AppendXdrClassicCString(&out, row.grantee, 253);
    AppendXdrClassicCString(&out, row.field_name, 253);
    AppendXdrClassicCString(&out, row.grantor, 253);
    AppendXdrClassicCString(&out, row.privilege, 253);
    return out;
  }
  if (slots.size() == 8) {
    AppendXdrU32(&out, 1);  // row-present flag
    AppendXdrU32(&out, static_cast<std::uint32_t>(
                           static_cast<std::int32_t>(row.grant_option)));
    AppendXdrU32(&out, static_cast<std::uint32_t>(
                           static_cast<std::int32_t>(row.user_type)));
    AppendXdrU32(&out, static_cast<std::uint32_t>(
                           static_cast<std::int32_t>(row.object_type)));
    AppendXdrU32(&out, 0);  // nullable string indicator slot in generated BLR
    AppendXdrClassicCString(&out, row.grantee, 253);
    AppendXdrClassicCString(&out, row.privilege, 253);
    AppendXdrClassicCString(&out, row.grantor, 253);
    return out;
  }
  return {};
}

bool WriteFirebirdPrivilegeRowsBatch(int fd,
                                     const FirebirdClassicDataRequest& request,
                                     FirebirdRemoteHandle* classic_request,
                                     const std::vector<FirebirdPrivilegeRow>& rows,
                                     bool piggyback,
                                     std::string_view trace_name) {
  if (piggyback) {
    if (!WritePacket(fd, FirebirdPiggybackResponsePacket(
                             request.message_number, FirebirdStatusVector(0)))) {
      return false;
    }
  }

  std::vector<FirebirdClassicMessageSlot> slots;
  if (!FirebirdClassicMessageSlots(classic_request->data, request.message_number, &slots)) {
    return false;
  }

  bool emitted_row = false;
  while (classic_request->next_row_index < rows.size()) {
    const bool last_row = classic_request->next_row_index + 1 == rows.size();
    const auto row_packet = FirebirdClassicPrivilegeRowPacket(
        request, slots, rows[classic_request->next_row_index], last_row ? 0 : 1);
    if (row_packet.empty() || !WritePacket(fd, row_packet)) return false;
    ++classic_request->next_row_index;
    emitted_row = true;
    if (last_row) break;
  }
  if (!emitted_row && classic_request->next_row_index == rows.size()) {
    const auto zero_message = FirebirdClassicZeroMessagePacket(request, classic_request->data, 0);
    if (zero_message.empty() || !WritePacket(fd, zero_message)) return false;
    ++classic_request->next_row_index;
  } else if (classic_request->next_row_index > rows.size()) {
    const auto zero_message = FirebirdClassicZeroMessagePacket(request, classic_request->data, 0);
    if (zero_message.empty() || !WritePacket(fd, zero_message)) return false;
  }

  TraceFirebirdWorker(std::string("classic_request.") + std::string(trace_name) +
                      ".rows=" + std::to_string(rows.size()) + " eof_sent=true");
  return true;
}

