bool FirebirdStatementRequiresPhysicalSelectDescriptor(
    std::string_view sql_text) {
  const std::string uncommented = StripFirebirdBodyLineComments(
      StripSqlBlockComments(StripTerminatingSemicolon(sql_text)));
  const std::string upper = ToUpperAscii(TrimAscii(uncommented));
  const auto starts_with_command = [&](std::string_view command) {
    if (!upper.starts_with(command)) return false;
    if (upper.size() == command.size()) return true;
    const char boundary = upper[command.size()];
    return std::isspace(static_cast<unsigned char>(boundary)) != 0 ||
           boundary == ';' || boundary == '(' || boundary == '\'' ||
           boundary == '"';
  };
  return starts_with_command("SELECT") || starts_with_command("WITH");
}

