std::optional<std::string>
EscapeFirebirdConversionDiagnosticJsonString(std::string_view text) {
  constexpr char kHex[] = "0123456789ABCDEF";
  std::string escaped;
  escaped.reserve(text.size());
  std::size_t offset = 0;
  while (offset < text.size()) {
    const auto first = static_cast<unsigned char>(text[offset]);
    if (first < 0x20u) {
      escaped += "\\u00";
      escaped.push_back(kHex[(first >> 4) & 0x0fu]);
      escaped.push_back(kHex[first & 0x0fu]);
      ++offset;
      continue;
    }
    if (first == static_cast<unsigned char>('"')) {
      escaped += "\\\"";
      ++offset;
      continue;
    }
    if (first == static_cast<unsigned char>('\\')) {
      escaped += "\\\\";
      ++offset;
      continue;
    }
    if (first <= 0x7fu) {
      escaped.push_back(static_cast<char>(first));
      ++offset;
      continue;
    }

    std::size_t count = 0;
    unsigned char second_min = 0x80u;
    unsigned char second_max = 0xbfu;
    if (first >= 0xc2u && first <= 0xdfu) {
      count = 2;
    } else if (first >= 0xe0u && first <= 0xefu) {
      count = 3;
      if (first == 0xe0u) second_min = 0xa0u;
      if (first == 0xedu) second_max = 0x9fu;
    } else if (first >= 0xf0u && first <= 0xf4u) {
      count = 4;
      if (first == 0xf0u) second_min = 0x90u;
      if (first == 0xf4u) second_max = 0x8fu;
    } else {
      return std::nullopt;
    }
    if (offset + count > text.size()) return std::nullopt;
    const auto second = static_cast<unsigned char>(text[offset + 1]);
    if (second < second_min || second > second_max) return std::nullopt;
    for (std::size_t index = 2; index < count; ++index) {
      const auto continuation =
          static_cast<unsigned char>(text[offset + index]);
      if (continuation < 0x80u || continuation > 0xbfu) {
        return std::nullopt;
      }
    }
    escaped.append(text.substr(offset, count));
    offset += count;
  }
  return escaped;
}

std::optional<FirebirdConversionErrorPresentation>
PresentFirebirdConversionInputDiagnostic(
    const ipc::MessageVectorSet& messages,
    std::string_view operation) {
  constexpr std::string_view kDiagnosticCode =
      "SB_DIAG_FUNCTION_CONVERSION_INPUT";
  constexpr std::string_view kFieldName = "conversion_input_text";
  constexpr std::size_t kMaximumConversionInputBytes = 1024;
  if (messages.diagnostics.empty() ||
      messages.diagnostics.front().code != kDiagnosticCode) {
    return std::nullopt;
  }

  const std::string* conversion_input = nullptr;
  for (const auto& field : messages.diagnostics.front().fields) {
    if (field.name != kFieldName) continue;
    if (conversion_input != nullptr) return std::nullopt;
    conversion_input = &field.value;
  }
  if (conversion_input == nullptr || conversion_input->empty() ||
      conversion_input->size() > kMaximumConversionInputBytes ||
      conversion_input->find('\0') != std::string::npos) {
    return std::nullopt;
  }
  const auto escaped_input =
      EscapeFirebirdConversionDiagnosticJsonString(*conversion_input);
  const auto escaped_operation =
      EscapeFirebirdConversionDiagnosticJsonString(operation);
  if (!escaped_input || !escaped_operation) return std::nullopt;

  FirebirdConversionErrorPresentation presentation;
  presentation.conversion_input_text = *conversion_input;
  presentation.response_json =
      "{\"ok\":false,\"wire_operation\":\"" +
      *escaped_operation +
      "\",\"diagnostic_code\":\"FIREBIRD.CONVERSION.INPUT_ERROR\","
      "\"sqlstate\":\"22018\",\"conversion_input\":\"" +
      *escaped_input +
      "\",\"runtime_policy\":\"structured_engine_diagnostic_presentation\"}";
  AppendFirebirdStatusInt(&presentation.encoded_status_vector,
                          kIscArgGds,
                          kIscConvertError);
  AppendFirebirdStatusText(&presentation.encoded_status_vector,
                           kIscArgString,
                           *conversion_input);
  AppendFirebirdStatusText(&presentation.encoded_status_vector,
                           kIscArgSqlState,
                           "22018");
  AppendXdrU32(&presentation.encoded_status_vector, kIscArgEnd);
  return presentation;
}

// FIREBIRD_GLOBAL_COUNT_PROJECTION_WORKER_BEGIN
bool ValidateFirebirdRelationProjectionViewCompletePacket(
    const FirebirdRelationProjectionViewSelectRoute& route,
    const std::vector<FirebirdRelationProjectionViewOutputDescriptor>& outputs,
    std::string_view view_uuid,
    std::string_view view_descriptor_uuid,
    std::uint64_t view_descriptor_generation,
    std::string_view server_result_payload,
    std::vector<FirebirdScalarProjectionWireRow>* rows,
    std::uint64_t server_row_count,
    bool cursor_present,
    std::string* diagnostic) {
  auto refuse = [&](std::string reason) {
    if (rows != nullptr) rows->clear();
    if (diagnostic != nullptr) *diagnostic = std::move(reason);
    return false;
  };
  if (rows == nullptr || !route.recognized() || outputs.size() != 2u ||
      outputs[0].ordinal != 0u || outputs[1].ordinal != 1u ||
      view_uuid.empty() || view_descriptor_uuid.empty() ||
      view_descriptor_generation == 0u || outputs[1].nullable) {
    return refuse("exact_relation_projection_view_binding_required");
  }
  if (TextLineValueLocal(server_result_payload, "operation_id") !=
          "dml.select_rows" ||
      TextLineValueLocal(server_result_payload, "result_kind") !=
          "query_rowset") {
    return refuse("query_rowset_result_kind_required");
  }
  const auto payload_row_count = ParseUnsignedText(
      TextLineValueLocal(server_result_payload, "row_count"));
  if (!payload_row_count || *payload_row_count != server_row_count ||
      rows->size() != server_row_count || cursor_present ||
      !TextLineValueLocal(server_result_payload,
                          "row[" + std::to_string(server_row_count) + "]")
           .empty()) {
    return refuse("complete_initial_relation_view_rowset_required");
  }

  for (std::size_t row_index = 0; row_index < rows->size(); ++row_index) {
    auto& row = (*rows)[row_index];
    if (row.cells.size() != 2u) {
      return refuse("exact_two_result_cells_required");
    }
    const auto raw_fields = ParseSemicolonFieldOrder(
        TextLineValueLocal(server_result_payload,
                           "row[" + std::to_string(row_index) + "]"));
    const auto metadata = SplitTopLevelSemicolon(
        TextLineValueLocal(server_result_payload,
                           "row_meta[" + std::to_string(row_index) + "]"));
    if (raw_fields.size() != 2u || metadata.size() != 2u) {
      return refuse("ordered_engine_fields_and_metadata_required");
    }
    for (std::size_t ordinal = 0; ordinal < 2u; ++ordinal) {
      const auto& output = outputs[ordinal];
      const auto& cell = row.cells[ordinal];
      if (raw_fields[ordinal].first != output.name ||
          raw_fields[ordinal].second != cell.text ||
          (!output.nullable && cell.is_null) ||
          (cell.is_null && !cell.text.empty())) {
        return refuse("ordered_relation_view_output_mismatch");
      }
      if (!cell.is_null) {
        const auto value = ParseSignedText(cell.text);
        if (!value ||
            *value < std::numeric_limits<std::int32_t>::min() ||
            *value > std::numeric_limits<std::int32_t>::max() ||
            std::to_string(*value) != cell.text) {
          return refuse("canonical_int32_relation_view_value_required");
        }
      }
      const std::string expected_metadata =
          output.name + ":" + output.canonical_type_name + ":" +
          (cell.is_null ? "null" : "not_null");
      if (metadata[ordinal] != expected_metadata) {
        return refuse("engine_int32_relation_view_metadata_required");
      }
    }
  }

  auto has_evidence = [&](std::string_view kind, std::string_view value) {
    const std::string expected =
        "evidence=" + std::string(kind) + ":" + std::string(value);
    std::size_t start = 0;
    while (start <= server_result_payload.size()) {
      const std::size_t end = server_result_payload.find('\n', start);
      const std::string_view line = server_result_payload.substr(
          start,
          end == std::string_view::npos
              ? server_result_payload.size() - start
              : end - start);
      if (line == expected) return true;
      if (end == std::string_view::npos) break;
      start = end + 1u;
    }
    return false;
  };
  if (!has_evidence("dml_result_projection", "relation_projection") ||
      !has_evidence("relation_projection_relation_scan",
                    "one_mga_visible_scan") ||
      !has_evidence("relation_projection_visible_rows_scanned",
                    std::to_string(server_row_count)) ||
      !has_evidence("relation_projection_output_count", "2") ||
      !has_evidence("relation_projection_row_storage", "none") ||
      !has_evidence("relation_projection_view_marker",
                    kFirebirdRelationProjectionViewMarkerV1) ||
      !has_evidence("relation_projection_view_uuid", view_uuid) ||
      !has_evidence("relation_projection_view_descriptor_uuid",
                    view_descriptor_uuid) ||
      !has_evidence("relation_projection_view_descriptor_generation",
                    std::to_string(view_descriptor_generation)) ||
      !has_evidence("relation_projection_view_expansion",
                    "engine_owned_sql_free") ||
      !has_evidence("relation_projection_view_parser_sql", "false")) {
    return refuse("relation_projection_view_engine_evidence_required");
  }
  if (diagnostic != nullptr) diagnostic->clear();
  return true;
}

std::vector<FirebirdScalarProjectionWireDescriptor>
DescribeFirebirdGlobalCountProjectionWireDescriptors(
    const FirebirdGlobalCountProjectionRoute& route) {
  std::vector<FirebirdScalarProjectionWireDescriptor> descriptors;
  if (!route.recognized() ||
      route.items[0].operation !=
          FirebirdGlobalCountProjectionOperation::kCountStar ||
      route.items[1].operation !=
          FirebirdGlobalCountProjectionOperation::kCountNonNullField ||
      route.items[2].operation !=
          FirebirdGlobalCountProjectionOperation::kCountDistinctField) {
    return descriptors;
  }
  descriptors.reserve(3);
  for (const auto& item : route.items) {
    if (item.aggregate_function_uuid !=
            kFirebirdCanonicalCountAggregateUuid ||
        item.output_alias.empty()) {
      return {};
    }
    FirebirdScalarProjectionWireDescriptor descriptor;
    descriptor.name = item.output_alias;
    descriptor.source_name = item.output_alias;
    descriptor.sql_type = 580;  // SQL_INT64 without nullable flag.
    descriptor.length = 8;
    descriptor.scale = 0;
    descriptor.subtype = 0;
    descriptor.nullable = false;
    descriptors.push_back(std::move(descriptor));
  }
  return descriptors;
}

bool ValidateFirebirdGlobalCountProjectionCompletePacket(
    const FirebirdGlobalCountProjectionRoute& route,
    std::string_view server_result_payload,
    const std::vector<FirebirdScalarProjectionWireDescriptor>& descriptors,
    std::vector<FirebirdScalarProjectionWireRow>* rows,
    std::uint64_t server_row_count,
    bool cursor_present,
    std::string* diagnostic) {
  auto refuse = [&](std::string reason) {
    if (rows != nullptr) rows->clear();
    if (diagnostic != nullptr) *diagnostic = std::move(reason);
    return false;
  };
  if (rows == nullptr || !route.recognized() || route.items.size() != 3) {
    return refuse("exact_global_count_route_required");
  }
  const auto expected_descriptors =
      DescribeFirebirdGlobalCountProjectionWireDescriptors(route);
  if (expected_descriptors.size() != 3 || descriptors.size() != 3) {
    return refuse("exact_three_column_sqlda_required");
  }
  for (std::size_t index = 0; index < descriptors.size(); ++index) {
    const auto& actual = descriptors[index];
    const auto& expected = expected_descriptors[index];
    if (actual.name != expected.name ||
        actual.source_name != expected.source_name ||
        !actual.relation.empty() || !actual.owner.empty() ||
        actual.sql_type != 580 || actual.length != 8 ||
        actual.scale != 0 || actual.subtype != 0 || actual.nullable ||
        !actual.character_set.empty() || actual.character_length != 0) {
      return refuse("sql_int64_descriptor_mismatch");
    }
  }

  if (TextLineValueLocal(server_result_payload, "operation_id") !=
          "dml.select_rows" ||
      TextLineValueLocal(server_result_payload, "result_kind") !=
          "global_aggregate_projection_rowset") {
    return refuse("global_aggregate_result_kind_required");
  }
  const auto payload_row_count = ParseUnsignedText(
      TextLineValueLocal(server_result_payload, "row_count"));
  if (!payload_row_count || *payload_row_count != 1 ||
      server_row_count != 1 || cursor_present || rows->size() != 1 ||
      !TextLineValueLocal(server_result_payload, "row[1]").empty()) {
    return refuse("one_complete_initial_row_required");
  }
  if (rows->front().cells.size() != 3) {
    return refuse("exact_three_result_cells_required");
  }

  const auto raw_fields = ParseSemicolonFieldOrder(
      TextLineValueLocal(server_result_payload, "row[0]"));
  if (raw_fields.size() != 3) {
    return refuse("exact_three_engine_fields_required");
  }
  for (std::size_t index = 0; index < 3; ++index) {
    const auto& cell = rows->front().cells[index];
    if (raw_fields[index].first != route.items[index].output_alias ||
        raw_fields[index].second != cell.text || cell.is_null) {
      return refuse("ordered_non_null_count_field_required");
    }
    const auto value = ParseSignedText(cell.text);
    if (!value || *value < 0 || std::to_string(*value) != cell.text) {
      return refuse("canonical_nonnegative_int64_count_required");
    }
  }

  const auto metadata = SplitTopLevelSemicolon(
      TextLineValueLocal(server_result_payload, "row_meta[0]"));
  if (metadata.size() != 3) {
    return refuse("exact_three_engine_field_descriptors_required");
  }
  for (std::size_t index = 0; index < 3; ++index) {
    const std::string expected = route.items[index].output_alias +
                                 ":int64:not_null";
    if (metadata[index] != expected) {
      return refuse("engine_int64_not_null_metadata_required");
    }
  }

  auto has_evidence = [&](std::string_view kind, std::string_view value) {
    const std::string expected =
        "evidence=" + std::string(kind) + ":" + std::string(value);
    std::size_t start = 0;
    while (start <= server_result_payload.size()) {
      const std::size_t end = server_result_payload.find('\n', start);
      const std::string_view line = server_result_payload.substr(
          start, end == std::string_view::npos
                     ? server_result_payload.size() - start
                     : end - start);
      if (line == expected) return true;
      if (end == std::string_view::npos) break;
      start = end + 1;
    }
    return false;
  };
  if (!has_evidence("dml_result_projection",
                    "global_aggregate_projection") ||
      !has_evidence("global_aggregate_relation_scan",
                    "one_mga_visible_scan") ||
      !has_evidence("global_aggregate_output_count", "3") ||
      !has_evidence("global_aggregate_function_uuid",
                    kFirebirdCanonicalCountAggregateUuid)) {
    return refuse("global_aggregate_engine_evidence_required");
  }
  if (diagnostic != nullptr) diagnostic->clear();
  return true;
}
// FIREBIRD_GLOBAL_COUNT_PROJECTION_WORKER_END

// FIREBIRD_GLOBAL_AVG_PROJECTION_WORKER_BEGIN
std::vector<FirebirdScalarProjectionWireDescriptor>
DescribeFirebirdGlobalAvgProjectionWireDescriptors(
    const FirebirdGlobalAvgProjectionRoute& route,
    FirebirdGlobalAvgResultKind result_kind) {
  std::vector<FirebirdScalarProjectionWireDescriptor> descriptors;
  if (!route.recognized() ||
      route.item.aggregate_function_uuid !=
          kFirebirdCanonicalAvgAggregateUuid ||
      route.item.output_alias.empty() ||
      result_kind == FirebirdGlobalAvgResultKind::kUnsupported) {
    return descriptors;
  }
  FirebirdScalarProjectionWireDescriptor descriptor;
  descriptor.name = route.item.output_alias;
  descriptor.source_name = route.item.output_alias;
  descriptor.length = 8;
  descriptor.scale = 0;
  descriptor.subtype = 0;
  descriptor.nullable = true;
  descriptor.sql_type =
      result_kind == FirebirdGlobalAvgResultKind::kNullableInt64
          ? 580   // SQL_INT64; nullable is carried separately.
          : 480;  // SQL_DOUBLE; nullable is carried separately.
  descriptors.push_back(std::move(descriptor));
  return descriptors;
}

bool ValidateFirebirdGlobalAvgProjectionCompletePacket(
    const FirebirdGlobalAvgProjectionRoute& route,
    FirebirdGlobalAvgResultKind result_kind,
    std::string_view server_result_payload,
    const std::vector<FirebirdScalarProjectionWireDescriptor>& descriptors,
    std::vector<FirebirdScalarProjectionWireRow>* rows,
    std::uint64_t server_row_count,
    bool cursor_present,
    std::string* diagnostic) {
  auto refuse = [&](std::string reason) {
    if (rows != nullptr) rows->clear();
    if (diagnostic != nullptr) *diagnostic = std::move(reason);
    return false;
  };
  if (rows == nullptr || !route.recognized() ||
      result_kind == FirebirdGlobalAvgResultKind::kUnsupported) {
    return refuse("exact_global_avg_route_required");
  }
  const auto expected_descriptors =
      DescribeFirebirdGlobalAvgProjectionWireDescriptors(route, result_kind);
  if (expected_descriptors.size() != 1 || descriptors.size() != 1) {
    return refuse("exact_one_column_sqlda_required");
  }
  const auto& actual = descriptors.front();
  const auto& expected = expected_descriptors.front();
  if (actual.name != expected.name ||
      actual.source_name != expected.source_name ||
      !actual.relation.empty() || !actual.owner.empty() ||
      actual.sql_type != expected.sql_type || actual.length != 8 ||
      actual.scale != 0 || actual.subtype != 0 || !actual.nullable ||
      !actual.character_set.empty() || actual.character_length != 0) {
    return refuse("nullable_avg_descriptor_mismatch");
  }

  if (TextLineValueLocal(server_result_payload, "operation_id") !=
          "dml.select_rows" ||
      TextLineValueLocal(server_result_payload, "result_kind") !=
          "global_aggregate_projection_rowset") {
    return refuse("global_aggregate_result_kind_required");
  }
  const auto payload_row_count = ParseUnsignedText(
      TextLineValueLocal(server_result_payload, "row_count"));
  if (!payload_row_count || *payload_row_count != 1 ||
      server_row_count != 1 || cursor_present || rows->size() != 1 ||
      !TextLineValueLocal(server_result_payload, "row[1]").empty()) {
    return refuse("one_complete_initial_row_required");
  }
  if (rows->front().cells.size() != 1) {
    return refuse("exact_one_result_cell_required");
  }

  const auto raw_fields = ParseSemicolonFieldOrder(
      TextLineValueLocal(server_result_payload, "row[0]"));
  auto& cell = rows->front().cells.front();
  if (raw_fields.size() != 1 ||
      raw_fields.front().first != route.item.output_alias ||
      raw_fields.front().second != cell.text) {
    return refuse("ordered_avg_field_required");
  }
  if (!cell.is_null) {
    if (result_kind == FirebirdGlobalAvgResultKind::kNullableInt64) {
      const auto value = ParseSignedText(cell.text);
      if (!value || std::to_string(*value) != cell.text) {
        return refuse("canonical_int64_avg_required");
      }
    } else {
      const auto value = ParseDoubleText(cell.text);
      if (!value || !std::isfinite(*value) ||
          TrimAscii(cell.text) != cell.text) {
        return refuse("finite_real64_avg_required");
      }
    }
  } else if (!cell.text.empty() || !raw_fields.front().second.empty()) {
    return refuse("sql_null_avg_payload_required");
  }

  const auto metadata = SplitTopLevelSemicolon(
      TextLineValueLocal(server_result_payload, "row_meta[0]"));
  const std::string expected_type =
      result_kind == FirebirdGlobalAvgResultKind::kNullableInt64
          ? "int64"
          : "real64";
  const std::string expected_metadata =
      route.item.output_alias + ":" + expected_type + ":" +
      (cell.is_null ? "null" : "not_null");
  if (metadata.size() != 1 || metadata.front() != expected_metadata) {
    return refuse("engine_nullable_avg_metadata_required");
  }

  auto has_evidence = [&](std::string_view kind, std::string_view value) {
    const std::string expected_evidence =
        "evidence=" + std::string(kind) + ":" + std::string(value);
    std::size_t start = 0;
    while (start <= server_result_payload.size()) {
      const std::size_t end = server_result_payload.find('\n', start);
      const std::string_view line = server_result_payload.substr(
          start, end == std::string_view::npos
                     ? server_result_payload.size() - start
                     : end - start);
      if (line == expected_evidence) return true;
      if (end == std::string_view::npos) break;
      start = end + 1;
    }
    return false;
  };
  if (!has_evidence("dml_result_projection",
                    "global_aggregate_projection") ||
      !has_evidence("global_aggregate_relation_scan",
                    "one_mga_visible_scan") ||
      !has_evidence("global_aggregate_output_count", "1") ||
      !has_evidence("global_aggregate_function_uuid",
                    kFirebirdCanonicalAvgAggregateUuid)) {
    return refuse("global_aggregate_engine_evidence_required");
  }
  if (diagnostic != nullptr) diagnostic->clear();
  return true;
}
// FIREBIRD_GLOBAL_AVG_PROJECTION_WORKER_END

std::vector<FirebirdScalarProjectionWireDescriptor>
DescribeFirebirdScalarProjectionWireDescriptors(
    const FirebirdScalarProjectionRoute& route) {
  std::vector<FirebirdScalarProjectionWireDescriptor> descriptors;
  if (!route.recognized()) return descriptors;
  descriptors.reserve(route.items.size());
  for (std::size_t index = 0; index < route.items.size(); ++index) {
    const auto& item = route.items[index];
    FirebirdScalarProjectionWireDescriptor descriptor;
    descriptor.name = item.result_name;
    descriptor.source_name = "c" + std::to_string(index);
    descriptor.scale = item.scale;
    descriptor.subtype = item.subtype;
    descriptor.nullable = item.nullable;
    switch (item.output_kind) {
      case FirebirdScalarProjectionOutputKind::kBinaryOctet:
        // Genuine Firebird 5.0.4 describes ASCII_CHAR as fixed TEXT(1),
        // CHARACTER SET NONE.  Charset details remain internal worker fields.
        descriptor.sql_type = 452;
        descriptor.length = 1;
        descriptor.character_set = "NONE";
        descriptor.character_length = 1;
        break;
      case FirebirdScalarProjectionOutputKind::kInt16:
      case FirebirdScalarProjectionOutputKind::kExactInt16:
        descriptor.sql_type = 500;
        descriptor.length = 2;
        break;
      case FirebirdScalarProjectionOutputKind::kInt32:
      case FirebirdScalarProjectionOutputKind::kExactInt32:
        descriptor.sql_type = 496;
        descriptor.length = 4;
        break;
      case FirebirdScalarProjectionOutputKind::kInt64:
      case FirebirdScalarProjectionOutputKind::kExactInt64:
        descriptor.sql_type = 580;
        descriptor.length = 8;
        break;
      case FirebirdScalarProjectionOutputKind::kFixedText:
        if (item.declared_length == 0) return {};
        descriptor.sql_type = 452;
        descriptor.length = item.declared_length;
        descriptor.character_set = "NONE";
        descriptor.character_length = item.declared_length;
        break;
      case FirebirdScalarProjectionOutputKind::kVaryingText:
        if (item.declared_length == 0) return {};
        descriptor.sql_type = 448;
        descriptor.length = item.declared_length;
        descriptor.character_set = "NONE";
        descriptor.character_length = item.declared_length;
        break;
      case FirebirdScalarProjectionOutputKind::kReal64:
        descriptor.sql_type = 480;
        descriptor.length = 8;
        break;
      case FirebirdScalarProjectionOutputKind::kDate:
        descriptor.sql_type = 570;
        descriptor.length = 4;
        break;
      case FirebirdScalarProjectionOutputKind::kTimestamp:
        descriptor.sql_type = 510;
        descriptor.length = 8;
        break;
      case FirebirdScalarProjectionOutputKind::kTime:
        descriptor.sql_type = 560;
        descriptor.length = 4;
        break;
    }
    descriptors.push_back(std::move(descriptor));
  }
  return descriptors;
}

bool DecodeFirebirdScalarProjectionRows(
    const FirebirdScalarProjectionRoute& route,
    std::vector<FirebirdScalarProjectionWireRow>* rows,
    std::string* diagnostic) {
#ifdef _WIN32
  if (!route.recognized()) return true;
  (void)rows;
  if (diagnostic != nullptr) {
    *diagnostic = "firebird_binary_worker_unavailable";
  }
  return false;
#else
  return DecodeFirebirdScalarProjectionRowsImpl(route, rows, diagnostic);
#endif
}

bool ValidateFirebirdScalarProjectionCompletePacket(
    const FirebirdScalarProjectionRoute& route,
    std::size_t decoded_row_count,
    std::uint64_t server_row_count,
    bool cursor_present,
    std::string* diagnostic) {
  if (!route.recognized()) return true;
  if (decoded_row_count == 0 && server_row_count == 1 && cursor_present) {
    // The execute result publishes the engine's total scalar cardinality but
    // deliberately withholds the row packet behind the ordinary engine
    // cursor. Validation of the value and terminal cursor state completes on
    // the first fetch packet.
    return true;
  }
  if (decoded_row_count != server_row_count) {
    if (diagnostic != nullptr) {
      *diagnostic = "result_row_count_mismatch";
    }
    return false;
  }
  if (decoded_row_count != 1) {
    if (diagnostic != nullptr) {
      *diagnostic = "exactly_one_complete_result_row_required";
    }
    return false;
  }
  if (cursor_present) {
    if (diagnostic != nullptr) {
      *diagnostic = "constant_scalar_projection_incomplete_cursor";
    }
    return false;
  }
  return true;
}

FirebirdPersistedRelationMetadata ProjectFirebirdPersistedRelationMetadata(
    const ipc::PublicNameResolutionResult& resolved,
    std::string_view fallback_name) {
  FirebirdPersistedRelationMetadata projected;
  const auto table =
      FirebirdTableFromPersistedRelationProjection(resolved, fallback_name);
  if (!table) return projected;

  projected.present = true;
  projected.name = table->name;
  projected.descriptor_uuid = table->descriptor_uuid;
  projected.relation_uuid = table->relation_uuid;
  projected.descriptor_generation = table->descriptor_generation;
  projected.validated_resource_epoch = table->validated_resource_epoch;
  projected.columns.reserve(table->columns.size());
  for (const auto& column : table->columns) {
    FirebirdPersistedColumnMetadata metadata;
    metadata.name = column.name;
    metadata.column_uuid = column.column_uuid;
    metadata.type_descriptor_uuid = column.type_descriptor_uuid;
    metadata.canonical_type_name = column.canonical_type_name;
    metadata.charset_uuid = column.charset_uuid;
    metadata.collation_uuid = column.collation_uuid;
    metadata.character_set = column.character_set;
    metadata.collation = column.collation;
    metadata.sql_type = column.sql_type;
    metadata.length = column.length;
    metadata.character_length = column.character_length;
    metadata.nullable = column.nullable;
    projected.columns.push_back(std::move(metadata));
  }
  return projected;
}

int ServeFirebirdWorkerSession(int fd) {
#ifdef _WIN32
  (void)fd;
  return 1;
#else
  if (PeerStartsWithFirebirdConnect(fd)) {
    return ServeFirebirdBinaryConnect(fd);
  }
  std::string line;
  while (ReadLine(fd, &line)) {
    bool close = false;
    const auto response = HandleLine(line, &close);
    if (!WriteAll(fd, response)) return 1;
    if (close) break;
  }
  return 0;
#endif
}

